      expect.objectContaining({ email: validUserData.email })
    );
    expect(mockNotifier.sendWelcome).toHaveBeenCalledWith(result.id);
    expect(result.success).toBe(true);
  });
});
```

### 2. Mock-First Approach

```typescript
