/**
 * Product Quantization Validation Tests
 *
 * Validates the PQ implementation inside the Quantizer class (hnsw-index.ts):
 * k-means convergence, encoding, distance, compression, training threshold,
 * and pre-training fallback.
 */
import { describe, it, expect } from 'vitest';
import { HNSWIndex } from '../../@claude-flow/memory/src/hnsw-index.js';

const DIM = 384;
const NUM_SUB = 8;

/** Create a deterministic vector: cluster centre + small noise */
function makeVec(centre: number[], noise = 0.01, seed = 0): Float32Array {
  const v = new Float32Array(DIM);
  for (let i = 0; i < DIM; i++) {
    v[i] = centre[i % centre.length] + noise * Math.sin(seed * 17 + i);
  }
  return v;
}

/** Build three well-separated cluster centres */
const C1 = Array.from({ length: DIM }, () => 1.0);
const C2 = Array.from({ length: DIM }, () => -1.0);
const C3 = Array.from({ length: DIM }, () => 0.0);

// ---------------------------------------------------------------------------
// Helpers to reach into the private Quantizer via the index
// ---------------------------------------------------------------------------
function createPQIndex(maxElements = 600): HNSWIndex {
  return new HNSWIndex({
    dimensions: DIM,
    M: 4,
    efConstruction: 20,
    maxElements,
    metric: 'euclidean',
    quantization: { type: 'product', subquantizers: NUM_SUB, codebookSize: 256 },
  });
}

function getQuantizer(index: HNSWIndex): any {
  return (index as any).quantizer;
}

// ===========================================================================
describe('Product Quantization', () => {
  // -------------------------------------------------------------------------
  // 1. k-means converges on 3 clear clusters
  // -------------------------------------------------------------------------
  it('k-means converges on 3 well-separated clusters', () => {
    const q = getQuantizer(createPQIndex());

    // Build tiny dataset of 2-d points in 3 clusters.
    // Interleave so the first 3 points seed one centroid per cluster
    // (kMeans init picks the first k data points).
    const data: number[][] = [];
    for (let i = 0; i < 30; i++) {
      data.push([0 + Math.random() * 0.1, 0 + Math.random() * 0.1]);
      data.push([10 + Math.random() * 0.1, 10 + Math.random() * 0.1]);
      data.push([20 + Math.random() * 0.1, 20 + Math.random() * 0.1]);
    }

    // Access private kMeans
    const centroids: number[][] = (q as any).kMeans(data, 3, 50);

    expect(centroids).toHaveLength(3);

    // Each centroid should be near one of [0,0], [10,10], [20,20]
    const targets = [[0, 0], [10, 10], [20, 20]];
    const matched = new Set<number>();
    for (const c of centroids) {
      for (let t = 0; t < targets.length; t++) {
        const dist = Math.hypot(c[0] - targets[t][0], c[1] - targets[t][1]);
        if (dist < 1.0 && !matched.has(t)) { matched.add(t); break; }
      }
    }
    expect(matched.size).toBe(3);
  });

  // -------------------------------------------------------------------------
  // 2. PQ encoding returns correct number of indices
  // -------------------------------------------------------------------------
  it('PQ encoding returns numSubquantizers indices after training', async () => {
    const index = createPQIndex();
    const q = getQuantizer(index);

    // Feed 256 vectors to trigger training
    const vecs: number[][] = [];
    for (let i = 0; i < 256; i++) {
      const v = makeVec(i < 128 ? C1 : C2, 0.05, i);
      vecs.push(Array.from(v));
    }
    q.trainingVectors = vecs;
    q.codebooks = q.trainProductQuantizer(vecs, NUM_SUB, 256);
    q.pqTrained = true;

    const encoded = q.encode(makeVec(C1, 0.01, 999));
    expect(encoded).toBeInstanceOf(Float32Array);
    expect(encoded.length).toBe(NUM_SUB);
    // All indices should be in [0, 256)
    for (let i = 0; i < encoded.length; i++) {
      expect(encoded[i]).toBeGreaterThanOrEqual(0);
      expect(encoded[i]).toBeLessThan(256);
    }
  });

  // -------------------------------------------------------------------------
  // 3. PQ distance between identical vectors is 0
  // -------------------------------------------------------------------------
  it('PQ distance between identical encoded vectors is 0', () => {
    const index = createPQIndex();
    const q = getQuantizer(index);

    // Train codebooks
    const vecs: number[][] = [];
    for (let i = 0; i < 256; i++) vecs.push(Array.from(makeVec(C1, 0.1, i)));
    q.codebooks = q.trainProductQuantizer(vecs, NUM_SUB, 256);
    q.pqTrained = true;

    const v = makeVec(C1, 0.01, 42);
    const enc = q.encode(v);
    const indices = new Uint8Array(enc);

    const dist = q.productQuantizeDistance(indices, indices);
    expect(dist).toBe(0);
  });

  // -------------------------------------------------------------------------
  // 4. PQ distance between different vectors is > 0
  // -------------------------------------------------------------------------
  it('PQ distance between different encoded vectors is > 0', () => {
    const index = createPQIndex();
    const q = getQuantizer(index);

    const vecs: number[][] = [];
    for (let i = 0; i < 256; i++) {
      vecs.push(Array.from(makeVec(i < 128 ? C1 : C2, 0.05, i)));
    }
    q.codebooks = q.trainProductQuantizer(vecs, NUM_SUB, 256);
    q.pqTrained = true;

    const enc1 = new Uint8Array(q.encode(makeVec(C1, 0.001, 0)));
    const enc2 = new Uint8Array(q.encode(makeVec(C2, 0.001, 1)));

    const dist = q.productQuantizeDistance(enc1, enc2);
    expect(dist).toBeGreaterThan(0);
  });

  // -------------------------------------------------------------------------
  // 5. Compression ratio: 384-dim float32 -> 8 bytes with 8 sub-quantizers
  // -------------------------------------------------------------------------
  it('compression ratio is correct (384-dim f32 -> 8 sub-quantizers)', () => {
    const index = createPQIndex();
    const stats = index.getStats();
    // product quantization compression ratio = subquantizers count
    expect(stats.compressionRatio).toBe(NUM_SUB);
  });

  // -------------------------------------------------------------------------
  // 6. Training threshold: accumulates until 256, then trains
  // -------------------------------------------------------------------------
  it('training threshold works: not trained until 256 vectors', () => {
    const index = createPQIndex(600);
    const q = getQuantizer(index);

    // Feed 255 vectors — should NOT be trained yet
    for (let i = 0; i < 255; i++) {
      q.encode(makeVec(C1, 0.1, i));
    }
    expect(q.isPQTrained).toBe(false);
    expect(q.trainingVectors).toHaveLength(255);

    // Feed the 256th — should trigger training
    q.encode(makeVec(C2, 0.1, 256));
    expect(q.isPQTrained).toBe(true);
    expect(q.getCodebooks()).not.toBeNull();
    expect(q.getCodebooks()!).toHaveLength(NUM_SUB);
    // Training data freed after training
    expect(q.trainingVectors).toHaveLength(0);
  });

  // -------------------------------------------------------------------------
  // 7. Pre-training fallback: returns averaged sub-vectors before training
  // -------------------------------------------------------------------------
  it('pre-training fallback returns sub-vector means', () => {
    const index = createPQIndex();
    const q = getQuantizer(index);

    // A constant vector of 2.0 everywhere
    const constant = new Float32Array(DIM).fill(2.0);
    const result = q.encode(constant);

    // Before training, each element should be the mean of the sub-vector slice
    // For a constant 2.0 vector, every sub-vector mean is 2.0
    expect(result.length).toBe(NUM_SUB);
    for (let i = 0; i < result.length; i++) {
      expect(result[i]).toBeCloseTo(2.0, 5);
    }
  });
});

// Pretrain-from-history regression guard (ADR-077).
//
// We don't shell out to git or gh here — instead we drive the same code paths
// the script uses (distillAndSerialise → recordTrajectory + storeNeuralPatterns)
// with an embedded fixture. This keeps the test deterministic, offline, and
// fast. If the wiring regresses (#2245 again), this test fails.
//
// What we assert:
//   1. Every fixture item produces a distilled 4-field representation.
//   2. recordTrajectory bumps globalStats.{trajectoriesRecorded, patternsLearned}.
//   3. storeNeuralPatterns adds to the neural store and the count is readable
//      via getNeuralStoreStats().
//   4. getUnifiedLearningStats() returns a coherent view across all four stores.
//   5. learningPath signal — recordTrajectory returns success without throwing,
//      proving the trajectory pipeline (not just memory-bridge) ran.

import { describe, it, expect, beforeAll } from 'vitest';
import { distillAndSerialise } from '../src/memory/structured-distill.js';
import {
  recordTrajectory,
  getUnifiedLearningStats,
  flushIntelligenceStats,
} from '../src/memory/intelligence.js';
import {
  storeNeuralPatterns,
  getNeuralStoreStats,
  neuralTools,
} from '../src/mcp-tools/neural-tools.js';

// Fixture — a tiny mock "history" shaped like real ruflo commits + issues.
// Intentionally small so this stays fast. The shape (subject + body + verdict)
// matches what pretrain-from-github.mjs builds from git log + gh issue list.
const FIXTURE = [
  {
    source: 'commit', id: 'commit-aaa1', verdict: 'success' as const,
    subject: 'fix(intelligence): wire hooks_task-completed to recordTrajectory',
    body: 'Fixes #2245. The MCP tool now calls recordTrajectory() instead of just bumping a stub counter. Updated src/mcp-tools/hooks-tools.ts:142.',
  },
  {
    source: 'commit', id: 'commit-aaa2', verdict: 'success' as const,
    subject: 'feat(memory): unified learning-stats aggregator (ADR-075)',
    body: 'Adds getUnifiedLearningStats() in src/memory/intelligence.ts that returns a coherent view across all 4 stores with a consistency block.',
  },
  {
    source: 'commit', id: 'commit-aaa3', verdict: 'success' as const,
    subject: 'feat(intelligence): structured distillation (ADR-076)',
    body: '4-field schema: summary, detail, labels, paths. Per arXiv:2603.13017. Serialiser leads with labels.',
  },
  {
    source: 'issue', id: 'issue-2245', verdict: 'success' as const,
    subject: 'Self-learning reports success but persists nothing',
    body: 'signalsProcessed never moves. hooks_task-completed returns success but downstream counters stay at zero.',
  },
  {
    source: 'issue', id: 'issue-2241', verdict: 'partial' as const,
    subject: 'Dream Cycle 2026-05-30 performance scan',
    body: 'MV-HNSW 14x gap. LAMaS 38-46% latency. Security and hive-mind scans incoming.',
  },
];

describe('pretrain-from-github wiring guard (#2245 regression)', () => {
  let before: Awaited<ReturnType<typeof getUnifiedLearningStats>>;
  let afterStats: Awaited<ReturnType<typeof getUnifiedLearningStats>>;
  let neuralBefore: Awaited<ReturnType<typeof getNeuralStoreStats>>;
  let neuralAfter: Awaited<ReturnType<typeof getNeuralStoreStats>>;
  let trainedCount = 0;

  beforeAll(async () => {
    before = await getUnifiedLearningStats();
    neuralBefore = await getNeuralStoreStats();

    for (const item of FIXTURE) {
      const distilled = distillAndSerialise(`${item.subject}\n\n${item.body}`);
      // Distillation must be non-empty for every item.
      expect(distilled.length).toBeGreaterThan(10);

      await recordTrajectory(
        [{
          type: 'result',
          content: distilled,
          metadata: { source: item.source, id: item.id, subject: item.subject.slice(0, 200) },
          timestamp: Date.now(),
        }],
        item.verdict,
      );
      trainedCount++;
    }

    await storeNeuralPatterns(
      FIXTURE.map((item) => ({
        name: item.subject.slice(0, 200),
        type: item.source === 'commit' ? 'history-commit' : 'history-issue',
        content: distillAndSerialise(`${item.subject}\n\n${item.body}`),
        metadata: { source: item.source, id: item.id, verdict: item.verdict },
      })),
    );

    flushIntelligenceStats();
    afterStats = await getUnifiedLearningStats();
    neuralAfter = await getNeuralStoreStats();
  });

  it('feeds every fixture item through recordTrajectory without errors', () => {
    expect(trainedCount).toBe(FIXTURE.length);
  });

  it('bumps globalStats.trajectoriesRecorded by at least the fixture size', () => {
    expect(afterStats.global.trajectoriesRecorded - before.global.trajectoriesRecorded)
      .toBeGreaterThanOrEqual(FIXTURE.length);
  });

  it('bumps globalStats.patternsLearned (Round B/C wiring still alive)', () => {
    expect(afterStats.global.patternsLearned - before.global.patternsLearned)
      .toBeGreaterThan(0);
  });

  it('populates the neural store (closes #2245 "neural_patterns stays empty" gap)', () => {
    expect(neuralAfter.patternCount - neuralBefore.patternCount)
      .toBeGreaterThanOrEqual(FIXTURE.length);
  });

  it('getUnifiedLearningStats returns the 4 documented sub-views', () => {
    expect(afterStats.global).toBeDefined();
    expect(afterStats.sona).toBeDefined();
    expect(afterStats.memoryBridge).toBeDefined();
    expect(afterStats.neuralPatterns).toBeDefined();
    expect(afterStats.consistency).toBeDefined();
    expect(Array.isArray(afterStats.consistency.notes)).toBe(true);
  });

  it('distillation captures issue/commit identifiers in the embedded form', () => {
    // The fixture intentionally includes recognisable tokens. The distilled
    // form should preserve them so downstream retrieval can match.
    const item = FIXTURE[3]; // issue-2245
    const distilled = distillAndSerialise(`${item.subject}\n\n${item.body}`);
    expect(distilled).toMatch(/2245|self-learning|persists/i);
  });

  // ADR-078 — hybrid retrieval should be at least as discriminative as cosine
  // alone on an exact-keyword query. We don't require a strict inequality
  // because on a 5-item fixture both modes can return the same top-1.
  it('hybrid search returns a non-empty result and respects mode parameter', async () => {
    const tool = neuralTools.find((t) => t.name === 'neural_patterns');
    expect(tool).toBeDefined();

    const hybrid = await tool!.handler({
      action: 'search',
      query: 'structured distillation 4-field schema',
      mode: 'hybrid',
      limit: 3,
    });
    expect(hybrid.mode).toBe('hybrid');
    expect(Array.isArray(hybrid.results)).toBe(true);
    expect(hybrid.results.length).toBeGreaterThan(0);
    // Top-1 of a query targeting commit-aaa3 (Structured Distillation, ADR-076)
    // should mention either 'structured', 'distillation', or 'ADR-076'.
    const top1Name = String(hybrid.results[0].name).toLowerCase();
    expect(top1Name).toMatch(/structured|distillation|adr-076|076/);
    // Hybrid path returns the extra ADR-078 fields.
    expect(hybrid.results[0]).toHaveProperty('hybridScore');
    expect(hybrid.results[0]).toHaveProperty('cosineScore');
    expect(hybrid.results[0]).toHaveProperty('bm25Score');

    const cosine = await tool!.handler({
      action: 'search',
      query: 'structured distillation 4-field schema',
      mode: 'cosine',
      limit: 3,
    });
    expect(cosine.mode).toBe('cosine');
    expect(Array.isArray(cosine.results)).toBe(true);
    // Cosine path does NOT include the hybrid breakdown.
    expect(cosine.results[0]).not.toHaveProperty('hybridScore');
  });
});

// Regression tests for #2239 — Q-state encoder discarded the keyword block.
//
// The previous 31-bit truncating fold collapsed four routing-keyword-distinct
// tasks (`test/review/architect/optimize the new module now`) to ONE Q-state.
// After the FNV-1a fold and encoder-version=2 migration, keyword-distinct
// tasks must produce distinct state keys, and a persisted v1 model must
// reset its Q-table on load (keys are not comparable across encoder versions).

import { describe, it, expect } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { QLearningRouter } from '../src/ruvector/q-learning-router.js';

const r = new QLearningRouter();
const stateKey = (s: string) => r.getStateKey(s);

describe('Q-state encoder (#2239)', () => {
  it('produces distinct state keys for the reporter\'s six keyword-distinct tasks', () => {
    const tasks = [
      'implement the new module now',
      'test the new module now',
      'review the new module now',
      'architect the new module now',
      'research the new module now',
      'optimize the new module now',
    ];
    const keys = tasks.map(stateKey);
    expect(new Set(keys).size).toBe(tasks.length); // no collapse to one Q-state
  });

  it('still produces the SAME key for the SAME input (deterministic)', () => {
    expect(stateKey('test this module')).toBe(stateKey('test this module'));
  });

  it('produces a `fstate_…` shape', () => {
    expect(stateKey('refactor the API')).toMatch(/^fstate_[0-9a-z]+$/);
  });
});

describe('encoder-version migration (#2239)', () => {
  it('resets the Q-table on encoder-version mismatch (v1 persisted → v2 current)', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'q-mig-'));
    const modelPath = join(dir, 'q-learning-model.json');
    // A v1 persisted model with one fake state — v1 keys are not portable.
    writeFileSync(modelPath, JSON.stringify({
      version: '1.0.0',
      // encoderVersion missing → treated as 1
      config: { numActions: 8 },
      qTable: { 'fstate_legacy': { qValues: [99, 99, 99, 99, 99, 99, 99, 99], visits: 50 } },
      stats: { stepCount: 100, updateCount: 50, avgTDError: 0.1, epsilon: 0.5 },
      metadata: { savedAt: new Date(0).toISOString(), totalExperiences: 100 },
    }));

    const router = new QLearningRouter({ modelPath });
    const loaded = await router.loadModel(modelPath);
    expect(loaded).toBe(true);

    // The legacy state must NOT survive (its key was computed by the old fold).
    const exported = router.export();
    expect(Object.keys(exported)).not.toContain('fstate_legacy');

    rmSync(dir, { recursive: true, force: true });
  });

  it('a v2 persisted model loads its Q-table intact', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'q-v2-'));
    const modelPath = join(dir, 'q-learning-model.json');
    // Compute a real v2 key from the live encoder.
    const seed = new QLearningRouter();
    const realKey = seed.getStateKey('keep this entry across restart');

    writeFileSync(modelPath, JSON.stringify({
      version: '1.0.0',
      encoderVersion: 2,
      config: { numActions: 8 },
      qTable: { [realKey]: { qValues: [1, 2, 3, 4, 5, 6, 7, 8], visits: 7 } },
      stats: { stepCount: 0, updateCount: 0, avgTDError: 0, epsilon: 0.5 },
      metadata: { savedAt: new Date().toISOString(), totalExperiences: 0 },
    }));

    const router = new QLearningRouter({ modelPath });
    expect(await router.loadModel(modelPath)).toBe(true);
    expect(Object.keys(router.export())).toContain(realKey);

    rmSync(dir, { recursive: true, force: true });
  });
});

