      expect(analysis).toBeDefined();
    });

    it('should handle Unicode identifiers', () => {
      const analysis = analyzer.analyze('function \u00e9valuate() { return true; }', 'unicode.ts');
      expect(analysis.functions.length).toBeGreaterThanOrEqual(0);
    });
  });
});

