@@ -1,5 +0,0 @@
-export function deleted() {
-  return 'gone';
-}
-
-export const constant = 'value';
`;
      const files = classifier.parseDiff(diff);
      expect(files.length).toBe(1);
      expect(files[0].deletions).toBeGreaterThan(0);
