#!/usr/bin/env node
/**
 * @claude-flow/cli - CLI Entry Point
 *
 * Claude Flow V3 Command Line Interface
 *
 * Auto-detects MCP mode when stdin is piped and no args provided.
 * This allows: echo '{"jsonrpc":"2.0",...}' | npx @claude-flow/cli
 */

import { randomUUID } from 'crypto';
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

// #2253 / #2256: Console filter installed BEFORE any other import. Two jobs:
//
// 1. Suppress the cosmetic "[AgentDB Patch] Controller index not found"
//    warning from agentic-flow (it expects agentdb v1.x but we use v3).
//    Tight match — must include BOTH the prefix AND the specific text;
//    other [AgentDB Patch] messages flow through. Audit log
//    audit_1776483149979 flagged a broader filter as too aggressive.
//
// 2. Redirect noisy stdout writes from upstream embedder libraries
//    (ruvector ONNX loader, ruvector-onnx-embeddings-wasm parallel
//    embedder) to stderr. Those libraries use console.log for progress
//    messages — "Loading model:", "  Downloading: …", "🚀 Initializing N
//    workers" — which corrupts MCP JSON-RPC stdio (#2253) and is noise
//    on stdout. stderr is the right channel for progress to a TTY user,
//    and the MCP stdio framer reads stdout only.
//
// This MUST be installed before `import('../dist/src/index.js')` so the
// patch is in place before agentic-flow / ruvector load transitively.
const _origWarn = console.warn;
const _origLog = console.log;
const _origError = console.error;
const _isCosmeticAgentdbPatchNoise = (msg) =>
  msg.includes('[AgentDB Patch]') && msg.includes('Controller index not found');
const _STDERR_REDIRECT_PREFIXES = [
  'Loading model: ',
  '  Downloading: ',
  '  Cache hit: ',
  '  Disk cache hit: ',
  'Model cache cleared',
  '🚀 Initializing ',
  '✅ ',
];
// agentdb's EmbeddingService.initialize() prints this cluster when
// `@xenova/transformers` fails to load (commonly: macOS arm64 without
// `brew install vips` — sharp can't resolve libvips). The warnings claim
// agentdb is "falling back to mock embeddings", but memory-bridge.ts's
// rescueAgentdbEmbedder swaps the embedder over to ruvector ONNX in
// that exact case, so the user is NOT on mocks. The warnings are stale
// and misleading; drop them. Match anchored to exact upstream prefixes
// (agentdb/dist/controllers/EmbeddingService.js:48–56) so unrelated
// warnings always flow through.
const _AGENTDB_MOCK_FALLBACK_DROP_PREFIXES = [
  'Transformers.js initialization failed:',
  '   Falling back to mock embeddings for testing',
  '   This is normal if:',
  '     - Running offline/without internet access',
  '     - Model not yet downloaded',
  '     - Network connectivity issues',
  '   To use real embeddings:',
  '     - Ensure internet connectivity for first',
  '     - Or pre-download: npx agentdb',
];
const _shouldRedirectToStderr = (msg) => {
  for (const prefix of _STDERR_REDIRECT_PREFIXES) {
    if (msg.startsWith(prefix)) return true;
  }
  return false;
};
const _isAgentdbMockFallbackNoise = (msg) => {
  for (const prefix of _AGENTDB_MOCK_FALLBACK_DROP_PREFIXES) {
    if (msg.startsWith(prefix)) return true;
  }
  return false;
};
console.warn = (...args) => {
  const head = String(args[0] ?? '');
  if (_isCosmeticAgentdbPatchNoise(head)) return;
  if (_isAgentdbMockFallbackNoise(head)) return;
  _origWarn.apply(console, args);
};
console.log = (...args) => {
  const head = String(args[0] ?? '');
  if (_isCosmeticAgentdbPatchNoise(head)) return;
  if (_shouldRedirectToStderr(head)) {
    _origError.apply(console, args);
    return;
  }
  _origLog.apply(console, args);
};

// #2256 fast path: --version / -V / --help / -h must NOT trigger heavy
// imports (agentic-flow, ruvector ONNX, etc.) — those eagerly download a
// 23 MB ONNX model on cold cache, blocking 60+ s and causing SIGTERM
// under common timeout windows (npx default, MCP stdio 30 s). Resolve
// version directly from package.json and exit before any heavy import.
{
  const _argv = process.argv.slice(2);
  if (_argv.length === 1 && (_argv[0] === '--version' || _argv[0] === '-V')) {
    try {
      const __dirname = dirname(fileURLToPath(import.meta.url));
      const pkg = JSON.parse(readFileSync(join(__dirname, '..', 'package.json'), 'utf-8'));
      process.stdout.write(`ruflo v${pkg.version || '0.0.0'}\n`);
    } catch {
      process.stdout.write('ruflo v0.0.0\n');
    }
    process.exit(0);
  }
  // --help / -h with no other args also stays lightweight — fall through
  // to the existing fast help path inside index.ts; we don't short-circuit
  // here because some users pass `<command> --help` which needs lazy command
  // loading. The version short-circuit is the only one safe to inline.
}

// Check if we should run in MCP server mode
// Conditions:
//   1. stdin is being piped AND no CLI arguments provided (auto-detect)
//   2. stdin is being piped AND args are "mcp start" (explicit, e.g. npx claude-flow@alpha mcp start)
//   3. EXCEPT — if the user explicitly passed --transport <non-stdio>
//      (e.g. -t http), defer to the parser. Without this, every smoke
//      test or non-TTY caller of `mcp start -t http` got force-routed
//      into stdio mode and never hit the HTTP server (#1874 follow-up).
const cliArgs = process.argv.slice(2);
const isExplicitMCP = cliArgs.length >= 1 && cliArgs[0] === 'mcp' && (cliArgs.length === 1 || cliArgs[1] === 'start');
const explicitNonStdioTransport = cliArgs.some((a, i) => {
  // -t <value> | --transport <value>
  if ((a === '-t' || a === '--transport') && cliArgs[i + 1] && cliArgs[i + 1] !== 'stdio') return true;
  // --transport=<value>
  if (/^--transport=/.test(a) && !/^--transport=stdio$/.test(a)) return true;
  return false;
});
const isMCPMode = !process.stdin.isTTY
  && !explicitNonStdioTransport
  && (process.argv.length === 2 || isExplicitMCP);

if (isMCPMode) {
  // Run MCP server mode
  const { listMCPTools, callMCPTool, hasTool } = await import('../dist/src/mcp-client.js');

  const VERSION = '3.0.0';
  const sessionId = `mcp-${Date.now()}-${randomUUID().slice(0, 8)}`;

  console.error(
    `[${new Date().toISOString()}] INFO [claude-flow-mcp] (${sessionId}) Starting in stdio mode`
  );

  // Audit-flagged DoS protection (audit_1776483149979): cap the
  // newline-buffered stdin parser so a malicious client cannot pipe
  // gigabytes of un-newlined data and exhaust memory before
  // JSON.parse runs. 10MB is far above any legitimate MCP message
  // (the protocol's largest realistic payloads — tool descriptions,
  // batch search results — top out at ~1MB).
  const MCP_MAX_BUFFER_BYTES = 10 * 1024 * 1024;
  let buffer = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', async (chunk) => {
    buffer += chunk;
    if (buffer.length > MCP_MAX_BUFFER_BYTES) {
      // Drop the buffer + emit a protocol-level error so the client
      // sees the rejection rather than a silent OOM.
      console.log(JSON.stringify({
        jsonrpc: '2.0',
        id: null,
        error: {
          code: -32700,
          message: `Buffered stdin exceeds ${MCP_MAX_BUFFER_BYTES} bytes without newline; resetting`,
        },
      }));
      buffer = '';
      return;
    }
    let lines = buffer.split('\n');
    buffer = lines.pop() || '';

    for (const line of lines) {
      if (line.trim()) {
        let message;
        try {
          message = JSON.parse(line);
        } catch {
          console.log(JSON.stringify({
            jsonrpc: '2.0',
            id: null,
            error: { code: -32700, message: 'Parse error' },
          }));
          continue;
        }
        try {
          const response = await handleMessage(message);
          if (response) {
            console.log(JSON.stringify(response));
          }
        } catch (error) {
          // #1606: Return proper internal error instead of parse error
          console.log(JSON.stringify({
            jsonrpc: '2.0',
            id: message.id ?? null,
            error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
          }));
        }
      }
    }
  });

  process.stdin.on('end', () => {
    process.exit(0);
  });

  async function handleMessage(message) {
    if (!message.method) {
      return {
        jsonrpc: '2.0',
        id: message.id,
        error: { code: -32600, message: 'Invalid Request: missing method' },
      };
    }

    const params = message.params || {};

    switch (message.method) {
      case 'initialize':
        return {
          jsonrpc: '2.0',
          id: message.id,
          result: {
            protocolVersion: '2024-11-05',
            serverInfo: { name: 'ruflo', version: VERSION },
            capabilities: {
              tools: { listChanged: true },
              resources: { subscribe: true, listChanged: true },
            },
          },
        };

      case 'tools/list': {
        const tools = listMCPTools();
        return {
          jsonrpc: '2.0',
          id: message.id,
          result: {
            tools: tools.map(tool => ({
              name: tool.name,
              description: tool.description,
              inputSchema: tool.inputSchema,
            })),
          },
        };
      }

      case 'tools/call': {
        const toolName = params.name;
        const toolParams = params.arguments || {};

        if (!hasTool(toolName)) {
          return {
            jsonrpc: '2.0',
            id: message.id,
            error: { code: -32601, message: `Tool not found: ${toolName}` },
          };
        }

        try {
          const result = await callMCPTool(toolName, toolParams, { sessionId });
          return {
            jsonrpc: '2.0',
            id: message.id,
            result: { content: [{ type: 'text', text: JSON.stringify(result, null, 2) }] },
          };
        } catch (error) {
          return {
            jsonrpc: '2.0',
            id: message.id,
            error: {
              code: -32603,
              message: error instanceof Error ? error.message : 'Tool execution failed',
            },
          };
        }
      }

      case 'notifications/initialized':
        return null;

      case 'ping':
        return { jsonrpc: '2.0', id: message.id, result: {} };

      default:
        return {
          jsonrpc: '2.0',
          id: message.id,
          error: { code: -32601, message: `Method not found: ${message.method}` },
        };
    }
  }
} else {
  // Run normal CLI mode
  const { CLI } = await import('../dist/src/index.js');
  const cli = new CLI();
  cli.run()
    .then(() => {
      // #1552: Exit cleanly after one-shot commands.
      // Long-running commands (daemon foreground, mcp, status --watch) never resolve,
      // so this only fires for normal CLI commands.
      process.exit(0);
    })
    .catch((error) => {
      console.error('Fatal error:', error.message);
      process.exit(1);
    });
}

#!/usr/bin/env node
/**
 * @claude-flow/cli - MCP Server Entry Point
 *
 * Direct stdio MCP server for Claude Code integration.
 * This entry point handles stdin/stdout directly for MCP protocol
 * without any CLI formatting output that would corrupt the protocol.
 */

import { randomUUID } from 'crypto';

// Suppress the SPECIFIC cosmetic "[AgentDB Patch] Controller index not found"
// noise. Tight match (both prefix AND "Controller index not found") so other
// [AgentDB Patch] warnings about real issues still flow through. Also patch
// console.log because the underlying call site uses it. See bin/cli.js for
// the same rationale.
const _origWarn = console.warn;
const _origLog = console.log;
const _isCosmeticAgentdbPatchNoise = (msg) =>
  msg.includes('[AgentDB Patch]') && msg.includes('Controller index not found');
console.warn = (...args) => {
  if (_isCosmeticAgentdbPatchNoise(String(args[0] ?? ''))) return;
  _origWarn.apply(console, args);
};
console.log = (...args) => {
  if (_isCosmeticAgentdbPatchNoise(String(args[0] ?? ''))) return;
  _origLog.apply(console, args);
};

import { listMCPTools, callMCPTool, hasTool } from '../dist/src/mcp-client.js';

const VERSION = '3.0.0';
const sessionId = `mcp-${Date.now()}-${randomUUID().slice(0, 8)}`;

// Log to stderr (doesn't corrupt stdout for MCP protocol)
console.error(
  `[${new Date().toISOString()}] INFO [claude-flow-mcp] (${sessionId}) Starting in stdio mode`
);
console.error(JSON.stringify({
  arch: process.arch,
  mode: 'mcp-stdio',
  nodeVersion: process.version,
  pid: process.pid,
  platform: process.platform,
  protocol: 'stdio',
  sessionId,
  version: VERSION,
}));

// Handle stdin messages
// Audit-flagged DoS protection (audit_1776483149979): cap stdin buffer
// to 10MB. See bin/cli.js for the same protection on the auto-detect path.
const MCP_MAX_BUFFER_BYTES = 10 * 1024 * 1024;
let buffer = '';

process.stdin.setEncoding('utf8');
process.stdin.on('data', async (chunk) => {
  buffer += chunk;

  if (buffer.length > MCP_MAX_BUFFER_BYTES) {
    console.log(JSON.stringify({
      jsonrpc: '2.0',
      id: null,
      error: {
        code: -32700,
        message: `Buffered stdin exceeds ${MCP_MAX_BUFFER_BYTES} bytes without newline; resetting`,
      },
    }));
    buffer = '';
    return;
  }

  // Process complete JSON messages (newline-delimited)
  let lines = buffer.split('\n');
  buffer = lines.pop() || ''; // Keep incomplete line in buffer

  for (const line of lines) {
    if (line.trim()) {
      try {
        const message = JSON.parse(line);
        const response = await handleMessage(message);
        if (response) {
          console.log(JSON.stringify(response));
        }
      } catch (error) {
        console.error(
          `[${new Date().toISOString()}] ERROR [claude-flow-mcp] Failed to parse:`,
          error instanceof Error ? error.message : String(error)
        );
        // Send parse error response
        console.log(JSON.stringify({
          jsonrpc: '2.0',
          id: null,
          error: { code: -32700, message: 'Parse error' },
        }));
      }
    }
  }
});

process.stdin.on('end', () => {
  console.error(
    `[${new Date().toISOString()}] INFO [claude-flow-mcp] (${sessionId}) stdin closed, shutting down...`
  );
  process.exit(0);
});

// Handle process termination
process.on('SIGINT', () => {
  console.error(`[${new Date().toISOString()}] INFO [claude-flow-mcp] Received SIGINT`);
  process.exit(0);
});

process.on('SIGTERM', () => {
  console.error(`[${new Date().toISOString()}] INFO [claude-flow-mcp] Received SIGTERM`);
  process.exit(0);
});

/**
 * Handle MCP message
 */
async function handleMessage(message) {
  if (!message.method) {
    return {
      jsonrpc: '2.0',
      id: message.id,
      error: { code: -32600, message: 'Invalid Request: missing method' },
    };
  }

  const params = message.params || {};

  try {
    switch (message.method) {
      case 'initialize':
        return {
          jsonrpc: '2.0',
          id: message.id,
          result: {
            protocolVersion: '2024-11-05',
            serverInfo: { name: 'ruflo', version: VERSION },
            capabilities: {
              tools: { listChanged: true },
              resources: { subscribe: true, listChanged: true },
            },
          },
        };

      case 'tools/list': {
        const tools = listMCPTools();
        return {
          jsonrpc: '2.0',
          id: message.id,
          result: {
            tools: tools.map(tool => ({
              name: tool.name,
              description: tool.description,
              inputSchema: tool.inputSchema,
            })),
          },
        };
      }

      case 'tools/call': {
        const toolName = params.name;
        const toolParams = params.arguments || {};

        if (!hasTool(toolName)) {
          return {
            jsonrpc: '2.0',
            id: message.id,
            error: { code: -32601, message: `Tool not found: ${toolName}` },
          };
        }

        try {
          const result = await callMCPTool(toolName, toolParams, { sessionId });
          return {
            jsonrpc: '2.0',
            id: message.id,
            result: { content: [{ type: 'text', text: JSON.stringify(result, null, 2) }] },
          };
        } catch (error) {
          return {
            jsonrpc: '2.0',
            id: message.id,
            error: {
              code: -32603,
              message: error instanceof Error ? error.message : 'Tool execution failed',
            },
          };
        }
      }

      case 'notifications/initialized':
        console.error(`[${new Date().toISOString()}] INFO [claude-flow-mcp] Client initialized`);
        return null; // No response for notifications

      case 'ping':
        return {
          jsonrpc: '2.0',
          id: message.id,
          result: {},
        };

      default:
        return {
          jsonrpc: '2.0',
          id: message.id,
          error: { code: -32601, message: `Method not found: ${message.method}` },
        };
    }
  } catch (error) {
    console.error(`[${new Date().toISOString()}] ERROR [claude-flow-mcp] ${message.method}:`, error);
    return {
      jsonrpc: '2.0',
      id: message.id,
      error: {
        code: -32603,
        message: error instanceof Error ? error.message : 'Internal error',
      },
    };
  }
}

/**
 * Claude Flow Plugin Registry Cloud Function
 *
 * Secure IPFS publishing with:
 * - Ed25519 signature verification
 * - Model import/export tracking
 * - Plugin sharing analytics
 * - Download tracking
 *
 * Deploy:
 *   gcloud functions deploy publish-registry \
 *     --gen2 --runtime=nodejs20 --region=us-central1 \
 *     --trigger-http --allow-unauthenticated \
 *     --service-account=plugin-registry-publisher@claude-flow.iam.gserviceaccount.com
 */

import { SecretManagerServiceClient } from '@google-cloud/secret-manager';
import { Storage } from '@google-cloud/storage';
import * as ed from '@noble/ed25519';

const secretManager = new SecretManagerServiceClient();
const storage = new Storage();

const PROJECT_ID = process.env.GCP_PROJECT || 'claude-flow';
const BUCKET_NAME = 'claude-flow-plugin-registry';
const PINATA_API_URL = 'https://api.pinata.cloud';

/**
 * Get secret from Secret Manager
 */
async function getSecret(name) {
  const [version] = await secretManager.accessSecretVersion({
    name: `projects/${PROJECT_ID}/secrets/${name}/versions/latest`,
  });
  return version.payload.data.toString();
}

/**
 * Sign registry with Ed25519
 */
async function signRegistry(registry, privateKeyHex) {
  const privateKey = Buffer.from(privateKeyHex, 'hex');
  const publicKey = await ed.getPublicKeyAsync(privateKey);

  // Create copy without signature fields
  const registryToSign = { ...registry };
  delete registryToSign.registrySignature;
  delete registryToSign.registryPublicKey;

  const message = JSON.stringify(registryToSign);
  const signature = await ed.signAsync(
    new TextEncoder().encode(message),
    privateKey
  );

  return {
    signature: Buffer.from(signature).toString('hex'),
    publicKey: `ed25519:${Buffer.from(publicKey).toString('hex')}`,
  };
}

/**
 * Pin JSON to IPFS via Pinata
 */
async function pinToIPFS(data, name, jwt) {
  const response = await fetch(`${PINATA_API_URL}/pinning/pinJSONToIPFS`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${jwt}`,
    },
    body: JSON.stringify({
      pinataContent: data,
      pinataMetadata: {
        name,
        keyvalues: {
          type: 'plugin-registry',
          publishedAt: new Date().toISOString(),
          version: data.version || '1.0.0',
        },
      },
      pinataOptions: {
        cidVersion: 1,
      },
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Pinata error: ${response.status} - ${error}`);
  }

  return response.json();
}

/**
 * Fetch npm stats for packages
 */
async function fetchNpmStats(packageName) {
  try {
    const [downloadsRes, packageRes] = await Promise.all([
      fetch(`https://api.npmjs.org/downloads/point/last-week/${encodeURIComponent(packageName)}`, {
        signal: AbortSignal.timeout(5000),
      }),
      fetch(`https://registry.npmjs.org/${encodeURIComponent(packageName)}/latest`, {
        signal: AbortSignal.timeout(5000),
      }),
    ]);

    const downloads = downloadsRes.ok ? (await downloadsRes.json()).downloads || 0 : 0;
    const version = packageRes.ok ? (await packageRes.json()).version || 'unknown' : 'unknown';

    return { downloads, version };
  } catch {
    return { downloads: 0, version: 'unknown' };
  }
}

/**
 * Track plugin download/share event
 */
async function trackEvent(bucket, eventType, pluginId, metadata = {}) {
  const file = bucket.file(`analytics/${eventType}/${new Date().toISOString().split('T')[0]}.jsonl`);
  const event = JSON.stringify({
    timestamp: new Date().toISOString(),
    eventType,
    pluginId,
    ...metadata,
  }) + '\n';

  try {
    await file.save(event, { resumable: false });
  } catch {
    // Append to existing file
    const [exists] = await file.exists();
    if (exists) {
      const [content] = await file.download();
      await file.save(content.toString() + event);
    }
  }
}

/**
 * Export model/pattern to IPFS
 */
async function exportModel(modelData, jwt) {
  const result = await pinToIPFS(modelData, `claude-flow-model-${Date.now()}`, jwt);
  return {
    cid: result.IpfsHash,
    size: result.PinSize,
    gateways: [
      `https://gateway.pinata.cloud/ipfs/${result.IpfsHash}`,
      `https://ipfs.io/ipfs/${result.IpfsHash}`,
    ],
  };
}

/**
 * Import model from IPFS CID
 */
async function importModel(cid) {
  const gateways = [
    'https://gateway.pinata.cloud',
    'https://ipfs.io',
    'https://dweb.link',
  ];

  for (const gateway of gateways) {
    try {
      const response = await fetch(`${gateway}/ipfs/${cid}`, {
        signal: AbortSignal.timeout(30000),
        headers: { 'Accept': 'application/json' },
      });

      if (response.ok) {
        return {
          success: true,
          data: await response.json(),
          gateway,
        };
      }
    } catch {
      continue;
    }
  }

  return { success: false, error: 'Model not found on any gateway' };
}

/**
 * Main Cloud Function handler
 */
export async function publishRegistry(req, res) {
  // CORS headers
  res.set('Access-Control-Allow-Origin', '*');
  res.set('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.set('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.status(204).send('');
  }

  try {
    const { action = 'publish' } = req.query;
    const bucket = storage.bucket(BUCKET_NAME);

    switch (action) {
      case 'publish': {
        // Get secrets
        const [pinataJwt, privateKey] = await Promise.all([
          getSecret('pinata-jwt'),
          getSecret('registry-private-key'),
        ]);

        // Fetch registry from GCS
        const file = bucket.file('registry.json');
        const [content] = await file.download();
        const registry = JSON.parse(content.toString());

        // Update timestamps and fetch live npm stats
        registry.updatedAt = new Date().toISOString();

        // Fetch live stats for each plugin
        for (const plugin of registry.plugins) {
          const stats = await fetchNpmStats(plugin.id);
          plugin.downloads = stats.downloads;
          plugin.version = stats.version !== 'unknown' ? stats.version : plugin.version;
        }

        registry.totalDownloads = registry.plugins.reduce((sum, p) => sum + p.downloads, 0);

        // Sign registry
        const { signature, publicKey } = await signRegistry(registry, privateKey);
        registry.registrySignature = signature;
        registry.registryPublicKey = publicKey;

        // Pin to IPFS
        const pinResult = await pinToIPFS(registry, 'claude-flow-plugin-registry', pinataJwt);

        // Save latest CID to GCS
        await bucket.file('latest-cid.txt').save(pinResult.IpfsHash);

        // Track publish event
        await trackEvent(bucket, 'publish', 'registry', {
          cid: pinResult.IpfsHash,
          pluginCount: registry.plugins.length,
        });

        return res.json({
          success: true,
          cid: pinResult.IpfsHash,
          updatedAt: registry.updatedAt,
          pluginCount: registry.plugins.length,
          totalDownloads: registry.totalDownloads,
          gateways: [
            `https://gateway.pinata.cloud/ipfs/${pinResult.IpfsHash}`,
            `https://ipfs.io/ipfs/${pinResult.IpfsHash}`,
            `https://dweb.link/ipfs/${pinResult.IpfsHash}`,
          ],
          publicKey,
        });
      }

      case 'export-model': {
        const pinataJwt = await getSecret('pinata-jwt');
        const modelData = req.body;

        if (!modelData) {
          return res.status(400).json({ error: 'Model data required' });
        }

        const result = await exportModel(modelData, pinataJwt);
        await trackEvent(bucket, 'model-export', modelData.id || 'unknown');

        return res.json({
          success: true,
          ...result,
        });
      }

      case 'import-model': {
        const { cid } = req.query;

        if (!cid) {
          return res.status(400).json({ error: 'CID required' });
        }

        const result = await importModel(cid);
        await trackEvent(bucket, 'model-import', cid);

        return res.json(result);
      }

      case 'track-download': {
        const { pluginId } = req.body || req.query;

        if (!pluginId) {
          return res.status(400).json({ error: 'Plugin ID required' });
        }

        await trackEvent(bucket, 'download', pluginId);
        return res.json({ success: true });
      }

      case 'analytics': {
        const { period = '7d' } = req.query;

        // Read analytics files
        const [files] = await bucket.getFiles({ prefix: 'analytics/' });
        const analytics = {
          downloads: {},
          exports: 0,
          imports: 0,
          publishes: 0,
        };

        for (const file of files.slice(-7)) { // Last 7 files
          try {
            const [content] = await file.download();
            const lines = content.toString().split('\n').filter(Boolean);
            for (const line of lines) {
              const event = JSON.parse(line);
              if (event.eventType === 'download') {
                analytics.downloads[event.pluginId] = (analytics.downloads[event.pluginId] || 0) + 1;
              } else if (event.eventType === 'model-export') {
                analytics.exports++;
              } else if (event.eventType === 'model-import') {
                analytics.imports++;
              } else if (event.eventType === 'publish') {
                analytics.publishes++;
              }
            }
          } catch {
            continue;
          }
        }

        return res.json(analytics);
      }

      case 'status': {
        // Get latest CID
        try {
          const [content] = await bucket.file('latest-cid.txt').download();
          const cid = content.toString().trim();

          return res.json({
            healthy: true,
            latestCid: cid,
            gateways: [
              `https://gateway.pinata.cloud/ipfs/${cid}`,
              `https://ipfs.io/ipfs/${cid}`,
            ],
          });
        } catch {
          return res.json({
            healthy: false,
            error: 'No registry published yet',
          });
        }
      }

      case 'rate': {
        // Rate a plugin or model (stored in GCS, no SQL)
        const { itemId, itemType = 'plugin', rating, userId } = req.body || {};

        if (!itemId || !rating || rating < 1 || rating > 5) {
          return res.status(400).json({ error: 'itemId and rating (1-5) required' });
        }

        // Generate anonymous user ID if not provided
        const finalUserId = userId || `anon-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

        // Store rating in GCS (JSON file per item)
        const ratingsFile = bucket.file(`ratings/${itemType}/${itemId}.json`);
        let ratings = { ratings: [], average: 0, count: 0 };

        try {
          const [exists] = await ratingsFile.exists();
          if (exists) {
            const [content] = await ratingsFile.download();
            ratings = JSON.parse(content.toString());
          }
        } catch {
          // File doesn't exist, use defaults
        }

        // Check if user already rated (prevent duplicate ratings)
        const existingIndex = ratings.ratings.findIndex(r => r.userId === finalUserId);
        if (existingIndex >= 0) {
          // Update existing rating
          ratings.ratings[existingIndex] = {
            userId: finalUserId,
            rating: Number(rating),
            timestamp: new Date().toISOString(),
          };
        } else {
          // Add new rating
          ratings.ratings.push({
            userId: finalUserId,
            rating: Number(rating),
            timestamp: new Date().toISOString(),
          });
        }

        // Recalculate average
        ratings.count = ratings.ratings.length;
        ratings.average = ratings.ratings.reduce((sum, r) => sum + r.rating, 0) / ratings.count;

        // Save updated ratings
        await ratingsFile.save(JSON.stringify(ratings, null, 2), {
          contentType: 'application/json',
        });

        // Track rating event
        await trackEvent(bucket, 'rating', itemId, { rating, itemType });

        return res.json({
          success: true,
          itemId,
          average: Math.round(ratings.average * 10) / 10,
          count: ratings.count,
        });
      }

      case 'get-ratings': {
        // Get ratings for a plugin or model
        const { itemId, itemType = 'plugin' } = req.query;

        if (!itemId) {
          return res.status(400).json({ error: 'itemId required' });
        }

        const ratingsFile = bucket.file(`ratings/${itemType}/${itemId}.json`);

        try {
          const [exists] = await ratingsFile.exists();
          if (!exists) {
            return res.json({ itemId, average: 0, count: 0, ratings: [] });
          }

          const [content] = await ratingsFile.download();
          const ratings = JSON.parse(content.toString());

          return res.json({
            itemId,
            average: Math.round(ratings.average * 10) / 10,
            count: ratings.count,
            // Don't expose individual user ratings
          });
        } catch {
          return res.json({ itemId, average: 0, count: 0 });
        }
      }

      case 'bulk-ratings': {
        // Get ratings for multiple items at once
        const { itemIds, itemType = 'plugin' } = req.body || req.query;

        if (!itemIds || !Array.isArray(itemIds)) {
          return res.status(400).json({ error: 'itemIds array required' });
        }

        const results = {};

        for (const itemId of itemIds.slice(0, 50)) { // Limit to 50 items
          try {
            const ratingsFile = bucket.file(`ratings/${itemType}/${itemId}.json`);
            const [exists] = await ratingsFile.exists();

            if (exists) {
              const [content] = await ratingsFile.download();
              const ratings = JSON.parse(content.toString());
              results[itemId] = {
                average: Math.round(ratings.average * 10) / 10,
                count: ratings.count,
              };
            } else {
              results[itemId] = { average: 0, count: 0 };
            }
          } catch {
            results[itemId] = { average: 0, count: 0 };
          }
        }

        return res.json(results);
      }

      default:
        return res.status(400).json({ error: `Unknown action: ${action}` });
    }
  } catch (error) {
    console.error('Function error:', error);
    return res.status(500).json({ error: error.message });
  }
}

