#!/usr/bin/env node
// benchmark-codemods.mjs — measured benchmark for deterministic Tier-1 codemods (ADR-143).
//
// Runs every case in bench/codemod-corpus.json through applyCodemod() and records:
//   - correctness vs the golden `expected` output
//   - latency (avg / p50 / p99 / max)
//   - cost: $0 measured (no API call) + estimated savings vs an LLM edit
//
// Writes a run JSON (tagged summary.benchmark="codemod-tier1") into the
// cost-tracker plugin's runs dir, which is exactly what `cost-trend` reads:
//   plugins/ruflo-cost-tracker/docs/benchmarks/runs/codemod-<timestamp>.json
// View the series with: BENCH_NAME=codemod-tier1 node scripts/trend.mjs
//
// Usage:
//   node scripts/benchmark-codemods.mjs            # build dist first (npm run build)
//   BENCH_JSON=1 node scripts/benchmark-codemods.mjs   # machine-readable JSON to stdout
//   BENCH_NO_WRITE=1 node scripts/benchmark-codemods.mjs  # don't write a run file

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const REPO_ROOT = resolve(SCRIPT_DIR, '../../../..');
// Write to the cost-tracker plugin's runs dir — the exact path `cost-trend` reads.
const RUNS_DIR = join(REPO_ROOT, 'plugins', 'ruflo-cost-tracker', 'docs', 'benchmarks', 'runs');

// Estimated per-edit LLM cost (USD). Documented estimates, NOT a live call —
// used only to express the savings of a $0 deterministic codemod.
const LLM_EDIT_COST = { haiku: 0.0002, sonnet: 0.003, opus: 0.015 };

function percentile(sorted, p) {
  if (sorted.length === 0) return 0;
  const idx = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[idx];
}

async function main() {
  const { applyCodemod } = await import('../dist/src/ruvector/codemods/engine.js');
  const corpus = JSON.parse(readFileSync(join(CLI_ROOT, 'bench', 'codemod-corpus.json'), 'utf-8'));
  const cases = corpus.cases;

  const results = [];
  const latencies = [];
  let correct = 0;

  for (const c of cases) {
    const t0 = performance.now();
    const r = applyCodemod(c.intent, c.code, { language: c.language });
    const latencyMs = performance.now() - t0;
    latencies.push(latencyMs);
    const ok = r.success && r.output === c.expected;
    if (ok) correct++;
    results.push({
      id: c.id, intent: c.intent, correct: ok, changed: r.changed,
      edits: r.edits, latencyMs: Number(latencyMs.toFixed(4)),
      ...(ok ? {} : { gotPrefix: (r.output ?? '').slice(0, 80), reason: r.reason }),
    });
  }

  const sorted = [...latencies].sort((a, b) => a - b);
  const avg = latencies.reduce((s, x) => s + x, 0) / latencies.length;
  const winRate = correct / cases.length;
  const estSavings = {
    vsHaiku: Number((LLM_EDIT_COST.haiku * cases.length).toFixed(6)),
    vsSonnet: Number((LLM_EDIT_COST.sonnet * cases.length).toFixed(6)),
    vsOpus: Number((LLM_EDIT_COST.opus * cases.length).toFixed(6)),
  };

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'codemod-tier1',
    corpusVersion: corpus.version,
    corpusSize: cases.length,
    winRate,
    winRatePct: `${(winRate * 100).toFixed(1)}%`,
    successCount: correct,
    avgLatencyMs: Number(avg.toFixed(4)),
    p50LatencyMs: Number(percentile(sorted, 50).toFixed(4)),
    p99LatencyMs: Number(percentile(sorted, 99).toFixed(4)),
    maxLatencyMs: Number(Math.max(...latencies).toFixed(4)),
    structuralCostUsd: 0,
    llmBaseline: 'estimated',
    estimatedSavingsUsd: estSavings,
  };

  const run = { summary, results };

  if (process.env.BENCH_JSON) {
    console.log(JSON.stringify(run, null, 2));
  } else {
    console.log(`# Codemod Tier-1 benchmark (${cases.length} cases, corpus v${corpus.version})`);
    console.log('');
    console.log('| Metric | Value |');
    console.log('|---|---:|');
    console.log(`| Win rate (correct vs golden) | ${summary.winRatePct} (${correct}/${cases.length}) |`);
    console.log(`| Avg latency | ${summary.avgLatencyMs} ms |`);
    console.log(`| p50 / p99 / max latency | ${summary.p50LatencyMs} / ${summary.p99LatencyMs} / ${summary.maxLatencyMs} ms |`);
    console.log(`| Measured cost | $0 (no API call) |`);
    console.log(`| Est. savings vs Haiku/Sonnet/Opus | $${estSavings.vsHaiku} / $${estSavings.vsSonnet} / $${estSavings.vsOpus} |`);
    console.log('');
    const failed = results.filter((r) => !r.correct);
    if (failed.length) {
      console.log('## Failures');
      for (const f of failed) console.log(`- \`${f.id}\` (${f.intent}): ${f.reason ?? `got "${f.gotPrefix}"`}`);
      console.log('');
    }
  }

  if (!process.env.BENCH_NO_WRITE) {
    mkdirSync(RUNS_DIR, { recursive: true });
    const stamp = summary.runAt.replace(/[:.]/g, '-');
    writeFileSync(join(RUNS_DIR, `codemod-${stamp}.json`), JSON.stringify(run, null, 2));
    writeFileSync(join(RUNS_DIR, 'codemod-latest.json'), JSON.stringify(run, null, 2));
    if (!process.env.BENCH_JSON) console.log(`Wrote run to ${join(RUNS_DIR, `codemod-${stamp}.json`)}`);
  }

  // Non-zero exit if any case regressed — usable as a CI guardrail.
  if (correct !== cases.length) process.exit(1);
}

main().catch((err) => {
  console.error('benchmark failed:', err);
  process.exit(1);
});

#!/usr/bin/env node
// benchmark-cross-repo.mjs — cross-repo generalisation proof (ADR-084).
//
// Pretrains on a DIFFERENT repo's history (default: ruvnet/agentdb) and runs
// labelled queries about THAT repo's work. If the retrieval system genuinely
// generalises (vs overfits to the ruflo corpus it was tuned on), nDCG@3
// should stay near 0.96.
//
// Usage:
//   1. cd /tmp/agentdb-bench
//   2. REPO_ROOT=/tmp/agentdb-bench GH_REPO=ruvnet/agentdb \
//        node /path/to/pretrain-from-github.mjs    # writes /tmp/agentdb-bench/.claude-flow/neural/
//   3. cd /tmp/agentdb-bench && node /path/to/benchmark-cross-repo.mjs
//
// Or use the wrapper at the bottom that does both steps with --repo=<name>.

import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

// Labelled queries about agentdb's actual history (commits + issues
// observed via `git log` + `gh issue list` on ruvnet/agentdb).
// Each query targets a specific piece of work; labels are case-insensitive
// substring matches against the pattern name.
const QUERIES_AGENTDB = [
  { q: 'SQL injection fix REINDEX',
    labels: ['sql injection', 'reindex'] },
  { q: 'insecure PRNG random IDs',
    labels: ['insecure prng', 'random ids', 'random id', 'crypto', 'uuid'] },
  { q: 'JSON parse crash hardening',
    labels: ['json.parse', 'json parse', 'crash hardening'] },
  { q: 'protobuf critical CVE patch',
    labels: ['protobufjs', 'protobuf', 'cve'] },
  { q: 'spawnSync vs execSync security',
    labels: ['spawnsync', 'execsync'] },
  { q: 'better-sqlite3 inline schemas',
    labels: ['better-sqlite3', 'inline schema', 'schemas'] },
  { q: 'Claude Code marketplace plugins',
    labels: ['marketplace', 'plugin', 'claude code'] },
  { q: 'README rewrite ruflo style',
    labels: ['readme', 'rewrite'] },
  { q: 'WASM browser fs.readFileSync blocking',
    labels: ['wasm', 'browser', 'fs.readfilesync', 'readfilesync', 'agentdb/wasm'] },
  { q: 'AgentDB missing schema files',
    labels: ['missing schema', 'mising schema', 'schema files', 'not working'] },
];

// Labelled queries about agentic-flow's actual history.
const QUERIES_AGENTIC_FLOW = [
  { q: 'CWE-78 shell injection fix',
    labels: ['cwe-78', 'shell injection', 'execsync', 'safe-exec'] },
  { q: 'SSRF hardcoded key NaN panic security',
    labels: ['ssrf', 'hardcoded key', 'nan-panic', 'nan panic'] },
  { q: 'WebSocket QUIC transport fallback',
    labels: ['websocket', 'quic', 'transport'] },
  { q: 'agentdb submodule bump',
    labels: ['agentdb submodule', 'bump agentdb', 'submodule'] },
  { q: 'sql.js prepared statement leak',
    labels: ['sql.js', 'prepared statement', 'leak'] },
  { q: 'WASM ADR-071 integration',
    labels: ['wasm', 'adr-071', 'wasm-integration'] },
  { q: 'patch CVEs transitive overrides',
    labels: ['cve', 'patch', 'transitive', 'overrides'] },
  { q: 'GraphDatabaseAdapter delete API',
    labels: ['graphdatabaseadapter', 'delete api', 'reflexionmemory', 'deleteepisode'] },
  { q: 'release alpha publish version',
    labels: ['release', 'publish', 'alpha', 'version'] },
  { q: 'extract packages to dedicated repo',
    labels: ['extract', 'refactor', 'dedicated repo', 'submodule', 'agentdb'] },
];

// Auto-pick query set based on GH_REPO env var.
const QUERY_SETS = {
  'ruvnet/agentdb': QUERIES_AGENTDB,
  'ruvnet/agentic-flow': QUERIES_AGENTIC_FLOW,
};
const QUERIES = QUERY_SETS[process.env.GH_REPO] || QUERIES_AGENTDB;
const TOP_K = 5;

function isRelevant(name, labels) {
  if (!name || !labels?.length) return false;
  const lower = String(name).toLowerCase();
  return labels.some((s) => lower.includes(s.toLowerCase()));
}

function ndcgAtK(rankedRel, k) {
  const arr = rankedRel.slice(0, k);
  const dcg = arr.reduce((acc, rel, i) => acc + (rel ? 1 / Math.log2(i + 2) : 0), 0);
  const numRelevant = arr.filter(Boolean).length;
  if (numRelevant === 0) return 0;
  let idcg = 0;
  for (let i = 0; i < numRelevant; i++) idcg += 1 / Math.log2(i + 2);
  return idcg > 0 ? dcg / idcg : 0;
}

async function evalConfig(tool, params) {
  let top1 = 0, top3 = 0, ranks = [], ndcg3sum = 0, ndcg5sum = 0, p3sum = 0;
  const t0 = performance.now();
  const perQuery = [];
  for (const { q, labels } of QUERIES) {
    const r = await tool.handler({ action: 'search', query: q, mode: 'hybrid', limit: TOP_K, ...params });
    const matches = (r.results || []).slice(0, TOP_K);
    const rel = matches.map((m) => isRelevant(m?.name, labels));
    if (rel[0]) top1++;
    if (rel.slice(0, 3).some(Boolean)) top3++;
    const firstRank = rel.findIndex(Boolean);
    if (firstRank >= 0) ranks.push(firstRank + 1);
    ndcg3sum += ndcgAtK(rel, 3);
    ndcg5sum += ndcgAtK(rel, 5);
    p3sum += rel.slice(0, 3).filter(Boolean).length / 3;
    perQuery.push({ q, top1: rel[0] || false, topK: matches.map((m, i) => ({ name: m.name?.slice(0, 90), relevant: rel[i], score: (m.score ?? m.similarity)?.toFixed?.(3) })) });
  }
  const elapsed = performance.now() - t0;
  return {
    top1HitRate: top1 / QUERIES.length,
    top3HitRate: top3 / QUERIES.length,
    mrr3: ranks.reduce((s, r) => s + 1 / r, 0) / QUERIES.length,
    precision3: p3sum / QUERIES.length,
    ndcg3: ndcg3sum / QUERIES.length,
    ndcg5: ndcg5sum / QUERIES.length,
    avgLatencyMs: elapsed / QUERIES.length,
    perQuery,
  };
}

async function main() {
  const neural = await import(join(CLI_ROOT, 'dist/src/mcp-tools/neural-tools.js'));
  const intel = await import(join(CLI_ROOT, 'dist/src/memory/intelligence.js'));
  const stats = await intel.getUnifiedLearningStats();
  const storeSize = stats.neuralPatterns.patternCount;

  if (storeSize === 0) {
    console.error('No patterns in neural store. Run pretrain-from-github.mjs first (with REPO_ROOT + GH_REPO env).');
    process.exit(2);
  }

  const tool = neural.neuralTools.find((t) => t.name === 'neural_patterns');
  if (!tool) throw new Error('neural_patterns tool not found');

  console.log(`# Cross-repo generalisation benchmark (ADR-084)`);
  console.log(`Cwd: ${process.cwd()}`);
  console.log(`Store size: ${storeSize} patterns`);
  console.log(`Queries: ${QUERIES.length} (labelled set for ${process.env.GH_REPO || 'default agentdb'})`);
  console.log('');

  console.log('--- Hybrid path (defaults) ---');
  const hybrid = await evalConfig(tool, { rerank: false });
  console.log(`  top-1: ${(hybrid.top1HitRate * 100).toFixed(0)}%  top-3: ${(hybrid.top3HitRate * 100).toFixed(0)}%  MRR@3: ${hybrid.mrr3.toFixed(3)}  P3: ${hybrid.precision3.toFixed(3)}  nDCG@3: ${hybrid.ndcg3.toFixed(3)}  nDCG@5: ${hybrid.ndcg5.toFixed(3)}  ${hybrid.avgLatencyMs.toFixed(0)}ms`);

  console.log('--- Rerank path (defaults) ---');
  const rerank = await evalConfig(tool, { rerank: true });
  console.log(`  top-1: ${(rerank.top1HitRate * 100).toFixed(0)}%  top-3: ${(rerank.top3HitRate * 100).toFixed(0)}%  MRR@3: ${rerank.mrr3.toFixed(3)}  P3: ${rerank.precision3.toFixed(3)}  nDCG@3: ${rerank.ndcg3.toFixed(3)}  nDCG@5: ${rerank.ndcg5.toFixed(3)}  ${rerank.avgLatencyMs.toFixed(0)}ms`);

  console.log('\n--- Per-query rerank top-3 ---');
  for (const q of rerank.perQuery) {
    console.log(`Q: "${q.q}" (top-1: ${q.top1 ? '✓' : '✗'})`);
    for (const m of q.topK.slice(0, 3)) {
      console.log(`   ${m.relevant ? '★' : ' '} [${m.score ?? '—'}] ${m.name}`);
    }
  }

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'cross-repo-generalisation',
    repo: process.env.GH_REPO || 'unknown',
    cwd: process.cwd(),
    storeSize,
    queries: QUERIES.length,
    hybrid: {
      top1HitRate: hybrid.top1HitRate,
      top3HitRate: hybrid.top3HitRate,
      mrr3: hybrid.mrr3,
      precision3: hybrid.precision3,
      ndcg3: hybrid.ndcg3,
      ndcg5: hybrid.ndcg5,
      avgLatencyMs: hybrid.avgLatencyMs,
    },
    rerank: {
      top1HitRate: rerank.top1HitRate,
      top3HitRate: rerank.top3HitRate,
      mrr3: rerank.mrr3,
      precision3: rerank.precision3,
      ndcg3: rerank.ndcg3,
      ndcg5: rerank.ndcg5,
      avgLatencyMs: rerank.avgLatencyMs,
    },
    perQueryRerank: rerank.perQuery,
  };

  mkdirSync(RUNS_DIR, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  const repoSlug = (process.env.GH_REPO || 'unknown').replace('/', '-');
  writeFileSync(join(RUNS_DIR, `cross-repo-${repoSlug}-${stamp}.json`), JSON.stringify(summary, null, 2));
  writeFileSync(join(RUNS_DIR, `cross-repo-${repoSlug}-latest.json`), JSON.stringify(summary, null, 2));
  console.log(`\nWrote ${join(RUNS_DIR, `cross-repo-${repoSlug}-${stamp}.json`)}`);

  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// benchmark-pretrained-retrieval.mjs — proof that pretrained patterns are
// retrievable, not just stored.
//
// Runs sample queries against the neural store (post-pretrain) and reports
// the top-k matches. Demonstrates that after `pretrain-from-github.mjs`
// runs, an agent can recall relevant past work by intent.
//
// Usage:
//   1. node scripts/pretrain-from-github.mjs           # populate the store
//   2. node scripts/benchmark-pretrained-retrieval.mjs # query + report

import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const REPO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(REPO_ROOT, 'docs', 'benchmarks', 'runs');

// ADR-081 labelled held-out corpus. Each query has hand-curated
// `expectedSubstrings` — case-insensitive substring matches against the
// pattern's name. A result is "relevant" if its name contains ANY of the
// substrings. Tighter than the regex proxy used in ADRs 077-080 (which
// matched related-but-not-exact commits).
//
// `expect` (regex) is kept for backwards compatibility with the older
// numbers in ADRs 077-080. New metrics use expectedSubstrings.
const QUERIES = [
  {
    q: 'how was the Opus model alias fixed',
    expect: /opus|2232|model.*alias|4\.8/i,
    expectedSubstrings: ['opus 4.8', 'opus alias', 'opus model alias', '#2232'],
  },
  {
    q: 'self-learning wiring task-completed pretrain',
    expect: /self.?learning|task.?completed|pretrain|2245|074/i,
    expectedSubstrings: ['self-learning', 'adr-074', 'self learning', '#2245', 'task-completed'],
  },
  {
    q: 'deterministic codemod engine var-to-const',
    expect: /codemod|var.?to.?const|143|deterministic/i,
    expectedSubstrings: ['deterministic tier-1 codemod', 'adr-143', 'codemod', 'var-to-const'],
  },
  {
    q: 'MCP server orphan leak parent-death',
    expect: /mcp.*orphan|orphan.*mcp|parent.?death|leak/i,
    expectedSubstrings: ['mcp orphan', 'mcp servers orphan', 'parent-death', '#2234', 'orphan on every claude'],
  },
  {
    q: 'unified learning stats aggregator',
    expect: /unified|stats|aggregator|075/i,
    expectedSubstrings: ['unified learning-stats', 'adr-075', 'unified learning stats'],
  },
  {
    q: 'structured distillation 4-field schema',
    expect: /distillation|structured|076|4.?field/i,
    expectedSubstrings: ['structured distillation', 'adr-076', '4-field schema'],
  },
  {
    q: 'SQL injection migrate.ts table identifier',
    expect: /sql.?injection|migrate|table|identifier/i,
    expectedSubstrings: ['sql injection', 'shell injection', 'migrate.ts', 'agentdb', 'cve'],
  },
  {
    q: 'recall@k HNSW benchmark harness',
    expect: /recall|hnsw|benchmark|harness/i,
    expectedSubstrings: ['hnsw', 'memory-recall', 'benchmark suite', 'recall@k', 'benchmark intelligence'],
  },
  {
    q: 'Q-learning encoder keyword block',
    expect: /q.?learning|encoder|keyword|2239/i,
    expectedSubstrings: ['q-state encoder', 'route q-state', 'keyword block', '#2239', 'q-encoder'],
  },
  {
    q: 'security hardening crypto random IDs',
    expect: /security|hardening|crypto|random/i,
    expectedSubstrings: ['cwe-347', 'crypto.randomuuid', 'security fix', 'random id', 'crypto random'],
  },
];

/** Returns true if name contains ANY of the labelled substrings (case-insensitive). */
function isRelevant(name, expectedSubstrings) {
  if (!name || !expectedSubstrings?.length) return false;
  const lower = String(name).toLowerCase();
  return expectedSubstrings.some((s) => lower.includes(s.toLowerCase()));
}

/** nDCG@k with binary relevance (each relevant item contributes 1 / log2(i+1)). */
function ndcgAtK(rankedRelevance, k) {
  const arr = rankedRelevance.slice(0, k);
  const dcg = arr.reduce((acc, rel, i) => acc + (rel ? 1 / Math.log2(i + 2) : 0), 0);
  const numRelevant = arr.filter(Boolean).length;
  if (numRelevant === 0) return 0;
  // Ideal: all relevant items packed at positions 1..numRelevant
  let idcg = 0;
  for (let i = 0; i < numRelevant; i++) idcg += 1 / Math.log2(i + 2);
  return idcg > 0 ? dcg / idcg : 0;
}

const TOP_K = 5;

async function main() {
  const intel = await import(join(CLI_ROOT, 'dist/src/memory/intelligence.js'));
  const neural = await import(join(CLI_ROOT, 'dist/src/mcp-tools/neural-tools.js'));

  // §1 — snapshot the neural store + globalStats so we know what's there.
  const unified = await intel.getUnifiedLearningStats();
  const total = unified.neuralPatterns.patternCount;

  if (total === 0) {
    console.error('No patterns in neural store. Run scripts/pretrain-from-github.mjs first.');
    process.exit(2);
  }

  // §2 — A/B hybrid vs cosine-only (HYBRID=0 forces pre-3.10.18 behaviour).
  // Default runs hybrid (cosine + BM25 + MMR per ADR-078).
  const listTool = neural.neuralTools.find((t) => t.name === 'neural_patterns');
  const mode = process.env.HYBRID === '0' ? 'cosine' : 'hybrid';
  // ADR-080 opt-in cross-encoder rerank — set RERANK=1 to enable.
  const useRerank = process.env.RERANK === '1';

  // top-1-uniqueness — fraction of queries whose top-1 result is NOT the
  // same pattern ID as another query's top-1. Catches the "everyone gets
  // the same generic top-1" failure mode.
  const top1Ids = new Map();

  const tQuery0 = performance.now();
  const results = [];
  for (const { q, expect, expectedSubstrings } of QUERIES) {
    const r = await listTool.handler({ action: 'search', query: q, mode, limit: TOP_K, rerank: useRerank });
    const matches = (r.patterns || r.results || r.matches || []).slice(0, TOP_K);
    if (matches.length > 0) {
      const top1 = matches[0].id;
      top1Ids.set(top1, (top1Ids.get(top1) ?? 0) + 1);
    }

    // Two relevance signals per result:
    //   regexRel — old proxy (kept for back-compat with ADR-077-080 numbers)
    //   labelRel — ADR-081 hand-curated label match
    const regexRel = matches.map((m) => expect.test(m?.name ?? ''));
    const labelRel = matches.map((m) => isRelevant(m?.name, expectedSubstrings));

    // First rank where a labelled-relevant doc appears.
    let firstLabelRank = -1;
    for (let i = 0; i < matches.length; i++) {
      if (labelRel[i]) { firstLabelRank = i + 1; break; }
    }
    let firstRegexRank = -1;
    for (let i = 0; i < matches.length; i++) {
      if (regexRel[i]) { firstRegexRank = i + 1; break; }
    }

    results.push({
      query: q,
      matched: matches.length > 0,
      // Regex-proxy metrics (back-compat with ADR-077-080)
      top1Relevant: regexRel[0] || false,
      top3Relevant: regexRel.slice(0, 3).some(Boolean),
      firstRelevantRank: firstRegexRank,
      // ADR-081 labelled metrics
      label_top1: labelRel[0] || false,
      label_top3_count: labelRel.slice(0, 3).filter(Boolean).length,
      label_top5_count: labelRel.slice(0, 5).filter(Boolean).length,
      label_firstRank: firstLabelRank,
      label_ndcg3: ndcgAtK(labelRel, 3),
      label_ndcg5: ndcgAtK(labelRel, 5),
      topK: matches.map((m, i) => ({
        id: m.id,
        name: m.name?.slice(0, 100),
        type: m.type,
        score: m.score ?? m.similarity,
        cosineScore: m.cosineScore,
        bm25Score: m.bm25Score,
        mmrScore: m.mmrScore,
        labelRelevant: labelRel[i],
      })),
    });
  }
  const queryMs = performance.now() - tQuery0;

  const matchedQueries = results.filter((r) => r.matched).length;
  // Regex-proxy metrics (back-compat)
  const top1Hits = results.filter((r) => r.top1Relevant).length;
  const top3Hits = results.filter((r) => r.top3Relevant).length;
  const ranks = results.filter((r) => r.firstRelevantRank > 0).map((r) => r.firstRelevantRank);
  const mrr3 = QUERIES.length > 0
    ? Number((ranks.reduce((s, r) => s + 1 / r, 0) / QUERIES.length).toFixed(4))
    : 0;

  // ADR-081 labelled metrics — tighter ground truth than regex proxy.
  const label_top1Hits = results.filter((r) => r.label_top1).length;
  const label_top3HitsBinary = results.filter((r) => r.label_top3_count > 0).length;
  const label_ranks = results.filter((r) => r.label_firstRank > 0).map((r) => r.label_firstRank);
  const label_mrr3 = QUERIES.length > 0
    ? Number((label_ranks.reduce((s, r) => s + 1 / r, 0) / QUERIES.length).toFixed(4))
    : 0;
  const label_ndcg3_mean = QUERIES.length > 0
    ? Number((results.reduce((s, r) => s + r.label_ndcg3, 0) / QUERIES.length).toFixed(4))
    : 0;
  const label_ndcg5_mean = QUERIES.length > 0
    ? Number((results.reduce((s, r) => s + r.label_ndcg5, 0) / QUERIES.length).toFixed(4))
    : 0;
  // Mean precision@3 — fraction of top-3 that's relevant per query, averaged.
  const label_precision3 = QUERIES.length > 0
    ? Number((results.reduce((s, r) => s + r.label_top3_count / 3, 0) / QUERIES.length).toFixed(4))
    : 0;
  // top-1 collision: number of distinct top-1 IDs over the query count.
  const uniqueTop1 = top1Ids.size;
  const top1Diversity = Number((uniqueTop1 / QUERIES.length).toFixed(4));

  // top-3 redundancy: average fraction of top-3 results that are duplicates
  // of the same pattern within a single query (should be 0 — but if the same
  // ID appears twice in top-3 we surface it).
  let dupCount = 0, top3Slots = 0;
  for (const r of results) {
    const ids = r.topK.slice(0, 3).map((m) => m.id);
    top3Slots += ids.length;
    const seen = new Set();
    for (const id of ids) {
      if (seen.has(id)) dupCount++;
      seen.add(id);
    }
  }
  const top3DupRate = top3Slots > 0 ? Number((dupCount / top3Slots).toFixed(4)) : 0;

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'pretrained-retrieval',
    mode,                              // ADR-078: which retrieval path was used
    rerank: useRerank,                 // ADR-080: cross-encoder rerank on/off
    storeSize: total,
    queries: QUERIES.length,
    matchedQueries,
    matchRate: Number((matchedQueries / QUERIES.length).toFixed(4)),
    // Regex-proxy metrics (ADR-077-080 back-compat)
    top1HitRate: Number((top1Hits / QUERIES.length).toFixed(4)),
    top3HitRate: Number((top3Hits / QUERIES.length).toFixed(4)),
    mrr3,
    // ADR-081 labelled metrics — tighter ground truth
    label_top1HitRate: Number((label_top1Hits / QUERIES.length).toFixed(4)),
    label_top3HitRate: Number((label_top3HitsBinary / QUERIES.length).toFixed(4)),
    label_mrr3,
    label_precision3,
    label_ndcg3: label_ndcg3_mean,
    label_ndcg5: label_ndcg5_mean,
    top1Diversity,                     // 1.0 = every query gets a distinct top-1
    top3DupRate,                       // 0.0 = no duplicate IDs inside any top-3
    avgQueryLatencyMs: Number((queryMs / QUERIES.length).toFixed(2)),
    totalQueryMs: Number(queryMs.toFixed(2)),
    results,
    passed: matchedQueries === QUERIES.length,
  };

  if (process.env.BENCH_JSON) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(`# Pretrained-retrieval benchmark — proof of learning`);
    console.log(`Mode: ${mode}${mode === 'hybrid' ? ' (cosine + BM25 + MMR, ADR-078)' : ' (cosine-only, pre-3.10.18)'}${useRerank ? ' + cross-encoder rerank (ADR-080)' : ''}`);
    console.log(`Store size: ${total} patterns`);
    console.log(`Queries: ${QUERIES.length}`);
    console.log(`Match rate: ${(summary.matchRate * 100).toFixed(0)}% (${matchedQueries}/${QUERIES.length})`);
    console.log(`Top-1 hit rate (regex proxy): ${(summary.top1HitRate * 100).toFixed(0)}% (${top1Hits}/${QUERIES.length})`);
    console.log(`Top-3 hit rate (regex proxy): ${(summary.top3HitRate * 100).toFixed(0)}% (${top3Hits}/${QUERIES.length})`);
    console.log(`MRR@3 (regex proxy):          ${summary.mrr3}`);
    console.log('');
    console.log(`Top-1 hit rate (ADR-081 labelled): ${(summary.label_top1HitRate * 100).toFixed(0)}% (${label_top1Hits}/${QUERIES.length})`);
    console.log(`Top-3 hit rate (ADR-081 labelled): ${(summary.label_top3HitRate * 100).toFixed(0)}% (${label_top3HitsBinary}/${QUERIES.length})`);
    console.log(`MRR@3 (labelled):                  ${summary.label_mrr3}`);
    console.log(`Precision@3 (labelled, mean):      ${summary.label_precision3}`);
    console.log(`nDCG@3 (labelled, mean):           ${summary.label_ndcg3}`);
    console.log(`nDCG@5 (labelled, mean):           ${summary.label_ndcg5}`);
    console.log(`Top-1 diversity: ${(summary.top1Diversity * 100).toFixed(0)}% (${uniqueTop1} distinct top-1 IDs across ${QUERIES.length} queries)`);
    console.log(`Top-3 dup rate: ${(summary.top3DupRate * 100).toFixed(0)}%`);
    console.log(`Avg query latency: ${summary.avgQueryLatencyMs} ms`);
    console.log('');
    for (const r of results) {
      console.log(`Q: "${r.query}"`);
      if (r.topK.length === 0) {
        console.log(`   → no matches`);
      } else {
        for (const m of r.topK.slice(0, 3)) {
          console.log(`   → ${m.score?.toFixed?.(3) ?? '—'}  ${m.name}`);
        }
      }
    }
    console.log('');
    console.log(`Overall: ${summary.passed ? '✅ PASSED' : '⚠️  partial'}`);
  }

  if (!process.env.BENCH_NO_WRITE) {
    mkdirSync(RUNS_DIR, { recursive: true });
    const stamp = summary.runAt.replace(/[:.]/g, '-');
    writeFileSync(join(RUNS_DIR, `pretrained-retrieval-${stamp}.json`), JSON.stringify(summary, null, 2));
    writeFileSync(join(RUNS_DIR, 'pretrained-retrieval-latest.json'), JSON.stringify(summary, null, 2));
    if (!process.env.BENCH_JSON) console.log(`\nWrote ${join(RUNS_DIR, `pretrained-retrieval-${stamp}.json`)}`);
  }

  // ONNX runtime keeps a worker thread alive — force exit.
  process.exit(summary.passed ? 0 : 1);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// benchmark-self-learning.mjs — proof harness for #2245.
//
// Replaces the "self-learning reports success but persists nothing" theater
// with measured deltas: actually runs each entry point N times and prints what
// each one moved (or didn't). Writes a run JSON to docs/benchmarks/runs/ so
// future regressions are visible against a committed baseline.
//
// Usage:
//   node scripts/benchmark-self-learning.mjs                  # default N=20 per surface
//   N=50 BENCH_JSON=1 node scripts/benchmark-self-learning.mjs
//   BENCH_NO_WRITE=1 node scripts/benchmark-self-learning.mjs
//
// Repro:
//   1. Clone ruvnet/ruflo, npm install, build the CLI:
//        npm install && (cd v3/@claude-flow/cli && npx tsc -b)
//   2. Run this script. It prints a "before/after" table per surface.
//   3. Inspect docs/benchmarks/runs/self-learning-<ts>.json for the persisted
//      proof — diff against previous runs to catch any future regression.

import { mkdirSync, writeFileSync, mkdtempSync, rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const REPO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(REPO_ROOT, 'docs', 'benchmarks', 'runs');

const N = Number(process.env.N) || 20;

// Run in an isolated temp dir so we don't pollute the repo's neural store.
const SCRATCH = mkdtempSync(join(tmpdir(), 'learn-bench-'));
process.chdir(SCRATCH);

async function main() {
  const intel = await import(join(CLI_ROOT, 'dist/src/memory/intelligence.js'));
  const hooks = await import(join(CLI_ROOT, 'dist/src/mcp-tools/hooks-tools.js'));
  const neural = await import(join(CLI_ROOT, 'dist/src/mcp-tools/neural-tools.js'));

  intel.clearIntelligence();

  // -------------------------------------------------------------------------
  // §A — recordSignalProcessed
  // -------------------------------------------------------------------------
  const A_before = intel.getIntelligenceStats();
  const tA = performance.now();
  for (let i = 0; i < N; i++) intel.recordSignalProcessed();
  intel.flushIntelligenceStats();
  const dtA = performance.now() - tA;
  const A_after = intel.getIntelligenceStats();
  const A_delta = A_after.signalsProcessed - A_before.signalsProcessed;

  // -------------------------------------------------------------------------
  // §B — hooks_task-completed (trainPatterns:true) → trajectory pipeline
  // -------------------------------------------------------------------------
  const taskCompleted = hooks.hooksTools.find((t) => t.name === 'hooks_task-completed');
  const B_before = intel.getIntelligenceStats();
  const tB = performance.now();
  let B_trained = 0;
  for (let i = 0; i < N; i++) {
    const r = await taskCompleted.handler({
      taskId: `bench-${i}`,
      success: i % 5 !== 4, // 80% success, 20% failure — mixed verdict
      quality: 0.5 + (i % 5) * 0.1,
      trainPatterns: true,
      content: `Benchmark task ${i}: refactor or test or fix`,
    });
    if (r.learningPath === 'trajectory-pipeline') B_trained++;
  }
  const dtB = performance.now() - tB;
  const B_after = intel.getIntelligenceStats();

  // -------------------------------------------------------------------------
  // §C — hooks_task-completed recorded-only (negative control)
  // -------------------------------------------------------------------------
  const C_before = intel.getIntelligenceStats();
  const tC = performance.now();
  for (let i = 0; i < N; i++) {
    await taskCompleted.handler({ taskId: `bench-no-train-${i}`, success: true, quality: 0.8 });
  }
  const dtC = performance.now() - tC;
  const C_after = intel.getIntelligenceStats();

  // -------------------------------------------------------------------------
  // §D — storeNeuralPatterns + neural_patterns list reflects them
  // -------------------------------------------------------------------------
  const items = Array.from({ length: N }, (_, i) => ({
    name: `pattern-${i}`,
    type: 'bench-pattern',
    content: `import { thing${i} } from 'module${i}'`,
  }));
  const tD = performance.now();
  const D_store = await neural.storeNeuralPatterns(items);
  const dtD = performance.now() - tD;
  const listTool = neural.neuralTools.find((t) => t.name === 'neural_patterns');
  const D_list = await listTool.handler({ action: 'list' });

  // -------------------------------------------------------------------------
  // §E — multi-step trajectory pipeline (end-to-end)
  // -------------------------------------------------------------------------
  const trajStart = hooks.hooksTools.find((t) => t.name === 'hooks_intelligence_trajectory-start');
  const trajStep  = hooks.hooksTools.find((t) => t.name === 'hooks_intelligence_trajectory-step');
  const trajEnd   = hooks.hooksTools.find((t) => t.name === 'hooks_intelligence_trajectory-end');
  // NOTE: the MCP trajectory tools feed sonaCoordinator (queryable via
  // hooks_intelligence_stats), NOT globalStats. That's part of the broader
  // store-fragmentation problem #2245 identifies; we check observable
  // outcomes (persisted + sonaUpdate) instead of a globalStats delta.
  const tE = performance.now();
  let persistedCount = 0;
  let sonaUpdateCount = 0;
  if (trajStart && trajStep && trajEnd) {
    for (let i = 0; i < Math.min(5, N); i++) {
      const s = await trajStart.handler({ task: `multi-step bench ${i}`, agent: 'bench' });
      const id = s.trajectoryId;
      await trajStep.handler({ trajectoryId: id, type: 'observation', content: `obs ${i}` });
      await trajStep.handler({ trajectoryId: id, type: 'action',      content: `act ${i}` });
      await trajStep.handler({ trajectoryId: id, type: 'result',      content: `done ${i}` });
      const endRes = await trajEnd.handler({ trajectoryId: id, success: true });
      if (endRes.persisted) persistedCount++;
      if (endRes.learning?.sonaUpdate) sonaUpdateCount++;
    }
  }
  const dtE = performance.now() - tE;

  // -------------------------------------------------------------------------
  // §F — getUnifiedLearningStats (ADR-075)
  // -------------------------------------------------------------------------
  const tF = performance.now();
  const unified = await intel.getUnifiedLearningStats();
  const dtF = performance.now() - tF;
  const unifiedOk = unified.global && unified.sona && unified.memoryBridge && unified.neuralPatterns && unified.consistency;

  // -------------------------------------------------------------------------
  // Summary
  // -------------------------------------------------------------------------
  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'self-learning-2245',
    n: N,
    sections: {
      A_recordSignalProcessed: {
        calls: N,
        signalsProcessedDelta: A_delta,
        passed: A_delta === N,
        elapsedMs: Number(dtA.toFixed(2)),
      },
      B_taskCompleted_trainPatterns: {
        calls: N,
        trainedViaPipeline: B_trained,
        trajectoriesDelta: B_after.trajectoriesRecorded - B_before.trajectoriesRecorded,
        patternsLearnedDelta: B_after.patternsLearned - B_before.patternsLearned,
        passed: B_trained === N,
        elapsedMs: Number(dtB.toFixed(2)),
        avgLatencyMsPerCall: Number((dtB / N).toFixed(2)),
      },
      C_taskCompleted_recordedOnly: {
        calls: N,
        trajectoriesDelta: C_after.trajectoriesRecorded - C_before.trajectoriesRecorded,
        passed: (C_after.trajectoriesRecorded - C_before.trajectoriesRecorded) === 0,
        note: 'negative control — should NOT touch trajectories',
        elapsedMs: Number(dtC.toFixed(2)),
      },
      D_pretrain_neuralPatterns: {
        attempted: items.length,
        stored: D_store.stored,
        listTotal: D_list.total,
        passed: D_store.stored === items.length && D_list.total >= items.length,
        elapsedMs: Number(dtD.toFixed(2)),
      },
      E_multiStepTrajectory: {
        cycles: Math.min(5, N),
        persistedCount,
        sonaUpdateCount,
        passed: persistedCount === Math.min(5, N), // persistence is the must-pass; SONA depends on env
        note: 'MCP trajectory tools feed sonaCoordinator (see hooks_intelligence_stats), not globalStats — observable outcomes checked here',
        elapsedMs: Number(dtE.toFixed(2)),
      },
      F_unifiedStats: {
        shape: ['global', 'sona', 'memoryBridge', 'neuralPatterns', 'consistency'],
        observed: {
          'global.patternsLearned': unified.global.patternsLearned,
          'global.trajectoriesRecorded': unified.global.trajectoriesRecorded,
          'global.signalsProcessed': unified.global.signalsProcessed,
          'memoryBridge.totalEntries': unified.memoryBridge.totalEntries,
          'memoryBridge.reachable': unified.memoryBridge.reachable,
          'neuralPatterns.patternCount': unified.neuralPatterns.patternCount,
          'sona.available': unified.sona.available,
          'consistency.notes': unified.consistency.notes.length,
        },
        passed: !!unifiedOk,
        note: 'ADR-075 — one aggregator across the 4 stores. Each sub-view names its source.',
        elapsedMs: Number(dtF.toFixed(2)),
      },
    },
    finalState: {
      signalsProcessed: A_after.signalsProcessed,
      trajectoriesRecorded: intel.getIntelligenceStats().trajectoriesRecorded,
      patternsLearned: intel.getIntelligenceStats().patternsLearned,
    },
    scratch: SCRATCH,
  };

  const allPassed = Object.values(summary.sections).every((s) => s.passed);
  summary.passed = allPassed;

  if (process.env.BENCH_JSON) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(`# Self-learning benchmark (#2245) — N=${N}`);
    console.log('');
    console.log('| Section | Calls | Delta | Passed | Latency (ms) |');
    console.log('|---|---:|---:|:---:|---:|');
    console.log(`| A recordSignalProcessed | ${N} | +${summary.sections.A_recordSignalProcessed.signalsProcessedDelta} | ${summary.sections.A_recordSignalProcessed.passed ? '✅' : '❌'} | ${summary.sections.A_recordSignalProcessed.elapsedMs} |`);
    console.log(`| B task-completed (train) | ${N} | trained=${summary.sections.B_taskCompleted_trainPatterns.trainedViaPipeline}, trajectories+${summary.sections.B_taskCompleted_trainPatterns.trajectoriesDelta} | ${summary.sections.B_taskCompleted_trainPatterns.passed ? '✅' : '❌'} | ${summary.sections.B_taskCompleted_trainPatterns.elapsedMs} (${summary.sections.B_taskCompleted_trainPatterns.avgLatencyMsPerCall}/call) |`);
    console.log(`| C task-completed (record-only) | ${N} | trajectories+${summary.sections.C_taskCompleted_recordedOnly.trajectoriesDelta} (expected 0) | ${summary.sections.C_taskCompleted_recordedOnly.passed ? '✅' : '❌'} | ${summary.sections.C_taskCompleted_recordedOnly.elapsedMs} |`);
    console.log(`| D pretrain → neural_patterns | ${items.length} | stored=${summary.sections.D_pretrain_neuralPatterns.stored}, listed=${summary.sections.D_pretrain_neuralPatterns.listTotal} | ${summary.sections.D_pretrain_neuralPatterns.passed ? '✅' : '❌'} | ${summary.sections.D_pretrain_neuralPatterns.elapsedMs} |`);
    console.log(`| E multi-step trajectory | ${summary.sections.E_multiStepTrajectory.cycles} | persisted=${summary.sections.E_multiStepTrajectory.persistedCount}, sonaUpdate=${summary.sections.E_multiStepTrajectory.sonaUpdateCount} | ${summary.sections.E_multiStepTrajectory.passed ? '✅' : '❌'} | ${summary.sections.E_multiStepTrajectory.elapsedMs} |`);
    const f = summary.sections.F_unifiedStats;
    console.log(`| F unified-stats | 4 stores | bridge.reachable=${f.observed['memoryBridge.reachable']}, sona.available=${f.observed['sona.available']}, neural.count=${f.observed['neuralPatterns.patternCount']}, notes=${f.observed['consistency.notes']} | ${f.passed ? '✅' : '❌'} | ${f.elapsedMs} |`);
    console.log('');
    console.log(`Final state: signalsProcessed=${summary.finalState.signalsProcessed}, trajectoriesRecorded=${summary.finalState.trajectoriesRecorded}, patternsLearned=${summary.finalState.patternsLearned}`);
    console.log(`Overall: ${allPassed ? '✅ ALL PASSED' : '❌ FAILED'}`);
  }

  if (!process.env.BENCH_NO_WRITE) {
    mkdirSync(RUNS_DIR, { recursive: true });
    const stamp = summary.runAt.replace(/[:.]/g, '-');
    writeFileSync(join(RUNS_DIR, `self-learning-${stamp}.json`), JSON.stringify(summary, null, 2));
    writeFileSync(join(RUNS_DIR, 'self-learning-latest.json'), JSON.stringify(summary, null, 2));
    if (!process.env.BENCH_JSON) console.log(`\nWrote ${join(RUNS_DIR, `self-learning-${stamp}.json`)}`);
  }

  try { rmSync(SCRATCH, { recursive: true, force: true }); } catch {}

  if (!allPassed) process.exit(1);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// benchmark-trajectory-mrr.mjs — proof harness for Structured Distillation
// (#2241 §SOTA, arXiv:2603.13017).
//
// Measures retrieval MRR for raw vs structured-distilled trajectory content
// against a paired corpus. The arXiv paper reports raw → distilled MRR
// going from 0.745 to 0.759 on a 214 K-pair consensus-graded set; our corpus
// is much smaller and hand-curated, so the absolute numbers won't match,
// but the *direction* of the delta is what we're proving.
//
// Two embedders are supported:
//   - Real ONNX (Xenova/all-MiniLM-L6-v2 384-dim) via @claude-flow/embeddings
//     when available. Best signal.
//   - Hash-based deterministic fallback when ONNX isn't installed. Lower
//     signal; results still relative-comparable.
//
// Usage:
//   node scripts/benchmark-trajectory-mrr.mjs            # default
//   BENCH_JSON=1 node scripts/benchmark-trajectory-mrr.mjs
//   BENCH_NO_WRITE=1 node scripts/benchmark-trajectory-mrr.mjs

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const REPO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(REPO_ROOT, 'docs', 'benchmarks', 'runs');

const { distillAndSerialise, compressionRatio } = await import(
  join(CLI_ROOT, 'dist/src/memory/structured-distill.js')
);

// ---------------------------------------------------------------------------
// Embedder — prefers real ONNX, falls back to hash-based deterministic.
// ---------------------------------------------------------------------------
async function loadEmbedder() {
  // Tier 1: AgentDB's bridge-loaded ONNX embedder (the path the live MCP
  // server + vitest tests use, so we measure what users actually get).
  try {
    const mb = await import(join(CLI_ROOT, 'dist/src/memory/memory-bridge.js'));
    const probe = await mb.bridgeGenerateEmbedding('warm-up').catch(() => null);
    if (probe && probe.embedding && probe.embedding.length > 0 && probe.backend === 'onnx') {
      return {
        name: `bridge ONNX (${probe.model}, ${probe.dimensions}-dim)`,
        embed: async (text) => {
          const r = await mb.bridgeGenerateEmbedding(text);
          if (!r) throw new Error('bridge embed returned null');
          return r.embedding;
        },
      };
    }
  } catch { /* fall through */ }
  // Tier 2: hash-based deterministic. Clearly degraded; produces only
  // direction-of-effect signal, not absolute MRR numbers comparable to paper.
  console.error('⚠️  Real ONNX embedder unavailable — using hash-based deterministic fallback. Absolute MRR numbers are NOT comparable to the arXiv paper in this mode; relative comparison is also weak.');
  return {
    name: 'hash-fallback (no semantic signal — degraded mode)',
    embed: async (text) => hashEmbed(text, 384),
  };
}

function hashEmbed(text, dims) {
  const v = new Float32Array(dims);
  let seed = 0;
  for (let i = 0; i < text.length; i++) seed = (seed * 31 + text.charCodeAt(i)) | 0;
  let s = Math.abs(seed) | 1;
  for (let i = 0; i < dims; i++) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    v[i] = (s / 0x7fffffff) * 2 - 1;
  }
  // L2 normalise
  let n = 0;
  for (let i = 0; i < dims; i++) n += v[i] * v[i];
  n = Math.sqrt(n) || 1;
  for (let i = 0; i < dims; i++) v[i] /= n;
  return Array.from(v);
}

function cosine(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  const corpusPath = join(CLI_ROOT, 'bench', 'trajectory-mrr-corpus.json');
  const corpus = JSON.parse(readFileSync(corpusPath, 'utf-8'));
  const trajectories = corpus.trajectories;
  const embedder = await loadEmbedder();

  // Per-trajectory: embed both raw and distilled forms.
  const tEmbed0 = performance.now();
  const rawEmbs = [];
  const distEmbs = [];
  let totalRawBytes = 0;
  let totalDistBytes = 0;
  for (const t of trajectories) {
    const distilled = distillAndSerialise(t.raw);
    totalRawBytes += t.raw.length;
    totalDistBytes += distilled.length;
    rawEmbs.push(await embedder.embed(t.raw));
    distEmbs.push(await embedder.embed(distilled));
  }
  const embedMs = performance.now() - tEmbed0;

  // For each (query, gold) pair: rank all trajectories by cosine to the query
  // embedding. MRR = mean of 1 / rank-of-gold across all queries.
  const tQuery0 = performance.now();
  let rrRaw = 0, rrDist = 0;
  const perQuery = [];
  for (let i = 0; i < trajectories.length; i++) {
    const q = await embedder.embed(trajectories[i].query);
    const rankRaw = rankOf(q, rawEmbs, i);
    const rankDist = rankOf(q, distEmbs, i);
    rrRaw += 1 / rankRaw;
    rrDist += 1 / rankDist;
    perQuery.push({ id: trajectories[i].id, rankRaw, rankDist });
  }
  const queryMs = performance.now() - tQuery0;

  const N = trajectories.length;
  const mrrRaw = rrRaw / N;
  const mrrDist = rrDist / N;
  const delta = mrrDist - mrrRaw;
  const compression = totalRawBytes / Math.max(1, totalDistBytes);

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'trajectory-mrr',
    embedder: embedder.name,
    corpusVersion: corpus.version,
    corpusSize: N,
    mrr: {
      raw: Number(mrrRaw.toFixed(4)),
      distilled: Number(mrrDist.toFixed(4)),
      delta: Number(delta.toFixed(4)),
      paperReference: { raw: 0.745, distilled: 0.759, delta: 0.014, source: 'arXiv:2603.13017' },
    },
    compression: {
      totalRawBytes,
      totalDistBytes,
      ratio: Number(compression.toFixed(2)),
      paperReference: { tokensRaw: 371, tokensDistilled: 38, ratio: 9.76, source: 'arXiv:2603.13017' },
    },
    latencyMs: {
      embedAll: Number(embedMs.toFixed(2)),
      queryAll: Number(queryMs.toFixed(2)),
      perDistill: Number((embedMs / (2 * N)).toFixed(4)),
    },
    distilledIsBetter: delta > 0,
    perQueryRanks: perQuery,
  };

  if (process.env.BENCH_JSON) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(`# Trajectory MRR benchmark (#2241 §Structured Distillation)`);
    console.log(`Embedder: ${embedder.name}`);
    console.log(`Corpus: N=${N} (v${corpus.version})`);
    console.log('');
    console.log('| Metric | Raw | Distilled | Δ |');
    console.log('|---|---:|---:|---:|');
    console.log(`| MRR | ${summary.mrr.raw} | ${summary.mrr.distilled} | ${summary.mrr.delta >= 0 ? '+' : ''}${summary.mrr.delta} |`);
    console.log(`| Total bytes | ${totalRawBytes} | ${totalDistBytes} | ${compression.toFixed(2)}× compression |`);
    console.log('');
    console.log(`Distilled is ${summary.distilledIsBetter ? 'BETTER ✅' : 'WORSE ❌'} than raw on this corpus.`);
    console.log(`Paper (arXiv:2603.13017): MRR raw 0.745 → distilled 0.759 (Δ +0.014); compression ~9.76× (371→38 tokens).`);
  }

  if (!process.env.BENCH_NO_WRITE) {
    mkdirSync(RUNS_DIR, { recursive: true });
    const stamp = summary.runAt.replace(/[:.]/g, '-');
    writeFileSync(join(RUNS_DIR, `trajectory-mrr-${stamp}.json`), JSON.stringify(summary, null, 2));
    writeFileSync(join(RUNS_DIR, 'trajectory-mrr-latest.json'), JSON.stringify(summary, null, 2));
    if (!process.env.BENCH_JSON) console.log(`\nWrote ${join(RUNS_DIR, `trajectory-mrr-${stamp}.json`)}`);
  }
}

function rankOf(query, embeddings, goldIndex) {
  const scored = embeddings.map((e, i) => ({ i, score: cosine(query, e) }));
  scored.sort((a, b) => b.score - a.score);
  return scored.findIndex((s) => s.i === goldIndex) + 1;
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// grid-search-retrieval.mjs — sweep retrieval hyperparameters against the
// ADR-081 labelled corpus. Reports label nDCG@3, top-1, top-3, precision@3,
// MRR@3 per configuration. Identifies the best non-rerank and best rerank
// configs by nDCG@3.
//
// Run prerequisites: scripts/pretrain-from-github.mjs first.
//
// Usage:
//   node scripts/grid-search-retrieval.mjs                 # default grid
//   node scripts/grid-search-retrieval.mjs --quick         # smaller grid
//   BENCH_JSON=1 node scripts/grid-search-retrieval.mjs    # machine-readable
//
// Output also goes to docs/benchmarks/runs/grid-search-retrieval-<ts>.json

import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const REPO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(REPO_ROOT, 'docs', 'benchmarks', 'runs');

// Same labelled corpus as benchmark-pretrained-retrieval.mjs (ADR-081).
const QUERIES = [
  { q: 'how was the Opus model alias fixed',
    labels: ['opus 4.8', 'opus alias', 'opus model alias', '#2232'] },
  { q: 'self-learning wiring task-completed pretrain',
    labels: ['self-learning', 'adr-074', 'self learning', '#2245', 'task-completed'] },
  { q: 'deterministic codemod engine var-to-const',
    labels: ['deterministic tier-1 codemod', 'adr-143', 'codemod', 'var-to-const'] },
  { q: 'MCP server orphan leak parent-death',
    labels: ['mcp orphan', 'mcp servers orphan', 'parent-death', '#2234', 'orphan on every claude'] },
  { q: 'unified learning stats aggregator',
    labels: ['unified learning-stats', 'adr-075', 'unified learning stats'] },
  { q: 'structured distillation 4-field schema',
    labels: ['structured distillation', 'adr-076', '4-field schema'] },
  { q: 'SQL injection migrate.ts table identifier',
    labels: ['sql injection', 'shell injection', 'migrate.ts', 'agentdb', 'cve'] },
  { q: 'recall@k HNSW benchmark harness',
    labels: ['hnsw', 'memory-recall', 'benchmark suite', 'recall@k', 'benchmark intelligence'] },
  { q: 'Q-learning encoder keyword block',
    labels: ['q-state encoder', 'route q-state', 'keyword block', '#2239', 'q-encoder'] },
  { q: 'security hardening crypto random IDs',
    labels: ['cwe-347', 'crypto.randomuuid', 'security fix', 'random id', 'crypto random'] },
];

function isRelevant(name, labels) {
  if (!name || !labels?.length) return false;
  const lower = String(name).toLowerCase();
  return labels.some((s) => lower.includes(s.toLowerCase()));
}

function ndcgAtK(rankedRel, k) {
  const arr = rankedRel.slice(0, k);
  const dcg = arr.reduce((acc, rel, i) => acc + (rel ? 1 / Math.log2(i + 2) : 0), 0);
  const numRelevant = arr.filter(Boolean).length;
  if (numRelevant === 0) return 0;
  let idcg = 0;
  for (let i = 0; i < numRelevant; i++) idcg += 1 / Math.log2(i + 2);
  return idcg > 0 ? dcg / idcg : 0;
}

// ---------------------------------------------------------------------------
// Grid definitions
// ---------------------------------------------------------------------------

const QUICK = process.argv.includes('--quick');

// Non-rerank grid: alpha × subjectWeight × mmrLambda
const ALPHA_GRID = QUICK ? [0.5, 0.7] : [0.3, 0.5, 0.7];
const SUBJ_GRID = QUICK ? [3.0, 5.0] : [2.0, 3.0, 5.0];
const MMR_GRID = QUICK ? [0.5] : [0.3, 0.5, 0.7];

// Rerank grid: hybridWeight × ceWeight (sum to 1).
const RERANK_GRID = QUICK
  ? [[0.5, 0.5]]
  : [[0.2, 0.8], [0.3, 0.7], [0.4, 0.6], [0.5, 0.5], [0.6, 0.4], [0.7, 0.3], [0.8, 0.2]];

// ADR-083: when re-gridding rerank, sweep BOTH the hybrid sub-params (alpha, sw)
// AND the rerank weights. This catches joint-optima the per-axis grids miss.
const RERANK_HYBRID_ALPHA = QUICK ? [0.5] : [0.3, 0.5];
const RERANK_HYBRID_SW    = QUICK ? [2.0] : [2.0, 3.0];

// ---------------------------------------------------------------------------
// Eval
// ---------------------------------------------------------------------------

async function evalConfig(tool, params) {
  let top1Hits = 0, top3HitsBin = 0, ranks = [], ndcg3Sum = 0, prec3Sum = 0;
  const tStart = performance.now();
  for (const { q, labels } of QUERIES) {
    const r = await tool.handler({ action: 'search', query: q, mode: 'hybrid', limit: 5, ...params });
    const matches = (r.results || []).slice(0, 5);
    const rel = matches.map((m) => isRelevant(m?.name, labels));
    if (rel[0]) top1Hits++;
    if (rel.slice(0, 3).some(Boolean)) top3HitsBin++;
    const firstRank = rel.findIndex(Boolean);
    if (firstRank >= 0) ranks.push(firstRank + 1);
    ndcg3Sum += ndcgAtK(rel, 3);
    prec3Sum += rel.slice(0, 3).filter(Boolean).length / 3;
  }
  const elapsed = performance.now() - tStart;
  return {
    label_top1HitRate: top1Hits / QUERIES.length,
    label_top3HitRate: top3HitsBin / QUERIES.length,
    label_mrr3: ranks.reduce((s, r) => s + 1 / r, 0) / QUERIES.length,
    label_precision3: prec3Sum / QUERIES.length,
    label_ndcg3: ndcg3Sum / QUERIES.length,
    avgLatencyMs: elapsed / QUERIES.length,
  };
}

async function main() {
  const neural = await import(join(CLI_ROOT, 'dist/src/mcp-tools/neural-tools.js'));
  const tool = neural.neuralTools.find((t) => t.name === 'neural_patterns');
  if (!tool) throw new Error('neural_patterns tool not found');

  const configs = [];

  // §A — non-rerank grid (fast, ~3*3*3 = 27 configs at default)
  for (const alpha of ALPHA_GRID) {
    for (const subjectWeight of SUBJ_GRID) {
      for (const mmrLambda of MMR_GRID) {
        configs.push({
          name: `hybrid α=${alpha} sw=${subjectWeight} mmr=${mmrLambda}`,
          rerank: false,
          params: { rerank: false, alpha, subjectWeight, mmrLambda, bodyWeight: 1.0, typePenaltyFactor: 1.0 },
        });
      }
    }
  }

  // §B — rerank joint grid (ADR-083): hybridWeight × ceWeight × alpha × subjectWeight.
  // Each query takes ~1s with cross-encoder, so default full grid = 28 configs × 10
  // queries × 1s ≈ 5 minutes. Use --quick for 1 config (smoke).
  for (const [hybridWeight, ceWeight] of RERANK_GRID) {
    for (const alpha of RERANK_HYBRID_ALPHA) {
      for (const subjectWeight of RERANK_HYBRID_SW) {
        configs.push({
          name: `rerank hw=${hybridWeight} cw=${ceWeight} α=${alpha} sw=${subjectWeight}`,
          rerank: true,
          params: { rerank: true, alpha, subjectWeight, mmrLambda: 0.7, hybridWeight, ceWeight },
        });
      }
    }
  }

  console.log(`Grid-search: ${configs.length} configs across ${QUERIES.length} queries\n`);
  const results = [];
  for (const cfg of configs) {
    process.stdout.write(`  ${cfg.name.padEnd(40)} … `);
    const m = await evalConfig(tool, cfg.params);
    results.push({ ...cfg, metrics: m });
    console.log(`top1=${(m.label_top1HitRate * 100).toFixed(0)}% top3=${(m.label_top3HitRate * 100).toFixed(0)}% nDCG3=${m.label_ndcg3.toFixed(3)} P3=${m.label_precision3.toFixed(3)} MRR3=${m.label_mrr3.toFixed(3)} ${m.avgLatencyMs.toFixed(0)}ms`);
  }

  // Rank by label nDCG@3 (the canonical relevance metric).
  const byNdcg = [...results].sort((a, b) => b.metrics.label_ndcg3 - a.metrics.label_ndcg3);
  const byTop1 = [...results].sort((a, b) => b.metrics.label_top1HitRate - a.metrics.label_top1HitRate || b.metrics.label_ndcg3 - a.metrics.label_ndcg3);
  const byPrec3 = [...results].sort((a, b) => b.metrics.label_precision3 - a.metrics.label_precision3 || b.metrics.label_ndcg3 - a.metrics.label_ndcg3);

  const bestNonRerankByNdcg = byNdcg.find((r) => !r.rerank);
  const bestRerankByNdcg = byNdcg.find((r) => r.rerank);

  console.log('\n=== Top 5 by label nDCG@3 ===');
  for (const r of byNdcg.slice(0, 5)) {
    console.log(`  nDCG=${r.metrics.label_ndcg3.toFixed(3)}  top1=${(r.metrics.label_top1HitRate * 100).toFixed(0)}%  P3=${r.metrics.label_precision3.toFixed(3)}  ${r.name}`);
  }

  console.log('\n=== Top 5 by label top-1 (ties broken by nDCG) ===');
  for (const r of byTop1.slice(0, 5)) {
    console.log(`  top1=${(r.metrics.label_top1HitRate * 100).toFixed(0)}%  nDCG=${r.metrics.label_ndcg3.toFixed(3)}  P3=${r.metrics.label_precision3.toFixed(3)}  ${r.name}`);
  }

  console.log('\n=== Top 5 by label precision@3 ===');
  for (const r of byPrec3.slice(0, 5)) {
    console.log(`  P3=${r.metrics.label_precision3.toFixed(3)}  top1=${(r.metrics.label_top1HitRate * 100).toFixed(0)}%  nDCG=${r.metrics.label_ndcg3.toFixed(3)}  ${r.name}`);
  }

  console.log(`\n=== WINNERS ===`);
  console.log(`Best non-rerank (by nDCG@3):   ${bestNonRerankByNdcg.name}  → top1=${(bestNonRerankByNdcg.metrics.label_top1HitRate * 100).toFixed(0)}% nDCG=${bestNonRerankByNdcg.metrics.label_ndcg3.toFixed(3)}`);
  console.log(`Best rerank (by nDCG@3):       ${bestRerankByNdcg.name}  → top1=${(bestRerankByNdcg.metrics.label_top1HitRate * 100).toFixed(0)}% nDCG=${bestRerankByNdcg.metrics.label_ndcg3.toFixed(3)}`);

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'grid-search-retrieval',
    queries: QUERIES.length,
    configsEvaluated: configs.length,
    grid: { ALPHA_GRID, SUBJ_GRID, MMR_GRID, RERANK_GRID },
    results: results.map((r) => ({ name: r.name, rerank: r.rerank, params: r.params, metrics: r.metrics })),
    winners: {
      nDcg3: byNdcg[0].name,
      top1: byTop1[0].name,
      precision3: byPrec3[0].name,
      bestNonRerank: bestNonRerankByNdcg.name,
      bestRerank: bestRerankByNdcg.name,
    },
  };

  if (process.env.BENCH_JSON) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    mkdirSync(RUNS_DIR, { recursive: true });
    const stamp = summary.runAt.replace(/[:.]/g, '-');
    writeFileSync(join(RUNS_DIR, `grid-search-retrieval-${stamp}.json`), JSON.stringify(summary, null, 2));
    writeFileSync(join(RUNS_DIR, 'grid-search-retrieval-latest.json'), JSON.stringify(summary, null, 2));
    console.log(`\nWrote ${join(RUNS_DIR, `grid-search-retrieval-${stamp}.json`)}`);
  }

  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
/**
 * @claude-flow/cli postinstall — agentdb compatibility patches.
 *
 * Two patches applied to the user's installed agentdb tree:
 *
 * 1. Sibling directory copy (#1721 fix): agentic-flow's runtime patch
 *    expects agentdb's controllers + utils + core + services + types
 *    at `dist/<name>/` (legacy v1.x layout). agentdb v3 ships at
 *    `dist/src/<name>/`. Copy each `dist/src/<name>/` subdir to
 *    `dist/<name>/` so the legacy import paths resolve. Skip dirs that
 *    already exist so this is idempotent.
 *
 * 2. Exports-field augmentation (ADR-095 G7): six controller files
 *    exist in agentdb's dist but are not declared in its package.json
 *    `exports` field — `AttestationLog`, `MutationGuard`,
 *    `GuardedVectorBackend`, `GNNService`, `RVFOptimizer`,
 *    `GraphAdapter`. Without these declared, Node's strict exports
 *    enforcement blocks subpath imports even when the file is on disk.
 *    We add the missing entries (only if the file actually exists)
 *    so consumers can reach them via `agentdb/controllers/...`.
 *
 * Both patches are best-effort — failure to apply does not break
 * install (try/catch wraps each phase). Re-running is safe.
 */

'use strict';

const fs = require('node:fs');
const path = require('node:path');

function findAgentdbBase() {
  try {
    const r = require.resolve('agentdb');
    if (r.includes('dist/src')) return path.join(path.dirname(r), '..', '..');
    if (r.includes('dist')) return path.join(path.dirname(r), '..');
    return path.dirname(r);
  } catch { return null; }
}

/**
 * Find every agentdb installation reachable in the install's node_modules
 * tree. Necessary because pnpm/npm hoisting can place multiple copies of
 * agentdb (different versions) at different levels. Only patching the
 * resolved one leaves consumer code that imports through a different
 * resolution path with stale exports.
 *
 * Strategy: walk up from the postinstall script's directory, collect any
 * `node_modules/agentdb` we find along the way + the .pnpm cached copies
 * directly under the same node_modules/.pnpm/ root.
 */
function findAllAgentdbBases() {
  const found = new Set();
  let dir = __dirname;
  for (let i = 0; i < 12; i++) {
    const candidate = path.join(dir, 'node_modules', 'agentdb');
    if (fs.existsSync(path.join(candidate, 'package.json'))) {
      try { found.add(fs.realpathSync(candidate)); } catch { found.add(candidate); }
    }
    // Also check for .pnpm cache adjacent to this node_modules
    const pnpmDir = path.join(dir, 'node_modules', '.pnpm');
    if (fs.existsSync(pnpmDir)) {
      try {
        for (const e of fs.readdirSync(pnpmDir)) {
          if (e.startsWith('agentdb@')) {
            const adb = path.join(pnpmDir, e, 'node_modules', 'agentdb');
            if (fs.existsSync(path.join(adb, 'package.json'))) {
              try { found.add(fs.realpathSync(adb)); } catch { found.add(adb); }
            }
          }
        }
      } catch { /* ignore */ }
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return Array.from(found);
}

function copySiblings(base) {
  const srcDist = path.join(base, 'dist', 'src');
  if (!fs.existsSync(srcDist)) return;
  for (const entry of fs.readdirSync(srcDist)) {
    const src = path.join(srcDist, entry);
    const target = path.join(base, 'dist', entry);
    try {
      if (fs.statSync(src).isDirectory() && !fs.existsSync(target)) {
        fs.cpSync(src, target, { recursive: true });
      }
    } catch { /* best-effort */ }
  }
}

function augmentExports(base) {
  const pkgPath = path.join(base, 'package.json');
  if (!fs.existsSync(pkgPath)) return;
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8')); }
  catch { return; }
  if (!pkg.exports || typeof pkg.exports !== 'object') return;

  // Subpath → relative file path (only added if both: (a) file exists, (b) export not already declared)
  const additions = {
    './controllers/AttestationLog': './dist/src/security/AttestationLog.js',
    './controllers/MutationGuard': './dist/src/security/MutationGuard.js',
    './controllers/GuardedVectorBackend': './dist/src/backends/ruvector/GuardedVectorBackend.js',
    // GNNService and RVFOptimizer live outside dist/src/controllers/ in
    // current agentdb. Map to the actual paths so the export points at a
    // real file. Future agentdb versions may move them — the file-exists
    // guard below will skip cleanly if these paths drift.
    './controllers/GNNService': './dist/src/services/GNNService.js',
    './controllers/RVFOptimizer': './dist/src/optimizations/RVFOptimizer.js',
    // GraphAdapter location varies; try the graph-node backend path. If
    // missing, the file-exists guard skips it without error.
    './controllers/GraphAdapter': './dist/src/backends/graph-node/GraphAdapter.js',
    // Also expose the security index so consumers can import the security namespace.
    './security/controllers': './dist/src/security/index.js',
  };

  let changed = false;
  for (const [subpath, target] of Object.entries(additions)) {
    if (pkg.exports[subpath]) continue;
    const abs = path.join(base, target);
    if (!fs.existsSync(abs)) continue;
    pkg.exports[subpath] = target;
    changed = true;
  }

  if (changed) {
    try {
      fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf-8');
    } catch { /* best-effort */ }
  }
}

function main() {
  // Patch every reachable agentdb instance, not just the first resolution
  // result. pnpm/npm hoisting can leave multiple agentdb copies in the
  // install tree, and consumers may import through any of them.
  const bases = findAllAgentdbBases();
  if (bases.length === 0) {
    // Fall back to the single-base path so we still attempt something
    // when the directory walk didn't find anything (e.g. unusual installs).
    const base = findAgentdbBase();
    if (base) bases.push(base);
  }
  for (const base of bases) {
    try { copySiblings(base); } catch { /* phase 1 best-effort */ }
  }
}

main();

#!/usr/bin/env node
// pretrain-from-github.mjs — pretrain ruflo's self-learning system from its
// own GitHub history (commits + issues). Each commit/issue becomes one
// trajectory through the SONA + EWC++ pipeline; Structured Distillation
// (ADR-076) compresses each into the 4-field schema before embedding.
//
// What this proves:
//   - globalStats.{trajectoriesRecorded, patternsLearned, signalsProcessed}
//     all move from a measured before to a measured after.
//   - neural_patterns.patternCount grows.
//   - memory-bridge entries grow.
//   - The unified-stats aggregator's consistency block stays clean.
//   - Every item gets a learningPath of 'trajectory-pipeline' (not 'recorded-only').
//
// Usage:
//   node scripts/pretrain-from-github.mjs                   # 50 commits + 30 issues
//   COMMITS=200 ISSUES=100 node scripts/pretrain-from-github.mjs
//   SOURCE=git node scripts/pretrain-from-github.mjs        # git only, skip gh
//   BENCH_JSON=1 node scripts/pretrain-from-github.mjs      # machine-readable
//   BENCH_NO_WRITE=1 node scripts/pretrain-from-github.mjs  # don't write a run JSON
//
// Repro from a fresh checkout:
//   git clone https://github.com/ruvnet/ruflo && cd ruflo
//   npm install && ( cd v3/@claude-flow/cli && npx tsc -b )
//   node v3/@claude-flow/cli/scripts/pretrain-from-github.mjs

import { execSync } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

// ADR-084 cross-repo support — REPO_ROOT and GH_REPO env-overridable so the
// same script can pretrain on agentdb / agentic-flow / any other repo for
// generalisation testing. Defaults preserve ruflo behaviour.
const REPO_ROOT = process.env.REPO_ROOT ? resolve(process.env.REPO_ROOT) : RUFLO_ROOT;
const GH_REPO   = process.env.GH_REPO   || 'ruvnet/ruflo';

const COMMITS = Number(process.env.COMMITS) || 50;
const ISSUES  = Number(process.env.ISSUES)  || 30;
const SOURCE  = process.env.SOURCE || 'all'; // 'all' | 'git' | 'issues'

// ---------------------------------------------------------------------------
// Harvesters
// ---------------------------------------------------------------------------

// ADR-078 outcome signal — classify each commit by whether it was reverted,
// hotfix-followed, or stuck. Operates on the harvested-commits window plus a
// wider lookahead window for revert/hotfix detection.
//
// Verdicts emitted:
//   success — landed cleanly, no later commit reverted or fixed it
//   reverted — a later commit subject starts with `Revert "<this subject>"`
//   hotfixed — a later commit (within HOTFIX_WINDOW_COMMITS) shares >=50%
//              of the same touched files AND subject contains fix|hotfix|patch
//
// The "later" direction is git-log order (newest first → we look at older
// indices in the lookahead, which are NEWER commits chronologically).
const HOTFIX_WINDOW_COMMITS = Number(process.env.HOTFIX_WINDOW_COMMITS) || 20;
const HOTFIX_FILE_OVERLAP = Number(process.env.HOTFIX_FILE_OVERLAP) || 0.5;
const HOTFIX_KEYWORDS = /\b(fix|hotfix|patch|revert|bugfix|fixup)\b/i;

function harvestCommits(n) {
  if (SOURCE === 'issues') return [];
  const fmt = '%H%x00%s%x00%b%x01';
  // Pull a wider window so we have lookahead for revert/hotfix detection
  // without changing the trained set size n.
  const lookahead = HOTFIX_WINDOW_COMMITS;
  const raw = execSync(
    `git log --pretty=format:'${fmt}' -n ${n + lookahead} 2>/dev/null`,
    { cwd: REPO_ROOT, encoding: 'utf-8', maxBuffer: 64 * 1024 * 1024 },
  );

  // Parse all blocks (window + lookahead).
  const all = [];
  for (const block of raw.split('\x01')) {
    if (!block.trim()) continue;
    const [sha, subject, body] = block.split('\x00');
    if (!sha || !subject) continue;
    all.push({ sha, subject: subject.trim(), body: (body || '').trim() });
  }

  // For each commit in the trained slice, get its touched files.
  const filesCache = new Map();
  const filesOf = (sha) => {
    if (filesCache.has(sha)) return filesCache.get(sha);
    try {
      const out = execSync(
        `git show --pretty=format: --name-only ${sha} 2>/dev/null`,
        { cwd: REPO_ROOT, encoding: 'utf-8', maxBuffer: 8 * 1024 * 1024 },
      ).trim().split('\n').filter(Boolean);
      filesCache.set(sha, new Set(out));
      return filesCache.get(sha);
    } catch {
      filesCache.set(sha, new Set());
      return filesCache.get(sha);
    }
  };

  // Build a revert-target map: any commit whose subject starts with
  // `Revert "<X>"` flags X as reverted.
  const revertedSubjects = new Set();
  for (const c of all) {
    const m = c.subject.match(/^Revert\s+"(.+?)"/);
    if (m) revertedSubjects.add(m[1].trim());
  }

  const trained = all.slice(0, n);
  const entries = [];
  for (let i = 0; i < trained.length; i++) {
    const c = trained[i];
    const myFiles = filesOf(c.sha);

    let verdict = 'success';
    let outcomeNote = null;

    // Reverted? Check if any later (lower-index = newer) commit reverted us.
    if (revertedSubjects.has(c.subject)) {
      verdict = 'reverted';
      outcomeNote = 'subject reverted by a later commit';
    } else {
      // Hotfixed? A later commit within HOTFIX_WINDOW_COMMITS shares files
      // AND has fix/hotfix in its subject.
      const start = Math.max(0, i - HOTFIX_WINDOW_COMMITS);
      for (let j = start; j < i; j++) {
        const later = trained[j];
        if (!HOTFIX_KEYWORDS.test(later.subject)) continue;
        const laterFiles = filesOf(later.sha);
        if (laterFiles.size === 0 || myFiles.size === 0) continue;
        let overlap = 0;
        for (const f of laterFiles) if (myFiles.has(f)) overlap++;
        // Use min() so a small targeted fix on a big change still triggers
        // (semantic: "≥half of the smaller commit's files overlap").
        const overlapFrac = overlap / Math.min(laterFiles.size, myFiles.size);
        if (overlapFrac >= HOTFIX_FILE_OVERLAP) {
          verdict = 'hotfixed';
          outcomeNote = `${(overlapFrac * 100).toFixed(0)}% file overlap with later fix ${later.sha.slice(0, 8)}`;
          break;
        }
      }
    }

    entries.push({
      source: 'commit',
      id: `commit-${c.sha.slice(0, 12)}`,
      subject: c.subject,
      body: c.body,
      verdict,
      outcomeNote,
      content: `${c.subject}\n\n${c.body}`.slice(0, 8192),
    });
  }
  return entries;
}

function harvestIssues(n) {
  if (SOURCE === 'git') return [];
  try {
    const raw = execSync(
      `gh issue list --repo ${GH_REPO} --state all --limit ${n} --json number,title,body,state,closedAt 2>/dev/null`,
      { cwd: REPO_ROOT, encoding: 'utf-8', maxBuffer: 64 * 1024 * 1024 },
    );
    const items = JSON.parse(raw);
    return items.map((i) => ({
      source: 'issue',
      id: `issue-${i.number}`,
      subject: i.title,
      body: (i.body || '').slice(0, 8192),
      // closed = success outcome; open = partial (in-progress).
      verdict: i.state === 'CLOSED' ? 'success' : 'partial',
      content: `${i.title}\n\n${(i.body || '').slice(0, 8192)}`,
    }));
  } catch (err) {
    console.error(`gh issue harvest skipped (${err.message?.slice(0, 60)}). Set SOURCE=git to silence.`);
    return [];
  }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  const intel = await import(join(CLI_ROOT, 'dist/src/memory/intelligence.js'));
  const neural = await import(join(CLI_ROOT, 'dist/src/mcp-tools/neural-tools.js'));
  const { distillAndSerialise } = await import(join(CLI_ROOT, 'dist/src/memory/structured-distill.js'));

  // §1 — record the baseline (no clear; we want to learn ON TOP of whatever
  // history the user already has).
  const unified0 = await intel.getUnifiedLearningStats();
  const before = {
    trajectoriesRecorded: unified0.global.trajectoriesRecorded,
    patternsLearned: unified0.global.patternsLearned,
    signalsProcessed: unified0.global.signalsProcessed,
    neuralPatternCount: unified0.neuralPatterns.patternCount,
    memoryBridgeTotal: unified0.memoryBridge.totalEntries,
  };

  // §2 — harvest
  const tHarvest0 = performance.now();
  const commits = harvestCommits(COMMITS);
  const issues = harvestIssues(ISSUES);
  const items = [...commits, ...issues];
  const harvestMs = performance.now() - tHarvest0;

  if (!process.env.BENCH_JSON) {
    console.log(`# Pretrain from ruflo GitHub history`);
    console.log(`Harvested: ${commits.length} commits + ${issues.length} issues = ${items.length} trajectories (${harvestMs.toFixed(0)} ms)`);
  }

  // §3 — feed each item through the trajectory pipeline. The harvester
  // emits one of: success | partial | reverted | hotfixed. We map this to
  // the trajectory pipeline's binary verdict {success, partial} since the
  // pipeline doesn't accept arbitrary strings — but we preserve the original
  // outcome in metadata + the summary's verdictMix so the signal isn't lost.
  const verdictToPipeline = (v) => {
    if (v === 'success') return 'success';
    if (v === 'partial') return 'partial';
    if (v === 'reverted') return 'partial';   // a revert is the strongest "this was wrong" signal we have
    if (v === 'hotfixed') return 'partial';   // a same-files fix-followup is "needs adjustment"
    return 'success';
  };
  const verdictMix = { success: 0, partial: 0, reverted: 0, hotfixed: 0 };
  const tFeed0 = performance.now();
  let trained = 0;
  let failed = 0;
  const failures = [];
  for (const item of items) {
    try {
      const distilled = distillAndSerialise(item.content);
      verdictMix[item.verdict] = (verdictMix[item.verdict] ?? 0) + 1;
      await intel.recordTrajectory(
        [{
          type: 'result',
          content: distilled,
          metadata: {
            source: item.source,
            id: item.id,
            subject: item.subject.slice(0, 200),
            outcomeVerdict: item.verdict,
            outcomeNote: item.outcomeNote ?? null,
          },
          timestamp: Date.now(),
        }],
        verdictToPipeline(item.verdict),
      );
      trained++;
    } catch (err) {
      failed++;
      if (failures.length < 5) failures.push({ id: item.id, error: String(err.message).slice(0, 120) });
    }
  }
  const feedMs = performance.now() - tFeed0;
  intel.flushIntelligenceStats();

  // §4 — also seed the neural store directly from the same items so
  // `neural_patterns list` reflects them (closes the "globalStats moved but
  // neural_patterns didn't" consistency note from ADR-075).
  const tSeed0 = performance.now();
  const neuralItems = items.map((item) => ({
    name: item.subject.slice(0, 200),
    type: item.source === 'commit' ? 'history-commit' : 'history-issue',
    content: distillAndSerialise(item.content),
    metadata: { source: item.source, id: item.id, verdict: item.verdict },
  }));
  const seedResult = await neural.storeNeuralPatterns(neuralItems);
  const seedMs = performance.now() - tSeed0;

  // §5 — read the after-counters via the unified aggregator (this is what
  // hooks_intelligence_unified-stats would return for a live caller).
  const unified1 = await intel.getUnifiedLearningStats();
  const after = {
    trajectoriesRecorded: unified1.global.trajectoriesRecorded,
    patternsLearned: unified1.global.patternsLearned,
    signalsProcessed: unified1.global.signalsProcessed,
    neuralPatternCount: unified1.neuralPatterns.patternCount,
    memoryBridgeTotal: unified1.memoryBridge.totalEntries,
  };

  const deltas = Object.fromEntries(
    Object.keys(after).map((k) => [k, after[k] - before[k]]),
  );

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'pretrain-from-github',
    source: SOURCE,
    config: { COMMITS, ISSUES },
    harvest: {
      commits: commits.length,
      issues: issues.length,
      total: items.length,
      harvestMs: Number(harvestMs.toFixed(2)),
    },
    feed: {
      trained,
      failed,
      avgLatencyMs: items.length > 0 ? Number((feedMs / items.length).toFixed(2)) : 0,
      totalMs: Number(feedMs.toFixed(2)),
      sampleFailures: failures,
      verdictMix,   // ADR-078 outcome signal — counts per harvested verdict
    },
    seedNeuralStore: {
      stored: seedResult.stored,
      total: seedResult.total,
      seedMs: Number(seedMs.toFixed(2)),
    },
    before,
    after,
    deltas,
    consistency: unified1.consistency,
    passed:
      trained === items.length &&
      deltas.trajectoriesRecorded >= items.length &&
      deltas.neuralPatternCount >= items.length,
  };

  if (process.env.BENCH_JSON) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log('');
    console.log('| Counter | Before | After | Δ |');
    console.log('|---|---:|---:|---:|');
    for (const k of Object.keys(after)) {
      console.log(`| ${k} | ${before[k]} | ${after[k]} | +${deltas[k]} |`);
    }
    console.log('');
    console.log(`Trained via trajectory pipeline: ${trained}/${items.length}`);
    console.log(`Failed: ${failed}`);
    console.log(`Avg latency per trajectory: ${summary.feed.avgLatencyMs} ms`);
    console.log(`Neural store seeded: ${seedResult.stored}/${seedResult.total}`);
    console.log(`Verdict mix: success=${verdictMix.success} partial=${verdictMix.partial} reverted=${verdictMix.reverted} hotfixed=${verdictMix.hotfixed}`);
    console.log(`Overall: ${summary.passed ? '✅ PASSED' : '⚠️  partial'}`);
    if (unified1.consistency.notes.length > 0) {
      console.log(`\nConsistency notes:`);
      for (const n of unified1.consistency.notes) console.log(`  • ${n}`);
    }
  }

  if (!process.env.BENCH_NO_WRITE) {
    mkdirSync(RUNS_DIR, { recursive: true });
    const stamp = summary.runAt.replace(/[:.]/g, '-');
    writeFileSync(join(RUNS_DIR, `pretrain-from-github-${stamp}.json`), JSON.stringify(summary, null, 2));
    writeFileSync(join(RUNS_DIR, 'pretrain-from-github-latest.json'), JSON.stringify(summary, null, 2));
    if (!process.env.BENCH_JSON) console.log(`\nWrote ${join(RUNS_DIR, `pretrain-from-github-${stamp}.json`)}`);
  }

  // ONNX runtime keeps a worker thread alive — force exit so this can be used
  // as a CI step or chained with other scripts.
  process.exit(summary.passed ? 0 : 1);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env npx tsx
/**
 * Plugin Registry Publisher
 *
 * Publishes the plugin registry to IPFS via Pinata and updates IPNS pointer.
 *
 * Setup:
 * 1. Create Pinata account at https://pinata.cloud
 * 2. Generate API keys (JWT)
 * 3. Set environment variables:
 *    - PINATA_JWT: Your Pinata JWT token
 *    - REGISTRY_PRIVATE_KEY: Ed25519 private key (hex) for signing
 *
 * Usage:
 *   npx tsx scripts/publish-registry.ts
 *   npx tsx scripts/publish-registry.ts --dry-run
 *   npx tsx scripts/publish-registry.ts --registry ./custom-registry.json
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Types
interface PluginEntry {
  id: string;
  name: string;
  displayName: string;
  description: string;
  version: string;
  cid?: string;
  size: number;
  checksum: string;
  author: {
    id: string;
    displayName: string;
    verified: boolean;
  };
  license: string;
  categories: string[];
  tags: string[];
  downloads: number;
  rating: number;
  lastUpdated: string;
  minClaudeFlowVersion: string;
  type: string;
  hooks: string[];
  commands: string[];
  permissions: string[];
  exports: string[];
  verified: boolean;
  trustLevel: string;
}

interface PluginRegistry {
  version: string;
  type: 'plugins';
  updatedAt: string;
  ipnsName: string;
  plugins: PluginEntry[];
  categories: Array<{ id: string; name: string; description: string; pluginCount: number }>;
  totalPlugins: number;
  totalDownloads: number;
  featured: string[];
  trending: string[];
  newest: string[];
  official: string[];
  registrySignature?: string;
  registryPublicKey?: string;
}

interface PinataResponse {
  IpfsHash: string;
  PinSize: number;
  Timestamp: string;
}

// Configuration
const PINATA_API_URL = 'https://api.pinata.cloud';
const DEFAULT_REGISTRY_PATH = path.join(__dirname, '../src/plugins/store/registry.json');

// Parse command line arguments
const args = process.argv.slice(2);
const isDryRun = args.includes('--dry-run');
const registryPathArg = args.find(a => a.startsWith('--registry='));
const registryPath = registryPathArg
  ? registryPathArg.split('=')[1]
  : DEFAULT_REGISTRY_PATH;

/**
 * Fetch npm stats for a package
 */
async function fetchNpmStats(packageName: string): Promise<{ downloads: number; version: string } | null> {
  try {
    const downloadsUrl = `https://api.npmjs.org/downloads/point/last-week/${encodeURIComponent(packageName)}`;
    const downloadsRes = await fetch(downloadsUrl, { signal: AbortSignal.timeout(5000) });

    if (!downloadsRes.ok) return null;

    const downloadsData = await downloadsRes.json() as { downloads?: number };

    const packageUrl = `https://registry.npmjs.org/${encodeURIComponent(packageName)}/latest`;
    const packageRes = await fetch(packageUrl, { signal: AbortSignal.timeout(5000) });

    let version = 'unknown';
    if (packageRes.ok) {
      const packageData = await packageRes.json() as { version?: string };
      version = packageData.version || 'unknown';
    }

    return {
      downloads: downloadsData.downloads || 0,
      version,
    };
  } catch {
    return null;
  }
}

/**
 * Sign registry with Ed25519
 */
async function signRegistry(registry: PluginRegistry, privateKeyHex: string): Promise<{
  signature: string;
  publicKey: string;
}> {
  const ed = await import('@noble/ed25519');

  const privateKey = Buffer.from(privateKeyHex, 'hex');
  const publicKey = await ed.getPublicKeyAsync(privateKey);

  // Create a copy without signature fields for signing
  const registryToSign = { ...registry };
  delete registryToSign.registrySignature;
  delete registryToSign.registryPublicKey;

  const message = JSON.stringify(registryToSign);
  const signature = await ed.signAsync(
    new TextEncoder().encode(message),
    privateKey
  );

  return {
    signature: Buffer.from(signature).toString('hex'),
    publicKey: `ed25519:${Buffer.from(publicKey).toString('hex')}`,
  };
}

/**
 * Pin JSON to IPFS via Pinata
 */
async function pinToIPFS(data: unknown, name: string, jwt: string): Promise<PinataResponse> {
  const response = await fetch(`${PINATA_API_URL}/pinning/pinJSONToIPFS`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${jwt}`,
    },
    body: JSON.stringify({
      pinataContent: data,
      pinataMetadata: {
        name,
        keyvalues: {
          type: 'plugin-registry',
          publishedAt: new Date().toISOString(),
        },
      },
      pinataOptions: {
        cidVersion: 1,
      },
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Pinata error: ${response.status} - ${error}`);
  }

  return response.json() as Promise<PinataResponse>;
}

/**
 * Generate a demo registry from npm packages
 */
async function generateRegistry(): Promise<PluginRegistry> {
  console.log('📦 Fetching npm stats for plugins...');

  const officialPackages = [
    '@claude-flow/plugin-agentic-qe',
    '@claude-flow/plugin-prime-radiant',
    '@claude-flow/plugin-gastown-bridge',
    '@claude-flow/security',
    '@claude-flow/claims',
    '@claude-flow/embeddings',
    '@claude-flow/neural',
    '@claude-flow/performance',
    '@claude-flow/plugins',
  ];

  const plugins: PluginEntry[] = [];
  const now = new Date().toISOString();

  for (const pkg of officialPackages) {
    console.log(`  Fetching ${pkg}...`);
    const stats = await fetchNpmStats(pkg);

    plugins.push({
      id: pkg,
      name: pkg,
      displayName: pkg.replace('@claude-flow/plugin-', '').replace('@claude-flow/', ''),
      description: `Official Claude Flow plugin: ${pkg}`,
      version: stats?.version || '0.0.0',
      size: 100000,
      checksum: `sha256:${crypto.randomBytes(32).toString('hex')}`,
      author: {
        id: 'claude-flow-team',
        displayName: 'Claude Flow Team',
        verified: true,
      },
      license: 'MIT',
      categories: ['official'],
      tags: [pkg.split('/').pop() || ''],
      downloads: stats?.downloads || 0,
      rating: 0,
      lastUpdated: now,
      minClaudeFlowVersion: '3.0.0',
      type: 'integration',
      hooks: [],
      commands: [],
      permissions: ['memory', 'filesystem'],
      exports: [],
      verified: true,
      trustLevel: 'official',
    });
  }

  const totalDownloads = plugins.reduce((sum, p) => sum + p.downloads, 0);

  return {
    version: '1.0.0',
    type: 'plugins',
    updatedAt: now,
    ipnsName: '', // Will be set after publishing
    plugins,
    categories: [
      { id: 'official', name: 'Official', description: 'Official Claude Flow plugins', pluginCount: plugins.length },
    ],
    totalPlugins: plugins.length,
    totalDownloads,
    featured: plugins.slice(0, 3).map(p => p.id),
    trending: plugins.sort((a, b) => b.downloads - a.downloads).slice(0, 3).map(p => p.id),
    newest: plugins.slice(-3).map(p => p.id),
    official: plugins.map(p => p.id),
  };
}

/**
 * Main publish function
 */
async function main() {
  console.log('🚀 Plugin Registry Publisher\n');

  // Check environment
  const jwt = process.env.PINATA_JWT;
  const privateKey = process.env.REGISTRY_PRIVATE_KEY;

  if (!jwt) {
    console.error('❌ PINATA_JWT environment variable is required');
    console.log('\nGet your JWT from https://pinata.cloud/keys');
    process.exit(1);
  }

  // Load or generate registry
  let registry: PluginRegistry;

  if (fs.existsSync(registryPath)) {
    console.log(`📄 Loading registry from ${registryPath}`);
    const content = fs.readFileSync(registryPath, 'utf-8');
    registry = JSON.parse(content);
  } else {
    console.log('📄 Generating registry from npm packages...');
    registry = await generateRegistry();
  }

  // Update timestamp
  registry.updatedAt = new Date().toISOString();

  console.log(`\n📊 Registry Stats:`);
  console.log(`   Plugins: ${registry.plugins.length}`);
  console.log(`   Total Downloads: ${registry.totalDownloads.toLocaleString()}`);
  console.log(`   Updated: ${registry.updatedAt}`);

  // Sign registry if private key is available
  if (privateKey) {
    console.log('\n🔐 Signing registry with Ed25519...');
    const { signature, publicKey } = await signRegistry(registry, privateKey);
    registry.registrySignature = signature;
    registry.registryPublicKey = publicKey;
    console.log(`   Public Key: ${publicKey.slice(0, 30)}...`);
  } else {
    console.log('\n⚠️  No REGISTRY_PRIVATE_KEY set, skipping signature');
  }

  if (isDryRun) {
    console.log('\n🔍 Dry run - would publish:');
    console.log(JSON.stringify(registry, null, 2).slice(0, 1000) + '...');
    return;
  }

  // Pin to IPFS
  console.log('\n📌 Pinning to IPFS via Pinata...');
  try {
    const result = await pinToIPFS(registry, 'claude-flow-plugin-registry', jwt);

    console.log('\n✅ Published successfully!');
    console.log(`   CID: ${result.IpfsHash}`);
    console.log(`   Size: ${(result.PinSize / 1024).toFixed(2)} KB`);
    console.log(`\n🌐 Gateway URLs:`);
    console.log(`   https://gateway.pinata.cloud/ipfs/${result.IpfsHash}`);
    console.log(`   https://ipfs.io/ipfs/${result.IpfsHash}`);
