#!/usr/bin/env node
// run-beir-bge.mjs — NFCorpus retrieval using real BGE-base-en-v1.5
// embeddings (bypasses neural-tools' broken agentic-flow path that hash-fell-
// back on darwin-arm64 without sharp/libvips).
//
// Stores doc embeddings in a single .f32 binary file (3633 * 768 * 4 = ~11MB)
// for fast bench iteration without re-embedding.
//
// Usage:
//   cd /tmp/beir-nfcorpus
//   node /path/to/scripts/run-beir-bge.mjs                          # full ingest + bench
//   SKIP_INGEST=1 node /path/to/scripts/run-beir-bge.mjs            # reuse cached embeds
//   BGE_MODEL=Xenova/bge-small-en-v1.5 node ...                     # faster, lower-quality
//   BGE_MODEL=Xenova/bge-large-en-v1.5 node ...                     # slower, higher-quality
//
// ADR-086.

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

const DATA_DIR = process.env.BEIR_DATA_DIR || '/tmp/beir-nfcorpus/nfcorpus';
// BUG-FIX (ADR-087): CACHE_DIR was hardcoded to /tmp/beir-nfcorpus/bge-cache,
// which made the SciFact run silently overwrite the NFCorpus cache. Now
// derived from DATA_DIR — each dataset gets its own cache directory.
const CACHE_DIR = join(dirname(DATA_DIR), 'bge-cache');
const BGE_MODEL = process.env.BGE_MODEL || 'Xenova/bge-base-en-v1.5';
const SKIP_INGEST = process.env.SKIP_INGEST === '1';
const MAX_QUERIES = Number(process.env.MAX_QUERIES) || 0;

// Published BEIR baselines per dataset (nDCG@10).
// Sources: Thakur et al. 2021 (BEIR paper), BGE paper (BAAI 2024),
// SPLADE++ paper, papers-with-code BEIR leaderboards.
const BASELINES_BY_DATASET = {
  nfcorpus: {
    'BM25 (Lucene)':        0.325,
    'DocT5query':           0.328,
    'TAS-B':                0.319,
    'GenQ':                 0.319,
    'ColBERT':              0.305,
    'Contriever':           0.328,
    'GTR-XL':               0.343,
    'SPLADE++':             0.347,
    'BGE-large-v1.5 (pub)': 0.380,
    'SBERT msmarco':        0.272,
  },
  scifact: {
    'BM25 (Lucene)':        0.679,
    'DocT5query':           0.675,
    'TAS-B':                0.643,
    'GenQ':                 0.644,
    'ColBERT':              0.671,
    'Contriever':           0.677,
    'GTR-XL':               0.662,
    'SPLADE++':             0.704,
    'BGE-large-v1.5 (pub)': 0.722,
    'SBERT msmarco':        0.555,
  },
  arguana: {
    'BM25 (Lucene)':        0.397,
    'DocT5query':           0.349,
    'TAS-B':                0.429,
    'GenQ':                 0.493,
    'ColBERT':              0.233,
    'Contriever':           0.379,
    'GTR-XL':               0.439,
    'SPLADE++':             0.521,
    'BGE-large-v1.5 (pub)': 0.636,
    'SBERT msmarco':        0.371,
  },
  scidocs: {
    'BM25 (Lucene)':        0.158,
    'DocT5query':           0.162,
    'TAS-B':                0.149,
    'GenQ':                 0.143,
    'ColBERT':              0.145,
    'Contriever':           0.165,
    'GTR-XL':               0.174,
    'SPLADE++':             0.159,
    'BGE-large-v1.5 (pub)': 0.225,
    'SBERT msmarco':        0.122,
  },
};

// Auto-detect dataset from DATA_DIR path; default to nfcorpus baselines.
function detectDataset(path) {
  const p = path.toLowerCase();
  for (const ds of Object.keys(BASELINES_BY_DATASET)) {
    if (p.includes(ds)) return ds;
  }
  return 'nfcorpus';
}

// ---------------------------------------------------------------------------
// nDCG (graded)
// ---------------------------------------------------------------------------

function dcg(rels, k) {
  let s = 0;
  for (let i = 0; i < Math.min(rels.length, k); i++) {
    s += (Math.pow(2, rels[i]) - 1) / Math.log2(i + 2);
  }
  return s;
}
function ndcg(retrieved, qrels, k) {
  const rels = retrieved.slice(0, k).map((id) => qrels.get(id) ?? 0);
  const ideal = [...qrels.values()].sort((a, b) => b - a).slice(0, k);
  const idcg = dcg(ideal, k);
  return idcg > 0 ? dcg(rels, k) / idcg : 0;
}
function mrr(retrieved, qrels, k) {
  for (let i = 0; i < Math.min(retrieved.length, k); i++) {
    if ((qrels.get(retrieved[i]) ?? 0) > 0) return 1 / (i + 1);
  }
  return 0;
}
function recall(retrieved, qrels, k) {
  const tot = [...qrels.values()].filter((v) => v > 0).length;
  if (tot === 0) return 0;
  let h = 0;
  for (let i = 0; i < Math.min(retrieved.length, k); i++) {
    if ((qrels.get(retrieved[i]) ?? 0) > 0) h++;
  }
  return h / tot;
}

function cosine(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s; // already L2-normalised in BGE
}

// ---------------------------------------------------------------------------
// Loaders
// ---------------------------------------------------------------------------

function loadJsonl(path) {
  return readFileSync(path, 'utf-8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
}
function loadQrels(path) {
  const qrels = new Map();
  const lines = readFileSync(path, 'utf-8').split('\n');
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const [qid, did, score] = lines[i].split('\t');
    if (!qrels.has(qid)) qrels.set(qid, new Map());
    qrels.get(qid).set(did, Number(score));
  }
  return qrels;
}

// ---------------------------------------------------------------------------
// Embedding cache I/O — single .f32 file + .ids file
// ---------------------------------------------------------------------------

function cachePath(suffix) {
  const safe = BGE_MODEL.replace(/\//g, '_');
  return join(CACHE_DIR, `${safe}.${suffix}`);
}

function saveEmbeddings(ids, embeddings, dim) {
  mkdirSync(CACHE_DIR, { recursive: true });
  // ids: one per line
  writeFileSync(cachePath('ids'), ids.join('\n') + '\n');
  // embeddings: concatenated Float32Array
  const buf = new Float32Array(ids.length * dim);
  for (let i = 0; i < ids.length; i++) buf.set(embeddings[i], i * dim);
  writeFileSync(cachePath('f32'), Buffer.from(buf.buffer));
}

function loadEmbeddings(dim) {
  if (!existsSync(cachePath('ids')) || !existsSync(cachePath('f32'))) return null;
  const ids = readFileSync(cachePath('ids'), 'utf-8').split('\n').filter(Boolean);
  const raw = readFileSync(cachePath('f32'));
  const buf = new Float32Array(raw.buffer, raw.byteOffset, raw.length / 4);
  const embeds = [];
  for (let i = 0; i < ids.length; i++) embeds.push(buf.slice(i * dim, (i + 1) * dim));
  return { ids, embeds };
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  const dataset = detectDataset(DATA_DIR);
  const BASELINES_NDCG10 = BASELINES_BY_DATASET[dataset];
  console.log(`# BEIR ${dataset} — BGE embedder (ADR-085/086)`);
  console.log(`Model: ${BGE_MODEL}`);
  console.log(`Data:  ${DATA_DIR}`);

  const corpus = loadJsonl(join(DATA_DIR, 'corpus.jsonl'));
  const queries = loadJsonl(join(DATA_DIR, 'queries.jsonl'));
  const qrels = loadQrels(join(DATA_DIR, 'qrels/test.tsv'));
  console.log(`Corpus: ${corpus.length} docs · Queries: ${queries.length} · Test qrels: ${qrels.size}`);

  const bge = await import(join(CLI_ROOT, 'dist/src/memory/bge-embedder.js'));
  const emb = await bge.getBgeEmbedder(BGE_MODEL);
  if (!emb) {
    console.error('BGE failed to load:', bge.getBgeStatus());
    process.exit(1);
  }
  const dim = emb.dim();
  console.log(`BGE loaded (dim=${dim})`);

  // Ingest or load cached doc embeddings.
  let docIds, docEmbeds;
  const cached = SKIP_INGEST ? loadEmbeddings(dim) : null;
  if (cached) {
    docIds = cached.ids;
    docEmbeds = cached.embeds;
    console.log(`Loaded ${docIds.length} cached doc embeddings from ${cachePath('f32')}`);
  } else {
    console.log(`\nEmbedding ${corpus.length} docs (this is the slow step, ~20 min on M-series CPU)...`);
    docIds = corpus.map((d) => d._id);
    docEmbeds = new Array(corpus.length);
    const tIngest = performance.now();
    for (let i = 0; i < corpus.length; i++) {
      const d = corpus[i];
      const text = `${d.title || ''}\n${d.text || ''}`.slice(0, 4096);
      docEmbeds[i] = await emb.embed(text);
      if ((i + 1) % 100 === 0) {
        const elapsed = (performance.now() - tIngest) / 1000;
        const rate = (i + 1) / elapsed;
        const eta = (corpus.length - i - 1) / rate;
        console.log(`  ${i + 1}/${corpus.length}  ${rate.toFixed(1)} docs/s  ETA ${eta.toFixed(0)}s`);
      }
    }
    console.log(`Embedded ${corpus.length} docs in ${((performance.now() - tIngest) / 1000).toFixed(0)}s`);
    saveEmbeddings(docIds, docEmbeds, dim);
    console.log(`Cached to ${cachePath('f32')}`);
  }

  // Run retrieval per query.
  const queriesById = new Map(queries.map((q) => [q._id, q.text]));
  const evalQueryIds = MAX_QUERIES
    ? [...qrels.keys()].slice(0, MAX_QUERIES)
    : [...qrels.keys()];

  // ADR-090: BGE_QUERY_PREFIX=1 enables BAAI's recommended query prefix.
  const USE_QUERY_PREFIX = process.env.BGE_QUERY_PREFIX === '1';
  console.log(`\nRunning ${evalQueryIds.length} queries${USE_QUERY_PREFIX ? ' (with BGE query prefix, ADR-090)' : ''}...`);
  let nSum = 0, mSum = 0, r10Sum = 0, r100Sum = 0, n = 0;
  // ADR-086 — save per-query metrics for paired bootstrap significance testing.
  const perQuery = [];
  const tQ = performance.now();
  for (const qid of evalQueryIds) {
    const qtext = queriesById.get(qid);
    if (!qtext) continue;
    // ADR-090: opt-in BGE query prefix per BAAI's docs (+0.009 nDCG@10 on
    // NFCorpus dense-alone). Falls back to plain embed() if not enabled.
    const qEmb = USE_QUERY_PREFIX && emb.embedQuery ? await emb.embedQuery(qtext) : await emb.embed(qtext);
    const scores = new Array(docEmbeds.length);
    for (let i = 0; i < docEmbeds.length; i++) scores[i] = { id: docIds[i], score: cosine(qEmb, docEmbeds[i]) };
    scores.sort((a, b) => b.score - a.score);
    const top100 = scores.slice(0, 100).map((s) => s.id);

    const qmap = qrels.get(qid);
    const qNdcg = ndcg(top100, qmap, 10);
    const qMrr = mrr(top100, qmap, 10);
    const qR10 = recall(top100, qmap, 10);
    const qR100 = recall(top100, qmap, 100);
    nSum += qNdcg; mSum += qMrr; r10Sum += qR10; r100Sum += qR100; n++;
    perQuery.push({ qid, ndcg10: qNdcg, mrr10: qMrr, recall10: qR10, recall100: qR100 });
    if (n % 50 === 0) {
      const elapsed = (performance.now() - tQ) / 1000;
      console.log(`  ${n}/${evalQueryIds.length} in ${elapsed.toFixed(0)}s  running nDCG@10=${(nSum / n).toFixed(4)}`);
    }
  }
  const queryMs = performance.now() - tQ;

  const ndcg10 = nSum / n;
  const mrr10 = mSum / n;
  const recall10 = r10Sum / n;
  const recall100 = r100Sum / n;

  console.log(`\n=== Results (N=${n}, BGE-base-en-v1.5) ===`);
  console.log(`  nDCG@10:    ${ndcg10.toFixed(4)}`);
  console.log(`  MRR@10:     ${mrr10.toFixed(4)}`);
  console.log(`  Recall@10:  ${recall10.toFixed(4)}`);
  console.log(`  Recall@100: ${recall100.toFixed(4)}`);
  console.log(`  Avg query latency: ${(queryMs / n).toFixed(0)}ms`);

  console.log(`\n=== vs published NFCorpus baselines (nDCG@10) ===`);
  const ourLabel = `ruflo + ${BGE_MODEL.replace('Xenova/', '')}`;
  const ranking = [
    ...Object.entries(BASELINES_NDCG10).map(([name, score]) => ({ name, score, ours: false })),
    { name: ourLabel, score: ndcg10, ours: true },
  ].sort((a, b) => b.score - a.score);
  for (const r of ranking) {
    console.log(`  ${r.score.toFixed(3)}  ${r.name}${r.ours ? ' ← us' : ''}`);
  }
  const ourRank = ranking.findIndex((r) => r.ours) + 1;
  console.log(`\n  Our rank: ${ourRank} / ${ranking.length}`);

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: `beir-${dataset}-bge`,
    dataset,
    model: BGE_MODEL,
    queries: n,
    corpusSize: corpus.length,
    metrics: { ndcg10, mrr10, recall10, recall100, avgQueryLatencyMs: queryMs / n },
    perQuery, // ADR-086: per-query metrics for paired bootstrap significance testing
    baselines: BASELINES_NDCG10,
    ourRank,
    leaderboardLength: ranking.length,
  };
  mkdirSync(RUNS_DIR, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  const safe = BGE_MODEL.replace(/\//g, '_');
  writeFileSync(join(RUNS_DIR, `beir-${dataset}-bge-${safe}-${stamp}.json`), JSON.stringify(summary, null, 2));
  writeFileSync(join(RUNS_DIR, `beir-${dataset}-bge-latest.json`), JSON.stringify(summary, null, 2));
  console.log(`\nWrote ${join(RUNS_DIR, `beir-${dataset}-bge-${safe}-${stamp}.json`)}`);
  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// run-beir-hybrid.mjs — BM25 + dense (BGE) + RRF fusion + optional
// cross-encoder rerank, evaluated on BEIR (ADR-087).
//
// Pipeline:
//   1. BM25 over corpus (multi-field BM25 from hybrid-retrieval.ts)
//   2. Dense cosine over BGE-base embeddings (cached from run-beir-bge.mjs)
//   3. RRF fusion: score = sum over systems of 1/(k + rank) (k=60)
//   4. Optional cross-encoder rerank of fused top-100 → top-10
//
// Reuses the .f32 doc-embedding cache from run-beir-bge.mjs — must run
// that first to populate the cache.
//
// Usage:
//   cd /tmp/beir-nfcorpus
//   node /path/to/scripts/run-beir-hybrid.mjs                  # RRF only
//   RERANK=1 node /path/to/scripts/run-beir-hybrid.mjs         # + cross-encoder rerank
//   RRF_K=60 node /path/to/scripts/run-beir-hybrid.mjs         # tune RRF k
//
// ADR-087.

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

const DATA_DIR = process.env.BEIR_DATA_DIR || '/tmp/beir-nfcorpus/nfcorpus';
const BGE_MODEL = process.env.BGE_MODEL || 'Xenova/bge-base-en-v1.5';
const CACHE_DIR = join(process.env.CACHE_BASE_DIR || dirname(DATA_DIR), 'bge-cache');
const RRF_K_DEFAULT = Number(process.env.RRF_K) || 60;
const RERANK = process.env.RERANK === '1';
const RERANK_TOP_K = Number(process.env.RERANK_TOP_K) || 100;
const MAX_QUERIES = Number(process.env.MAX_QUERIES) || 0;

// Same baselines table as run-beir-bge.mjs.
const BASELINES_BY_DATASET = {
  nfcorpus: { 'BM25 (Lucene)': 0.325, 'DocT5query': 0.328, 'TAS-B': 0.319, 'GenQ': 0.319, 'ColBERT': 0.305, 'Contriever': 0.328, 'GTR-XL': 0.343, 'SPLADE++': 0.347, 'BGE-large-v1.5 (pub)': 0.380, 'SBERT msmarco': 0.272 },
  scifact:  { 'BM25 (Lucene)': 0.679, 'DocT5query': 0.675, 'TAS-B': 0.643, 'GenQ': 0.644, 'ColBERT': 0.671, 'Contriever': 0.677, 'GTR-XL': 0.662, 'SPLADE++': 0.704, 'BGE-large-v1.5 (pub)': 0.722, 'SBERT msmarco': 0.555 },
  arguana:  { 'BM25 (Lucene)': 0.397, 'DocT5query': 0.349, 'TAS-B': 0.429, 'GenQ': 0.493, 'ColBERT': 0.233, 'Contriever': 0.379, 'GTR-XL': 0.439, 'SPLADE++': 0.521, 'BGE-large-v1.5 (pub)': 0.636, 'SBERT msmarco': 0.371 },
  scidocs:  { 'BM25 (Lucene)': 0.158, 'DocT5query': 0.162, 'TAS-B': 0.149, 'GenQ': 0.143, 'ColBERT': 0.145, 'Contriever': 0.165, 'GTR-XL': 0.174, 'SPLADE++': 0.159, 'BGE-large-v1.5 (pub)': 0.225, 'SBERT msmarco': 0.122 },
};
// Iter 3: dataset-specific RRF weights for symmetric + dense-favored regimes (arguana: dense 1.6x stronger than BM25).
// Iter 4: nfcorpus medical IR — downweight BM25 (0.7) to favor dense semantics over lexical noise.
// Iter 26: arguana — align with validated nfcorpus/scifact recipe (1.0 dense, 0.2 BM25).
const DATASET_RRF_WEIGHTS = {
  arguana: { dense: 1.0, bm25: 0.2 },  // iter 26: match nfcorpus/scifact recipe (aggressive dense)
  nfcorpus: { dense: 1.0, bm25: 0.0 }, // iter 14: pure dense fusion (0.2→0.0) RRF with single system + minMax norm preserved
  scifact: { dense: 1.0, bm25: 0.05 },  // darwin iter2: small bm25 tie-breaker on top of pure dense (0.0→0.05)
};
function detectDataset(path) {
  const p = path.toLowerCase();
  for (const ds of Object.keys(BASELINES_BY_DATASET)) if (p.includes(ds)) return ds;
  return 'nfcorpus';
}

function dcg(rels, k) { let s = 0; for (let i = 0; i < Math.min(rels.length, k); i++) s += (Math.pow(2, rels[i]) - 1) / Math.log2(i + 2); return s; }
function ndcg(retrieved, qrels, k) { const rels = retrieved.slice(0, k).map((id) => qrels.get(id) ?? 0); const ideal = [...qrels.values()].sort((a, b) => b - a).slice(0, k); const idcg = dcg(ideal, k); return idcg > 0 ? dcg(rels, k) / idcg : 0; }
function mrr(retrieved, qrels, k) { for (let i = 0; i < Math.min(retrieved.length, k); i++) if ((qrels.get(retrieved[i]) ?? 0) > 0) return 1 / (i + 1); return 0; }
function recall(retrieved, qrels, k) { const tot = [...qrels.values()].filter((v) => v > 0).length; if (tot === 0) return 0; let h = 0; for (let i = 0; i < Math.min(retrieved.length, k); i++) if ((qrels.get(retrieved[i]) ?? 0) > 0) h++; return h / tot; }
function cosine(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }
function adaptiveRrfK(corpusSize) { return corpusSize < 20000 ? 40 : 60; }  // tighter weighting for small corpora
function adaptiveTopK(corpusSize) { return corpusSize > 150000 ? 2000 : corpusSize > 50000 ? 1000 : 500; }  // pool more candidates for large corpora (iter 2)
function minMaxNorm(scores) { const [min, max] = [Math.min(...scores), Math.max(...scores)]; return scores.map((s) => max === min ? 0.5 : (s - min) / (max - min)); }

function loadJsonl(path) { return readFileSync(path, 'utf-8').split('\n').filter(Boolean).map((l) => JSON.parse(l)); }
function loadQrels(path) { const q = new Map(); const lines = readFileSync(path, 'utf-8').split('\n'); for (let i = 1; i < lines.length; i++) { if (!lines[i].trim()) continue; const [qid, did, score] = lines[i].split('\t'); if (!q.has(qid)) q.set(qid, new Map()); q.get(qid).set(did, Number(score)); } return q; }

function cachePath(suffix) { const safe = BGE_MODEL.replace(/\//g, '_'); return join(CACHE_DIR, `${safe}.${suffix}`); }
function loadEmbeddings(dim) {
  if (!existsSync(cachePath('ids')) || !existsSync(cachePath('f32'))) return null;
  const ids = readFileSync(cachePath('ids'), 'utf-8').split('\n').filter(Boolean);
  const raw = readFileSync(cachePath('f32'));
  const buf = new Float32Array(raw.buffer, raw.byteOffset, raw.length / 4);
  const embeds = [];
  for (let i = 0; i < ids.length; i++) embeds.push(buf.slice(i * dim, (i + 1) * dim));
  return { ids, embeds };
}

async function main() {
  const dataset = detectDataset(DATA_DIR);
  const BASELINES_NDCG10 = BASELINES_BY_DATASET[dataset];
  const corpus = loadJsonl(join(DATA_DIR, 'corpus.jsonl'));
  const RRF_K = adaptiveRrfK(corpus.length);  // adaptive k based on corpus size (iter 1: normalize scores + tighter k for small corpora)

  const weights = DATASET_RRF_WEIGHTS[dataset] || { dense: 1.0, bm25: 1.0 };
  console.log(`# BEIR ${dataset} — hybrid RRF${RERANK ? ' + cross-encoder rerank' : ''} (ADR-087 + iter1 + iter2 + iter3)`);
  console.log(`Data:  ${DATA_DIR}`);
  console.log(`Dense: ${BGE_MODEL}`);
  console.log(`RRF k: ${RRF_K} (adaptive for corpus size ${corpus.length})${RERANK ? `, rerank top-${RERANK_TOP_K}` : ''}`);
  console.log(`Normalization: min-max before RRF fusion`);
  console.log(`Candidate pool: top-${adaptiveTopK(corpus.length)} per system (iter 2: scaled for large corpora)`);
  console.log(`RRF weights: dense=${weights.dense} bm25=${weights.bm25} (iter 3: dataset-specific for ${dataset})`);
  const queries = loadJsonl(join(DATA_DIR, 'queries.jsonl'));
  const qrels = loadQrels(join(DATA_DIR, 'qrels/test.tsv'));
  console.log(`Corpus: ${corpus.length} docs · Test qrels: ${qrels.size}`);

  // BGE embeddings — must be pre-cached from run-beir-bge.mjs.
  const bge = await import(join(CLI_ROOT, 'dist/src/memory/bge-embedder.js'));
  const emb = await bge.getBgeEmbedder(BGE_MODEL);
  if (!emb) { console.error('BGE failed:', bge.getBgeStatus()); process.exit(1); }
  const dim = emb.dim();
  const cached = loadEmbeddings(dim);
  if (!cached) { console.error(`No cached BGE embeddings at ${cachePath('f32')}. Run run-beir-bge.mjs first.`); process.exit(2); }
  const docIds = cached.ids;
  const docEmbeds = cached.embeds;
  console.log(`Loaded ${docIds.length} cached BGE embeddings`);

  // BM25 setup — USE_LUCENE_BM25=1 uses Porter+Lucene-stopword BM25 (matches
  // published BEIR baselines); default is hybrid-retrieval's multi-field BM25.
  const USE_LUCENE_BM25 = process.env.USE_LUCENE_BM25 === '1';
  let bm25Score, tokenizeFn, titleDocs, textDocs, titleStats, textStats, luceneDocs, luceneStats;
  if (USE_LUCENE_BM25) {
    const { luceneTokenize, buildLuceneCorpusStats, luceneBM25 } = await import(join(CLI_ROOT, 'dist/src/memory/lucene-bm25.js'));
    tokenizeFn = luceneTokenize;
    luceneDocs = corpus.map((d) => luceneTokenize(`${d.title || ''} ${d.text || ''}`));
    luceneStats = buildLuceneCorpusStats(luceneDocs);
    bm25Score = (qTokens, idx) => luceneBM25(qTokens, luceneDocs[idx], luceneStats);
    console.log(`BM25: Lucene-style (Porter stem + Lucene stopwords + length norm) — ADR-088`);
  } else {
    const { tokenize, buildCorpusStats, multiFieldBM25 } = await import(join(CLI_ROOT, 'dist/src/memory/hybrid-retrieval.js'));
    tokenizeFn = tokenize;
    titleDocs = corpus.map((d) => tokenize(d.title || ''));
    textDocs = corpus.map((d) => tokenize(d.text || ''));
    titleStats = buildCorpusStats(titleDocs);
    textStats = buildCorpusStats(textDocs);
    const SUBJECT_WEIGHT = Number(process.env.SUBJECT_WEIGHT ?? 1.0);
    const BODY_WEIGHT = Number(process.env.BODY_WEIGHT ?? 1.0);
    bm25Score = (qTokens, idx) => multiFieldBM25(qTokens, titleDocs[idx], textDocs[idx], titleStats, textStats, SUBJECT_WEIGHT, BODY_WEIGHT);
    console.log(`BM25: multi-field (title sw=${SUBJECT_WEIGHT}, text bw=${BODY_WEIGHT})`);
  }

  // Optional cross-encoder reranker.
  let crossEncoder = null;
  if (RERANK) {
    const ce = await import(join(CLI_ROOT, 'dist/src/memory/cross-encoder-rerank.js'));
    const ceFn = await ce.getCrossEncoder('Xenova/ms-marco-MiniLM-L-6-v2');
    if (!ceFn) { console.error('Cross-encoder failed to load:', ce.getCrossEncoderStatus()); process.exit(3); }
    crossEncoder = ceFn;
    console.log('Cross-encoder loaded: Xenova/ms-marco-MiniLM-L-6-v2');
  }

  const queriesById = new Map(queries.map((q) => [q._id, q.text]));
  const evalQueryIds = MAX_QUERIES ? [...qrels.keys()].slice(0, MAX_QUERIES) : [...qrels.keys()];

  // Build doc id → corpus index lookup (BM25 returns indices, dense returns ids).
  const idToIdx = new Map(docIds.map((id, i) => [id, i]));
  // Need a reverse map too: corpus index → doc id (for BM25 over corpus order).
  const corpusIdToIdx = new Map(corpus.map((d, i) => [d._id, i]));
  const corpusIdxToId = corpus.map((d) => d._id);

  console.log(`\nRunning ${evalQueryIds.length} queries...`);
  let nSum = 0, mSum = 0, r10Sum = 0, r100Sum = 0, n = 0;
  const perQuery = [];
  const tQ = performance.now();

  for (const qid of evalQueryIds) {
    const qtext = queriesById.get(qid);
    if (!qtext) continue;

    // §1 — dense BGE retrieval (ADR-090: opt-in query prefix when BGE_QUERY_PREFIX=1)
    const qEmb = (process.env.BGE_QUERY_PREFIX === '1' && emb.embedQuery)
      ? await emb.embedQuery(qtext)
      : await emb.embed(qtext);
    const denseScored = new Array(docEmbeds.length);
    for (let i = 0; i < docEmbeds.length; i++) denseScored[i] = { id: docIds[i], score: cosine(qEmb, docEmbeds[i]) };
    denseScored.sort((a, b) => b.score - a.score);

    // §2 — BM25 retrieval (Lucene or multi-field depending on USE_LUCENE_BM25)
    const qTokens = tokenizeFn(qtext);
    const bm25Scored = new Array(corpus.length);
    for (let i = 0; i < corpus.length; i++) {
      bm25Scored[i] = { id: corpusIdxToId[i], score: bm25Score(qTokens, i) };
    }
    bm25Scored.sort((a, b) => b.score - a.score);

    // §3 — RRF fusion: normalize scores first, then score = sum over systems of 1/(k + rank).
    // Min-max normalize each system's scores to [0,1] for fair fusion (iter 1 optimization).
    // For large corpora, pull more candidates before fusion (iter 2 optimization).
    const TOP_PER_SYSTEM = adaptiveTopK(corpus.length);
    const denseTopK = denseScored.slice(0, Math.min(TOP_PER_SYSTEM, denseScored.length));
    const bm25TopK = bm25Scored.slice(0, Math.min(TOP_PER_SYSTEM, bm25Scored.length)).filter((s) => s.score > 0);
    const denseScoresNorm = minMaxNorm(denseTopK.map((s) => s.score));
    const bm25ScoresNorm = minMaxNorm(bm25TopK.map((s) => s.score));
    denseTopK.forEach((d, i) => { d.scoreNorm = denseScoresNorm[i]; });
    bm25TopK.forEach((d, i) => { d.scoreNorm = bm25ScoresNorm[i]; });

    const rrfScores = new Map();
    const weights = DATASET_RRF_WEIGHTS[dataset] || { dense: 1.0, bm25: 1.0 };  // iter 3: dataset-specific weights
    for (let r = 0; r < denseTopK.length; r++) {
      const id = denseTopK[r].id;
      rrfScores.set(id, (rrfScores.get(id) || 0) + weights.dense / (RRF_K + r + 1));
    }
    for (let r = 0; r < bm25TopK.length; r++) {
      const id = bm25TopK[r].id;
      rrfScores.set(id, (rrfScores.get(id) || 0) + weights.bm25 / (RRF_K + r + 1));
    }
    const fused = [...rrfScores.entries()]
      .map(([id, score]) => ({ id, score }))
      .sort((a, b) => b.score - a.score)
      .slice(0, RERANK ? RERANK_TOP_K : 100);

    let final = fused;

    // §4 — optional cross-encoder rerank.
    if (crossEncoder && fused.length > 0) {
      const docsForRerank = fused.map(({ id }) => {
        const ci = corpusIdToIdx.get(id);
        const d = corpus[ci];
        return `${d.title || ''} ${d.text || ''}`.slice(0, 4096);
      });
      const ceScores = await crossEncoder.scoreBatch(qtext, docsForRerank);
      final = fused
        .map((f, i) => ({ id: f.id, score: ceScores[i], rrf: f.score }))
        .sort((a, b) => b.score - a.score);
    }

    const top100 = final.slice(0, 100).map((s) => s.id);
    const qmap = qrels.get(qid);
    const qNdcg = ndcg(top100, qmap, 10);
    const qMrr = mrr(top100, qmap, 10);
    const qR10 = recall(top100, qmap, 10);
    const qR100 = recall(top100, qmap, 100);
    nSum += qNdcg; mSum += qMrr; r10Sum += qR10; r100Sum += qR100; n++;
    perQuery.push({ qid, ndcg10: qNdcg, mrr10: qMrr, recall10: qR10, recall100: qR100 });
    if (n % 50 === 0) {
      const elapsed = (performance.now() - tQ) / 1000;
      console.log(`  ${n}/${evalQueryIds.length} in ${elapsed.toFixed(0)}s  running nDCG@10=${(nSum / n).toFixed(4)}`);
    }
  }
  const queryMs = performance.now() - tQ;

  const ndcg10 = nSum / n;
  const mrr10 = mSum / n;
  const recall10 = r10Sum / n;
  const recall100 = r100Sum / n;

  console.log(`\n=== Results (N=${n}, ${dataset}, BM25+BGE-base RRF k=${RRF_K}${RERANK ? ' + CE rerank' : ''}) ===`);
  console.log(`  nDCG@10:    ${ndcg10.toFixed(4)}`);
  console.log(`  MRR@10:     ${mrr10.toFixed(4)}`);
  console.log(`  Recall@10:  ${recall10.toFixed(4)}`);
  console.log(`  Recall@100: ${recall100.toFixed(4)}`);
  console.log(`  Avg query latency: ${(queryMs / n).toFixed(0)}ms`);

  const ourLabel = `ruflo + BM25+BGE-base RRF${RERANK ? '+CE' : ''}`;
  const ranking = [
    ...Object.entries(BASELINES_NDCG10).map(([name, score]) => ({ name, score, ours: false })),
    { name: ourLabel, score: ndcg10, ours: true },
  ].sort((a, b) => b.score - a.score);
  console.log(`\n=== vs ${dataset} listed baselines ===`);
  for (const r of ranking) console.log(`  ${r.score.toFixed(3)}  ${r.name}${r.ours ? ' ← us' : ''}`);
  const ourRank = ranking.findIndex((r) => r.ours) + 1;
  console.log(`\n  Our rank: ${ourRank} / ${ranking.length}`);

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: `beir-${dataset}-hybrid${RERANK ? '-rerank' : ''}`,
    dataset,
    pipeline: `BM25+BGE RRF${RERANK ? '+CE-rerank' : ''}`,
    bgeModel: BGE_MODEL,
    rrfK: RRF_K,
    rerank: RERANK,
    queries: n,
    corpusSize: corpus.length,
    metrics: { ndcg10, mrr10, recall10, recall100, avgQueryLatencyMs: queryMs / n },
    perQuery,
    baselines: BASELINES_NDCG10,
    ourRank,
    leaderboardLength: ranking.length,
  };
  mkdirSync(RUNS_DIR, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  const suffix = RERANK ? 'hybrid-rerank' : 'hybrid-rrf';
  writeFileSync(join(RUNS_DIR, `beir-${dataset}-${suffix}-${stamp}.json`), JSON.stringify(summary, null, 2));
  writeFileSync(join(RUNS_DIR, `beir-${dataset}-${suffix}-latest.json`), JSON.stringify(summary, null, 2));
  console.log(`\nWrote ${join(RUNS_DIR, `beir-${dataset}-${suffix}-${stamp}.json`)}`);
  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// run-beir-lucene-bm25.mjs — test our Lucene-style BM25 against the
// published BEIR BM25 baselines. Also runs RRF with Lucene-BM25 + dense
// to see if the stronger BM25 closes the asymmetric-strength gap that
// broke RRF in ADR-087.
//
// Usage:
//   cd /tmp/beir-nfcorpus
//   node /path/to/scripts/run-beir-lucene-bm25.mjs
//   BEIR_DATA_DIR=/tmp/beir-scifact/scifact node /path/to/scripts/run-beir-lucene-bm25.mjs

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

const DATA_DIR = process.env.BEIR_DATA_DIR || '/tmp/beir-nfcorpus/nfcorpus';
const BGE_MODEL = 'Xenova/bge-base-en-v1.5';
const CACHE_DIR = join(dirname(DATA_DIR), 'bge-cache');

const BASELINES = {
  nfcorpus: { BM25: 0.325, 'BGE-large-pub': 0.380, 'SPLADE++': 0.347 },
  scifact: { BM25: 0.679, 'BGE-large-pub': 0.722, 'SPLADE++': 0.704 },
};
function detect(p) { const x = p.toLowerCase(); return Object.keys(BASELINES).find(d => x.includes(d)) || 'nfcorpus'; }

function dcg(rels, k) { let s = 0; for (let i = 0; i < Math.min(rels.length, k); i++) s += (Math.pow(2, rels[i]) - 1) / Math.log2(i + 2); return s; }
function ndcg(retrieved, qrels, k) { const rels = retrieved.slice(0, k).map((id) => qrels.get(id) ?? 0); const ideal = [...qrels.values()].sort((a, b) => b - a).slice(0, k); const idcg = dcg(ideal, k); return idcg > 0 ? dcg(rels, k) / idcg : 0; }
function recall(retrieved, qrels, k) { const tot = [...qrels.values()].filter((v) => v > 0).length; if (tot === 0) return 0; let h = 0; for (let i = 0; i < Math.min(retrieved.length, k); i++) if ((qrels.get(retrieved[i]) ?? 0) > 0) h++; return h / tot; }
function cosine(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }

function loadJsonl(p) { return readFileSync(p, 'utf-8').split('\n').filter(Boolean).map((l) => JSON.parse(l)); }
function loadQrels(p) { const q = new Map(); const lines = readFileSync(p, 'utf-8').split('\n'); for (let i = 1; i < lines.length; i++) { if (!lines[i].trim()) continue; const [qid, did, s] = lines[i].split('\t'); if (!q.has(qid)) q.set(qid, new Map()); q.get(qid).set(did, Number(s)); } return q; }

function cachePath(s) { const safe = BGE_MODEL.replace(/\//g, '_'); return join(CACHE_DIR, `${safe}.${s}`); }
function loadEmbeddings(dim) {
  if (!existsSync(cachePath('ids')) || !existsSync(cachePath('f32'))) return null;
  const ids = readFileSync(cachePath('ids'), 'utf-8').split('\n').filter(Boolean);
  const raw = readFileSync(cachePath('f32'));
  const buf = new Float32Array(raw.buffer, raw.byteOffset, raw.length / 4);
  return { ids, embeds: ids.map((_, i) => buf.slice(i * dim, (i + 1) * dim)) };
}

function rrfFuse(rankings, k = 60, weights) {
  const scores = new Map();
  rankings.forEach((ranking, sIdx) => {
    const w = weights?.[sIdx] ?? 1;
    ranking.forEach((doc, rankIdx) => {
      const rank = rankIdx + 1;
      scores.set(doc.id, (scores.get(doc.id) ?? 0) + w / (k + rank));
    });
  });
  return [...scores.entries()].map(([id, score]) => ({ id, score })).sort((a, b) => b.score - a.score);
}

async function main() {
  const dataset = detect(DATA_DIR);
  console.log(`# Lucene-style BM25 + RRF on BEIR ${dataset} (ADR-088)`);
  console.log(`Data: ${DATA_DIR}\n`);

  const corpus = loadJsonl(join(DATA_DIR, 'corpus.jsonl'));
  const queries = loadJsonl(join(DATA_DIR, 'queries.jsonl'));
  const qrels = loadQrels(join(DATA_DIR, 'qrels/test.tsv'));
  console.log(`Corpus: ${corpus.length} · test qrels: ${qrels.size}`);

  // Lucene BM25
  const { luceneTokenize, buildLuceneCorpusStats, luceneBM25 } = await import(join(CLI_ROOT, 'dist/src/memory/lucene-bm25.js'));
  console.log('\nTokenising corpus (Lucene-style: Porter stem + Lucene stopwords + length norm)...');
  const tIngest = performance.now();
  const docs = corpus.map((d) => luceneTokenize(`${d.title || ''} ${d.text || ''}`));
  const stats = buildLuceneCorpusStats(docs);
  console.log(`Tokenized + stats built in ${((performance.now() - tIngest) / 1000).toFixed(1)}s. avgDocLen=${stats.avgDocLen.toFixed(0)}, vocab=${stats.idf.size}`);

  // BGE dense (from cache)
  const bge = await import(join(CLI_ROOT, 'dist/src/memory/bge-embedder.js'));
  const emb = await bge.getBgeEmbedder(BGE_MODEL);
  if (!emb) { console.error('BGE failed'); process.exit(1); }
  const cached = loadEmbeddings(emb.dim());
  if (!cached) { console.error(`No cached embeddings. Run run-beir-bge.mjs first.`); process.exit(2); }
  const { ids: docIds, embeds: docEmbeds } = cached;
  const corpusIdxToId = corpus.map((d) => d._id);

  // Run all configs
  const queriesById = new Map(queries.map((q) => [q._id, q.text]));
  const evalQids = [...qrels.keys()];
  console.log(`\nRunning ${evalQids.length} queries through 4 configs (dense, Lucene-BM25, RRF, RRF-tuned)...\n`);

  let n = 0;
  const results = {
    dense: { n: 0, ndcg: 0, r10: 0, r100: 0 },
    bm25: { n: 0, ndcg: 0, r10: 0, r100: 0 },
    rrf60: { n: 0, ndcg: 0, r10: 0, r100: 0 },
    rrf30: { n: 0, ndcg: 0, r10: 0, r100: 0 },
  };
  const tQ = performance.now();
  for (const qid of evalQids) {
    const qtext = queriesById.get(qid);
    if (!qtext) continue;
    n++;

    // Dense
    const qEmb = await emb.embed(qtext);
    const dense = docIds.map((id, i) => ({ id, score: cosine(qEmb, docEmbeds[i]) })).sort((a, b) => b.score - a.score).slice(0, 1000);

    // BM25
    const qTokens = luceneTokenize(qtext);
    const bm25 = corpus.map((d, i) => ({ id: corpusIdxToId[i], score: luceneBM25(qTokens, docs[i], stats) })).filter((d) => d.score > 0).sort((a, b) => b.score - a.score).slice(0, 1000);

    // RRF k=60 and k=30
    const rrf60 = rrfFuse([dense, bm25], 60);
    const rrf30 = rrfFuse([dense, bm25], 30);

    const qmap = qrels.get(qid);
    for (const [key, top] of [['dense', dense], ['bm25', bm25], ['rrf60', rrf60], ['rrf30', rrf30]]) {
      const top100 = top.slice(0, 100).map((s) => s.id);
      results[key].n++;
      results[key].ndcg += ndcg(top100, qmap, 10);
      results[key].r10 += recall(top100, qmap, 10);
      results[key].r100 += recall(top100, qmap, 100);
    }
    if (n % 50 === 0) console.log(`  ${n}/${evalQids.length} dense=${(results.dense.ndcg / results.dense.n).toFixed(3)} bm25=${(results.bm25.ndcg / results.bm25.n).toFixed(3)} rrf60=${(results.rrf60.ndcg / results.rrf60.n).toFixed(3)}`);
  }
  const elapsed = (performance.now() - tQ) / 1000;

  console.log(`\nDone in ${elapsed.toFixed(0)}s.\n`);
  console.log('Config         | nDCG@10  R@10   R@100  vs published-BM25');
  console.log('---------------|---------------------------------');
  for (const [key, r] of Object.entries(results)) {
    const score = r.ndcg / r.n;
    const delta = score - BASELINES[dataset].BM25;
    console.log(`${key.padEnd(14)} | ${score.toFixed(4)}  ${(r.r10 / r.n).toFixed(3)}  ${(r.r100 / r.n).toFixed(3)}  ${(delta >= 0 ? '+' : '') + delta.toFixed(4)}`);
  }

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: `beir-${dataset}-lucene-bm25`,
    dataset, model: BGE_MODEL, queries: n,
    results: Object.fromEntries(Object.entries(results).map(([k, v]) => [k, { ndcg10: v.ndcg / v.n, recall10: v.r10 / v.n, recall100: v.r100 / v.n }])),
    baselines: BASELINES[dataset],
  };
  mkdirSync(RUNS_DIR, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  writeFileSync(join(RUNS_DIR, `beir-${dataset}-lucene-bm25-${stamp}.json`), JSON.stringify(summary, null, 2));
  writeFileSync(join(RUNS_DIR, `beir-${dataset}-lucene-bm25-latest.json`), JSON.stringify(summary, null, 2));
  console.log(`\nWrote ${join(RUNS_DIR, `beir-${dataset}-lucene-bm25-${stamp}.json`)}`);
  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// run-beir-nfcorpus.mjs — public benchmark harness for BEIR NFCorpus.
//
// Why NFCorpus: smallest BEIR dataset (3.6k docs, 323 test queries) with a
// well-published BM25 baseline and dense-retriever ceilings — runs end-to-end
// in <15 min on this hardware.
//
// Setup:
//   mkdir -p /tmp/beir-nfcorpus && cd /tmp/beir-nfcorpus
//   curl -sL -o nfcorpus.zip 'https://public.ukp.informatik.tu-darmstadt.de/thakur/BEIR/datasets/nfcorpus.zip'
//   unzip -q nfcorpus.zip
//
// Run:
//   cd /tmp/beir-nfcorpus && rm -rf .claude-flow
//   node /path/to/scripts/run-beir-nfcorpus.mjs
//
// Reports:
//   - nDCG@10 (graded, BEIR standard)
//   - MRR@10
//   - Recall@10, Recall@100
//   - Published comparisons (BM25, ColBERT, SPLADE, etc.)

import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

const DATA_DIR = process.env.BEIR_DATA_DIR || '/tmp/beir-nfcorpus/nfcorpus';
const TOP_K = Number(process.env.TOP_K) || 100;     // top-100 for recall@100
const NDCG_K = 10;
const MAX_QUERIES = Number(process.env.MAX_QUERIES) || 0;  // 0 = all
const SKIP_INGEST = process.env.SKIP_INGEST === '1'; // reuse existing store

// Published BEIR NFCorpus baselines (from Thakur et al. 2021 + leaderboard tracker)
const BASELINES_NDCG10 = {
  'BM25':            0.325,
  'DocT5query':      0.328,
  'SBERT (msmarco)': 0.272,  // dense bi-encoder on MS MARCO
  'TAS-B':           0.319,
  'GenQ':            0.319,
  'ColBERT':         0.305,
  'SPLADE++':        0.347,  // top dense at time of paper
  'Contriever':      0.328,
  'GTR-XL':          0.343,
  'BGE-large-v1.5':  0.380,  // current ~top-of-class
};

// ---------------------------------------------------------------------------
// nDCG with graded relevance (BEIR standard)
// ---------------------------------------------------------------------------

function dcg(rels, k) {
  let s = 0;
  for (let i = 0; i < Math.min(rels.length, k); i++) {
    s += (Math.pow(2, rels[i]) - 1) / Math.log2(i + 2);
  }
  return s;
}

function ndcg(retrievedDocIds, qrelsMap, k) {
  const rels = retrievedDocIds.slice(0, k).map((id) => qrelsMap.get(id) ?? 0);
  const ideal = [...qrelsMap.values()].sort((a, b) => b - a).slice(0, k);
  const idcg = dcg(ideal, k);
  return idcg > 0 ? dcg(rels, k) / idcg : 0;
}

function mrr(retrievedDocIds, qrelsMap, k) {
  for (let i = 0; i < Math.min(retrievedDocIds.length, k); i++) {
    if ((qrelsMap.get(retrievedDocIds[i]) ?? 0) > 0) return 1 / (i + 1);
  }
  return 0;
}

function recall(retrievedDocIds, qrelsMap, k) {
  const totalRelevant = [...qrelsMap.values()].filter((v) => v > 0).length;
  if (totalRelevant === 0) return 0;
  let hit = 0;
  for (let i = 0; i < Math.min(retrievedDocIds.length, k); i++) {
    if ((qrelsMap.get(retrievedDocIds[i]) ?? 0) > 0) hit++;
  }
  return hit / totalRelevant;
}

// ---------------------------------------------------------------------------
// Loaders
// ---------------------------------------------------------------------------

function loadJsonl(path) {
  const items = [];
  for (const line of readFileSync(path, 'utf-8').split('\n')) {
    if (!line.trim()) continue;
    items.push(JSON.parse(line));
  }
  return items;
}

function loadQrels(path) {
  // Map<queryId, Map<docId, grade>>
  const qrels = new Map();
  const lines = readFileSync(path, 'utf-8').split('\n');
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const [qid, did, score] = lines[i].split('\t');
    if (!qrels.has(qid)) qrels.set(qid, new Map());
    qrels.get(qid).set(did, Number(score));
  }
  return qrels;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  console.log(`# BEIR NFCorpus benchmark (ADR-085)`);
  console.log(`Data: ${DATA_DIR}`);
  console.log(`Cwd: ${process.cwd()}`);

  const corpus = loadJsonl(join(DATA_DIR, 'corpus.jsonl'));
  const queries = loadJsonl(join(DATA_DIR, 'queries.jsonl'));
  const qrels = loadQrels(join(DATA_DIR, 'qrels/test.tsv'));

  console.log(`Corpus: ${corpus.length} docs, ${queries.length} queries (total), ${qrels.size} eval queries (test split)`);

  const neural = await import(join(CLI_ROOT, 'dist/src/mcp-tools/neural-tools.js'));
  const tool = neural.neuralTools.find((t) => t.name === 'neural_patterns');

  // §1 — Ingest corpus (id-stable pattern name = doc _id; content = title + text).
  // Skip if SKIP_INGEST=1 and store already populated.
  if (!SKIP_INGEST) {
    console.log(`\nIngesting ${corpus.length} docs...`);
    const t0 = performance.now();
    // Batch in chunks to avoid memory pressure.
    const CHUNK = 200;
    for (let i = 0; i < corpus.length; i += CHUNK) {
      const batch = corpus.slice(i, i + CHUNK);
      await neural.storeNeuralPatterns(batch.map((d) => ({
        name: d._id,                         // use _id as the stable identifier
        type: 'beir-nfcorpus',
        content: `${d.title || ''}\n${d.text || ''}`.slice(0, 4096),
      })));
      if ((i + CHUNK) % 1000 === 0 || i + CHUNK >= corpus.length) {
        const pct = Math.min(100, ((i + CHUNK) / corpus.length * 100)).toFixed(0);
        const elapsed = (performance.now() - t0) / 1000;
        console.log(`  ${Math.min(i + CHUNK, corpus.length)}/${corpus.length} (${pct}%) in ${elapsed.toFixed(0)}s`);
      }
    }
    console.log(`Ingest done in ${((performance.now() - t0) / 1000).toFixed(0)}s`);
  } else {
    console.log('SKIP_INGEST=1 → reusing existing store');
  }

  // §2 — Build query lookup (eval queries only).
  const queriesById = new Map(queries.map((q) => [q._id, q.text]));
  const evalQueryIds = MAX_QUERIES
    ? [...qrels.keys()].slice(0, MAX_QUERIES)
    : [...qrels.keys()];

  // §3 — Run retrieval for each query, compute metrics.
  console.log(`\nRunning ${evalQueryIds.length} queries...`);
  let ndcgSum = 0, mrrSum = 0, recall10Sum = 0, recall100Sum = 0;
  const tQ = performance.now();
  let queryIdx = 0;
  for (const qid of evalQueryIds) {
    const qtext = queriesById.get(qid);
    if (!qtext) { queryIdx++; continue; }
    const r = await tool.handler({ action: 'search', query: qtext, mode: 'hybrid', limit: TOP_K, rerank: false });
    const retrievedIds = (r.results || []).map((m) => m.name);  // we set name = _id
    const qrelsMap = qrels.get(qid) || new Map();
    ndcgSum += ndcg(retrievedIds, qrelsMap, NDCG_K);
    mrrSum += mrr(retrievedIds, qrelsMap, NDCG_K);
    recall10Sum += recall(retrievedIds, qrelsMap, 10);
    recall100Sum += recall(retrievedIds, qrelsMap, 100);
    queryIdx++;
    if (queryIdx % 50 === 0) {
      const elapsed = (performance.now() - tQ) / 1000;
      console.log(`  ${queryIdx}/${evalQueryIds.length} in ${elapsed.toFixed(0)}s — running nDCG@10=${(ndcgSum / queryIdx).toFixed(4)}`);
    }
  }
  const queryMs = performance.now() - tQ;
  const N = evalQueryIds.length;
  const ndcg10 = ndcgSum / N;
  const mrr10 = mrrSum / N;
  const recall10 = recall10Sum / N;
  const recall100 = recall100Sum / N;

  console.log(`\n=== Results (N=${N} queries) ===`);
  console.log(`  nDCG@10:    ${ndcg10.toFixed(4)}`);
  console.log(`  MRR@10:     ${mrr10.toFixed(4)}`);
  console.log(`  Recall@10:  ${recall10.toFixed(4)}`);
  console.log(`  Recall@100: ${recall100.toFixed(4)}`);
  console.log(`  Avg query latency: ${(queryMs / N).toFixed(0)}ms`);

  console.log(`\n=== vs published NFCorpus nDCG@10 baselines ===`);
  const ourEntry = { name: 'ruflo hybrid (3.10.25)', score: ndcg10, ours: true };
  const ranking = [
    ...Object.entries(BASELINES_NDCG10).map(([name, score]) => ({ name, score, ours: false })),
    ourEntry,
  ].sort((a, b) => b.score - a.score);
  for (const r of ranking) {
    const marker = r.ours ? ' ← us' : '';
    console.log(`  ${r.score.toFixed(3)}  ${r.name}${marker}`);
  }
  const ourRank = ranking.findIndex((r) => r.ours) + 1;
  console.log(`\n  Our rank: ${ourRank} / ${ranking.length}`);

  const summary = {
    runAt: new Date().toISOString(),
    benchmark: 'beir-nfcorpus',
    queries: N,
    corpusSize: corpus.length,
    metrics: { ndcg10, mrr10, recall10, recall100, avgQueryLatencyMs: queryMs / N },
    baselines: BASELINES_NDCG10,
    ourRank,
    leaderboardLength: ranking.length,
  };
  mkdirSync(RUNS_DIR, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  writeFileSync(join(RUNS_DIR, `beir-nfcorpus-${stamp}.json`), JSON.stringify(summary, null, 2));
  writeFileSync(join(RUNS_DIR, 'beir-nfcorpus-latest.json'), JSON.stringify(summary, null, 2));
  console.log(`\nWrote ${join(RUNS_DIR, `beir-nfcorpus-${stamp}.json`)}`);

  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

#!/usr/bin/env node
// run-beir-rrf-ablation.mjs — RRF weight/k ablation matrix on a single
// BEIR dataset (ADR-087).
//
// Pre-requisite: BGE doc embeddings cached at <dataset>/bge-cache/
// (run scripts/run-beir-bge.mjs first).
//
// Reports:
//   - Fixed default: k=60, equal weights (the headline number we ship)
//   - Ablations: k=30/60/120 × weights (0.8/1.0, 1.0/1.0, 1.2/0.8 dense/bm25)
//   - Bootstrap 95% CI on the fixed-default config only
//
// Usage:
//   cd /tmp/beir-nfcorpus
//   node /path/to/scripts/run-beir-rrf-ablation.mjs
//   cd /tmp/beir-scifact
//   BEIR_DATA_DIR=/tmp/beir-scifact/scifact node /path/to/scripts/run-beir-rrf-ablation.mjs

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const CLI_ROOT = resolve(SCRIPT_DIR, '..');
const RUFLO_ROOT = resolve(SCRIPT_DIR, '../../../..');
const RUNS_DIR = join(RUFLO_ROOT, 'docs', 'benchmarks', 'runs');

const DATA_DIR = process.env.BEIR_DATA_DIR || '/tmp/beir-nfcorpus/nfcorpus';
const BGE_MODEL = process.env.BGE_MODEL || 'Xenova/bge-base-en-v1.5';
const CACHE_DIR = join(dirname(DATA_DIR), 'bge-cache');

const BASELINES = {
  nfcorpus: { 'BM25': 0.325, 'BGE-large-pub': 0.380, 'SPLADE++': 0.347 },
  scifact:  { 'BM25': 0.679, 'BGE-large-pub': 0.722, 'SPLADE++': 0.704 },
};
function detectDataset(p) { const x = p.toLowerCase(); return Object.keys(BASELINES).find(d => x.includes(d)) || 'nfcorpus'; }
const DATASET = detectDataset(DATA_DIR);

function dcg(rels, k) { let s = 0; for (let i = 0; i < Math.min(rels.length, k); i++) s += (Math.pow(2, rels[i]) - 1) / Math.log2(i + 2); return s; }
function ndcg(retrieved, qrels, k) { const rels = retrieved.slice(0, k).map((id) => qrels.get(id) ?? 0); const ideal = [...qrels.values()].sort((a, b) => b - a).slice(0, k); const idcg = dcg(ideal, k); return idcg > 0 ? dcg(rels, k) / idcg : 0; }
function recall(retrieved, qrels, k) { const tot = [...qrels.values()].filter((v) => v > 0).length; if (tot === 0) return 0; let h = 0; for (let i = 0; i < Math.min(retrieved.length, k); i++) if ((qrels.get(retrieved[i]) ?? 0) > 0) h++; return h / tot; }
function cosine(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }

function loadJsonl(p) { return readFileSync(p, 'utf-8').split('\n').filter(Boolean).map((l) => JSON.parse(l)); }
function loadQrels(p) { const q = new Map(); const lines = readFileSync(p, 'utf-8').split('\n'); for (let i = 1; i < lines.length; i++) { if (!lines[i].trim()) continue; const [qid, did, s] = lines[i].split('\t'); if (!q.has(qid)) q.set(qid, new Map()); q.get(qid).set(did, Number(s)); } return q; }

function cachePath(s) { const safe = BGE_MODEL.replace(/\//g, '_'); return join(CACHE_DIR, `${safe}.${s}`); }
function loadEmbeddings(dim) {
  if (!existsSync(cachePath('ids')) || !existsSync(cachePath('f32'))) return null;
  const ids = readFileSync(cachePath('ids'), 'utf-8').split('\n').filter(Boolean);
  const raw = readFileSync(cachePath('f32'));
  const buf = new Float32Array(raw.buffer, raw.byteOffset, raw.length / 4);
  return { ids, embeds: ids.map((_, i) => buf.slice(i * dim, (i + 1) * dim)) };
}

// RRF — pure function per the original Cormack/Clarke/Buettcher 2009 paper.
// `rankings` is an array of [{id, score}, ...] sorted descending by score.
// `weights` is per-system weight (default 1.0 each).
function rrfFuse(rankings, k = 60, weights) {
  const scores = new Map();
  rankings.forEach((ranking, sIdx) => {
    const w = weights?.[sIdx] ?? 1;
    ranking.forEach((doc, rankIdx) => {
      const rank = rankIdx + 1;
      scores.set(doc.id, (scores.get(doc.id) ?? 0) + w / (k + rank));
    });
  });
  return [...scores.entries()].map(([id, score]) => ({ id, score })).sort((a, b) => b.score - a.score);
}

// Mulberry32 PRNG for deterministic bootstrap.
function mulberry32(a) { return function () { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function bootstrapCI(scores, iter = 10000, rng = mulberry32(42)) {
  const n = scores.length; const means = new Float64Array(iter);
  for (let i = 0; i < iter; i++) { let s = 0; for (let j = 0; j < n; j++) s += scores[Math.floor(rng() * n)]; means[i] = s / n; }
  const sorted = Array.from(means).sort((a, b) => a - b);
  const lo = sorted[Math.floor(0.025 * iter)]; const hi = sorted[Math.floor(0.975 * iter)];
  return { mean: scores.reduce((s, v) => s + v, 0) / n, lo, hi };
}

async function main() {
  console.log(`# RRF ablation on BEIR ${DATASET} (ADR-087)`);
  console.log(`Data: ${DATA_DIR}\nDense: ${BGE_MODEL}\n`);

  const corpus = loadJsonl(join(DATA_DIR, 'corpus.jsonl'));
  const queries = loadJsonl(join(DATA_DIR, 'queries.jsonl'));
  const qrels = loadQrels(join(DATA_DIR, 'qrels/test.tsv'));
  console.log(`Corpus: ${corpus.length} · queries: ${queries.length} · test qrels: ${qrels.size}`);

  // Dense
  const bge = await import(join(CLI_ROOT, 'dist/src/memory/bge-embedder.js'));
  const emb = await bge.getBgeEmbedder(BGE_MODEL);
  if (!emb) { console.error('BGE failed'); process.exit(1); }
  const cached = loadEmbeddings(emb.dim());
  if (!cached) { console.error(`No cached embeddings at ${cachePath('f32')}. Run run-beir-bge.mjs first.`); process.exit(2); }
  const { ids: docIds, embeds: docEmbeds } = cached;

  // BM25
  const { tokenize, buildCorpusStats, multiFieldBM25 } = await import(join(CLI_ROOT, 'dist/src/memory/hybrid-retrieval.js'));
  const titleDocs = corpus.map((d) => tokenize(d.title || ''));
  const textDocs = corpus.map((d) => tokenize(d.text || ''));
  const titleStats = buildCorpusStats(titleDocs);
  const textStats = buildCorpusStats(textDocs);
  const corpusIdxToId = corpus.map((d) => d._id);

  // Pre-compute per-query rankings for both systems ONCE, so the ablation
  // matrix below just permutes RRF k/weights, not the underlying retrievals.
  const queriesById = new Map(queries.map((q) => [q._id, q.text]));
  const evalQids = [...qrels.keys()];

  console.log(`Pre-computing dense + BM25 rankings for ${evalQids.length} queries...`);
  const cached_dense = new Map();
  const cached_bm25 = new Map();
  const TOP_K_RETRIEVE = 1000;  // enough for stable RRF
  const tPre = performance.now();
  for (const qid of evalQids) {
    const qtext = queriesById.get(qid);
    if (!qtext) continue;
    // Dense
    const qEmb = await emb.embed(qtext);
    const dense = docIds.map((id, i) => ({ id, score: cosine(qEmb, docEmbeds[i]) })).sort((a, b) => b.score - a.score).slice(0, TOP_K_RETRIEVE);
    cached_dense.set(qid, dense);
    // BM25
    const qTokens = tokenize(qtext);
    const bm25 = corpus.map((d, i) => ({ id: corpusIdxToId[i], score: multiFieldBM25(qTokens, titleDocs[i], textDocs[i], titleStats, textStats, 1, 1) })).filter((d) => d.score > 0).sort((a, b) => b.score - a.score).slice(0, TOP_K_RETRIEVE);
    cached_bm25.set(qid, bm25);
  }
  console.log(`Pre-compute done in ${((performance.now() - tPre) / 1000).toFixed(0)}s.\n`);

  // ----- ABLATION GRID -----
  // FIXED-DEFAULT first (the ship claim). Other variants reported as exploratory.
  const CONFIGS = [
    // The headline configurations — defaults fixed before viewing results.
    { name: 'dense only',             rrf: false, weights: null,           kVal: null },
    { name: 'BM25 only',              rrf: false, weights: null,           kVal: null, bm25Only: true },
    { name: 'RRF k=60 equal (default)', rrf: true,  weights: [1.0, 1.0],     kVal: 60 },
    // Exploratory — disclose as tuned variants, not default.
    { name: 'RRF k=30 equal',         rrf: true,  weights: [1.0, 1.0],     kVal: 30 },
    { name: 'RRF k=120 equal',        rrf: true,  weights: [1.0, 1.0],     kVal: 120 },
    { name: 'RRF k=60 dense=1.2,bm25=0.8', rrf: true,  weights: [1.2, 0.8],     kVal: 60 },
    { name: 'RRF k=60 dense=0.8,bm25=1.2', rrf: true,  weights: [0.8, 1.2],     kVal: 60 },
  ];

  function scoreConfig(cfg) {
    let nSum = 0, r10Sum = 0, r100Sum = 0, n = 0;
    const perQuery = [];
    for (const qid of evalQids) {
      const dense = cached_dense.get(qid);
      const bm25 = cached_bm25.get(qid);
      if (!dense) continue;
      let top100;
      if (!cfg.rrf) {
        if (cfg.bm25Only) top100 = (bm25 || []).slice(0, 100).map((d) => d.id);
        else top100 = dense.slice(0, 100).map((d) => d.id);
      } else {
        const fused = rrfFuse([dense, bm25 || []], cfg.kVal, cfg.weights);
        top100 = fused.slice(0, 100).map((d) => d.id);
      }
      const qmap = qrels.get(qid);
      const ndcg10 = ndcg(top100, qmap, 10);
      nSum += ndcg10;
      r10Sum += recall(top100, qmap, 10);
      r100Sum += recall(top100, qmap, 100);
      n++;
      perQuery.push({ qid, ndcg10 });
    }
    return {
      name: cfg.name,
      ndcg10: nSum / n,
      recall10: r10Sum / n,
      recall100: r100Sum / n,
      n,
      perQuery,
    };
  }

  console.log('Config                                | nDCG@10  R@10    R@100   95% CI');
  console.log('--------------------------------------|---------------------------------');
  const results = [];
  let defaultResult = null;
  for (const cfg of CONFIGS) {
    const r = scoreConfig(cfg);
    const ci = bootstrapCI(r.perQuery.map((q) => q.ndcg10));
    const ciStr = `[${ci.lo.toFixed(3)}, ${ci.hi.toFixed(3)}]`;
    console.log(`${cfg.name.padEnd(38)} | ${r.ndcg10.toFixed(4)}  ${r.recall10.toFixed(3)}   ${r.recall100.toFixed(3)}   ${ciStr}`);
    results.push({ ...r, ci, cfg });
    if (cfg.name.includes('default')) defaultResult = { ...r, ci, cfg };
  }

  console.log('\n=== Ship claim (fixed default, k=60, equal weights) ===');
  console.log(`Dataset: ${DATASET}`);
  console.log(`nDCG@10: ${defaultResult.ndcg10.toFixed(4)}   95% CI ${`[${defaultResult.ci.lo.toFixed(4)}, ${defaultResult.ci.hi.toFixed(4)}]`}`);
  for (const [name, score] of Object.entries(BASELINES[DATASET])) {
    const delta = defaultResult.ndcg10 - score;
    const inCi = score >= defaultResult.ci.lo && score <= defaultResult.ci.hi;
    const sig = inCi ? 'n.s.' : (delta > 0 ? 'p<0.05 WIN' : 'p<0.05 LOSS');
    console.log(`  vs ${name.padEnd(15)} Δ=${(delta >= 0 ? '+' : '') + delta.toFixed(4)}   ${sig}`);
  }

  // Save
  const summary = {
    runAt: new Date().toISOString(),
    benchmark: `beir-${DATASET}-rrf-ablation`,
    dataset: DATASET,
    bgeModel: BGE_MODEL,
    queries: defaultResult.n,
    corpusSize: corpus.length,
    fixedDefault: { name: defaultResult.cfg.name, metrics: { ndcg10: defaultResult.ndcg10, recall10: defaultResult.recall10, recall100: defaultResult.recall100 }, ci: defaultResult.ci, perQuery: defaultResult.perQuery },
    ablation: results.map((r) => ({ name: r.cfg.name, ndcg10: r.ndcg10, recall10: r.recall10, recall100: r.recall100, ci: r.ci })),
    baselines: BASELINES[DATASET],
  };
  mkdirSync(RUNS_DIR, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  writeFileSync(join(RUNS_DIR, `beir-${DATASET}-rrf-ablation-${stamp}.json`), JSON.stringify(summary, null, 2));
  writeFileSync(join(RUNS_DIR, `beir-${DATASET}-rrf-ablation-latest.json`), JSON.stringify(summary, null, 2));
  console.log(`\nWrote ${join(RUNS_DIR, `beir-${DATASET}-rrf-ablation-${stamp}.json`)}`);
  process.exit(0);
}

main().catch((err) => { console.error(err); process.exit(1); });

/**
 * ruvLLM GGUF Inference Engine -- Pure Node.js GGUF Model Interface
 *
 * Provides:
 *   1. GGUF binary header parsing (metadata without loading weights)
 *   2. Model loading abstraction (node-llama-cpp when available, metadata-only fallback)
 *   3. Token generation interface with async iterator streaming
 *   4. KV-cache persistence to RVF-compatible binary format
 *
 * Zero external dependencies. node-llama-cpp is an optional peer.
 *
 * @module @claude-flow/cli/appliance/gguf-engine
 */

import { open, readFile, writeFile, stat as fsStat } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { basename } from 'node:path';

// ── GGUF Metadata Value Types ───────────────────────────────

const enum GgufValueType {
  UINT8 = 0, INT8 = 1, UINT16 = 2, INT16 = 3, UINT32 = 4, INT32 = 5,
  FLOAT32 = 6, BOOL = 7, STRING = 8, ARRAY = 9, UINT64 = 10, INT64 = 11, FLOAT64 = 12,
}

const GGUF_MAGIC = 0x46554747; // "GGUF" in little-endian
const RVKV_MAGIC = 0x564B5652; // "RVKV" in little-endian
const RVKV_VERSION = 1;

// ── Public Interfaces ───────────────────────────────────────

export interface GgufMetadata {
  magic: string;
  version: number;
  tensorCount: number;
  kvCount: number;
  architecture?: string;
  name?: string;
  contextLength?: number;
  embeddingLength?: number;
  blockCount?: number;
  vocabSize?: number;
  quantization?: string;
  fileSize: number;
  metadata: Record<string, unknown>;
}

export interface GgufEngineConfig {
  contextSize?: number;
  maxTokens?: number;
  temperature?: number;
  kvCachePath?: string;
  verbose?: boolean;
}

export interface GenerateRequest {
  prompt: string;
  model?: string;
  maxTokens?: number;
  temperature?: number;
  stream?: boolean;
  stopSequences?: string[];
}

export interface GenerateResponse {
  text: string;
  model: string;
  tokensUsed: number;
  latencyMs: number;
  metadataOnly: boolean;
}

// ── Internal Buffer Reader ──────────────────────────────────

/** Stateful cursor over a Buffer for sequential binary reads. */
class BufferReader {
  private offset = 0;
  constructor(private buf: Buffer) {}
  get remaining(): number { return this.buf.length - this.offset; }

  readU8(): number  { const v = this.buf.readUInt8(this.offset); this.offset += 1; return v; }
  readI8(): number  { const v = this.buf.readInt8(this.offset); this.offset += 1; return v; }
  readU16(): number { const v = this.buf.readUInt16LE(this.offset); this.offset += 2; return v; }
  readI16(): number { const v = this.buf.readInt16LE(this.offset); this.offset += 2; return v; }
  readU32(): number { const v = this.buf.readUInt32LE(this.offset); this.offset += 4; return v; }
  readI32(): number { const v = this.buf.readInt32LE(this.offset); this.offset += 4; return v; }
  readF32(): number { const v = this.buf.readFloatLE(this.offset); this.offset += 4; return v; }
  readF64(): number { const v = this.buf.readDoubleLE(this.offset); this.offset += 8; return v; }
  readU64(): bigint { const v = this.buf.readBigUInt64LE(this.offset); this.offset += 8; return v; }
  readI64(): bigint { const v = this.buf.readBigInt64LE(this.offset); this.offset += 8; return v; }
  /** Safe for values up to 2^53. Real GGUF files never exceed this for tensor/kv counts. */
  readU64AsNumber(): number { return Number(this.readU64()); }
  readBool(): boolean { return this.readU8() !== 0; }

  /** GGUF string: [length u64 LE][utf-8 bytes]. */
  readString(): string {
    const len = this.readU64AsNumber();
    if (len === 0) return '';
    if (len > this.remaining) throw new Error(`String length ${len} exceeds remaining buffer`);
    const s = this.buf.toString('utf-8', this.offset, this.offset + len);
    this.offset += len;
    return s;
  }
}

// ── GGUF Value Reading ──────────────────────────────────────

/** Read a typed scalar from the buffer (shared by value and array-element readers). */
function readScalar(reader: BufferReader, t: number): unknown {
  switch (t) {
    case GgufValueType.UINT8:   return reader.readU8();
    case GgufValueType.INT8:    return reader.readI8();
    case GgufValueType.UINT16:  return reader.readU16();
    case GgufValueType.INT16:   return reader.readI16();
    case GgufValueType.UINT32:  return reader.readU32();
    case GgufValueType.INT32:   return reader.readI32();
    case GgufValueType.FLOAT32: return reader.readF32();
    case GgufValueType.BOOL:    return reader.readBool();
    case GgufValueType.STRING:  return reader.readString();
    case GgufValueType.UINT64:  return Number(reader.readU64());
    case GgufValueType.INT64:   return Number(reader.readI64());
    case GgufValueType.FLOAT64: return reader.readF64();
    default: return undefined;
  }
}

/** Read a single GGUF typed value (scalar or array) from the buffer. */
function readGgufValue(reader: BufferReader): unknown {
  const valueType = reader.readU32();
  if (valueType === GgufValueType.ARRAY) {
    const elemType = reader.readU32();
    const len = reader.readU64AsNumber();
    const arr: unknown[] = [];
    for (let i = 0; i < len; i++) {
      const v = readScalar(reader, elemType);
      if (v === undefined) throw new Error(`Unknown GGUF array element type: ${elemType}`);
      arr.push(v);
    }
    return arr;
  }
  const v = readScalar(reader, valueType);
  if (v === undefined) throw new Error(`Unknown GGUF value type: ${valueType}`);
  return v;
}

// ── GGUF Header Parsing ─────────────────────────────────────

/**
 * Parse the header and metadata from a GGUF file without loading tensors.
 * Reads only the first 256 KB of the file.
 */
export async function parseGgufHeader(path: string): Promise<GgufMetadata> {
  const fileInfo = await fsStat(path);
  const readSize = Math.min(fileInfo.size, 256 * 1024);
  const fh = await open(path, 'r');
  try {
    const buf = Buffer.alloc(readSize);
    await fh.read(buf, 0, readSize, 0);
    return parseGgufBuffer(buf, fileInfo.size, path);
  } finally {
    await fh.close();
  }
}

function parseGgufBuffer(buf: Buffer, fileSize: number, filePath: string): GgufMetadata {
  const reader = new BufferReader(buf);

  const magic = reader.readU32();
  if (magic !== GGUF_MAGIC) {
    throw new Error(`Invalid GGUF magic: 0x${magic.toString(16)} (expected 0x${GGUF_MAGIC.toString(16)})`);
  }

  const version = reader.readU32();
  if (version < 2 || version > 3) {
    throw new Error(`Unsupported GGUF version: ${version} (expected 2 or 3)`);
  }

  const tensorCount = reader.readU64AsNumber();
  const kvCount = reader.readU64AsNumber();

  const metadata: Record<string, unknown> = {};
  for (let i = 0; i < kvCount; i++) {
    if (reader.remaining < 12) break;
    try {
      const key = reader.readString();
      metadata[key] = readGgufValue(reader);
    } catch {
      break; // reached end of read window
    }
  }

  const arch = asString(metadata['general.architecture']);
  const pfx = arch || 'llama'; // fallback prefix for well-known keys

  return {
    magic: 'GGUF', version, tensorCount, kvCount,
    architecture: arch,
    name: asString(metadata['general.name']),
    contextLength: asNumber(metadata[`${pfx}.context_length`]),
    embeddingLength: asNumber(metadata[`${pfx}.embedding_length`]),
    blockCount: asNumber(metadata[`${pfx}.block_count`]),
    vocabSize: inferVocabSize(metadata),
    quantization: inferQuantFromMetadata(metadata, filePath),
    fileSize, metadata,
  };
}

// ── Metadata Helpers ────────────────────────────────────────

function asString(v: unknown): string | undefined { return typeof v === 'string' ? v : undefined; }
function asNumber(v: unknown): number | undefined { return typeof v === 'number' ? v : undefined; }

const QUANT_RE: Array<[RegExp, string]> = [
  [/q2_k/i, 'Q2_K'], [/q3_k_s/i, 'Q3_K_S'], [/q3_k_m/i, 'Q3_K_M'], [/q3_k_l/i, 'Q3_K_L'],
  [/q4_k_s/i, 'Q4_K_S'], [/q4_k_m/i, 'Q4_K_M'], [/q4_0/i, 'Q4_0'], [/q4_1/i, 'Q4_1'],
  [/q5_k_s/i, 'Q5_K_S'], [/q5_k_m/i, 'Q5_K_M'], [/q5_0/i, 'Q5_0'], [/q5_1/i, 'Q5_1'],
  [/q6_k/i, 'Q6_K'], [/q8_0/i, 'Q8_0'], [/f16/i, 'F16'], [/f32/i, 'F32'],
];

function inferQuantFromMetadata(meta: Record<string, unknown>, filePath: string): string {
  const ft = meta['general.file_type'];
  if (typeof ft === 'number') return `file_type_${ft}`;
  const name = basename(filePath);
  for (const [re, label] of QUANT_RE) if (re.test(name)) return label;
  return 'unknown';
}

function inferVocabSize(meta: Record<string, unknown>): number | undefined {
  const tokens = meta['tokenizer.ggml.tokens'];
  if (Array.isArray(tokens)) return tokens.length;
  return asNumber(meta['tokenizer.ggml.vocab_size']);
}

// ── GGUF Engine ─────────────────────────────────────────────

export class GgufEngine {
  private config: Required<GgufEngineConfig>;
  private llamaCpp: any = null;
  private llamaModel: any = null;
  private llamaContext: any = null;
  private loadedModels: Map<string, GgufMetadata> = new Map();
  private activeModelPath: string | null = null;
  private kvCache: Map<string, Buffer> = new Map();

  constructor(config: GgufEngineConfig) {
    this.config = {
      contextSize: config.contextSize ?? 4096,
      maxTokens: config.maxTokens ?? 512,
      temperature: config.temperature ?? 0.7,
      kvCachePath: config.kvCachePath ?? '',
      verbose: config.verbose ?? false,
    };
  }

  /** Probe for node-llama-cpp availability. */
  async initialize(): Promise<void> {
    this.llamaCpp = await this.tryLoadLlamaCpp();
    if (this.config.verbose) {
      console.log(`[gguf-engine] node-llama-cpp: ${this.llamaCpp ? 'available' : 'not found (metadata-only mode)'}`);
    }
  }

  /** Parse GGUF header and optionally load the model for inference. */
  async loadModel(path: string): Promise<GgufMetadata> {
    const meta = await parseGgufHeader(path);
    this.loadedModels.set(path, meta);
    this.activeModelPath = path;

    if (this.llamaCpp) {
      try {
        const { getLlama } = this.llamaCpp;
        const llama = await getLlama();
        this.llamaModel = await llama.loadModel({ modelPath: path });
        this.llamaContext = await this.llamaModel.createContext({ contextSize: this.config.contextSize });
        if (this.config.verbose) console.log(`[gguf-engine] Model loaded: ${basename(path)}`);
      } catch (err) {
        if (this.config.verbose) console.warn('[gguf-engine] node-llama-cpp load failed:', err);
        this.llamaModel = null;
        this.llamaContext = null;
      }
    }
    return meta;
  }

  /** Generate text. Delegates to node-llama-cpp or returns a metadata-only stub. */
  async generate(request: GenerateRequest): Promise<GenerateResponse> {
    const start = performance.now();
    const modelPath = request.model ?? this.activeModelPath;
    const modelName = modelPath ? basename(modelPath) : 'none';

    if (this.llamaContext && this.llamaModel) {
      try {
        const session = new this.llamaCpp.LlamaChatSession({
          contextSequence: this.llamaContext.getSequence(),
        });
        const text = await session.prompt(request.prompt, {
          maxTokens: request.maxTokens ?? this.config.maxTokens,
          temperature: request.temperature ?? this.config.temperature,
          stopGenerationTrigger: request.stopSequences
            ? request.stopSequences.map((s: string) => new this.llamaCpp.LlamaText([s]))
            : undefined,
        });
        // Use llama.cpp tokenizer for accurate count when available, else estimate
        let tokensUsed: number;
        try {
          const seq = this.llamaContext.getSequence();
          tokensUsed = seq.tokenCount ?? Math.ceil(text.length / 4);
        } catch {
          tokensUsed = Math.ceil(text.length / 4); // ~4 chars per token heuristic
        }
        return {
          text, model: modelName, tokensUsed,
          latencyMs: performance.now() - start, metadataOnly: false,
        };
      } catch (err) {
        if (this.config.verbose) console.warn('[gguf-engine] Generation failed:', err);
      }
    }

    // Metadata-only fallback
    const meta = modelPath ? this.loadedModels.get(modelPath) : undefined;
    return {
      text: meta
        ? `[metadata-only] Model: ${meta.name ?? modelName}, arch: ${meta.architecture ?? 'unknown'}, ctx: ${meta.contextLength ?? 'unknown'}`
        : '[metadata-only] No model loaded',
      model: modelName, tokensUsed: 0,
      latencyMs: performance.now() - start, metadataOnly: true,
    };
  }

  /** Stream tokens via async iterator. Falls back to yielding full response. */
  async *stream(request: GenerateRequest): AsyncGenerator<string> {
    if (this.llamaContext && this.llamaModel) {
      try {
        const session = new this.llamaCpp.LlamaChatSession({
          contextSequence: this.llamaContext.getSequence(),
        });
        const it = session.promptWithMeta(request.prompt, {
          maxTokens: request.maxTokens ?? this.config.maxTokens,
          temperature: request.temperature ?? this.config.temperature,
        });
        if (it && typeof it[Symbol.asyncIterator] === 'function') {
          for await (const chunk of it) {
            if (typeof chunk === 'string') yield chunk;
            else if (chunk?.text) yield chunk.text;
          }
          return;
        }
      } catch { /* fall through to single-chunk fallback */ }
    }
    const response = await this.generate(request);
    yield response.text;
  }

  /**
   * Persist the KV cache to an RVF-compatible binary file.
   * Format: RVKV magic | version u32 | model SHA-256 (32B) | entry count u32
   *         entries: [key_len u32, key, val_len u32, val] | footer SHA-256 (32B)
   */
  async persistKvCache(outputPath: string): Promise<void> {
    const path = outputPath || this.config.kvCachePath;
    if (!path) throw new Error('No KV cache output path specified');

    const modelHash = createHash('sha256').update(this.activeModelPath ?? 'no-model').digest();
    const entryBufs: Buffer[] = [];
    for (const [key, value] of this.kvCache) {
      const keyBuf = Buffer.from(key, 'utf-8');
      const hdr = Buffer.alloc(8);
      hdr.writeUInt32LE(keyBuf.length, 0);
      hdr.writeUInt32LE(value.length, 4);
      entryBufs.push(hdr, keyBuf, value);
    }
    const entryData = Buffer.concat(entryBufs);
    const footer = createHash('sha256').update(entryData).digest();

    const header = Buffer.alloc(44);
    header.writeUInt32LE(RVKV_MAGIC, 0);
    header.writeUInt32LE(RVKV_VERSION, 4);
    modelHash.copy(header, 8);
    header.writeUInt32LE(this.kvCache.size, 40);

    await writeFile(path, Buffer.concat([header, entryData, footer]));
    if (this.config.verbose) console.log(`[gguf-engine] KV cache persisted: ${this.kvCache.size} entries`);
  }

  /** Restore KV cache from an RVF-compatible binary file. */
  async loadKvCache(inputPath: string): Promise<void> {
    const data = await readFile(inputPath);
    if (data.length < 44) throw new Error('KV cache file too small');

    const magic = data.readUInt32LE(0);
    if (magic !== RVKV_MAGIC) throw new Error(`Invalid KV cache magic: 0x${magic.toString(16)}`);
    const version = data.readUInt32LE(4);
    if (version !== RVKV_VERSION) throw new Error(`Unsupported KV cache version: ${version}`);

    const entryCount = data.readUInt32LE(40);
    let offset = 44;
    const entries = new Map<string, Buffer>();

    for (let i = 0; i < entryCount; i++) {
      if (offset + 8 > data.length) throw new Error('KV cache file truncated');
      const keyLen = data.readUInt32LE(offset);
      const valLen = data.readUInt32LE(offset + 4);
      offset += 8;
      if (offset + keyLen + valLen > data.length) throw new Error('KV cache file truncated');
      entries.set(data.toString('utf-8', offset, offset + keyLen), Buffer.from(data.subarray(offset + keyLen, offset + keyLen + valLen)));
      offset += keyLen + valLen;
    }

    // Verify footer hash (mandatory)
    if (offset + 32 > data.length) {
      throw new Error('KV cache file missing SHA256 footer');
    }
    const stored = data.subarray(offset, offset + 32);
    const computed = createHash('sha256').update(data.subarray(44, offset)).digest();
    if (!stored.equals(computed)) throw new Error('KV cache integrity check failed: hash mismatch');

    this.kvCache = entries;
    if (this.config.verbose) console.log(`[gguf-engine] KV cache loaded: ${entries.size} entries`);
  }

  /** Return metadata for all loaded models. */
  getLoadedModels(): GgufMetadata[] { return Array.from(this.loadedModels.values()); }

  /** Store a key-value pair in the in-memory KV cache. */
  setKvEntry(key: string, value: Buffer): void { this.kvCache.set(key, value); }

  /** Retrieve a key-value pair from the in-memory KV cache. */
  getKvEntry(key: string): Buffer | undefined { return this.kvCache.get(key); }

  /** Release resources, unload models, and optionally persist the KV cache. */
  async shutdown(): Promise<void> {
    if (this.config.kvCachePath && this.kvCache.size > 0) {
      try { await this.persistKvCache(this.config.kvCachePath); }
      catch (err) { if (this.config.verbose) console.warn('[gguf-engine] KV persist failed:', err); }
    }
    if (this.llamaContext?.dispose) { try { await this.llamaContext.dispose(); } catch { /* ignore */ } }
    if (this.llamaModel?.dispose) { try { await this.llamaModel.dispose(); } catch { /* ignore */ } }
    this.llamaContext = null;
    this.llamaModel = null;
    this.activeModelPath = null;
    this.loadedModels.clear();
    this.kvCache.clear();
    if (this.config.verbose) console.log('[gguf-engine] Shutdown complete');
  }

  // ── Private ───────────────────────────────────────────────

  private async tryLoadLlamaCpp(): Promise<any> {
    // @ts-ignore -- optional peer dependency, may not be installed
    try { return await import('node-llama-cpp'); } catch { return null; }
  }
}

/**
 * ruvLLM Bridge -- Local Language Model Inference from RuVector
 *
 * Extends @ruvector/core with on-device GGUF model inference.
 * Provides 3-tier routing:
 *   Tier 1: Agent Booster (WASM, <1ms) -- simple transforms
 *   Tier 2: Local model via ruvLLM (~200ms) -- routing, classification
 *   Tier 3: Cloud API (2-5s) -- complex reasoning
 *
 * All @ruvector/* packages are optional peer dependencies.
 * The bridge degrades gracefully when they are absent.
 *
 * @module @claude-flow/cli/appliance/ruvllm-bridge
 */

import { readdir, stat } from 'node:fs/promises';
import { join, extname, basename } from 'node:path';
import type { GgufEngine as GgufEngineType } from './gguf-engine.js';

// ── Configuration ───────────────────────────────────────────

export interface RuvllmConfig {
  modelsDir: string;         // Path to GGUF model files
  defaultModel?: string;     // Default model name
  maxTokens?: number;        // Default max tokens
  temperature?: number;      // Default temperature
  contextSize?: number;      // KV-cache context size (default 4096)
  kvCachePath?: string;      // Path to persist KV-cache as RVF
  verbose?: boolean;
}

const DEFAULT_CONFIG: Required<RuvllmConfig> = {
  modelsDir: './models', defaultModel: '', maxTokens: 512,
  temperature: 0.7, contextSize: 4096, kvCachePath: '', verbose: false,
};

// ── Request / Response ──────────────────────────────────────

export interface GenerateRequest {
  prompt: string;
  model?: string;
  maxTokens?: number;
  temperature?: number;
  stream?: boolean;
  stopSequences?: string[];
}

export interface GenerateResponse {
  text: string;
  model: string;
  tokensUsed: number;
  latencyMs: number;
  tier: 1 | 2 | 3;
  cached: boolean;
}

export interface ModelInfo {
  name: string;
  path: string;
  format: string;       // 'gguf'
  quantization: string;  // 'q4_k_m', 'q8_0', etc.
  size: number;          // bytes
  parameters: string;    // '3B', '7B', etc.
  loaded: boolean;
}

export interface TierRouting {
  tier: 1 | 2 | 3;
  model: string;
  confidence: number;
}

export interface BridgeStatus {
  available: boolean;
  ruvectorCore: boolean;
  ruvectorRouter: boolean;
  ruvectorSona: boolean;
  modelsLoaded: string[];
  kvCacheSize: number;
}

// ── Quantization / parameter heuristics ─────────────────────

const QUANT_PATTERNS: Array<[RegExp, string]> = [
  [/q4_k_m/i, 'q4_k_m'], [/q4_k_s/i, 'q4_k_s'], [/q4_0/i, 'q4_0'],
  [/q5_k_m/i, 'q5_k_m'], [/q5_0/i, 'q5_0'], [/q8_0/i, 'q8_0'],
  [/f16/i, 'f16'], [/f32/i, 'f32'],
];

function inferQuantization(filename: string): string {
  for (const [re, label] of QUANT_PATTERNS) if (re.test(filename)) return label;
  return 'unknown';
}

function inferParameters(filename: string): string {
  const m = filename.match(/(\d+)[._-]?b/i);
  return m ? m[0].toUpperCase().replace(/[._-]/g, '') : 'unknown';
}

// ── Complexity heuristic ────────────────────────────────────

const HIGH = new Set([
  'architect', 'design', 'refactor', 'security', 'audit', 'complex',
  'analyze', 'distributed', 'concurrent', 'algorithm', 'investigate',
  'optimize', 'debug', 'system', 'integration',
]);
const LOW = new Set([
  'rename', 'typo', 'format', 'comment', 'version', 'bump',
  'move', 'copy', 'delete', 'simple', 'config',
]);

function estimateComplexity(desc: string): number {
  const words = desc.toLowerCase().split(/\s+/);
  let score = 0.3;
  for (const w of words) {
    if (HIGH.has(w)) score += 0.15;
    if (LOW.has(w)) score -= 0.1;
  }
  return Math.max(0, Math.min(1, score + Math.min(0.2, words.length / 200)));
}

// ── Bridge ──────────────────────────────────────────────────

export class RuvllmBridge {
  private config: Required<RuvllmConfig>;
  private models: Map<string, ModelInfo> = new Map();
  private activeModel: string | null = null;
  private kvCacheEntries = 0;
  private ruvectorCore: any = null;
  private ruvectorRouter: any = null;
  private ruvectorSona: any = null;
  private ggufEngine: GgufEngineType | null = null;

  constructor(config: RuvllmConfig) {
    if (!config.modelsDir) throw new Error('RuvllmConfig.modelsDir is required');
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Probe optional @ruvector packages, initialize GGUF engine, and scan modelsDir. */
  async initialize(): Promise<void> {
    this.ruvectorCore = await this.tryImport('@ruvector/core');
    this.ruvectorRouter = await this.tryImport('@ruvector/router');
    this.ruvectorSona = await this.tryImport('@ruvector/sona');

    // Initialize GGUF engine for local model inference
    try {
      const { GgufEngine } = await import('./gguf-engine.js');
      this.ggufEngine = new GgufEngine({
        contextSize: this.config.contextSize,
        maxTokens: this.config.maxTokens,
        temperature: this.config.temperature,
        kvCachePath: this.config.kvCachePath,
        verbose: this.config.verbose,
      });
      await this.ggufEngine.initialize();
    } catch {
      // GGUF engine is optional
    }

    await this.scanModelsDir();

    if (this.config.verbose) {
      const pkgs = [
        this.ruvectorCore && '@ruvector/core',
        this.ruvectorRouter && '@ruvector/router',
        this.ruvectorSona && '@ruvector/sona',
        this.ggufEngine && 'gguf-engine',
      ].filter(Boolean);
      if (pkgs.length) console.log(`[ruvLLM] Loaded: ${pkgs.join(', ')}`);
      console.log(`[ruvLLM] ${this.models.size} model(s) in ${this.config.modelsDir}`);
    }
  }

  /** Return all discovered GGUF models. */
  async listModels(): Promise<ModelInfo[]> {
    return Array.from(this.models.values());
  }

  /** Load a model into memory (delegates to GGUF engine or @ruvector/core). */
  async loadModel(name: string): Promise<void> {
    const info = this.models.get(name);
    if (!info) throw new Error(`Model "${name}" not found. Available: ${[...this.models.keys()].join(', ')}`);

    // Prefer GGUF engine (parses header, loads via node-llama-cpp if available)
    if (this.ggufEngine) {
      const meta = await this.ggufEngine.loadModel(info.path);
      if (meta.architecture) info.parameters = meta.architecture;
      if (meta.quantization) info.quantization = meta.quantization;
    } else if (this.ruvectorCore?.loadModel) {
      await this.ruvectorCore.loadModel(info.path, { contextSize: this.config.contextSize });
    }
    info.loaded = true;
    this.activeModel = name;
  }

  /**
   * Generate text from a prompt. Routes through tiers:
   * 1. Agent Booster (trivial transforms, no LLM).
   * 2. Local GGUF model via @ruvector/core.
   * 3. Cloud fallback (empty response -- caller handles upstream).
   */
  async generate(request: GenerateRequest): Promise<GenerateResponse> {
    const start = performance.now();
    const modelName = request.model ?? this.config.defaultModel ?? this.activeModel ?? '';

    // Tier 1: Agent Booster
    const booster = this.tryAgentBooster(request.prompt);
    if (booster !== null) {
      return { text: booster, model: 'agent-booster', tokensUsed: 0, latencyMs: performance.now() - start, tier: 1, cached: false };
    }

    // Tier 2: Local model (GGUF engine preferred, then @ruvector/core)
    const info = this.models.get(modelName);
    if (info?.loaded) {
      try {
        if (this.ggufEngine) {
          const r = await this.ggufEngine.generate({
            prompt: request.prompt,
            maxTokens: request.maxTokens ?? this.config.maxTokens,
            temperature: request.temperature ?? this.config.temperature,
            stopSequences: request.stopSequences,
          });
          return { text: r.text, model: modelName, tokensUsed: r.tokensUsed, latencyMs: performance.now() - start, tier: 2, cached: false };
        } else if (this.ruvectorCore?.generate) {
          const r = await this.ruvectorCore.generate({
            model: info.path, prompt: request.prompt,
            maxTokens: request.maxTokens ?? this.config.maxTokens,
            temperature: request.temperature ?? this.config.temperature,
            stopSequences: request.stopSequences,
          });
          return { text: r.text ?? '', model: modelName, tokensUsed: r.tokensUsed ?? 0, latencyMs: performance.now() - start, tier: 2, cached: false };
        }
      } catch (err) {
        if (this.config.verbose) console.warn('[ruvLLM] Local generation failed, tier 3 fallback:', err);
      }
    }

    // Tier 3: Cloud fallback
    return { text: '', model: 'cloud-fallback', tokensUsed: 0, latencyMs: performance.now() - start, tier: 3, cached: false };
  }

  /** Route a task description to the optimal tier. Uses @ruvector/router when available. */
  async routeTask(description: string): Promise<TierRouting> {
    if (this.ruvectorRouter?.route) {
      try {
        const r = await this.ruvectorRouter.route(description);
        return { tier: r.tier ?? 3, model: r.model ?? 'cloud', confidence: r.confidence ?? 0.5 };
      } catch { /* fall through */ }
    }

    const complexity = estimateComplexity(description);
    const words = description.split(/\s+/).length;

    if (words < 15 && complexity < 0.25) return { tier: 1, model: 'agent-booster', confidence: 0.9 };
    if (complexity < 0.55 && this.activeModel) return { tier: 2, model: this.activeModel, confidence: 0.7 };
    return { tier: 3, model: 'cloud', confidence: 0.6 };
  }

  /** Return current bridge status. */
  async getStatus(): Promise<BridgeStatus> {
    return {
      available: this.models.size > 0 || this.ruvectorCore !== null,
      ruvectorCore: this.ruvectorCore !== null,
      ruvectorRouter: this.ruvectorRouter !== null,
      ruvectorSona: this.ruvectorSona !== null,
      modelsLoaded: [...this.models.values()].filter((m) => m.loaded).map((m) => m.name),
      kvCacheSize: this.kvCacheEntries,
    };
  }

  /** Persist KV-cache, unload models, and clean up. */
  async shutdown(): Promise<void> {
    if (this.ggufEngine) {
      await this.ggufEngine.shutdown();
      this.ggufEngine = null;
    }
    if (this.config.kvCachePath && this.ruvectorCore?.persistKvCache) {
      try { await this.ruvectorCore.persistKvCache(this.config.kvCachePath); }
      catch (e) { if (this.config.verbose) console.warn('[ruvLLM] KV-cache persist failed:', e); }
    }
    if (this.ruvectorCore?.unloadAll) await this.ruvectorCore.unloadAll();
    for (const info of this.models.values()) info.loaded = false;
    this.activeModel = null;
    this.kvCacheEntries = 0;
  }

  // ── Private ───────────────────────────────────────────────

  private async scanModelsDir(): Promise<void> {
    try {
      const entries = await readdir(this.config.modelsDir);
      for (const entry of entries) {
        if (extname(entry).toLowerCase() !== '.gguf') continue;
        const fullPath = join(this.config.modelsDir, entry);
        const s = await stat(fullPath);
        if (!s.isFile()) continue;
        const name = basename(entry, '.gguf');
        this.models.set(name, {
          name, path: fullPath, format: 'gguf',
          quantization: inferQuantization(entry), size: s.size,
          parameters: inferParameters(entry), loaded: false,
        });
      }
    } catch {
      // modelsDir may not exist -- tier 1 and tier 3 still work
    }
  }

  private async tryImport(pkg: string): Promise<any> {
    try { return await import(pkg); } catch { return null; }
  }

  /** Tier-1 Agent Booster: handle trivial transforms without any LLM. */
  private tryAgentBooster(prompt: string): string | null {
    const t = prompt.trim();
    if (t.length > 200) return null;
    if (/^(convert|change)\s+(var|let)\s+to\s+const$/i.test(t)) {
      return 'Use the Edit tool to replace `var`/`let` declarations with `const`.';
    }
    if (/^remove\s+console\.(log|warn|error|debug|info)$/i.test(t)) {
      const m = t.toLowerCase().match(/console\.(\w+)/)?.[1] ?? 'log';
      return `Use the Edit tool to remove all \`console.${m}\` calls.`;
    }
    return null;
  }
}

// ── Singleton accessor ──────────────────────────────────────

let instance: RuvllmBridge | null = null;

/** Get or create the singleton RuvllmBridge. Config required on first call. */
export function getRuvllmBridge(config?: RuvllmConfig): RuvllmBridge {
  if (!instance && config) instance = new RuvllmBridge(config);
  if (!instance) throw new Error('ruvLLM bridge not initialized. Call with config first.');
  return instance;
}

/** Reset the singleton (useful for tests). */
