/** Check whether @ruvector/core is importable without loading the bridge. */
export async function isRuvllmAvailable(): Promise<boolean> {
  try { await import('@ruvector/core'); return true; } catch { return false; }
}

/**
 * RVFA Appliance Builder -- Constructs self-contained .rvf appliance files.
 *
 * Creates a single binary containing kernel, runtime, Ruflo CLI, models/keys,
 * AgentDB data, and the verification suite. See ADR-058.
 */

import {
  createHash, scryptSync, randomBytes, createCipheriv, createDecipheriv,
} from 'node:crypto';
import { readFileSync, existsSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { execSync } from 'node:child_process';
import {
  RvfaWriter, type RvfaHeader, type RvfaBootConfig, type RvfaModelConfig,
} from './rvfa-format.js';

// ── Public Interfaces ────────────────────────────────────────

export interface BuildOptions {
  profile: 'cloud' | 'hybrid' | 'offline';
  arch: string;
  output: string;
  rufloVersion?: string;
  models?: string[];
  apiKeys?: string;
  verbose?: boolean;
}

export interface BuildResult {
  outputPath: string;
  size: number;
  sections: { id: string; size: number; originalSize: number }[];
  duration: number;
  profile: string;
}

// ── Encryption Constants ─────────────────────────────────────

const SCRYPT_KEY_LEN = 32;
const SCRYPT_SALT_LEN = 32;
const SCRYPT_OPTS = { N: 16384, r: 8, p: 1 };
const AES_IV_LEN = 16;
const AES_TAG_LEN = 16;
const AES_ALG = 'aes-256-gcm' as const;

// ── Catalog ──────────────────────────────────────────────────

const RUFLO_COMMANDS = 'init agent swarm memory mcp task session config status start workflow hooks hive-mind daemon neural security performance providers plugins deployment embeddings claims migrate process doctor completions'.split(' ');

const AGENT_TYPES = 'coder reviewer tester planner researcher security-architect security-auditor memory-specialist performance-engineer hierarchical-coordinator mesh-coordinator adaptive-coordinator collective-intelligence-coordinator swarm-memory-manager byzantine-coordinator raft-manager gossip-coordinator consensus-builder crdt-synchronizer quorum-manager security-manager perf-analyzer performance-benchmarker task-orchestrator memory-coordinator smart-agent github-modes pr-manager code-review-swarm issue-tracker release-manager workflow-automation project-board-sync repo-architect multi-repo-swarm sparc-coord sparc-coder specification pseudocode architecture refinement backend-dev mobile-dev ml-developer cicd-engineer api-docs system-architect code-analyzer base-template-generator tdd-london-swarm production-validator'.split(' ');

const HOOK_TYPES = 'pre-edit post-edit pre-command post-command pre-task post-task session-start session-end session-restore notify route explain pretrain build-agents transfer teammate-idle task-completed'.split(' ');

const WORKER_TYPES = 'ultralearn optimize consolidate predict audit map preload deepdive document refactor benchmark testgaps'.split(' ');

const OFFLINE_MODELS = [
  { name: 'phi-3-mini-q4', format: 'gguf', sizeHint: '2.3GB', params: '3.8B' },
  { name: 'qwen2.5-coder-3b-q4', format: 'gguf', sizeHint: '1.7GB', params: '3B' },
];

// ── API Key Encryption / Decryption ──────────────────────────

/** Encrypt API keys from a .env file. Output: salt(32)+iv(16)+tag(16)+ciphertext */
export function encryptApiKeys(envPath: string, passphrase: string): Buffer {
  const keys = parseEnvFile(readFileSync(envPath, 'utf-8'));
  const plaintext = Buffer.from(JSON.stringify(keys), 'utf-8');

  const salt = randomBytes(SCRYPT_SALT_LEN);
  const key = scryptSync(passphrase, salt, SCRYPT_KEY_LEN, SCRYPT_OPTS);
  const iv = randomBytes(AES_IV_LEN);
  const cipher = createCipheriv(AES_ALG, key, iv);
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);

  return Buffer.concat([salt, iv, cipher.getAuthTag(), encrypted]);
}

/** Decrypt API keys previously encrypted with encryptApiKeys. */
export function decryptApiKeys(buf: Buffer, passphrase: string): Record<string, string> {
  const minLen = SCRYPT_SALT_LEN + AES_IV_LEN + AES_TAG_LEN + 1;
  if (buf.length < minLen) {
    throw new Error(`Encrypted buffer too short: need >= ${minLen}B, got ${buf.length}B`);
  }

  let off = 0;
  const salt = buf.subarray(off, off += SCRYPT_SALT_LEN);
  const iv = buf.subarray(off, off += AES_IV_LEN);
  const tag = buf.subarray(off, off += AES_TAG_LEN);
  const ciphertext = buf.subarray(off);

  const key = scryptSync(passphrase, salt, SCRYPT_KEY_LEN, SCRYPT_OPTS);
  const decipher = createDecipheriv(AES_ALG, key, iv);
  decipher.setAuthTag(tag);

  return JSON.parse(
    Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf-8'),
  );
}

// ── Builder ──────────────────────────────────────────────────

type SectionId = 'kernel' | 'runtime' | 'ruflo' | 'models' | 'data' | 'verify';

export class RvfaBuilder {
  private opts: Required<BuildOptions>;

  constructor(options: BuildOptions) {
    this.opts = {
      arch: options.arch || 'x86_64',
      profile: options.profile,
      output: resolve(options.output),
      rufloVersion: options.rufloVersion || detectRufloVersion(),
      models: options.models ?? defaultModelsForProfile(options.profile),
      apiKeys: options.apiKeys ?? '',
      verbose: options.verbose ?? false,
    };
  }

  async build(): Promise<BuildResult> {
    const t0 = performance.now();
    this.log(`Building RVFA appliance (profile=${this.opts.profile}, arch=${this.opts.arch})`);

    const outDir = dirname(this.opts.output);
    if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });

    const stages: { id: SectionId; raw: Buffer; label: string }[] = [
      { id: 'kernel',  raw: this.buildKernelSection(),  label: 'Kernel (Alpine rootfs)' },
      { id: 'runtime', raw: this.buildRuntimeSection(), label: 'Runtime (Node.js + Claude Code)' },
      { id: 'ruflo',   raw: this.buildRufloSection(),   label: 'Ruflo CLI' },
      { id: 'models',  raw: this.buildModelsSection(),  label: `Models (${this.opts.profile})` },
      { id: 'data',    raw: this.buildDataSection(),    label: 'Data (AgentDB)' },
      { id: 'verify',  raw: this.buildVerifySection(),  label: 'Verify (test suite)' },
    ];

    const writer = new RvfaWriter(this.buildHeaderPartial());
    const summary: BuildResult['sections'] = [];

    for (const s of stages) {
      const st = performance.now();
      this.log(`  Stage: ${s.label}...`);
      writer.addSection(s.id, s.raw, { type: s.id });
      this.log(`    ${fmtBytes(s.raw.length)} raw (${elapsed(st)})`);
      summary.push({ id: s.id, size: 0, originalSize: s.raw.length });
    }

    const binary = writer.build();

    // Patch compressed sizes from the built header
    try {
      const hLen = binary.readUInt32LE(8);
      const hdr = JSON.parse(binary.subarray(12, 12 + hLen).toString('utf-8')) as RvfaHeader;
      for (const sec of hdr.sections) {
        const e = summary.find((x) => x.id === sec.id);
        if (e) e.size = sec.size;
      }
    } catch { /* non-fatal */ }

    writeFileSync(this.opts.output, binary);
    const duration = performance.now() - t0;

    this.log('');
    this.log('RVFA appliance built successfully.');
    this.log(`  Output: ${this.opts.output}  Size: ${fmtBytes(binary.length)}  Duration: ${elapsed(t0)}`);
    for (const s of summary) {
      const r = s.originalSize > 0 && s.size > 0
        ? ` (${((1 - s.size / s.originalSize) * 100).toFixed(1)}% reduction)` : '';
      this.log(`    ${s.id}: ${fmtBytes(s.originalSize)} -> ${fmtBytes(s.size)}${r}`);
    }

    return { outputPath: this.opts.output, size: binary.length, sections: summary, duration, profile: this.opts.profile };
  }

  // ── Section Builders ─────────────────────────────────────

  private buildKernelSection(): Buffer {
    return jsonBuf({
      type: 'kernel', distribution: 'alpine', version: '3.23', arch: this.opts.arch,
      packages: ['busybox', 'dumb-init', 'musl'],
      init: '/sbin/init -> ruflo-init (PID 1)',
      features: ['minimal rootfs', 'read-only root filesystem', 'tmpfs for /tmp and /run', 'seccomp profile applied'],
      sizeTarget: '~5MB compressed',
      note: 'Manifest-only: actual rootfs fetched during full build pipeline',
    });
  }

  private buildRuntimeSection(): Buffer {
    let nodeVersion = 'v22.0.0';
    try { nodeVersion = execSync('node --version', { encoding: 'utf-8' }).trim(); } catch { /* keep default */ }

    return jsonBuf({
      type: 'runtime',
      node: { version: nodeVersion, target: 'v22', variant: `linux-${this.opts.arch}-musl`, stripped: true, excludes: ['npm', 'corepack', 'debug-symbols'] },
      claudeCode: { name: 'claude-code-cli', entrypoint: '/usr/local/bin/claude' },
      paths: { node: '/usr/local/bin/node', claude: '/usr/local/bin/claude' },
    });
  }

  private buildRufloSection(): Buffer {
    let packageMeta: Record<string, unknown> | null = null;
    try {
      const raw = execSync('npm pack ruflo@latest --dry-run --json 2>/dev/null', { encoding: 'utf-8', timeout: 15_000 });
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) packageMeta = parsed[0];
    } catch { /* manifest-only fallback */ }

    return jsonBuf({
      type: 'ruflo', version: this.opts.rufloVersion,
      package: packageMeta ?? { name: 'ruflo', version: this.opts.rufloVersion },
      commands: RUFLO_COMMANDS, commandCount: RUFLO_COMMANDS.length,
      agents: AGENT_TYPES, agentCount: AGENT_TYPES.length,
      hooks: { count: HOOK_TYPES.length, types: HOOK_TYPES },
      workers: { count: WORKER_TYPES.length, types: WORKER_TYPES },
      mcpTools: 215,
    });
  }

  private buildModelsSection(): Buffer {
    const p = this.opts.profile;
    const resolveModels = (names: string[]) => names.map((n) => OFFLINE_MODELS.find((m) => m.name === n) ?? { name: n, format: 'gguf', sizeHint: 'unknown', params: 'unknown' });

    if (p === 'cloud') {
      const content: Record<string, unknown> = { type: 'models', profile: 'cloud', provider: 'api-vault', models: [] };
      if (this.opts.apiKeys && existsSync(this.opts.apiKeys)) {
        const enc = encryptApiKeys(this.opts.apiKeys, generateBuildPassphrase());
        content.vault = { format: AES_ALG, kdf: 'scrypt', kdfParams: SCRYPT_OPTS, encrypted: enc.toString('base64') };
        this.log('    API keys encrypted into vault');
      } else {
        content.vault = null;
        content.note = 'No API keys provided; set --api-keys to include vault';
      }
      return jsonBuf(content);
    }

    if (p === 'hybrid') {
      const content: Record<string, unknown> = {
        type: 'models', profile: 'hybrid', provider: 'hybrid', engine: 'ruvllm+api-vault',
        localModels: resolveModels(this.opts.models),
        routing: { tier1: { handler: 'agent-booster', latency: '<1ms' }, tier2: { handler: 'local-model', latency: '~200ms' }, tier3: { handler: 'cloud-api', latency: '2-5s' }, complexityThreshold: 0.3 },
      };
      if (this.opts.apiKeys && existsSync(this.opts.apiKeys)) {
        const enc = encryptApiKeys(this.opts.apiKeys, generateBuildPassphrase());
        content.vault = { format: AES_ALG, kdf: 'scrypt', encrypted: enc.toString('base64') };
        this.log('    API keys encrypted into vault');
      }
      return jsonBuf(content);
    }

    // offline
    const names = this.opts.models.length > 0 ? this.opts.models : ['phi-3-mini-q4', 'qwen2.5-coder-3b-q4'];
    return jsonBuf({
      type: 'models', profile: 'offline', provider: 'ruvllm', engine: 'ruvllm',
      models: resolveModels(names),
      routing: { tier1: { handler: 'agent-booster-wasm', latency: '<1ms' }, tier2: { handler: 'phi-3-mini-q4', latency: '~200ms' }, tier3: { handler: 'qwen2.5-coder-3b-q4', latency: '~2s' }, fallbackToCloud: false },
      kvCache: { backend: 'rvf', persistence: true },
      note: 'Manifest-only: GGUF weights fetched during full build pipeline',
    });
  }

  private buildDataSection(): Buffer {
    // Empty RVF database header (matches rvf-backend.ts RVF\0 magic)
    const rvfMagic = Buffer.from([0x52, 0x56, 0x46, 0x00]);
    const hdrJson = Buffer.from(JSON.stringify({
      magic: 'RVF\0', version: 1, dimensions: 1536, metric: 'cosine',
      quantization: 'fp32', entryCount: 0, createdAt: Date.now(), updatedAt: Date.now(),
    }), 'utf-8');
    const hdrLen = Buffer.alloc(4);
    hdrLen.writeUInt32LE(hdrJson.length, 0);
    const rvfDb = Buffer.concat([rvfMagic, hdrLen, hdrJson]);

    const manifest = jsonBuf({
      type: 'data',
      components: {
        agentDb: { format: 'rvf', magicBytes: 'RVF\\0', databaseSize: rvfDb.length },
        hnswIndex: { type: 'hnsw-index', dimensions: 1536, metric: 'cosine', m: 16, efConstruction: 200, maxElements: 100_000, vectorCount: 0 },
        sonaPatterns: { type: 'sona-patterns', version: 1, architecture: 'self-optimizing-neural', adaptationTime: '<0.05ms', patterns: [], expertCount: 8, moeConfig: { topK: 2, capacityFactor: 1.25, loadBalancingLoss: 0.01 } },
        pluginRegistry: { source: 'ipfs', snapshotted: true, pluginCount: 20 },
      },
    });

    return Buffer.concat([rvfDb, Buffer.from('\n---DATA-MANIFEST---\n'), manifest]);
  }

  private buildVerifySection(): Buffer {
    const scriptPath = resolve(dirname(new URL(import.meta.url).pathname), '../../../../scripts/verify-appliance.sh');
    let script: Buffer;

    if (existsSync(scriptPath)) {
      script = readFileSync(scriptPath);
      this.log(`    Bundled verify-appliance.sh (${fmtBytes(script.length)})`);
    } else {
      script = Buffer.from([
        '#!/bin/sh', 'set -e', 'RUFLO_CMD="${RUFLO_CMD:-ruflo}"',
        'echo "Running basic verification..."',
        '$RUFLO_CMD --version && echo "  OK: CLI" || echo "  FAIL: CLI"',
        '$RUFLO_CMD doctor && echo "  OK: Doctor" || echo "  FAIL: Doctor"',
        'echo "Verification complete."',
      ].join('\n'), 'utf-8');
      this.log('    Using stub verify script (verify-appliance.sh not found)');
    }

    const manifest = jsonBuf({
      type: 'verify-manifest', categories: 35, criticalChecks: 95,
      script: 'verify-appliance.sh',
      scriptSha256: createHash('sha256').update(script).digest('hex'),
      quickMode: { categories: [1, 2, 3, 4, 5, 25] },
    });

    return Buffer.concat([script, Buffer.from('\n---VERIFY-MANIFEST---\n'), manifest]);
  }

  // ── Header ───────────────────────────────────────────────

  private buildHeaderPartial(): Partial<RvfaHeader> {
    const providerMap: Record<string, RvfaModelConfig['provider']> = { cloud: 'api-vault', hybrid: 'hybrid', offline: 'ruvllm' };
    const caps = ['cli-26-commands', 'agents-60-plus', 'hooks-17', 'workers-12', 'mcp-215-tools', 'agentdb-rvf', 'hnsw-search', 'sona-patterns', 'security-scanning', 'performance-profiling', 'hive-mind-consensus', 'plugin-registry'];
    if (this.opts.profile !== 'cloud') caps.push('local-inference-ruvllm');
    if (this.opts.profile !== 'offline') caps.push('cloud-api-vault');

    const boot: RvfaBootConfig = {
      entrypoint: '/opt/ruflo/bin/cli.js',
      args: ['--profile', this.opts.profile],
      env: { NODE_ENV: 'production', CLAUDE_FLOW_MEMORY_BACKEND: 'hybrid', CLAUDE_FLOW_LOG_LEVEL: 'info' },
      isolation: this.opts.profile === 'cloud' ? 'container' : 'native',
    };

    const models: RvfaModelConfig = {
      provider: providerMap[this.opts.profile],
      engine: this.opts.profile === 'cloud' ? undefined : 'ruvllm-0.1.0',
      models: this.opts.models.length > 0 ? this.opts.models : undefined,
      vaultEncryption: this.opts.profile !== 'offline' ? 'aes-256-gcm' : undefined,
    };

    return {
      magic: 'RVFA', version: 1, name: 'ruflo-appliance', appVersion: this.opts.rufloVersion,
      arch: this.opts.arch, platform: 'linux', profile: this.opts.profile,
      created: new Date().toISOString(), boot, models, capabilities: caps,
    };
  }

  private log(msg: string): void {
    if (this.opts.verbose) console.log(`[RvfaBuilder] ${msg}`);
  }
}

// ── Helpers ──────────────────────────────────────────────────

function jsonBuf(obj: unknown): Buffer {
  return Buffer.from(JSON.stringify(obj, null, 2), 'utf-8');
}

function parseEnvFile(content: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const eq = t.indexOf('=');
    if (eq === -1) continue;
    const k = t.substring(0, eq).trim();
    let v = t.substring(eq + 1).trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    if (k) result[k] = v;
  }
  return result;
}

function detectRufloVersion(): string {
  try {
    const p = resolve(dirname(new URL(import.meta.url).pathname), '../../package.json');
    if (existsSync(p)) return JSON.parse(readFileSync(p, 'utf-8')).version ?? '3.5.0';
  } catch { /* ignore */ }
  return '3.5.0';
}

function defaultModelsForProfile(profile: string): string[] {
  if (profile === 'offline') return ['phi-3-mini-q4', 'qwen2.5-coder-3b-q4'];
  if (profile === 'hybrid') return ['phi-3-mini-q4'];
  return [];
}

function generateBuildPassphrase(): string {
  return randomBytes(32).toString('hex');
}

function fmtBytes(b: number): string {
  if (b < 1024) return `${b}B`;
  if (b < 1048576) return `${(b / 1024).toFixed(1)}KB`;
  if (b < 1073741824) return `${(b / 1048576).toFixed(1)}MB`;
  return `${(b / 1073741824).toFixed(2)}GB`;
}

function elapsed(t: number): string {
  const ms = performance.now() - t;
  return ms < 1000 ? `${ms.toFixed(0)}ms` : `${(ms / 1000).toFixed(2)}s`;
}

/**
 * RVFA Distribution & Hot-Patch Module
 *
 * IPFS publishing of RVFA appliances via Pinata and RVFP binary patches
 * for section-level hot updates with atomic rollback.
 *
 * RVFP layout: [4B "RVFP"] [4B version u32LE] [4B header_len u32LE]
 *              [header JSON] [new section data] [32B SHA256 footer]
 */

import { createHash, sign, verify as edVerify } from 'node:crypto';
import { readFile, writeFile, rename, unlink, copyFile, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';
import { request as httpsRequest } from 'node:https';
import { gzipSync, gunzipSync } from 'node:zlib';
import { RvfaReader, RvfaWriter } from './rvfa-format.js';

// ── Constants ────────────────────────────────────────────────
const RVFP_VERSION = 1;
const PRE = 12; // preamble: 4 magic + 4 version + 4 header_len
const SHA_LEN = 32;
const DEFAULT_GW = 'https://gateway.pinata.cloud';
const DEFAULT_API = 'https://api.pinata.cloud';

// ── Types ────────────────────────────────────────────────────
export interface RvfpHeader {
  magic: 'RVFP'; version: number;
  targetApplianceName: string; targetApplianceVersion: string;
  targetSection: string; patchVersion: string; created: string;
  newSectionSize: number; newSectionSha256: string;
  compression: 'none' | 'gzip'; signature?: string; signedBy?: string;
}
export interface CreatePatchOptions {
  targetName: string; targetVersion: string; sectionId: string;
  sectionData: Buffer; patchVersion: string;
  compression?: 'none' | 'gzip'; privateKey?: Buffer; signedBy?: string;
}
export interface ApplyOptions { backup?: boolean; verify?: boolean; publicKey?: Buffer }
export interface ApplyResult {
  success: boolean; backupPath?: string; newSize: number;
  patchedSection: string; errors: string[];
}
export interface PatchVerifyResult { valid: boolean; header: RvfpHeader; errors: string[] }
export interface PublishConfig { pinataJwt?: string; gatewayUrl?: string; apiUrl?: string }
export interface PublishMetadata { name?: string; description?: string; version?: string; profile?: string }
export interface PublishResult { cid: string; size: number; gatewayUrl: string; pinataUrl: string }
export interface PublishedItem { cid: string; name: string; size: number; date: string }

// ── Crypto helpers ───────────────────────────────────────────
function sha256(d: Buffer): string { return createHash('sha256').update(d).digest('hex'); }
function sha256B(d: Buffer): Buffer { return createHash('sha256').update(d).digest(); }

function detectKeyFormat(key: Buffer): { format: 'pem' | 'der'; type: string } {
  const str = key.toString('utf-8');
  if (str.includes('BEGIN PRIVATE KEY')) return { format: 'pem', type: 'pkcs8' };
  if (str.includes('BEGIN PUBLIC KEY')) return { format: 'pem', type: 'spki' };
  // Heuristic: DER-encoded keys are raw binary, never valid UTF-8 "BEGIN"
  return { format: 'der', type: 'pkcs8' }; // caller must override type for public keys
}

function edSign(data: Buffer, key: Buffer): string {
  const det = detectKeyFormat(key);
  return sign(null, data, { key, format: det.format, type: det.type } as any).toString('hex');
}
function edCheck(data: Buffer, sig: string, key: Buffer): boolean {
  try {
    const det = detectKeyFormat(key);
    const type = det.format === 'pem' ? det.type : 'spki'; // public key for verify
    return edVerify(null, data, { key, format: det.format, type } as any, Buffer.from(sig, 'hex'));
  } catch { return false; }
}

// ── HTTP helpers ─────────────────────────────────────────────
function pinataReq(
  method: string, path: string, jwt: string, body?: Buffer, ct?: string,
): Promise<{ status: number; data: unknown }> {
  return new Promise((resolve, reject) => {
    const u = new URL(path);
    const h: Record<string, string> = { Authorization: `Bearer ${jwt}` };
    if (ct) h['Content-Type'] = ct;
    if (body) h['Content-Length'] = String(body.length);
    const req = httpsRequest(
      { hostname: u.hostname, path: u.pathname + u.search, method, headers: h },
      (res) => {
        const ch: Buffer[] = [];
        res.on('data', (c: Buffer) => ch.push(c));
        res.on('end', () => {
          const raw = Buffer.concat(ch);
          let data: unknown;
          try { data = JSON.parse(raw.toString('utf-8')); } catch { data = raw; }
          resolve({ status: res.statusCode ?? 0, data });
        });
      },
    );
    req.setTimeout(30_000, () => { req.destroy(new Error('Request timed out after 30s')); });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

function httpGet(url: string, maxRedirects = 5): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    if (maxRedirects <= 0) return reject(new Error('Too many redirects'));
    const u = new URL(url);
    const req = httpsRequest({ hostname: u.hostname, path: u.pathname + u.search, method: 'GET' }, (res) => {
      if (res.statusCode && res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return void httpGet(res.headers.location, maxRedirects - 1).then(resolve, reject);
      }
      const ch: Buffer[] = [];
      res.on('data', (c: Buffer) => ch.push(c));
      res.on('end', () => resolve(Buffer.concat(ch)));
    });
    req.setTimeout(30_000, () => { req.destroy(new Error('Request timed out after 30s')); });
    req.on('error', reject);
    req.end();
  });
}

function multipart(
  name: string, file: string, data: Buffer, meta?: string,
): { body: Buffer; ct: string } {
  const b = `----Rvfa${Date.now()}${Math.random().toString(36).slice(2)}`;
  const parts: Buffer[] = [];
  if (meta) {
    parts.push(Buffer.from(
      `--${b}\r\nContent-Disposition: form-data; name="pinataMetadata"\r\n` +
      `Content-Type: application/json\r\n\r\n${meta}\r\n`,
    ));
  }
  parts.push(Buffer.from(
    `--${b}\r\nContent-Disposition: form-data; name="${name}"; filename="${file}"\r\n` +
    `Content-Type: application/octet-stream\r\n\r\n`,
  ));
  parts.push(data, Buffer.from(`\r\n--${b}--\r\n`));
  return { body: Buffer.concat(parts), ct: `multipart/form-data; boundary=${b}` };
}

/** Extract patch section data and bounds from a parsed patch buffer. */
function patchData(buf: Buffer): { start: number; end: number; section: Buffer } {
  const hLen = buf.readUInt32LE(8);
  const start = PRE + hLen;
  const end = buf.length - SHA_LEN;
  return { start, end, section: buf.subarray(start, end) };
}

/** Canonical JSON: recursive key-sorting for deterministic serialization. */
function canonicalJson(value: unknown): string {
  return JSON.stringify(value, (_key, val) => {
    if (val !== null && typeof val === 'object' && !Array.isArray(val) && !Buffer.isBuffer(val)) {
      const sorted: Record<string, unknown> = {};
      for (const k of Object.keys(val as Record<string, unknown>).sort()) {
        sorted[k] = (val as Record<string, unknown>)[k];
      }
      return sorted;
    }
    return val;
  });
}

/** Build a failed ApplyResult. */
function failResult(sec: string, errs: string[], extra?: Partial<ApplyResult>): ApplyResult {
  return { success: false, newSize: 0, patchedSection: sec, errors: errs, ...extra };
}

// ── RvfaPatcher ──────────────────────────────────────────────
export class RvfaPatcher {
  static async createPatch(opts: CreatePatchOptions): Promise<Buffer> {
    const comp = opts.compression ?? 'none';
    const payload = comp === 'gzip' ? gzipSync(opts.sectionData) : opts.sectionData;
    const header: RvfpHeader = {
      magic: 'RVFP', version: RVFP_VERSION,
      targetApplianceName: opts.targetName, targetApplianceVersion: opts.targetVersion,
      targetSection: opts.sectionId, patchVersion: opts.patchVersion,
      created: new Date().toISOString(), newSectionSize: payload.length,
      newSectionSha256: sha256(payload), compression: comp,
    };
    if (opts.privateKey && opts.signedBy) {
      const signable = Buffer.concat([Buffer.from(canonicalJson(header), 'utf-8'), payload]);
      header.signature = edSign(signable, opts.privateKey);
      header.signedBy = opts.signedBy;
    }
    const hJson = Buffer.from(JSON.stringify(header), 'utf-8');
    const magic = Buffer.from('RVFP');
    const ver = Buffer.alloc(4); ver.writeUInt32LE(RVFP_VERSION, 0);
    const hLen = Buffer.alloc(4); hLen.writeUInt32LE(hJson.length, 0);
    return Buffer.concat([magic, ver, hLen, hJson, payload, sha256B(payload)]);
  }

  static parsePatchHeader(buf: Buffer): RvfpHeader {
    if (buf.length < PRE) throw new Error('Buffer too small for RVFP preamble');
    const magic = buf.subarray(0, 4).toString('ascii');
    if (magic !== 'RVFP') throw new Error(`Invalid RVFP magic: "${magic}"`);
    const ver = buf.readUInt32LE(4);
    if (ver !== RVFP_VERSION) throw new Error(`Unsupported RVFP version: ${ver}`);
    const hLen = buf.readUInt32LE(8);
    if (PRE + hLen > buf.length) throw new Error('Buffer too small for declared header');
    const h = JSON.parse(buf.subarray(PRE, PRE + hLen).toString('utf-8')) as RvfpHeader;
    if (h.magic !== 'RVFP') throw new Error('RVFP header magic mismatch');
    return h;
  }

  static async verifyPatch(buf: Buffer): Promise<PatchVerifyResult> {
    const errors: string[] = [];
    let header: RvfpHeader;
    try { header = RvfaPatcher.parsePatchHeader(buf); } catch (e) {
      const empty: RvfpHeader = {
        magic: 'RVFP', version: 0, targetApplianceName: '', targetApplianceVersion: '',
        targetSection: '', patchVersion: '', created: '', newSectionSize: 0,
        newSectionSha256: '', compression: 'none',
      };
      return { valid: false, header: empty, errors: [(e as Error).message] };
    }
    const { start, end, section } = patchData(buf);
    if (end < start) {
      errors.push('Patch too small: no room for section data and footer');
      return { valid: false, header, errors };
    }
    if (section.length !== header.newSectionSize)
      errors.push(`Size mismatch: header=${header.newSectionSize}, actual=${section.length}`);
    if (sha256(section) !== header.newSectionSha256)
      errors.push('Section SHA256 mismatch');
    if (!sha256B(section).equals(buf.subarray(buf.length - SHA_LEN)))
      errors.push('Footer SHA256 mismatch');
    return { valid: errors.length === 0, header, errors };
  }

  static async applyPatch(
    rvfaPath: string, patchBuf: Buffer, opts?: ApplyOptions,
  ): Promise<ApplyResult> {
    const doBackup = opts?.backup ?? true;
    const doVerify = opts?.verify ?? true;

    // Parse & verify patch
    let header: RvfpHeader;
    try { header = RvfaPatcher.parsePatchHeader(patchBuf); } catch (e) {
      return failResult('', [(e as Error).message]);
    }
    const sec = header.targetSection;

    // Verify signature
    if (opts?.publicKey && header.signature) {
      const { section } = patchData(patchBuf);
      const unsigned = { ...header } as Record<string, unknown>;
      delete unsigned.signature; delete unsigned.signedBy;
      const signable = Buffer.concat([Buffer.from(canonicalJson(unsigned), 'utf-8'), section]);
      if (!edCheck(signable, header.signature, opts.publicKey))
        return failResult(sec, ['Patch signature verification failed']);
    }

    // Verify patch integrity
    const check = await RvfaPatcher.verifyPatch(patchBuf);
    if (!check.valid) return failResult(sec, check.errors);

    // Read target RVFA
    let reader: RvfaReader;
    try { reader = await RvfaReader.fromFile(rvfaPath); } catch (e) {
      return failResult(sec, [`Failed to read RVFA: ${(e as Error).message}`]);
    }
    const rh = reader.getHeader();

    // Verify target matches
    const errs: string[] = [];
    if (rh.name !== header.targetApplianceName)
      errs.push(`Name mismatch: patch="${header.targetApplianceName}", file="${rh.name}"`);
    if (rh.appVersion !== header.targetApplianceVersion)
      errs.push(`Version mismatch: patch="${header.targetApplianceVersion}", file="${rh.appVersion}"`);
    if (errs.length) return failResult(sec, errs);
    if (!rh.sections.find((s) => s.id === sec))
      return failResult(sec, [`Section "${sec}" not found in appliance`]);

    // Backup
    let backupPath: string | undefined;
    if (doBackup) { backupPath = rvfaPath + '.bak'; await copyFile(rvfaPath, backupPath); }

    // Extract new section data from patch (decompress if needed)
    let newData = patchData(patchBuf).section;
    if (header.compression === 'gzip') newData = gunzipSync(newData);

    // Rebuild RVFA with replaced section
    const writer = new RvfaWriter({ ...rh, sections: [] });
    for (const s of rh.sections) {
      const comp = s.compression === 'zstd' ? 'gzip' : s.compression;
      if (s.id === sec) {
        writer.addSection(s.id, newData, { compression: comp, type: s.type });
      } else {
        writer.addSection(s.id, reader.extractSection(s.id), { compression: comp, type: s.type });
      }
    }
    const newRvfa = writer.build();

    // Atomic write (tmp + rename)
    const tmpPath = rvfaPath + `.tmp.${Date.now()}`;
    try {
      await writeFile(tmpPath, newRvfa);
      await rename(tmpPath, rvfaPath);
    } catch (e) {
      await unlink(tmpPath).catch(() => {});
      if (backupPath) await copyFile(backupPath, rvfaPath).catch(() => {});
      return failResult(sec, [`Atomic write failed: ${(e as Error).message}`], { backupPath });
    }

    // Post-patch verification with rollback
    if (doVerify) {
      try {
        const vr = await RvfaReader.fromFile(rvfaPath);
        const vResult = vr.verify();
        if (!vResult.valid) {
          if (backupPath) await copyFile(backupPath, rvfaPath).catch(() => {});
          return failResult(sec, [`Post-patch verification failed: ${vResult.errors.join('; ')}`],
            { backupPath, newSize: newRvfa.length });
        }
      } catch (e) {
        if (backupPath) await copyFile(backupPath, rvfaPath).catch(() => {});
        return failResult(sec, [`Post-patch verify error: ${(e as Error).message}`],
          { backupPath, newSize: newRvfa.length });
      }
    }

    return { success: true, backupPath, newSize: newRvfa.length, patchedSection: sec, errors: [] };
  }
}

// ── RvfaPublisher ────────────────────────────────────────────
export class RvfaPublisher {
  private jwt: string;
  private gw: string;
  private api: string;

  constructor(config: PublishConfig) {
    this.jwt = config.pinataJwt || process.env.PINATA_API_JWT || '';
    this.gw = (config.gatewayUrl || DEFAULT_GW).replace(/\/+$/, '');
    this.api = (config.apiUrl || DEFAULT_API).replace(/\/+$/, '');
    if (!this.jwt) throw new Error('Pinata JWT required (config.pinataJwt or PINATA_API_JWT)');
  }

  private async upload(
    fileName: string, data: Buffer, kv: Record<string, string>,
  ): Promise<PublishResult> {
    const meta = JSON.stringify({ name: fileName, keyvalues: kv });
    const { body, ct } = multipart('file', fileName, data, meta);
    const res = await pinataReq('POST', `${this.api}/pinning/pinFileToIPFS`, this.jwt, body, ct);
    if (res.status !== 200)
      throw new Error(`Pinata upload failed (HTTP ${res.status}): ${JSON.stringify(res.data)}`);
    const r = res.data as { IpfsHash: string; PinSize: number };
    return {
      cid: r.IpfsHash, size: r.PinSize,
      gatewayUrl: `${this.gw}/ipfs/${r.IpfsHash}`, pinataUrl: `${this.api}/pinning/pins/${r.IpfsHash}`,
    };
  }

  async publish(rvfaPath: string, meta?: PublishMetadata): Promise<PublishResult> {
    const data = await readFile(rvfaPath);
    const name = meta?.name || rvfaPath.split('/').pop() || 'appliance.rvf';
    return this.upload(name, data, {
      type: 'rvfa-appliance', version: meta?.version || '',
      profile: meta?.profile || '', description: meta?.description || '',
    });
  }

  async publishPatch(patchBuf: Buffer, meta?: PublishMetadata): Promise<PublishResult> {
    const name = meta?.name || `patch-${Date.now()}.rvfp`;
    return this.upload(name, patchBuf, {
      type: 'rvfp-patch', version: meta?.version || '', description: meta?.description || '',
    });
  }

  async fetch(cid: string, outputPath: string): Promise<void> {
    const data = await httpGet(`${this.gw}/ipfs/${cid}`);
    await mkdir(dirname(outputPath), { recursive: true });
    await writeFile(outputPath, data);
  }

  async list(): Promise<PublishedItem[]> {
    const res = await pinataReq('GET', `${this.api}/data/pinList?status=pinned&pageLimit=100`, this.jwt);
    if (res.status !== 200)
      throw new Error(`Pinata list failed (HTTP ${res.status}): ${JSON.stringify(res.data)}`);
    const d = res.data as { rows: Array<{
      ipfs_pin_hash: string; metadata?: { name?: string }; size: number; date_pinned: string;
    }> };
    return (d.rows || []).map((r) => ({
      cid: r.ipfs_pin_hash, name: r.metadata?.name || r.ipfs_pin_hash,
      size: r.size, date: r.date_pinned,
    }));
  }

  async pin(cid: string, name?: string): Promise<void> {
    const body = Buffer.from(JSON.stringify({ hashToPin: cid, pinataMetadata: { name: name || cid } }));
    const res = await pinataReq('POST', `${this.api}/pinning/pinByHash`, this.jwt, body, 'application/json');
    if (res.status !== 200)
      throw new Error(`Pinata pin failed (HTTP ${res.status}): ${JSON.stringify(res.data)}`);
  }
}

// ── Convenience exports ──────────────────────────────────────
export function createPublisher(config?: Partial<PublishConfig>): RvfaPublisher {
  return new RvfaPublisher({ pinataJwt: config?.pinataJwt, gatewayUrl: config?.gatewayUrl, apiUrl: config?.apiUrl });
}

export async function createAndVerifyPatch(
  options: CreatePatchOptions,
): Promise<{ patch: Buffer; verification: PatchVerifyResult }> {
  const patch = await RvfaPatcher.createPatch(options);
  const verification = await RvfaPatcher.verifyPatch(patch);
  return { patch, verification };
}

/**
 * RVFA (RuVector Format Appliance) — Binary format reader/writer
 * for self-contained Ruflo appliances.
 *
 * Binary layout:
 *   [4B magic "RVFA"] [4B version u32LE] [4B header_len u32LE]
 *   [header_len B JSON header] [section data ...] [32B SHA256 footer]
 */

import { createHash } from 'node:crypto';
import { gzipSync, gunzipSync } from 'node:zlib';
import { readFile } from 'node:fs/promises';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const RVFA_MAGIC = Buffer.from('RVFA');
export const RVFA_VERSION = 1;

const MAGIC_SIZE = 4;
const VERSION_SIZE = 4;
const HEADER_LEN_SIZE = 4;
const PREAMBLE_SIZE = MAGIC_SIZE + VERSION_SIZE + HEADER_LEN_SIZE; // 12
const SHA256_SIZE = 32;
const MAX_HEADER_JSON_SIZE = 1024 * 1024; // 1 MB

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface RvfaHeader {
  magic: string;
  version: number;
  name: string;
  appVersion: string;
  arch: string;
  platform: string;
  profile: 'cloud' | 'hybrid' | 'offline';
  created: string;
  sections: RvfaSection[];
  boot: RvfaBootConfig;
  models: RvfaModelConfig;
  capabilities: string[];
}

export interface RvfaSection {
  id: string;
  type: string;
  offset: number;
  size: number;
  originalSize: number;
  sha256: string;
  compression: 'none' | 'gzip' | 'zstd';
}

export interface RvfaBootConfig {
  entrypoint: string;
  args: string[];
  env: Record<string, string>;
  isolation: 'container' | 'microvm' | 'native';
}

export interface RvfaModelConfig {
  provider: 'ruvllm' | 'api-vault' | 'hybrid';
  engine?: string;
  models?: string[];
  vaultEncryption?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function sha256(data: Buffer): string {
  return createHash('sha256').update(data).digest('hex');
}

function sha256Bytes(data: Buffer): Buffer {
  return createHash('sha256').update(data).digest();
}

/** Format bytes into a human-readable string (e.g. '2.3 GB'). */
export function formatSize(bytes: number): string {
  if (bytes < 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let idx = 0;
  let value = bytes;
  while (value >= 1024 && idx < units.length - 1) {
    value /= 1024;
    idx++;
  }
  return idx === 0 ? `${value} ${units[idx]}` : `${value.toFixed(1)} ${units[idx]}`;
}

/** Create a sensible default header for a given profile. */
export function createDefaultHeader(
  profile: 'cloud' | 'hybrid' | 'offline',
): RvfaHeader {
  const modelDefaults: Record<string, RvfaModelConfig> = {
    cloud: { provider: 'api-vault', vaultEncryption: 'aes-256-gcm' },
    hybrid: {
      provider: 'hybrid',
      engine: 'ruvllm-0.1.0',
      models: ['phi-3-mini-q4'],
      vaultEncryption: 'aes-256-gcm',
    },
    offline: {
      provider: 'ruvllm',
      engine: 'ruvllm-0.1.0',
      models: ['phi-3-mini-q4'],
    },
  };

  const capDefaults: Record<string, string[]> = {
    cloud: ['mcp', 'swarm', 'memory', 'hooks', 'neural', 'api-vault'],
    hybrid: ['mcp', 'swarm', 'memory', 'hooks', 'neural', 'ruvllm', 'api-vault'],
    offline: ['mcp', 'swarm', 'memory', 'hooks', 'neural', 'ruvllm'],
  };

  return {
    magic: 'RVFA',
    version: RVFA_VERSION,
    name: '',
    appVersion: '3.5.0',
    arch: 'x86_64',
    platform: 'linux',
    profile,
    created: new Date().toISOString(),
    sections: [],
    boot: {
      entrypoint: '/opt/ruflo/bin/ruflo',
      args: ['--appliance'],
      env: {},
      isolation: profile === 'cloud' ? 'container' : 'native',
    },
    models: modelDefaults[profile],
    capabilities: capDefaults[profile],
  };
}

/** Type-guard that validates an unknown value is a well-formed RvfaHeader. */
export function validateHeader(header: unknown): header is RvfaHeader {
  if (typeof header !== 'object' || header === null) return false;
  const h = header as Record<string, unknown>;
  const str = (v: unknown) => typeof v === 'string';
  const obj = (v: unknown) => typeof v === 'object' && v !== null;
  const oneOf = (v: unknown, vals: string[]) => vals.includes(v as string);

  if (h.magic !== 'RVFA' || typeof h.version !== 'number' || h.version < 1) return false;
  if (!str(h.name) || !str(h.appVersion) || !str(h.arch) || !str(h.platform)) return false;
  if (!oneOf(h.profile, ['cloud', 'hybrid', 'offline'])) return false;
  if (!str(h.created) || !Array.isArray(h.sections) || !Array.isArray(h.capabilities)) return false;

  if (!obj(h.boot)) return false;
  const boot = h.boot as Record<string, unknown>;
  if (!str(boot.entrypoint) || !Array.isArray(boot.args) || !obj(boot.env)) return false;
  if (!oneOf(boot.isolation, ['container', 'microvm', 'native'])) return false;

  if (!obj(h.models)) return false;
  if (!oneOf((h.models as Record<string, unknown>).provider, ['ruvllm', 'api-vault', 'hybrid'])) return false;

  for (const sec of h.sections as unknown[]) {
    if (!obj(sec)) return false;
    const s = sec as Record<string, unknown>;
    if (!str(s.id) || !str(s.type) || !str(s.sha256)) return false;
    if (typeof s.offset !== 'number' || typeof s.size !== 'number') return false;
    if (typeof s.originalSize !== 'number') return false;
    if (!oneOf(s.compression, ['none', 'gzip', 'zstd'])) return false;
  }
  return true;
}

// ---------------------------------------------------------------------------
// RvfaWriter
// ---------------------------------------------------------------------------
/** Internal staging type used by the writer before offsets are known. */
interface StagedSection {
  id: string; type: string; data: Buffer;
  originalSize: number; sha256: string; compression: 'none' | 'gzip' | 'zstd';
}

export class RvfaWriter {
  private header: RvfaHeader;
  private staged: StagedSection[] = [];

  constructor(partial: Partial<RvfaHeader>) {
    const profile = partial.profile ?? 'cloud';
    const defaults = createDefaultHeader(profile);
    this.header = { ...defaults, ...partial, sections: [] };
  }

  /**
   * Add a section to the appliance image.
   *
   * @param id      Section identifier (e.g. 'kernel', 'runtime', 'ruflo').
   * @param data    Raw (uncompressed) section payload.
   * @param options Optional compression and MIME type overrides.
   */
  addSection(
    id: string,
    data: Buffer,
    options?: { compression?: 'none' | 'gzip' | 'zstd'; type?: string },
  ): void {
    const compression = options?.compression ?? 'gzip';
    const mimeType = options?.type ?? 'application/octet-stream';

    let compressed: Buffer;
    let actualCompression: 'none' | 'gzip' | 'zstd' = compression;

    if (compression === 'gzip') {
      compressed = gzipSync(data);
    } else if (compression === 'zstd') {
      // zstd not available in core Node.js — fall back to gzip
      compressed = gzipSync(data);
      actualCompression = 'gzip';
    } else {
      compressed = data;
    }

    const hash = sha256(compressed);

    this.staged.push({
      id,
      type: mimeType,
      data: compressed,
      originalSize: data.length,
      sha256: hash,
      compression: actualCompression,
    });
  }

  /**
   * Assemble the final RVFA binary image.
   *
   * Layout:
   *   [4B magic] [4B version] [4B header_len]
   *   [header JSON bytes]
   *   [section 0 bytes] [section 1 bytes] ...
   *   [32B SHA256 of all section bytes combined]
   */
  build(): Buffer {
    // Build section descriptors with placeholder offsets
    const sectionDescriptors: RvfaSection[] = this.staged.map((s) => ({
      id: s.id,
      type: s.type,
      offset: 0,
      size: s.data.length,
      originalSize: s.originalSize,
      sha256: s.sha256,
      compression: s.compression,
    }));

    // Iteratively compute offsets: the header contains the offsets as JSON,
    // so changing offsets can change the header length. We converge quickly.
    this.header.sections = sectionDescriptors;
    let headerJson = Buffer.from(JSON.stringify(this.header), 'utf-8');
    let prevLen = -1;

    for (let attempt = 0; attempt < 5 && headerJson.length !== prevLen; attempt++) {
      prevLen = headerJson.length;
      const dataAreaStart = PREAMBLE_SIZE + headerJson.length;
      let cursor = dataAreaStart;
      for (let i = 0; i < this.staged.length; i++) {
        sectionDescriptors[i].offset = cursor;
        cursor += this.staged[i].data.length;
      }
      this.header.sections = sectionDescriptors;
      headerJson = Buffer.from(JSON.stringify(this.header), 'utf-8');
    }

    // Build preamble buffers
    const magicBuf = Buffer.from('RVFA');
    const versionBuf = Buffer.alloc(VERSION_SIZE);
    versionBuf.writeUInt32LE(RVFA_VERSION, 0);
    const headerLenBuf = Buffer.alloc(HEADER_LEN_SIZE);
    headerLenBuf.writeUInt32LE(headerJson.length, 0);

    // Concatenate section data
    const sectionBuffers = this.staged.map((s) => s.data);
    const allSectionData = Buffer.concat(sectionBuffers);

    // Footer: SHA256 of all section data combined
    const footer = sha256Bytes(allSectionData);

    return Buffer.concat([
      magicBuf,
      versionBuf,
      headerLenBuf,
      headerJson,
      allSectionData,
      footer,
    ]);
  }
}

// ---------------------------------------------------------------------------
// RvfaReader
// ---------------------------------------------------------------------------
export class RvfaReader {
  private buf: Buffer;
  private header: RvfaHeader;

  private constructor(buf: Buffer, header: RvfaHeader) {
    this.buf = buf;
    this.header = header;
  }

  /** Parse an RVFA image from an in-memory Buffer. */
  static fromBuffer(buf: Buffer): RvfaReader {
    if (buf.length < PREAMBLE_SIZE) {
      throw new Error('Buffer too small to contain RVFA preamble');
    }

    // Magic
    const magic = buf.subarray(0, MAGIC_SIZE).toString('ascii');
    if (magic !== 'RVFA') {
      throw new Error(`Invalid RVFA magic: expected "RVFA", got "${magic}"`);
    }

    // Version
    const version = buf.readUInt32LE(MAGIC_SIZE);
    if (version !== RVFA_VERSION) {
      throw new Error(
        `Unsupported RVFA version: ${version} (expected ${RVFA_VERSION})`,
      );
    }

    // Header length
    const headerLen = buf.readUInt32LE(MAGIC_SIZE + VERSION_SIZE);
    if (headerLen > MAX_HEADER_JSON_SIZE) {
      throw new Error(
        `Header JSON exceeds maximum size (${headerLen} > ${MAX_HEADER_JSON_SIZE})`,
      );
    }
    if (PREAMBLE_SIZE + headerLen > buf.length) {
      throw new Error('Buffer too small to contain declared header');
    }

    // Parse header JSON
    const headerSlice = buf.subarray(PREAMBLE_SIZE, PREAMBLE_SIZE + headerLen);
    let parsed: unknown;
    try {
      parsed = JSON.parse(headerSlice.toString('utf-8'));
    } catch {
      throw new Error('Failed to parse RVFA header JSON');
    }

    if (!validateHeader(parsed)) {
      throw new Error('RVFA header failed validation');
    }
    const header = parsed as RvfaHeader;

    // Bounds-check every section offset
    const totalSize = buf.length;
    for (const sec of header.sections) {
      if (sec.offset < 0 || sec.size < 0) {
        throw new Error(`Section "${sec.id}" has negative offset or size`);
      }
      if (sec.offset + sec.size > totalSize - SHA256_SIZE) {
        throw new Error(
          `Section "${sec.id}" extends beyond buffer ` +
            `(offset=${sec.offset}, size=${sec.size}, bufLen=${totalSize})`,
        );
      }
    }

    // Check for overlapping sections
    const sorted = [...header.sections].sort((a, b) => a.offset - b.offset);
    for (let i = 1; i < sorted.length; i++) {
      const prev = sorted[i - 1];
      const curr = sorted[i];
      if (prev.offset + prev.size > curr.offset) {
        throw new Error(
          `Sections "${prev.id}" and "${curr.id}" overlap ` +
            `(${prev.offset}+${prev.size} > ${curr.offset})`,
        );
      }
    }

    return new RvfaReader(buf, header);
  }

  /** Read an RVFA image from a file path. */
  static async fromFile(path: string): Promise<RvfaReader> {
    if (path.includes('\0')) {
      throw new Error('Path contains null bytes');
    }
    const data = await readFile(path);
    return RvfaReader.fromBuffer(data);
  }

  /** Return the parsed header. */
  getHeader(): RvfaHeader {
    return this.header;
  }

  /** List all sections declared in the header. */
  getSections(): RvfaSection[] {
    return this.header.sections;
  }

  /**
   * Extract and decompress a section by its id.
   *
   * @param id  The section identifier (e.g. 'kernel', 'runtime').
   * @returns   The decompressed section payload.
   */
  extractSection(id: string): Buffer {
    const sec = this.header.sections.find((s) => s.id === id);
    if (!sec) {
      throw new Error(`Section "${id}" not found`);
    }

    if (sec.offset + sec.size > this.buf.length - SHA256_SIZE) {
      throw new Error(`Section "${id}" exceeds buffer bounds`);
    }

    const raw = this.buf.subarray(sec.offset, sec.offset + sec.size);

    if (sec.compression === 'gzip') {
      return gunzipSync(raw);
    }
    if (sec.compression === 'zstd') {
      // zstd not natively supported — attempt gzip fallback (mirrors writer)
      try {
        return gunzipSync(raw);
      } catch {
        throw new Error(
          'zstd decompression is not supported in this environment',
        );
      }
    }

    // compression === 'none'
    return Buffer.from(raw);
  }

  /**
   * Verify the integrity of the RVFA image.
   *
   * Checks:
   *  1. Magic bytes
   *  2. Version number
   *  3. SHA256 of each section's compressed data
   *  4. SHA256 footer (all section data combined)
   */
  verify(): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    // 1. Magic
    const magic = this.buf.subarray(0, MAGIC_SIZE).toString('ascii');
    if (magic !== 'RVFA') {
      errors.push(`Invalid magic: "${magic}"`);
    }

    // 2. Version
    const version = this.buf.readUInt32LE(MAGIC_SIZE);
    if (version !== RVFA_VERSION) {
      errors.push(`Unsupported version: ${version}`);
    }

    // 3. Per-section SHA256
    const sectionDataParts: Buffer[] = [];
    for (const sec of this.header.sections) {
      if (sec.offset + sec.size > this.buf.length - SHA256_SIZE) {
        errors.push(`Section "${sec.id}" extends beyond buffer`);
        continue;
      }
      const raw = this.buf.subarray(sec.offset, sec.offset + sec.size);
      sectionDataParts.push(raw);

      const actual = sha256(raw);
      if (actual !== sec.sha256) {
        errors.push(
          `Section "${sec.id}" SHA256 mismatch: ` +
            `expected ${sec.sha256}, got ${actual}`,
        );
      }
    }

    // 4. Footer SHA256
    if (this.buf.length >= SHA256_SIZE) {
      const allSections = Buffer.concat(sectionDataParts);
      const expectedFooter = sha256Bytes(allSections);
      const actualFooter = this.buf.subarray(this.buf.length - SHA256_SIZE);

      if (!expectedFooter.equals(actualFooter)) {
        errors.push(
          `Footer SHA256 mismatch: expected ${expectedFooter.toString('hex')}, ` +
            `got ${actualFooter.toString('hex')}`,
        );
      }
    } else {
      errors.push('Buffer too small to contain SHA256 footer');
    }

    return { valid: errors.length === 0, errors };
  }
}

/**
 * RVFA Runner -- Boot and run self-contained Ruflo appliances.
 *
 * Supports three run modes (cli, mcp, verify) and two isolation
 * strategies (native Node.js, container via Docker).
 *
 * @module @claude-flow/cli/appliance/rvfa-runner
 */

import { writeFile, mkdir, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { spawn } from 'node:child_process';
import { tmpdir } from 'node:os';
import { RvfaReader } from './rvfa-format.js';
import type { RvfaHeader, RvfaSection } from './rvfa-format.js';

// ── Options & Result ────────────────────────────────────────

export interface RunOptions {
  mode: 'cli' | 'mcp' | 'verify';
  isolation: 'container' | 'native';
  verbose?: boolean;
  /** Passphrase for decrypting the API-key vault in the models section. */
  passphrase?: string;
}

export interface RunResult {
  exitCode: number;
  stdout: string;
  stderr: string;
  /** Wall-clock duration in milliseconds. */
  duration: number;
}

// ── Internal helpers ────────────────────────────────────────

/** Spawn a child process and capture stdout/stderr. */
function spawnAsync(
  cmd: string, args: string[],
  opts: { cwd?: string; env?: NodeJS.ProcessEnv; verbose?: boolean },
): Promise<RunResult> {
  return new Promise((resolve) => {
    const start = performance.now();
    const out: Buffer[] = [];
    const err: Buffer[] = [];
    const child = spawn(cmd, args, {
      cwd: opts.cwd, env: { ...process.env, ...opts.env }, stdio: ['pipe', 'pipe', 'pipe'],
    });
    child.stdout.on('data', (c: Buffer) => { out.push(c); if (opts.verbose) process.stdout.write(c); });
    child.stderr.on('data', (c: Buffer) => { err.push(c); if (opts.verbose) process.stderr.write(c); });
    child.on('close', (code) => resolve({
      exitCode: code ?? 1, stdout: Buffer.concat(out).toString(), stderr: Buffer.concat(err).toString(),
      duration: performance.now() - start,
    }));
    child.on('error', (e) => resolve({
      exitCode: 1, stdout: '', stderr: e.message, duration: performance.now() - start,
    }));
  });
}

const fail = (stderr: string): RunResult => ({ exitCode: 1, stdout: '', stderr, duration: 0 });
const cleanup = (dir: string) => rm(dir, { recursive: true, force: true }).catch(() => {});

/** Check whether the reader has a section with the given id. */
function hasSection(reader: RvfaReader, id: string): boolean {
  return reader.getSections().some((s) => s.id === id);
}

/** Safely extract a section, returning null if absent. */
function tryExtract(reader: RvfaReader, id: string): Buffer | null {
  try {
    return reader.extractSection(id);
  } catch {
    return null;
  }
}

// ── Runner ──────────────────────────────────────────────────

export class RvfaRunner {
  private reader: RvfaReader;
  private header: RvfaHeader;

  private constructor(reader: RvfaReader) {
    this.reader = reader;
    this.header = reader.getHeader();
  }

  /** Read and parse an RVFA file from disk. Throws on invalid input. */
  static async fromFile(rvfaPath: string): Promise<RvfaRunner> {
    const reader = await RvfaReader.fromFile(rvfaPath);
    return new RvfaRunner(reader);
  }

  /** Create a runner from an already-loaded buffer. */
  static fromBuffer(buf: Buffer): RvfaRunner {
    return new RvfaRunner(RvfaReader.fromBuffer(buf));
  }

  /**
   * Boot the appliance: verify integrity, then dispatch to the
   * requested isolation strategy and run mode.
   */
  async boot(options: RunOptions): Promise<RunResult> {
    const { valid, errors } = this.reader.verify();
    if (!valid) {
      return fail(`Integrity check failed:\n${errors.join('\n')}`);
    }

    if (options.mode === 'verify') return this.runVerify(options);
    if (options.isolation === 'container') return this.runContainer(options);
    return this.runNative(options);
  }

  /**
   * Run natively via Node.js: extract RUFLO section to a temp dir,
   * configure env vars, optionally decrypt API-key vault, and spawn.
   */
  async runNative(options: RunOptions): Promise<RunResult> {
    const workDir = join(tmpdir(), `rvfa-${this.header.name}-${Date.now()}`);
    try {
      await mkdir(workDir, { recursive: true });

      const ruflo = tryExtract(this.reader, 'ruflo');
      if (!ruflo) return fail('RVFA appliance does not contain a "ruflo" section');

      const entryFile = join(workDir, 'ruflo-bundle.js');
      await writeFile(entryFile, ruflo);

      const env: Record<string, string> = {
        ...this.header.boot.env,
        RVFA_APPLIANCE_NAME: this.header.name,
        RVFA_APPLIANCE_VERSION: this.header.appVersion,
        RVFA_RUN_MODE: options.mode,
        RVFA_PROFILE: this.header.profile,
      };

      if (options.passphrase && this.header.models.provider !== 'ruvllm') {
        const vault = tryExtract(this.reader, 'models');
        if (vault) {
          const keys = await this.decryptVault(vault, options.passphrase);
          if (keys) Object.assign(env, keys);
        }
      }

      const args = [...this.header.boot.args];
      if (options.mode === 'mcp') args.push('--mcp', '--transport', 'stdio');

      return spawnAsync(this.header.boot.entrypoint || 'node', [entryFile, ...args], {
        cwd: workDir, env, verbose: options.verbose,
      });
    } finally {
      await cleanup(workDir);
    }
  }

  /**
   * Run in a Docker container: generate a Dockerfile from the
   * extracted sections, build the image, and run it.
   */
  async runContainer(options: RunOptions): Promise<RunResult> {
    const dockerCheck = await spawnAsync('docker', ['info'], { verbose: false });
    if (dockerCheck.exitCode !== 0) {
      return fail('Docker is not available. Install Docker or use isolation: "native".');
    }

    const workDir = join(tmpdir(), `rvfa-container-${Date.now()}`);
    try {
      await mkdir(workDir, { recursive: true });

      const ruflo = tryExtract(this.reader, 'ruflo');
      if (!ruflo) return fail('RVFA appliance does not contain a "ruflo" section');
      await writeFile(join(workDir, 'ruflo-bundle.js'), ruflo);

      const data = tryExtract(this.reader, 'data');
      if (data) await writeFile(join(workDir, 'data.bin'), data);

      const envFlags: string[] = [];
      for (const [k, v] of Object.entries(this.header.boot.env)) envFlags.push('-e', `${k}=${v}`);
      envFlags.push('-e', `RVFA_RUN_MODE=${options.mode}`, '-e', `RVFA_PROFILE=${this.header.profile}`);

      const baseImage = this.header.platform === 'alpine' ? 'node:20-alpine' : 'node:20-slim';
      const cmdArgs = this.header.boot.args.map((a) => `, "${a}"`).join('');
      const dockerfile = [
        `FROM ${baseImage}`, 'WORKDIR /app', 'COPY ruflo-bundle.js .',
        data ? 'COPY data.bin .' : '', `CMD ["node", "ruflo-bundle.js"${cmdArgs}]`,
      ].filter(Boolean).join('\n');
      await writeFile(join(workDir, 'Dockerfile'), dockerfile);

      const imageName = `rvfa-${this.header.name}:${this.header.appVersion}`.toLowerCase();
      const build = await spawnAsync('docker', ['build', '-t', imageName, '.'], {
        cwd: workDir, verbose: options.verbose,
      });
      if (build.exitCode !== 0) {
        return { ...build, stderr: `Docker build failed:\n${build.stderr}` };
      }

      return spawnAsync('docker', ['run', '--rm', ...envFlags, imageName], { verbose: options.verbose });
    } finally {
      await cleanup(workDir);
    }
  }

  /**
   * Run the verification suite. Extracts the VERIFY section and
   * executes it; falls back to a basic integrity report.
   */
  async runVerify(options: RunOptions): Promise<RunResult> {
    const start = performance.now();
    const verifyPayload = tryExtract(this.reader, 'verify');

    if (!verifyPayload) {
      const { valid, errors } = this.reader.verify();
      const lines = [
        `Appliance: ${this.header.name} v${this.header.appVersion}`,
        `Profile:   ${this.header.profile}`,
        `Sections:  ${this.header.sections.length}`,
        `Integrity: ${valid ? 'PASS' : 'FAIL'}`,
        ...errors.map((e) => `  FAIL: ${e}`),
        errors.length === 0 ? '  All checks PASS' : '',
      ];
      return {
        exitCode: valid ? 0 : 1,
        stdout: lines.filter(Boolean).join('\n'), stderr: '',
        duration: performance.now() - start,
      };
    }

    const workDir = join(tmpdir(), `rvfa-verify-${Date.now()}`);
    try {
      await mkdir(workDir, { recursive: true });
      await writeFile(join(workDir, 'verify.js'), verifyPayload);
      return spawnAsync('node', [join(workDir, 'verify.js')], {
        cwd: workDir, verbose: options.verbose,
        env: { RVFA_APPLIANCE_NAME: this.header.name, RVFA_APPLIANCE_VERSION: this.header.appVersion },
      });
    } finally {
      await cleanup(workDir);
    }
  }

  /** Return appliance metadata without booting. */
  getInfo(): {
    header: RvfaHeader;
    sections: { id: string; size: number; originalSize: number }[];
    totalSize: number;
  } {
    const sections = this.reader.getSections();
    const totalSize = sections.reduce((sum, s) => sum + s.size, 0);
    return {
      header: { ...this.header },
      sections: sections.map((s) => ({ id: s.id, size: s.size, originalSize: s.originalSize })),
      totalSize,
    };
  }

  // ── Private ───────────────────────────────────────────────

  /**
   * Decrypt an API-key vault (AES-256-GCM).
   * Layout: [16-byte IV][ciphertext][16-byte auth-tag]
   * Key derived via PBKDF2 with salt = "rvfa-vault-{name}".
   */
  private async decryptVault(payload: Buffer, passphrase: string): Promise<Record<string, string> | null> {
    try {
      const { createDecipheriv, pbkdf2Sync } = await import('node:crypto');
      if (payload.length < 33) return null;

      const iv = payload.subarray(0, 16);
      const tag = payload.subarray(payload.length - 16);
      const ciphertext = payload.subarray(16, payload.length - 16);
      const key = pbkdf2Sync(passphrase, Buffer.from(`rvfa-vault-${this.header.name}`), 100_000, 32, 'sha256');

      const decipher = createDecipheriv('aes-256-gcm', key, iv);
      decipher.setAuthTag(tag);
      const dec = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
      return JSON.parse(dec.toString('utf-8'));
    } catch {
      return null;
    }
  }
}

/**
 * RVFA Ed25519 Code Signing -- Digital signatures for RVFA appliance files.
 *
 * Provides tamper detection and publisher identity verification using
 * Ed25519 (RFC 8032) via Node.js native crypto. Zero external dependencies.
 *
 * @module @claude-flow/cli/appliance/rvfa-signing
 */

import {
  generateKeyPairSync, createHash, sign, verify,
  createPublicKey, createPrivateKey,
  type KeyObject,
} from 'node:crypto';
import { readFile, writeFile, stat, chmod, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

// ── Constants ────────────────────────────────────────────────

const PREAMBLE_SIZE = 12; // 4B magic + 4B version + 4B header_len
const SHA256_SIZE = 32;
const KEY_FILE_MODE = 0o600;

// ── Public Interfaces ────────────────────────────────────────

export interface RvfaKeyPair {
  publicKey: Buffer;
  privateKey: Buffer;
  fingerprint: string;
}

export interface SignatureMetadata {
  algorithm: 'ed25519';
  publicKeyFingerprint: string;
  signature: string;
  signedAt: string;
  signedBy?: string;
  scope: 'full' | 'sections';
}

export interface VerifyResult {
  valid: boolean;
  signerFingerprint?: string;
  signedAt?: string;
  signedBy?: string;
  errors: string[];
}

// ── Key Management ───────────────────────────────────────────

/** Compute the fingerprint of a public key: first 16 hex chars of its SHA256. */
function computeFingerprint(publicKeyPem: string): string {
  return createHash('sha256')
    .update(publicKeyPem, 'utf-8')
    .digest('hex')
    .slice(0, 16);
}

/**
 * Generate a new Ed25519 key pair for RVFA signing.
 */
export async function generateKeyPair(): Promise<RvfaKeyPair> {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519', {
    publicKeyEncoding: { type: 'spki', format: 'pem' },
    privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
  });

  const pubBuf = Buffer.from(publicKey as string, 'utf-8');
  const privBuf = Buffer.from(privateKey as string, 'utf-8');
  const fingerprint = computeFingerprint(publicKey as string);

  return { publicKey: pubBuf, privateKey: privBuf, fingerprint };
}

/**
 * Save a key pair to disk as PEM files.
 *
 * @param keyPair  The key pair to persist.
 * @param dir      Directory to write files into.
 * @param name     Base name for the key files (default: 'rvfa-signing').
 * @returns Paths to the written public and private key files.
 */
export async function saveKeyPair(
  keyPair: RvfaKeyPair,
  dir: string,
  name = 'rvfa-signing',
): Promise<{ publicKeyPath: string; privateKeyPath: string }> {
  await mkdir(dir, { recursive: true });

  const pubPath = `${dir}/${name}.pub`;
  const privPath = `${dir}/${name}.key`;

  await writeFile(pubPath, keyPair.publicKey);
  await writeFile(privPath, keyPair.privateKey, { mode: KEY_FILE_MODE });

  // Ensure private key has restrictive permissions even on existing files
  await chmod(privPath, KEY_FILE_MODE);

  return { publicKeyPath: pubPath, privateKeyPath: privPath };
}

/**
 * Load a key pair from PEM files on disk.
 *
 * @param dir   Directory containing the key files.
 * @param name  Base name for the key files (default: 'rvfa-signing').
 */
export async function loadKeyPair(
  dir: string,
  name = 'rvfa-signing',
): Promise<RvfaKeyPair> {
  const pubPath = `${dir}/${name}.pub`;
  const privPath = `${dir}/${name}.key`;

  const publicKey = await readFile(pubPath);
  const privateKey = await readFile(privPath);

  // Warn if private key permissions are too open
  const privStat = await stat(privPath);
  const mode = privStat.mode & 0o777;
  if (mode & 0o077) {
    console.warn(
      `[rvfa-signing] WARNING: Private key ${privPath} has open permissions ` +
      `(${mode.toString(8)}). Consider running: chmod 600 ${privPath}`,
    );
  }

  const fingerprint = computeFingerprint(publicKey.toString('utf-8'));
  return { publicKey, privateKey, fingerprint };
}

/**
 * Load a public key from a single PEM file.
 */
export async function loadPublicKey(path: string): Promise<Buffer> {
  return readFile(path);
}

// ── Internal Helpers ─────────────────────────────────────────

/**
 * Recursively sort object keys for canonical JSON serialization.
 * Produces deterministic output regardless of insertion order.
 */
function canonicalJson(value: unknown): string {
  return JSON.stringify(value, (_key, val) => {
    if (val !== null && typeof val === 'object' && !Array.isArray(val) && !Buffer.isBuffer(val)) {
      const sorted: Record<string, unknown> = {};
      for (const k of Object.keys(val as Record<string, unknown>).sort()) {
        sorted[k] = (val as Record<string, unknown>)[k];
      }
      return sorted;
    }
    return val;
  });
}

/**
 * Parse an RVFA binary into its components without full validation.
 * Returns the header object, header JSON bytes, section data region, and footer.
 */
function parseRvfaBinary(buf: Buffer): {
  header: Record<string, unknown>;
  headerStart: number;
  headerEnd: number;
  sectionData: Buffer;
  footer: Buffer;
} {
  if (buf.length < PREAMBLE_SIZE + SHA256_SIZE) {
    throw new Error('Buffer too small to be a valid RVFA file');
  }

  const magic = buf.subarray(0, 4).toString('ascii');
  if (magic !== 'RVFA') {
    throw new Error(`Invalid RVFA magic: expected "RVFA", got "${magic}"`);
  }

  const headerLen = buf.readUInt32LE(8);
  const headerStart = PREAMBLE_SIZE;
  const headerEnd = headerStart + headerLen;

  if (headerEnd > buf.length - SHA256_SIZE) {
    throw new Error('Header length extends beyond buffer');
  }

  const headerJson = buf.subarray(headerStart, headerEnd).toString('utf-8');
  let header: Record<string, unknown>;
  try {
    header = JSON.parse(headerJson) as Record<string, unknown>;
  } catch {
    throw new Error('Failed to parse RVFA header JSON');
  }

  const footer = buf.subarray(buf.length - SHA256_SIZE);
  const sectionData = buf.subarray(headerEnd, buf.length - SHA256_SIZE);

  return { header, headerStart, headerEnd, sectionData, footer };
}

/**
 * Compute the signing digest for an RVFA file.
 *
 * The digest is SHA256 of: canonical_header_json (without signature field)
 *                         + section_data_bytes
 *                         + footer_32_bytes
 */
function computeSigningDigest(
  header: Record<string, unknown>,
  sectionData: Buffer,
  footer: Buffer,
): Buffer {
  // Strip signature field from header for digest computation
  const stripped = { ...header };
  delete stripped.signature;

  const canonical = Buffer.from(canonicalJson(stripped), 'utf-8');

  return createHash('sha256')
    .update(canonical)
    .update(sectionData)
    .update(footer)
    .digest();
}

/** Convert a Buffer or PEM string into a KeyObject. */
function toPrivateKeyObject(key: Buffer | string): KeyObject {
  const pem = Buffer.isBuffer(key) ? key.toString('utf-8') : key;
  return createPrivateKey(pem);
}

/** Convert a Buffer or PEM string into a KeyObject. */
function toPublicKeyObject(key: Buffer | string): KeyObject {
  const pem = Buffer.isBuffer(key) ? key.toString('utf-8') : key;
  return createPublicKey(pem);
}

/**
 * Rebuild the RVFA binary with an updated header.
 *
 * Preserves the original preamble version, recalculates header length,
 * and keeps section data and footer intact.
 */
function rebuildRvfa(
  originalBuf: Buffer,
  newHeader: Record<string, unknown>,
  sectionData: Buffer,
  footer: Buffer,
): Buffer {
  const headerJson = Buffer.from(JSON.stringify(newHeader), 'utf-8');

  // Preamble: magic + version + new header length
  const preamble = Buffer.alloc(PREAMBLE_SIZE);
  originalBuf.copy(preamble, 0, 0, 8); // magic + version unchanged
  preamble.writeUInt32LE(headerJson.length, 8);

  return Buffer.concat([preamble, headerJson, sectionData, footer]);
}

// ── RvfaSigner ───────────────────────────────────────────────

/**
 * Signs RVFA appliance files and data with Ed25519.
 */
export class RvfaSigner {
  private readonly keyObj: KeyObject;
  private readonly fingerprint: string;

  constructor(privateKey: Buffer | string) {
    this.keyObj = toPrivateKeyObject(privateKey);

    // Derive public key to compute fingerprint
    const pubPem = createPublicKey(this.keyObj)
      .export({ type: 'spki', format: 'pem' }) as string;
    this.fingerprint = computeFingerprint(pubPem);
  }

  /**
   * Sign an RVFA appliance file in-place.
   *
   * Algorithm:
   *  1. Read and parse the RVFA binary
   *  2. Strip any existing signature from the header
   *  3. Compute SHA256 of [canonical_header + section_data + footer]
   *  4. Sign the digest with Ed25519
   *  5. Embed signature metadata into the header
   *  6. Write the updated binary back to the file
   *
   * @param rvfaPath   Path to the .rvf appliance file.
   * @param signedBy   Optional publisher name.
   * @returns The signature metadata that was embedded.
   */
  async signAppliance(rvfaPath: string, signedBy?: string): Promise<SignatureMetadata> {
    const buf = await readFile(rvfaPath);
    const { header, sectionData, footer } = parseRvfaBinary(buf);

    // Compute digest over header (without signature) + sections + footer
    const digest = computeSigningDigest(header, sectionData, footer);

    // Ed25519 sign
    const sig = sign(null, digest, this.keyObj);

    const metadata: SignatureMetadata = {
      algorithm: 'ed25519',
      publicKeyFingerprint: this.fingerprint,
      signature: sig.toString('hex'),
      signedAt: new Date().toISOString(),
      signedBy,
      scope: 'full',
    };

    // Embed signature in header and rebuild
    header.signature = metadata;
    const rebuilt = rebuildRvfa(buf, header, sectionData, footer);
    await writeFile(rvfaPath, rebuilt);

    return metadata;
  }

  /**
   * Sign a section footer hash (detached signature).
   *
   * @param footerHash  The 32-byte SHA256 footer hash from an RVFA file.
   * @returns Hex-encoded Ed25519 signature.
   */
  async signSections(footerHash: Buffer): Promise<string> {
    if (footerHash.length !== SHA256_SIZE) {
      throw new Error(
        `Footer hash must be ${SHA256_SIZE} bytes, got ${footerHash.length}`,
      );
    }
    const sig = sign(null, footerHash, this.keyObj);
    return sig.toString('hex');
  }

  /**
   * Sign an RVFP patch file (detached signature).
   *
   * @param patchData  The raw patch binary data.
   * @returns Hex-encoded Ed25519 signature.
   */
  async signPatch(patchData: Buffer): Promise<string> {
    const digest = createHash('sha256').update(patchData).digest();
    const sig = sign(null, digest, this.keyObj);
    return sig.toString('hex');
  }
}

// ── RvfaVerifier ─────────────────────────────────────────────

/**
 * Verifies Ed25519 signatures on RVFA appliance files and data.
 */
export class RvfaVerifier {
  private readonly keyObj: KeyObject;
  private readonly fingerprint: string;

  constructor(publicKey: Buffer | string) {
    this.keyObj = toPublicKeyObject(publicKey);
    const pem = Buffer.isBuffer(publicKey) ? publicKey.toString('utf-8') : publicKey;
    this.fingerprint = computeFingerprint(pem);
  }

  /**
   * Verify the Ed25519 signature embedded in an RVFA appliance file.
   *
   * @param rvfaPath  Path to the .rvf appliance file.
   * @returns Verification result with details and any errors.
   */
  async verifyAppliance(rvfaPath: string): Promise<VerifyResult> {
    const errors: string[] = [];

    let buf: Buffer;
    try {
      buf = await readFile(rvfaPath);
    } catch (err) {
      return { valid: false, errors: [`Failed to read file: ${(err as Error).message}`] };
    }

    let parsed: ReturnType<typeof parseRvfaBinary>;
    try {
      parsed = parseRvfaBinary(buf);
    } catch (err) {
      return { valid: false, errors: [`Invalid RVFA file: ${(err as Error).message}`] };
    }

    const { header, sectionData, footer } = parsed;

    // Extract signature metadata from header
    const sigRaw = header.signature;
    if (!sigRaw || typeof sigRaw !== 'object') {
      return { valid: false, errors: ['No signature found in RVFA header'] };
    }

    const sigMeta = sigRaw as Record<string, unknown>;
    if (sigMeta.algorithm !== 'ed25519') {
      errors.push(`Unsupported algorithm: ${String(sigMeta.algorithm)}`);
      return { valid: false, errors };
    }

    if (typeof sigMeta.signature !== 'string' || !sigMeta.signature) {
      errors.push('Signature field is missing or empty');
      return { valid: false, errors };
    }

    // Recompute the digest the same way the signer did
    const digest = computeSigningDigest(header, sectionData, footer);

    // Verify
    let sigBuf: Buffer;
    try {
      sigBuf = Buffer.from(sigMeta.signature as string, 'hex');
    } catch {
      errors.push('Signature is not valid hex');
      return { valid: false, errors };
    }

    let valid: boolean;
    try {
      valid = verify(null, digest, this.keyObj, sigBuf);
    } catch (err) {
      errors.push(`Verification error: ${(err as Error).message}`);
      return { valid: false, errors };
    }

    if (!valid) {
      errors.push('Ed25519 signature verification failed: data may be tampered');
    }

    return {
      valid,
      signerFingerprint: sigMeta.publicKeyFingerprint as string | undefined,
      signedAt: sigMeta.signedAt as string | undefined,
      signedBy: sigMeta.signedBy as string | undefined,
      errors,
    };
  }

  /**
   * Verify a detached Ed25519 signature over arbitrary data.
   *
   * @param data       The data that was signed.
   * @param signature  Hex-encoded Ed25519 signature.
   */
  async verifyDetached(data: Buffer, signature: string): Promise<boolean> {
    const digest = createHash('sha256').update(data).digest();
    const sigBuf = Buffer.from(signature, 'hex');
    return verify(null, digest, this.keyObj, sigBuf);
  }

  /**
   * Verify an RVFP patch file signature.
   *
   * @param patchData  The raw patch binary data.
   * @param signature  Hex-encoded Ed25519 signature.
   */
  async verifyPatch(patchData: Buffer, signature: string): Promise<boolean> {
    const digest = createHash('sha256').update(patchData).digest();
    const sigBuf = Buffer.from(signature, 'hex');
    return verify(null, digest, this.keyObj, sigBuf);
  }
}

/**
 * Autopilot Shared State Module
 *
 * Centralizes state management, validation, and task discovery
 * for both CLI command and MCP tools. Eliminates code duplication.
 *
 * ADR-072: Autopilot Integration
 * Security: Addresses prototype pollution, NaN bypass, input validation
 */

import { randomUUID } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync, mkdirSync, readdirSync, renameSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { homedir } from 'node:os';

// ── Constants ─────────────────────────────────────────────────

export const STATE_DIR = '.claude-flow/data';
export const STATE_FILE = `${STATE_DIR}/autopilot-state.json`;
export const LOG_FILE = `${STATE_DIR}/autopilot-log.json`;

/** Maximum entries kept in state.history (prevents unbounded growth) */
const MAX_HISTORY_ENTRIES = 50;

/** Maximum entries kept in the event log */
const MAX_LOG_ENTRIES = 1000;

/** Allowlist for valid task sources */
export const VALID_TASK_SOURCES = new Set(['team-tasks', 'swarm-tasks', 'file-checklist']);

/** Terminal task statuses */
export const TERMINAL_STATUSES = new Set(['completed', 'done', 'cancelled', 'skipped', 'failed']);

// ── Types ─────────────────────────────────────────────────────

export interface AutopilotState {
  sessionId: string;
  enabled: boolean;
  startTime: number;
  iterations: number;
  maxIterations: number;
  timeoutMinutes: number;
  taskSources: string[];
  lastCheck: number | null;
  history: Array<{ ts: number; iteration: number; completed: number; total: number }>;
}

export interface AutopilotLogEntry {
  ts: number;
  event: string;
  [key: string]: unknown;
}

export interface TaskInfo {
  id: string;
  subject: string;
  status: string;
  source: string;
}

export interface TaskProgress {
  completed: number;
  total: number;
  percent: number;
  incomplete: TaskInfo[];
}

// ── Validation Helpers ────────────────────────────────────────

/**
 * Sanitize a parsed JSON object to prevent prototype pollution.
 * Removes __proto__, constructor, and prototype keys recursively.
 */
function sanitizeObject(obj: unknown): unknown {
  if (obj === null || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(sanitizeObject);

  const clean: Record<string, unknown> = {};
  for (const key of Object.keys(obj as Record<string, unknown>)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
    clean[key] = sanitizeObject((obj as Record<string, unknown>)[key]);
  }
  return clean;
}

/**
 * Safe JSON.parse that prevents prototype pollution.
 */
export function safeJsonParse<T>(raw: string): T {
  return sanitizeObject(JSON.parse(raw)) as T;
}

/**
 * Validate and coerce a numeric parameter. Returns the default if
 * the input is NaN, undefined, or outside the allowed range.
 */
export function validateNumber(value: unknown, min: number, max: number, defaultValue: number): number {
  if (value === undefined || value === null) return defaultValue;
  const num = Number(value);
  if (!Number.isFinite(num)) return defaultValue;
  return Math.min(Math.max(min, Math.round(num)), max);
}

/**
 * Validate task sources against the allowlist.
 * Returns only valid sources; falls back to defaults if none are valid.
 */
export function validateTaskSources(sources: unknown): string[] {
  const defaults = ['team-tasks', 'swarm-tasks', 'file-checklist'];
  if (!Array.isArray(sources)) return defaults;
  const valid = sources
    .filter((s): s is string => typeof s === 'string')
    .map(s => s.trim())
    .filter(s => VALID_TASK_SOURCES.has(s));
  return valid.length > 0 ? valid : defaults;
}

// ── State Management ──────────────────────────────────────────

export function getDefaultState(): AutopilotState {
  return {
    sessionId: randomUUID(),
    enabled: false,
    startTime: Date.now(),
    iterations: 0,
    maxIterations: 50,
    timeoutMinutes: 240,
    taskSources: ['team-tasks', 'swarm-tasks', 'file-checklist'],
    lastCheck: null,
    history: [],
  };
}

export function loadState(): AutopilotState {
  const filePath = resolve(STATE_FILE);
  const defaults = getDefaultState();
  try {
    if (existsSync(filePath)) {
      const raw = safeJsonParse<Partial<AutopilotState>>(readFileSync(filePath, 'utf-8'));
      const merged = { ...defaults, ...raw };
      // Re-validate fields that could be tampered with
      merged.maxIterations = validateNumber(merged.maxIterations, 1, 1000, 50);
      merged.timeoutMinutes = validateNumber(merged.timeoutMinutes, 1, 1440, 240);
      merged.iterations = validateNumber(merged.iterations, 0, 1000, 0);
      merged.taskSources = validateTaskSources(merged.taskSources);
      // Cap history to prevent unbounded growth
      if (Array.isArray(merged.history) && merged.history.length > MAX_HISTORY_ENTRIES) {
        merged.history = merged.history.slice(-MAX_HISTORY_ENTRIES);
      }
      return merged;
    }
  } catch {
    // Corrupted state file — return defaults
  }
  return defaults;
}

export function saveState(state: AutopilotState): void {
  const dir = resolve(STATE_DIR);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  // Cap history before saving
  if (state.history.length > MAX_HISTORY_ENTRIES) {
    state.history = state.history.slice(-MAX_HISTORY_ENTRIES);
  }
  const tmpFile = resolve(STATE_FILE) + '.tmp';
  writeFileSync(tmpFile, JSON.stringify(state, null, 2));
  renameSync(tmpFile, resolve(STATE_FILE));
}

export function appendLog(entry: AutopilotLogEntry): void {
  const filePath = resolve(LOG_FILE);
  const dir = resolve(STATE_DIR);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  let log: AutopilotLogEntry[] = [];
  try {
    if (existsSync(filePath)) {
      log = safeJsonParse<AutopilotLogEntry[]>(readFileSync(filePath, 'utf-8'));
      if (!Array.isArray(log)) log = [];
    }
  } catch {
    log = [];
  }
  log.push(entry);
  if (log.length > MAX_LOG_ENTRIES) log = log.slice(-MAX_LOG_ENTRIES);
  const tmpFile = filePath + '.tmp';
  writeFileSync(tmpFile, JSON.stringify(log, null, 2));
  renameSync(tmpFile, filePath);
}

export function loadLog(): AutopilotLogEntry[] {
  const filePath = resolve(LOG_FILE);
  try {
    if (existsSync(filePath)) {
      const result = safeJsonParse<AutopilotLogEntry[]>(readFileSync(filePath, 'utf-8'));
      return Array.isArray(result) ? result : [];
    }
  } catch {
    // Corrupted log — return empty
  }
  return [];
}

// ── Task Discovery ────────────────────────────────────────────

export function discoverTasks(sources: string[]): TaskInfo[] {
  const tasks: TaskInfo[] = [];

  // Only process valid sources
  const validSources = sources.filter(s => VALID_TASK_SOURCES.has(s));

  for (const source of validSources) {
    if (source === 'team-tasks') {
      const tasksDir = join(homedir(), '.claude', 'tasks');
      try {
        if (existsSync(tasksDir)) {
          const teams = readdirSync(tasksDir, { withFileTypes: true });
          for (const team of teams) {
            if (!team.isDirectory()) continue;
            const teamDir = join(tasksDir, team.name);
            const files = readdirSync(teamDir).filter((f: string) => f.endsWith('.json'));
            for (const file of files) {
              try {
                const data = safeJsonParse<Record<string, unknown>>(readFileSync(join(teamDir, file), 'utf-8'));
                tasks.push({
                  id: String(data.id || file.replace('.json', '')),
                  subject: String(data.subject || data.title || file),
                  status: String(data.status || 'unknown'),
                  source: 'team-tasks',
                });
              } catch { /* skip individual file */ }
            }
          }
        }
      } catch { /* skip source */ }
    }

    if (source === 'swarm-tasks') {
      const swarmFile = resolve('.claude-flow/swarm-tasks.json');
      try {
        if (existsSync(swarmFile)) {
          const data = safeJsonParse<Record<string, unknown> | unknown[]>(readFileSync(swarmFile, 'utf-8'));
          const swarmTasks = Array.isArray(data) ? data : ((data as Record<string, unknown>).tasks as unknown[] || []);
          for (const t of swarmTasks) {
            if (t && typeof t === 'object') {
              const task = t as Record<string, unknown>;
              tasks.push({
                id: String(task.id || task.taskId || `swarm-${tasks.length}`),
                subject: String(task.subject || task.description || task.name || 'Unnamed task'),
                status: String(task.status || 'unknown'),
                source: 'swarm-tasks',
              });
            }
          }
        }
      } catch { /* skip source */ }
    }

    if (source === 'file-checklist') {
      const checklistFile = resolve('.claude-flow/data/checklist.json');
      try {
        if (existsSync(checklistFile)) {
          const data = safeJsonParse<Record<string, unknown> | unknown[]>(readFileSync(checklistFile, 'utf-8'));
          const items = Array.isArray(data) ? data : ((data as Record<string, unknown>).items as unknown[] || []);
          for (const item of items) {
            if (item && typeof item === 'object') {
              const i = item as Record<string, unknown>;
              tasks.push({
                id: String(i.id || `check-${tasks.length}`),
                subject: String(i.subject || i.text || i.description || 'Unnamed item'),
                status: String(i.status || (i.done ? 'completed' : 'pending')),
                source: 'file-checklist',
              });
            }
          }
        }
      } catch { /* skip source */ }
    }
  }

  return tasks;
}

// ── Progress Helpers ──────────────────────────────────────────

export function isTerminal(status: string): boolean {
  return TERMINAL_STATUSES.has(status.toLowerCase());
}

export function getProgress(tasks: TaskInfo[]): TaskProgress {
  const completed = tasks.filter(t => isTerminal(t.status)).length;
  const total = tasks.length;
  const percent = total === 0 ? 100 : Math.round((completed / total) * 100);
  const incomplete = tasks.filter(t => !isTerminal(t.status));
  return { completed, total, percent, incomplete };
}

// ── Reward Calculation ────────────────────────────────────────

export function calculateReward(iterations: number, durationMs: number): number {
  const iterFactor = (1 - iterations / (iterations + 10)) * 0.6;
  const timeFactor = (1 - Math.min(durationMs / 3600000, 1)) * 0.4;
  return Math.round((iterFactor + timeFactor) * 100) / 100;
}

// ── Learning Integration ──────────────────────────────────────

export async function tryLoadLearning(): Promise<{ initialize: () => Promise<boolean>; [key: string]: unknown } | null> {
  try {
    const modPath = 'agentic-flow/dist/coordination/autopilot-learning.js';
    const mod = await import(/* webpackIgnore: true */ modPath).catch(() => null);
    if (mod?.AutopilotLearning) {
      const instance = new mod.AutopilotLearning();
      if (await instance.initialize()) return instance;
    }
  } catch { /* not available */ }
  return null;
}

