/**
 * Smoke tests — ADR-135 Track I: Causal failure-avoidance edges
 *
 * All I/O is mocked (no real filesystem or network calls).
 *
 * Tests:
 *   1. Record one failure → retrieve same-signature question → returns hint
 *   2. Record 3 failures → retrieve unrelated question → returns empty hint
 *   3. Same edge recorded twice → occurrenceCount=2, not duplicated
 *   4. File doesn't exist → graceful empty result on retrieve
 *   5. Corrupted JSONL line → skipped, doesn't crash
 *   6. maxEdgesPerSignature cap respected (no new edge after cap)
 *   7. Signature computation is deterministic (same input → same output)
 *   8. Correct answer trajectory → no edges recorded
 *
 * Usage:
 *   npx tsx src/benchmarks/gaia-causal-memory.smoke.ts
 *
 * Refs: ADR-135, #2156
 */

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import {
  computeQuestionSignature,
  inferFailureType,
  recordCausalFailures,
  retrieveCausalHints,
  type CausalEdge,
} from './gaia-causal-memory.js';
import type { GaiaQuestion } from './gaia-loader.js';
import type { GaiaAgentResult } from './gaia-agent.js';

// ---------------------------------------------------------------------------
// Mini test runner (zero external deps)
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;
const results: Array<{ name: string; ok: boolean; error?: string }> = [];

async function test(name: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
    passed++;
    results.push({ name, ok: true });
    console.log(`  PASS  ${name}`);
  } catch (err) {
    failed++;
    const msg = err instanceof Error ? err.message : String(err);
    results.push({ name, ok: false, error: msg });
    console.error(`  FAIL  ${name}`);
    console.error(`        ${msg}`);
  }
}

function assert(condition: boolean, message: string): void {
  if (!condition) {
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertEqual<T>(actual: T, expected: T, label: string): void {
  if (actual !== expected) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

function makeQuestion(text: string): GaiaQuestion {
  return {
    task_id: 'smoke-' + text.slice(0, 8),
    level: 1,
    question: text,
    final_answer: 'ignored-in-smoke',
    file_name: null,
    file_path: null,
  };
}

function makeResult(overrides: Partial<GaiaAgentResult> = {}): GaiaAgentResult {
  return {
    questionId: 'smoke-q1',
    finalAnswer: 'wrong answer',
    turns: 3,
    toolCallsByName: { web_search: 2 },
    totalInputTokens: 100,
    totalOutputTokens: 50,
    wallMs: 1500,
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// Test suite
// ---------------------------------------------------------------------------

async function runAll(): Promise<void> {
  console.log('\nADR-135 Track I — causal failure-avoidance edges (smoke)\n');

  // We use a fresh temp dir per test group to isolate state.
  const tmpBase = path.join(os.tmpdir(), 'ruflo-causal-smoke-' + process.pid);

  // -------------------------------------------------------------------------
  // Test 1: Record one failure → retrieve same-signature question → hint returned
  // -------------------------------------------------------------------------
  await test('1. record one failure → retrieve same question → hint returned', async () => {
    const dir = path.join(tmpBase, 't1');
    fs.mkdirSync(dir, { recursive: true });
    const storePath = path.join(dir, 'edges.jsonl');

    const question = makeQuestion('What is the capital of France?');
    const result = makeResult({ finalAnswer: 'London' });

    const recRes = await recordCausalFailures(question, result, false, { storePath });
    assert(recRes.edgesRecorded > 0, 'should have recorded at least one edge');

    const retRes = await retrieveCausalHints(question, { storePath });
    assert(retRes.edgesMatched > 0, 'should match the stored edge');
    assert(retRes.hint.length > 0, 'hint should be non-empty');
    assert(retRes.hint.includes('[PRIOR FAILURES]'), 'hint should contain [PRIOR FAILURES] header');
    assert(retRes.hint.includes('web_search'), 'hint should mention the failed tool');
  });

  // -------------------------------------------------------------------------
  // Test 2: Record 3 failures → retrieve unrelated question → empty hint
  // -------------------------------------------------------------------------
  await test('2. record 3 failures → retrieve unrelated question → empty hint', async () => {
    const dir = path.join(tmpBase, 't2');
    fs.mkdirSync(dir, { recursive: true });
    const storePath = path.join(dir, 'edges.jsonl');

    const questions = [
      makeQuestion('What is the capital of France?'),
      makeQuestion('Who wrote Hamlet?'),
      makeQuestion('What is 2 + 2?'),
    ];

    for (const q of questions) {
      await recordCausalFailures(q, makeResult(), false, { storePath });
    }

    const unrelated = makeQuestion('Completely different and unrelated question about astrophysics and quantum phenomena XYZ123');
    const retRes = await retrieveCausalHints(unrelated, { storePath });

    assertEqual(retRes.edgesMatched, 0, 'edgesMatched for unrelated question');
    assertEqual(retRes.hint, '', 'hint for unrelated question');
  });

  // -------------------------------------------------------------------------
  // Test 3: Same edge recorded twice → occurrenceCount=2, not duplicated
  // -------------------------------------------------------------------------
  await test('3. same edge recorded twice → occurrenceCount=2, not duplicated', async () => {
    const dir = path.join(tmpBase, 't3');
    fs.mkdirSync(dir, { recursive: true });
    const storePath = path.join(dir, 'edges.jsonl');

    const question = makeQuestion('What year did World War II end?');
    const result = makeResult({ toolCallsByName: { web_search: 1 } });

    // Record same failure twice
    await recordCausalFailures(question, result, false, { storePath });
    await recordCausalFailures(question, result, false, { storePath });

    // Read the JSONL directly and count lines / occurrence counts
    const raw = fs.readFileSync(storePath, 'utf8');
    const lines = raw.trim().split('\n').filter((l) => l.trim() !== '');
    const edges: CausalEdge[] = lines.map((l) => JSON.parse(l) as CausalEdge);

    // Should have exactly one edge for this signature+tool+step
    const sig = computeQuestionSignature(question.question);
    const sigEdges = edges.filter((e) => e.questionSignature === sig && e.failedTool === 'web_search');
    assertEqual(sigEdges.length, 1, 'should have exactly one edge per signature+tool+step');
    assertEqual(sigEdges[0].occurrenceCount, 2, 'occurrenceCount after two recordings');
  });

  // -------------------------------------------------------------------------
  // Test 4: File doesn't exist → graceful empty result on retrieve
  // -------------------------------------------------------------------------
  await test('4. file does not exist → graceful empty result on retrieve', async () => {
    const storePath = path.join(tmpBase, 'nonexistent', 'edges.jsonl');
    const question = makeQuestion('How many legs does a spider have?');

    const retRes = await retrieveCausalHints(question, { storePath });
    assertEqual(retRes.edgesMatched, 0, 'edgesMatched when file absent');
    assertEqual(retRes.hint, '', 'hint when file absent');
  });

  // -------------------------------------------------------------------------
  // Test 5: Corrupted JSONL line → skipped, doesn't crash
  // -------------------------------------------------------------------------
  await test('5. corrupted JSONL line → skipped, does not crash', async () => {
    const dir = path.join(tmpBase, 't5');
    fs.mkdirSync(dir, { recursive: true });
    const storePath = path.join(dir, 'edges.jsonl');

    const goodQuestion = makeQuestion('Name the largest planet in the solar system.');
    const goodEdge: CausalEdge = {
      questionSignature: computeQuestionSignature(goodQuestion.question),
      failedTool: 'python_exec',
      failedTrajectoryStep: 'python_exec called once; failure type=wrong_answer',
      observedFailureType: 'wrong_answer',
      createdAt: new Date().toISOString(),
      occurrenceCount: 1,
    };

    // Write one valid edge + one corrupted line
    fs.mkdirSync(path.dirname(storePath), { recursive: true });
    fs.writeFileSync(
      storePath,
      JSON.stringify(goodEdge) + '\n' +
      '{"this": is not valid JSON!!!\n' +
      '{"partial":true\n',
      'utf8',
    );

    // retrieve should work and not throw
    const retRes = await retrieveCausalHints(goodQuestion, { storePath });
    assertEqual(retRes.edgesMatched, 1, 'should still find the one valid edge');
    assert(retRes.hint.includes('[PRIOR FAILURES]'), 'hint should be returned for valid edge');
    assert(retRes.hint.includes('python_exec'), 'hint should reference python_exec');
  });

  // -------------------------------------------------------------------------
  // Test 6: maxEdgesPerSignature cap respected
  // -------------------------------------------------------------------------
  await test('6. maxEdgesPerSignature cap respected', async () => {
    const dir = path.join(tmpBase, 't6');
    fs.mkdirSync(dir, { recursive: true });
    const storePath = path.join(dir, 'edges.jsonl');
    const maxEdgesPerSignature = 2;

    const question = makeQuestion('Explain the theory of relativity in simple terms.');

    // Record 3 failures with different tools — only first 2 should be stored
    for (const tool of ['web_search', 'file_read', 'python_exec']) {
      const result = makeResult({ toolCallsByName: { [tool]: 1 } });
      await recordCausalFailures(question, result, false, {
        storePath,
        maxEdgesPerSignature,
      });
    }

    const raw = fs.readFileSync(storePath, 'utf8');
    const lines = raw.trim().split('\n').filter((l) => l.trim() !== '');
    const sig = computeQuestionSignature(question.question);
    const sigEdges = lines
      .map((l) => JSON.parse(l) as CausalEdge)
      .filter((e) => e.questionSignature === sig);

    assert(
      sigEdges.length <= maxEdgesPerSignature,
      `should have at most ${maxEdgesPerSignature} edges, got ${sigEdges.length}`,
    );
  });

  // -------------------------------------------------------------------------
  // Test 7: Signature computation is deterministic
  // -------------------------------------------------------------------------
  await test('7. signature computation is deterministic', async () => {
    const text = 'What is the boiling point of water at sea level?';

    const sig1 = computeQuestionSignature(text);
    const sig2 = computeQuestionSignature(text);
    const sig3 = computeQuestionSignature(text.trim()); // trim should not change result
    const sig4 = computeQuestionSignature(text.toUpperCase().toLowerCase()); // normalisation

    assertEqual(sig1, sig2, 'same input produces same signature (call 1 vs 2)');
    assertEqual(sig1, sig3, 'trimmed input produces same signature');
    assertEqual(sig1, sig4, 'case-normalised input produces same signature');
    assertEqual(sig1.length, 16, 'signature is 16 hex characters');

    // Different text should produce different signature (with overwhelming probability)
    const sigOther = computeQuestionSignature('Completely different question about astronomy.');
    assert(sig1 !== sigOther, 'different inputs produce different signatures');
  });

  // -------------------------------------------------------------------------
  // Test 8: Correct answer trajectory → no edges recorded
  // -------------------------------------------------------------------------
  await test('8. correct answer trajectory → no edges recorded', async () => {
    const dir = path.join(tmpBase, 't8');
    fs.mkdirSync(dir, { recursive: true });
    const storePath = path.join(dir, 'edges.jsonl');

    const question = makeQuestion('What color is the sky on a clear day?');
    const result = makeResult({ finalAnswer: 'blue' });

    // wasCorrect = true
    const recRes = await recordCausalFailures(question, result, true, { storePath });
    assertEqual(recRes.edgesRecorded, 0, 'no edges for correct trajectory');
    assert(!fs.existsSync(storePath), 'store file should not be created for correct answer');
  });

  // -------------------------------------------------------------------------
  // Bonus: inferFailureType unit checks
  // -------------------------------------------------------------------------
  await test('inferFailureType: null for correct answers', async () => {
    const result = makeResult({ finalAnswer: 'blue' });
    const ft = inferFailureType(result, true);
    assertEqual(ft, null, 'inferFailureType returns null for wasCorrect=true');
  });

  await test('inferFailureType: timeout when timedOut=true', async () => {
    const result = makeResult({ timedOut: true });
    const ft = inferFailureType(result, false);
    assertEqual(ft, 'timeout', 'inferFailureType=timeout when timedOut flag set');
  });

  await test('inferFailureType: tool_error when error present', async () => {
    const result = makeResult({ error: 'network timeout' });
    const ft = inferFailureType(result, false);
    assertEqual(ft, 'tool_error', 'inferFailureType=tool_error when error field set');
  });

  await test('inferFailureType: empty_result when finalAnswer is null', async () => {
    const result = makeResult({ finalAnswer: null });
    const ft = inferFailureType(result, false);
    assertEqual(ft, 'empty_result', 'inferFailureType=empty_result when finalAnswer=null');
  });

  await test('inferFailureType: wrong_answer for normal failure', async () => {
    const result = makeResult({ finalAnswer: 'incorrect value' });
    const ft = inferFailureType(result, false);
    assertEqual(ft, 'wrong_answer', 'inferFailureType=wrong_answer for normal wrong answer');
  });

  // -------------------------------------------------------------------------
  // Cleanup
  // -------------------------------------------------------------------------
  try {
    fs.rmSync(tmpBase, { recursive: true, force: true });
  } catch {
    // Non-fatal cleanup failure; temp files will be cleared by OS.
  }

  // -------------------------------------------------------------------------
  // Summary
  // -------------------------------------------------------------------------
  console.log(`\n${'─'.repeat(60)}`);
  console.log(`Results: ${passed} passed, ${failed} failed (${passed + failed} total)`);

  if (failed > 0) {
    console.error('\nFailed tests:');
    for (const r of results.filter((r) => !r.ok)) {
      console.error(`  ${r.name}: ${r.error}`);
    }
    process.exit(1);
  } else {
    console.log('\nAll smoke tests passed.');
    console.log(
      '\nNote: Track I lift is compound (+0pp first run, +2-5pp after 5+ runs).',
    );
    console.log(
      'Wiring into gaia-bench.ts is a follow-up PR (in-flight conflict avoidance).',
    );
    process.exit(0);
  }
}

runAll().catch((err) => {
  console.error('Unhandled error in smoke runner:', err);
  process.exit(1);
});

/**
 * GAIA Causal Failure-Avoidance Memory — ADR-135 Track I
 *
 * Records causal edges after each failed GAIA trajectory:
 *   "trying tool X on question type Y → caused failure Z"
 *
 * Before each new question, retrieves matching causal edges and injects
 * an "avoid these approaches" hint into the agent's system prompt.
 *
 * This is one of ruflo's 6 architectural primitives distinguishing it
 * from HAL: HAL is stateless across runs; ruflo accumulates causal memory.
 *
 * Storage: JSONL file at ~/.cache/ruflo/gaia/causal-edges.jsonl
 *   - Simple, portable, no runtime dependency on AgentDB
 *   - Production upgrade path: switch to AgentDB causal-edge MCP controller
 *     (`mcp__claude-flow__agentdb_causal-edge`) for cross-session persistence
 *     and embedding-based similarity matching.
 *
 * Expected lift:
 *   - First run (no edges yet): +0pp  (empty hint → no overhead)
 *   - After 5+ runs (warm-up):  +2-5pp compound
 *
 * NOT wired into gaia-bench.ts here — wiring is a follow-up PR once all
 * in-flight iterators (29/31/34/35/37) have landed to avoid conflicts.
 *
 * Refs: ADR-135, ADR-133, #2156
 */

import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import * as readline from 'node:readline';
import type { GaiaQuestion } from './gaia-loader.js';
import type { GaiaAgentResult } from './gaia-agent.js';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/** Observation failure categories derived from trajectory analysis. */
export type FailureType =
  | 'empty_result'
  | 'timeout'
  | 'wrong_answer'
  | 'tool_error';

/**
 * A causal edge: "in a question of signature S, using tool T in way W
 * caused failure F."  occurrenceCount increments each time the same
 * (signature, tool, step) triple is observed again instead of duplicating.
 */
export interface CausalEdge {
  /** Deterministic hash of the normalised question text. */
  questionSignature: string;
  /** Tool name that failed (e.g. 'web_search', 'python_exec'). */
  failedTool: string;
  /** Brief description of what the failing step attempted. */
  failedTrajectoryStep: string;
  /** Categorised failure type. */
  observedFailureType: FailureType;
  /** ISO-8601 timestamp of first observation. */
  createdAt: string;
  /** Increments when the same edge is observed in a subsequent run. */
  occurrenceCount: number;
}

/** Options for causal-memory operations. */
export interface CausalMemoryOptions {
  /**
   * Override the JSONL store path.
   * Default: ~/.cache/ruflo/gaia/causal-edges.jsonl
   */
  storePath?: string;
  /**
   * Maximum edges to return per question signature when retrieving hints.
   * Default: 5
   */
  maxEdgesPerSignature?: number;
  /**
   * Signature similarity threshold (0–1).  Currently unused for the simple
   * hash-based implementation; reserved for future RuVector upgrade.
   * Default: 0.7
   */
  similarityThreshold?: number;
}

/** Result of a recordCausalFailures call. */
export interface RecordResult {
  edgesRecorded: number;
  storePath: string;
}

/** Result of a retrieveCausalHints call. */
export interface RetrieveResult {
  /**
   * System-prompt-ready hint string.
   * Empty string when no edges match (caller must not inject empty hints).
   */
  hint: string;
  edgesMatched: number;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

const DEFAULT_STORE_SUFFIX = path.join('.cache', 'ruflo', 'gaia', 'causal-edges.jsonl');
const DEFAULT_MAX_EDGES = 5;

/** Resolve the JSONL store path from options, defaulting to ~/.cache/ruflo/…  */
function resolveStorePath(options?: CausalMemoryOptions): string {
  if (options?.storePath) {
    return options.storePath;
  }
  return path.join(os.homedir(), DEFAULT_STORE_SUFFIX);
}

/**
 * Compute a deterministic question signature.
 *
 * Algorithm (v1, hash-based):
 *   1. Lower-case the question text.
 *   2. Collapse runs of whitespace to a single space and trim.
 *   3. SHA-256 → first 16 hex characters (64-bit prefix, collision-unlikely
 *      for the ~450-question GAIA validation set).
 *
 * Future (v2, embedding-based): replace with RuVector cosine similarity so
 * semantically similar questions (paraphrases, translated variants) share
 * causal edges across runs.
 */
export function computeQuestionSignature(questionText: string): string {
  const normalised = questionText.toLowerCase().replace(/\s+/g, ' ').trim();
  return crypto.createHash('sha256').update(normalised, 'utf8').digest('hex').slice(0, 16);
}

/** Derive a failure type from a completed agent result + known correctness. */
export function inferFailureType(
  result: GaiaAgentResult,
  wasCorrect: boolean,
): FailureType | null {
  if (wasCorrect) {
    return null; // Not a failure — callers should skip this question.
  }
  if (result.timedOut === true) {
    return 'timeout';
  }
  if (result.error) {
    return 'tool_error';
  }
  if (result.finalAnswer === null || result.finalAnswer.trim() === '') {
    return 'empty_result';
  }
  return 'wrong_answer';
}

/**
 * Parse one JSONL line into a CausalEdge.
 * Returns null if the line is empty, a comment, or malformed.
 */
function parseLine(line: string): CausalEdge | null {
  const trimmed = line.trim();
  if (trimmed === '' || trimmed.startsWith('//') || trimmed.startsWith('#')) {
    return null;
  }
  try {
    const parsed = JSON.parse(trimmed) as Record<string, unknown>;
    // Minimal shape guard — avoids crashing on partially-written lines.
    if (
      typeof parsed.questionSignature !== 'string' ||
      typeof parsed.failedTool !== 'string' ||
      typeof parsed.failedTrajectoryStep !== 'string' ||
      typeof parsed.observedFailureType !== 'string' ||
      typeof parsed.createdAt !== 'string' ||
      typeof parsed.occurrenceCount !== 'number'
    ) {
      return null;
    }
    return parsed as unknown as CausalEdge;
  } catch {
    // Corrupted line — skip gracefully.
    return null;
  }
}

/** Read all valid CausalEdge entries from the JSONL store. */
async function readAllEdges(storePath: string): Promise<CausalEdge[]> {
  if (!fs.existsSync(storePath)) {
    return [];
  }
  const edges: CausalEdge[] = [];
  const fileStream = fs.createReadStream(storePath, { encoding: 'utf8' });
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });
  for await (const line of rl) {
    const edge = parseLine(line);
    if (edge !== null) {
      edges.push(edge);
    }
  }
  return edges;
}

/** Write all edges back to the JSONL store (full rewrite for upsert support). */
function writeAllEdges(storePath: string, edges: CausalEdge[]): void {
  const dir = path.dirname(storePath);
  fs.mkdirSync(dir, { recursive: true });
  const content = edges.map((e) => JSON.stringify(e)).join('\n') + (edges.length > 0 ? '\n' : '');
  fs.writeFileSync(storePath, content, { encoding: 'utf8' });
}

// ---------------------------------------------------------------------------
// Trajectory analysis
// ---------------------------------------------------------------------------

/**
 * Inspect a failed trajectory and extract tool-level failure events.
 *
 * The agent result carries `toolCallsByName` (tool → call count).  For a
 * failed run we attribute the failure to the most-used tool, since that is
 * the tool whose repeated use did not converge to a correct answer.
 *
 * Returns an array of (tool, stepDescription, failureType) triples.
 * Empty array when there is nothing attributable.
 */
function extractFailureEvents(
  result: GaiaAgentResult,
  failureType: FailureType,
): Array<{ tool: string; step: string; type: FailureType }> {
  const events: Array<{ tool: string; step: string; type: FailureType }> = [];

  const toolCalls = result.toolCallsByName;
  if (!toolCalls || Object.keys(toolCalls).length === 0) {
    // No tool calls at all — record a synthetic "no_tool" event.
    events.push({
      tool: 'no_tool_called',
      step: `Agent failed with type=${failureType} without making any tool calls`,
      type: failureType,
    });
    return events;
  }

  // Attribute one event per tool that was called at least once.
  for (const [toolName, callCount] of Object.entries(toolCalls)) {
    const step = buildStepDescription(toolName, callCount, failureType);
    events.push({ tool: toolName, step, type: failureType });
  }

  return events;
}

function buildStepDescription(
  toolName: string,
  callCount: number,
  failureType: FailureType,
): string {
  const timesStr = callCount === 1 ? 'once' : `${callCount} times`;
  switch (failureType) {
    case 'empty_result':
      return `${toolName} called ${timesStr} but returned empty/no-result`;
    case 'timeout':
      return `${toolName} called ${timesStr} but agent timed out before converging`;
    case 'tool_error':
      return `${toolName} called ${timesStr} but raised an execution error`;
    case 'wrong_answer':
      return `${toolName} called ${timesStr} but final answer was incorrect`;
    default:
      return `${toolName} called ${timesStr}; failure type=${failureType}`;
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * After a GAIA trajectory completes, analyse it for causal failure patterns
 * and persist each observed edge in the JSONL store.
 *
 * Behaviour:
 *   - If `wasCorrect === true`, no edges are written (zero overhead).
 *   - Each (signature, tool, step) triple is deduplicated: if the same triple
 *     already exists in the store, its `occurrenceCount` is incremented in
 *     place rather than appending a new line.
 *   - Edges beyond `maxEdgesPerSignature` (default 5) per signature are
 *     discarded to keep the store bounded.
 *
 * @param question   - The GaiaQuestion that was attempted.
 * @param result     - The agent result from runGaiaAgent().
 * @param wasCorrect - Whether the final answer was judged correct.
 * @param options    - Optional store path and limits.
 * @returns Number of edges written/updated and the resolved store path.
 */
export async function recordCausalFailures(
  question: GaiaQuestion,
  result: GaiaAgentResult,
  wasCorrect: boolean,
  options?: CausalMemoryOptions,
): Promise<RecordResult> {
  const storePath = resolveStorePath(options);
  const maxEdges = options?.maxEdgesPerSignature ?? DEFAULT_MAX_EDGES;

  const failureType = inferFailureType(result, wasCorrect);
  if (failureType === null) {
    // Correct answer — nothing to record.
    return { edgesRecorded: 0, storePath };
  }

  const signature = computeQuestionSignature(question.question);
  const failureEvents = extractFailureEvents(result, failureType);

  if (failureEvents.length === 0) {
    return { edgesRecorded: 0, storePath };
  }

  // Load existing edges, upsert, cap, rewrite.
  const existing = await readAllEdges(storePath);

  let edgesRecorded = 0;

  for (const event of failureEvents) {
    // Count how many edges already exist for this signature.
    const sigEdges = existing.filter((e) => e.questionSignature === signature);

    // Check for exact duplicate (signature + tool + step).
    const dupIdx = existing.findIndex(
      (e) =>
        e.questionSignature === signature &&
        e.failedTool === event.tool &&
        e.failedTrajectoryStep === event.step,
    );

    if (dupIdx >= 0) {
      // Increment occurrence count in place.
      existing[dupIdx].occurrenceCount += 1;
      edgesRecorded++;
      continue;
    }

    // New edge — only add if we haven't hit the per-signature cap.
    if (sigEdges.length >= maxEdges) {
      continue; // Cap reached; discard.
    }

    const newEdge: CausalEdge = {
      questionSignature: signature,
      failedTool: event.tool,
      failedTrajectoryStep: event.step,
      observedFailureType: event.type,
      createdAt: new Date().toISOString(),
      occurrenceCount: 1,
    };
    existing.push(newEdge);
    edgesRecorded++;
  }

  if (edgesRecorded > 0) {
    writeAllEdges(storePath, existing);
  }

  return { edgesRecorded, storePath };
}

/**
 * Before running a new question, retrieve causal edges from prior failures
 * that match the question's signature and format them as a system-prompt hint.
 *
 * Return contract:
 *   - No edges matched → `{ hint: '', edgesMatched: 0 }` — caller MUST NOT
 *     inject an empty hint (wastes tokens; may confuse the model).
 *   - 1+ edges matched → `{ hint: '[PRIOR FAILURES] …', edgesMatched: N }`.
 *
 * @param question - The GaiaQuestion about to be attempted.
 * @param options  - Optional store path and limits.
 * @returns Formatted hint string and match count.
 */
export async function retrieveCausalHints(
  question: GaiaQuestion,
  options?: CausalMemoryOptions,
): Promise<RetrieveResult> {
  const storePath = resolveStorePath(options);
  const maxEdges = options?.maxEdgesPerSignature ?? DEFAULT_MAX_EDGES;

  const signature = computeQuestionSignature(question.question);
  const allEdges = await readAllEdges(storePath);

  // Filter to this question's signature, sort by occurrence count descending
  // so the most-reinforced warnings appear first.
  const matched = allEdges
    .filter((e) => e.questionSignature === signature)
    .sort((a, b) => b.occurrenceCount - a.occurrenceCount)
    .slice(0, maxEdges);

  if (matched.length === 0) {
    return { hint: '', edgesMatched: 0 };
  }

  const lines = matched.map((e) => {
    const times = e.occurrenceCount === 1 ? '1 time' : `${e.occurrenceCount} times`;
    return `  - ${e.failedTool} failed ${times} (${e.observedFailureType}): ${e.failedTrajectoryStep}`;
  });

  const hint =
    '[PRIOR FAILURES] On similar questions, these approaches failed:\n' +
    lines.join('\n') +
    '\nAvoid repeating these patterns. Try alternative tools or approaches.';

  return { hint, edgesMatched: matched.length };
}

/**
 * Smoke tests for the GAIA convergence layer (gaia-convergence.ts).
 *
 * 10 assertions covering:
 *   T1:  max_turns hit → checkConvergenceTriggers returns 'max_turns'
 *   T2:  same tool+args 3× in window → returns 'loop'
 *   T3:  120k tokens → returns 'token_overflow'
 *   T4:  forceCommit with prose-embedded answer in history → extraction succeeds
 *   T5:  forceCommit with explicit FINAL_ANSWER: X in response → returns X
 *   T6:  forceCommit on truly empty/looping conversation → returns null (graceful)
 *   T7:  argsHash deterministic — same args → same hash
 *   T8:  argsHash distinguishes — different args → different hash
 *   T9:  ConvergenceState records turn counts correctly via recordTurn
 *   T10: Anti-loop window correctly slides — only last 5 turns matter
 *
 * Refs: #2156, iter 62
 */

import assert from 'node:assert';
import {
  checkConvergenceTriggers,
  forceCommit,
  argsHash,
  createConvergenceState,
  recordTurn,
  extractFinalAnswerFromText,
  extractFromPriorMessages,
  TOKEN_OVERFLOW_THRESHOLD,
  LOOP_REPEAT_THRESHOLD,
  LOOP_WINDOW_SIZE,
} from './gaia-convergence.js';
import type { ConvergenceState } from './gaia-convergence.js';

// ---------------------------------------------------------------------------
// Test harness
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void | Promise<void>): void {
  const result = fn();
  if (result && typeof (result as Promise<void>).then === 'function') {
    (result as Promise<void>)
      .then(() => {
        console.log(`  PASS  ${name}`);
        passed++;
      })
      .catch((err: unknown) => {
        console.error(`  FAIL  ${name}: ${(err as Error).message ?? err}`);
        failed++;
      });
  } else {
    try {
      console.log(`  PASS  ${name}`);
      passed++;
    } catch (err: unknown) {
      console.error(`  FAIL  ${name}: ${(err as Error).message ?? err}`);
      failed++;
    }
  }
}

async function testAsync(name: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
    console.log(`  PASS  ${name}`);
    passed++;
  } catch (err: unknown) {
    console.error(`  FAIL  ${name}: ${(err as Error).message ?? err}`);
    failed++;
  }
}

// ---------------------------------------------------------------------------
// T1: max_turns hit → returns 'max_turns'
// ---------------------------------------------------------------------------

test('T1: max_turns hit returns max_turns', () => {
  const state: ConvergenceState = {
    turnCount: 12,
    totalTokens: 1000,
    toolCalls: [],
    detectedFailureMode: null,
  };
  const result = checkConvergenceTriggers(state, 12);
  assert.strictEqual(result, 'max_turns', `Expected 'max_turns', got ${result!}`);
});

// ---------------------------------------------------------------------------
// T2: same tool+args 3× in last 5 turns → returns 'loop'
// ---------------------------------------------------------------------------

test('T2: loop detection — same tool+args 3x in window', () => {
  const hash = argsHash('web_search', { query: 'test' });
  const state: ConvergenceState = {
    turnCount: 5,
    totalTokens: 5000,
    toolCalls: [
      { name: 'web_search', argsHash: hash, turn: 1 },
      { name: 'web_search', argsHash: hash, turn: 2 },
      { name: 'web_search', argsHash: hash, turn: 3 },
    ],
    detectedFailureMode: null,
  };
  const result = checkConvergenceTriggers(state, 15);
  assert.strictEqual(result, 'loop', `Expected 'loop', got ${result!}`);
});

// ---------------------------------------------------------------------------
// T3: 120k tokens → returns 'token_overflow'
// ---------------------------------------------------------------------------

test('T3: token_overflow at threshold', () => {
  const state: ConvergenceState = {
    turnCount: 5,
    totalTokens: TOKEN_OVERFLOW_THRESHOLD,
    toolCalls: [],
    detectedFailureMode: null,
  };
  const result = checkConvergenceTriggers(state, 20);
  assert.strictEqual(result, 'token_overflow', `Expected 'token_overflow', got ${result!}`);
});

// ---------------------------------------------------------------------------
// T4: forceCommit with prose-embedded answer in prior history → extraction succeeds
// ---------------------------------------------------------------------------

await testAsync('T4: forceCommit — prose-embedded FINAL_ANSWER in prior history', async () => {
  const messages = [
    { role: 'user', content: 'What is 2+2?' },
    {
      role: 'assistant',
      content: 'Let me think about this. The answer is definitely 4. FINAL_ANSWER: 4',
    },
    { role: 'user', content: 'tool results...' },
    { role: 'assistant', content: 'I got confused. Let me recalculate.' },
  ];

  // callModel returns an empty response (simulating no new FINAL_ANSWER)
  const callModel = async () => 'I need to think more about this.';

  const result = await forceCommit(messages as Array<{ role: string; content: string | unknown }>, callModel, 'max_turns');

  assert.strictEqual(result.answer, '4', `Expected '4', got ${result.answer!}`);
  assert.strictEqual(result.usedFallback, true, 'Expected usedFallback=true for history scan');
});

// ---------------------------------------------------------------------------
// T5: forceCommit with explicit FINAL_ANSWER: X in forced response → returns X
// ---------------------------------------------------------------------------

await testAsync('T5: forceCommit — explicit FINAL_ANSWER in forced-commit response', async () => {
  const messages = [
    { role: 'user', content: 'What is the capital of France?' },
    { role: 'assistant', content: 'I need to search for this.' },
  ];

  // callModel returns a response WITH FINAL_ANSWER
  const callModel = async () => 'Based on my knowledge, the capital is Paris. FINAL_ANSWER: Paris';

  const result = await forceCommit(messages as Array<{ role: string; content: string | unknown }>, callModel, 'max_turns');

  assert.strictEqual(result.answer, 'Paris', `Expected 'Paris', got ${result.answer!}`);
  assert.strictEqual(result.usedFallback, false, 'Expected usedFallback=false when direct extraction');
  assert.strictEqual(result.triggerMode, 'max_turns');
});

// ---------------------------------------------------------------------------
// T6: forceCommit on truly empty conversation → returns null (graceful)
// ---------------------------------------------------------------------------

await testAsync('T6: forceCommit — graceful null on empty conversation', async () => {
  const messages = [
    { role: 'user', content: 'What is something unknowable?' },
    { role: 'assistant', content: 'I have been calling tools repeatedly with no progress.' },
  ];

  // callModel returns nothing useful
  const callModel = async () => 'I cannot determine the answer to this question.';

  const result = await forceCommit(messages as Array<{ role: string; content: string | unknown }>, callModel, 'loop');

  assert.strictEqual(result.answer, null, `Expected null, got ${result.answer!}`);
  assert.strictEqual(result.triggerMode, 'loop');
});

// ---------------------------------------------------------------------------
// T7: argsHash deterministic — same args → same hash
// ---------------------------------------------------------------------------

test('T7: argsHash is deterministic', () => {
  const h1 = argsHash('web_search', { query: 'hello world', limit: 5 });
  const h2 = argsHash('web_search', { query: 'hello world', limit: 5 });
  assert.strictEqual(h1, h2, 'Same inputs must produce identical hash');
  assert.ok(h1.length === 16, `Hash should be 16 hex chars, got ${h1.length}`);
});

// ---------------------------------------------------------------------------
// T8: argsHash distinguishes — different args → different hash
// ---------------------------------------------------------------------------

test('T8: argsHash distinguishes different args', () => {
  const h1 = argsHash('web_search', { query: 'hello' });
  const h2 = argsHash('web_search', { query: 'world' });
  assert.notStrictEqual(h1, h2, 'Different args must produce different hash');

  const h3 = argsHash('calculator', { query: 'hello' });
  assert.notStrictEqual(h1, h3, 'Different tool names must produce different hash');
});

// ---------------------------------------------------------------------------
// T9: ConvergenceState records turn counts correctly via recordTurn
// ---------------------------------------------------------------------------

test('T9: recordTurn increments turnCount and totalTokens', () => {
  const state = createConvergenceState();

  assert.strictEqual(state.turnCount, 0);
  assert.strictEqual(state.totalTokens, 0);
  assert.strictEqual(state.toolCalls.length, 0);

  recordTurn(state, 1500, [
    { name: 'web_search', args: { query: 'test' } },
    { name: 'calculator', args: { expr: '2+2' } },
  ]);

  assert.strictEqual(state.turnCount, 1, `Expected turnCount=1, got ${state.turnCount}`);
  assert.strictEqual(state.totalTokens, 1500, `Expected totalTokens=1500, got ${state.totalTokens}`);
  assert.strictEqual(state.toolCalls.length, 2, `Expected 2 tool calls recorded, got ${state.toolCalls.length}`);
  assert.strictEqual(state.toolCalls[0].name, 'web_search');
  assert.strictEqual(state.toolCalls[0].turn, 1);

  recordTurn(state, 2000, []);

  assert.strictEqual(state.turnCount, 2);
  assert.strictEqual(state.totalTokens, 3500);
});

// ---------------------------------------------------------------------------
// T10: Anti-loop window correctly slides — only last LOOP_WINDOW_SIZE turns matter
// ---------------------------------------------------------------------------

test('T10: loop window slides — old calls outside window do not trigger', () => {
  const hash = argsHash('web_search', { query: 'test' });

  // 4 repeated calls followed by 5 different calls — window is last 5 only
  const oldCalls = Array.from({ length: 4 }, (_, i) => ({
    name: 'web_search', argsHash: hash, turn: i + 1,
  }));
  const recentCalls = Array.from({ length: LOOP_WINDOW_SIZE }, (_, i) => ({
    name: `tool_${i}`, argsHash: argsHash(`tool_${i}`, {}), turn: i + 5,
  }));

  const state: ConvergenceState = {
    turnCount: 9,
    totalTokens: 9000,
    toolCalls: [...oldCalls, ...recentCalls],
    detectedFailureMode: null,
  };

  const result = checkConvergenceTriggers(state, 20);
  assert.strictEqual(result, null,
    `Expected null (old calls outside window), got ${result!}`);
});

