/**
 * GAIA Adversarial Critic — ADR-135 Track D
 *
 * After the main agent produces a candidate answer, a Sonnet pass reviews it.
 * If the critic verdict is "fail", the orchestrator re-runs the agent with the
 * critique injected as additional context.
 *
 * Motivation (iter 29 finding): tool quality is the bottleneck on L1 (~20.8%).
 * The critic catches wrong-because-of-bad-tool-result answers BEFORE submission,
 * without requiring better search backends.  Expected L1 lift: +3-5pp.
 *
 * Design:
 *  - NEW file only; NOT wired into gaia-bench.ts yet to avoid merge conflicts
 *    with in-flight iter 29/31/34 branches.  Wiring is a small follow-up PR.
 *  - `criticReview()` — single Sonnet call, returns structured verdict.
 *  - `runGaiaAgentWithCritic()` — orchestration wrapper: runs agent, calls
 *    critic, retries once on "fail".  "uncertain" is treated as "pass" (don't
 *    burn retries on borderline cases).
 *  - API errors and malformed JSON from the critic are caught; original
 *    candidate is returned with an error-flagged verdict.
 *  - Default opt-in: enableCritic=false.  Set true via RunWithCriticOptions.
 *
 * Cost discipline:
 *  - Critic uses claude-sonnet-4-6 (separate from the agent's default Haiku).
 *  - One critic call + one optional retry = max 2 extra Sonnet calls per Q.
 *  - Approximate extra cost per question: ~$0.003-0.005 (well within budget).
 *
 * Plugin sync TODO (follow-up PR after gaia-bench wiring):
 *  - Update plugins/ruflo-workflows/commands/gaia-run.md with --enable-critic flag.
 *  - Update plugins/ruflo-workflows/skills/gaia-debugging/SKILL.md: add critic
 *    as a recommended diagnostic step for wrong-answer analysis.
 *
 * Refs: ADR-135, ADR-133, iter 29 finding, #2156
 */

import { execSync } from 'node:child_process';
import {
  GaiaQuestion,
} from './gaia-loader.js';
import {
  runGaiaAgent,
  GaiaAgentResult,
  GaiaAgentOptions,
} from './gaia-agent.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ANTHROPIC_API_URL = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_API_VERSION = '2023-06-01';

/** Default model for the critic — Sonnet for higher reasoning quality. */
const DEFAULT_CRITIC_MODEL = 'claude-sonnet-4-6';

/** Max tokens for the critic response (verdict JSON is short). */
const CRITIC_MAX_TOKENS = 512;

/** Sonnet pricing (input/output per million tokens, 2026-05-27).
 *  Used only for cost estimation in CriticVerdict. */
const SONNET_INPUT_COST_PER_M = 3.0;
const SONNET_OUTPUT_COST_PER_M = 15.0;

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/**
 * Structured verdict returned by the adversarial critic.
 *
 * - "pass"      → critic agrees with the candidate; no retry needed.
 * - "fail"      → critic found a flaw; suggestedRevision provided if possible.
 * - "uncertain" → critic is unsure; treated as "pass" to avoid burning retries.
 */
export type CriticVerdictType = 'pass' | 'fail' | 'uncertain';

export interface CriticVerdict {
  /** Critic's assessment of the candidate answer. */
  verdict: CriticVerdictType;
  /** Short explanation of the reasoning (1-3 sentences). */
  reasoning: string;
  /** Suggested correction when verdict is "fail"; may be empty string. */
  suggestedRevision?: string;
  /** Estimated USD cost of this critic call. */
  costUsd: number;
  /** True when the critic call itself failed (API error, malformed JSON). */
  error?: boolean;
  /** Original raw response text when parse failed. */
  rawResponse?: string;
}

export interface CriticOptions {
  /**
   * Model to use for the critic pass.
   * Defaults to 'claude-sonnet-4-6' (intentionally separate from agent model).
   */
  model?: string;
  /**
   * Maximum number of agent retries on "fail" verdict.
   * Default: 1 (one retry).  Set to 0 to disable retries (observe-only mode).
   */
  maxRetries?: number;
  /** Anthropic API key (resolved via env/gcloud if omitted). */
  apiKey?: string;
}

// Extended result returned by the critic-wrapped orchestrator.
export interface GaiaAgentResultWithCritic extends GaiaAgentResult {
  /** All critic verdicts collected (one per agent attempt). */
  criticVerdicts: CriticVerdict[];
  /** How many retries were actually attempted (0 if critic passed first time). */
  retriesAttempted: number;
}

/** Options for runGaiaAgentWithCritic, extending core agent options. */
export interface RunWithCriticOptions extends GaiaAgentOptions {
  /**
   * Enable the adversarial critic pass.  Default: false.
   * When false, runGaiaAgentWithCritic behaves identically to runGaiaAgent.
   */
  enableCritic?: boolean;
  /** Critic-specific configuration. */
  criticOptions?: CriticOptions;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/** Resolve Anthropic API key using the same precedence as gaia-agent.ts. */
function resolveApiKey(override?: string): string {
  if (override) return override;
  const fromEnv = process.env['ANTHROPIC_API_KEY'];
  if (fromEnv) return fromEnv;
  try {
    return execSync(
      'gcloud secrets versions access latest --secret=ANTHROPIC_API_KEY',
      { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] },
    ).trim();
  } catch {
    throw new Error(
      'ANTHROPIC_API_KEY not set and gcloud fallback failed. ' +
      'Set ANTHROPIC_API_KEY env var or ensure gcloud access.',
    );
  }
}

/**
 * Build the critic system prompt.
 * Instructs Sonnet to act as an adversarial reviewer and respond in JSON.
 */
function buildCriticSystemPrompt(): string {
  return `You are an adversarial reviewer of agent answers on the GAIA benchmark. \
Your job is to find flaws in candidate answers before they are submitted.

Given a question, a candidate answer, and a summary of the agent's reasoning \
trajectory, you must decide whether the candidate answer is correct.

Evaluation criteria:
1. Does the answer directly address what the question asks?
2. Is there evidence in the trajectory that supports the answer?
3. Are there obvious flaws (wrong unit, wrong format, missed constraint, \
fabricated source, off-by-one error, truncation)?
4. For numeric answers: is the magnitude and unit plausible?
5. For list answers: are all required items present and correctly ordered?

Respond ONLY with a JSON object — no markdown, no prose outside the JSON:
{"verdict":"pass"|"fail"|"uncertain","reasoning":"<1-3 sentences>","suggestedRevision":"<corrected answer or empty string>"}

Use "uncertain" only when you genuinely cannot determine correctness from the \
available information. Never use "uncertain" to avoid making a decision when \
evidence is available.`;
}

/**
 * Build the critic user message combining the question, candidate answer,
 * and a compressed view of the agent trajectory.
 */
function buildCriticUserMessage(
  question: GaiaQuestion,
  candidateAnswer: string,
  trajectory: { steps: Array<{ tool?: string; result?: string; reasoning?: string }>; turns: number },
): string {
  // Summarise trajectory: first 2 + last 2 steps to keep tokens bounded.
  const steps = trajectory.steps ?? [];
  const summarised = steps.length <= 4
    ? steps
    : [...steps.slice(0, 2), ...steps.slice(-2)];

  const trajectoryText = summarised.length === 0
    ? '(no tool calls recorded)'
    : summarised.map((s, i) => {
        const label = s.tool ? `Step ${i + 1} [${s.tool}]` : `Step ${i + 1}`;
        const result = s.result ? ` → ${s.result.slice(0, 200)}` : '';
        return `${label}${result}`;
      }).join('\n');

  return `QUESTION: ${question.question}

CANDIDATE ANSWER: ${candidateAnswer}

AGENT TRAJECTORY (${trajectory.turns} turns, summarised):
${trajectoryText}`;
}

/**
 * Attempt to extract a verdict from a potentially malformed JSON string.
 * Falls back gracefully to "uncertain" with the raw text preserved.
 */
function parseVerdictFallback(raw: string): Partial<CriticVerdict> {
  // Try standard JSON parse first.
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const verdict = parsed['verdict'] as string;
    if (verdict === 'pass' || verdict === 'fail' || verdict === 'uncertain') {
      return {
        verdict,
        reasoning: (parsed['reasoning'] as string) ?? '',
        suggestedRevision: (parsed['suggestedRevision'] as string) ?? '',
      };
    }
  } catch {
    // Fall through to regex extraction.
  }

  // Regex extraction for embedded JSON in prose.
  const jsonMatch = raw.match(/\{[\s\S]*?"verdict"\s*:\s*"(pass|fail|uncertain)"[\s\S]*?\}/);
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[0]) as Record<string, unknown>;
      return {
        verdict: parsed['verdict'] as CriticVerdictType,
        reasoning: (parsed['reasoning'] as string) ?? '',
        suggestedRevision: (parsed['suggestedRevision'] as string) ?? '',
      };
    } catch {
      // Fall through.
    }
  }

  // Last resort: extract verdict keyword from raw text.
  const verdictMatch = raw.match(/\b(pass|fail|uncertain)\b/i);
  return {
    verdict: verdictMatch
      ? (verdictMatch[1].toLowerCase() as CriticVerdictType)
      : 'uncertain',
    reasoning: `Critic returned malformed JSON; extracted verdict heuristically.`,
    suggestedRevision: '',
    rawResponse: raw.slice(0, 500),
  };
}

// ---------------------------------------------------------------------------
// Core critic function
// ---------------------------------------------------------------------------

/**
 * Run the adversarial critic against a candidate answer.
 *
 * @param question     - The GAIA question being evaluated.
 * @param candidateAnswer - The agent's proposed final answer.
 * @param trajectory   - Lightweight trajectory summary from the agent run.
 * @param options      - Critic configuration (model, apiKey).
 * @returns            CriticVerdict with verdict, reasoning, cost.
 */
export async function criticReview(
  question: GaiaQuestion,
  candidateAnswer: string,
  trajectory: { steps: Array<{ tool?: string; result?: string; reasoning?: string }>; turns: number },
  options?: CriticOptions,
): Promise<CriticVerdict> {
  const model = options?.model ?? DEFAULT_CRITIC_MODEL;
  const apiKey = resolveApiKey(options?.apiKey);
  const t0 = Date.now();

  const requestBody = {
    model,
    max_tokens: CRITIC_MAX_TOKENS,
    system: buildCriticSystemPrompt(),
    messages: [
      {
        role: 'user',
        content: buildCriticUserMessage(question, candidateAnswer, trajectory),
      },
    ],
  };

  let rawResponseText = '';
  try {
    const response = await fetch(ANTHROPIC_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': ANTHROPIC_API_VERSION,
      },
      body: JSON.stringify(requestBody),
    });

    if (!response.ok) {
      const errText = await response.text().catch(() => '');
      throw new Error(`Anthropic API error ${response.status}: ${errText.slice(0, 200)}`);
    }

    const data = await response.json() as {
      content: Array<{ type: string; text?: string }>;
      usage?: { input_tokens: number; output_tokens: number };
    };

    const inputTokens = data.usage?.input_tokens ?? 0;
    const outputTokens = data.usage?.output_tokens ?? 0;
    const costUsd =
      (inputTokens / 1_000_000) * SONNET_INPUT_COST_PER_M +
      (outputTokens / 1_000_000) * SONNET_OUTPUT_COST_PER_M;

    rawResponseText = data.content
      .filter(b => b.type === 'text')
      .map(b => b.text ?? '')
      .join('');

    const parsed = parseVerdictFallback(rawResponseText);

    return {
      verdict: parsed.verdict ?? 'uncertain',
      reasoning: parsed.reasoning ?? '',
      suggestedRevision: parsed.suggestedRevision ?? '',
      costUsd,
      ...(parsed.rawResponse ? { rawResponse: parsed.rawResponse } : {}),
    };
  } catch (err) {
    const wallMs = Date.now() - t0;
    const errMsg = err instanceof Error ? err.message : String(err);
    // Graceful fallback: treat critic error as "uncertain" so agent result
    // is still returned rather than throwing.
    return {
      verdict: 'uncertain',
      reasoning: `Critic call failed after ${wallMs}ms: ${errMsg.slice(0, 200)}`,
      suggestedRevision: '',
      costUsd: 0,
      error: true,
      rawResponse: rawResponseText.slice(0, 200) || undefined,
    };
  }
}

// ---------------------------------------------------------------------------
// Orchestration wrapper
// ---------------------------------------------------------------------------

/**
 * Run the GAIA agent with an optional adversarial critic pass.
 *
 * When enableCritic=false (default), this is a thin pass-through to
 * runGaiaAgent with an empty criticVerdicts array.
 *
 * When enableCritic=true:
 *  1. Run runGaiaAgent normally.
 *  2. If the agent produced a finalAnswer, call criticReview.
 *  3. If verdict is "fail" and retriesAttempted < maxRetries:
 *     a. Re-run the agent with the critique injected as additional context.
 *     b. Call criticReview again on the new answer.
 *  4. Return the final result with all critic verdicts attached.
 *
 * Note on "uncertain": treated as "pass" (no retry triggered).
 */
export async function runGaiaAgentWithCritic(
  question: GaiaQuestion,
  options: RunWithCriticOptions = {},
): Promise<GaiaAgentResultWithCritic> {
  const { enableCritic = false, criticOptions, ...agentOptions } = options;

  // Fast path: critic disabled.
  if (!enableCritic) {
    const result = await runGaiaAgent(question, agentOptions);
    return { ...result, criticVerdicts: [], retriesAttempted: 0 };
  }

  const maxRetries = criticOptions?.maxRetries ?? 1;
  const criticVerdicts: CriticVerdict[] = [];
  let retriesAttempted = 0;

  // First agent run.
  let agentResult = await runGaiaAgent(question, agentOptions);

  // If agent timed out or errored with no answer, skip critic.
  if (agentResult.finalAnswer == null) {
    return { ...agentResult, criticVerdicts, retriesAttempted };
  }

  // Build a lightweight trajectory summary from the agent result.
  // gaia-agent.ts doesn't expose step-level detail in GaiaAgentResult, so we
  // synthesise from the available fields (tool call counts, turn count).
  const makeTrajectory = (result: GaiaAgentResult) => ({
    turns: result.turns,
    steps: Object.entries(result.toolCallsByName).map(([tool, count]) => ({
      tool,
      result: `called ${count} time(s)`,
    })),
  });

  // First critic pass.
  let verdict = await criticReview(
    question,
    agentResult.finalAnswer,
    makeTrajectory(agentResult),
    criticOptions,
  );
  criticVerdicts.push(verdict);

  // Retry loop on "fail".
  while (verdict.verdict === 'fail' && retriesAttempted < maxRetries) {
    retriesAttempted += 1;

    // Inject critique as additional context via the system prompt append.
    // We pass it through GaiaAgentOptions.criticFeedback — gaia-agent.ts does
    // NOT yet read this field (wiring is follow-up PR), but storing it here
    // makes the contract explicit and harmless (unknown options are ignored).
    const retryOptions: GaiaAgentOptions & { criticFeedback?: string } = {
      ...agentOptions,
      criticFeedback:
        `Previous answer "${agentResult.finalAnswer}" was flagged by adversarial review: ` +
        `${verdict.reasoning}` +
        (verdict.suggestedRevision
          ? ` Suggested revision: ${verdict.suggestedRevision}`
          : ''),
    };

    agentResult = await runGaiaAgent(question, retryOptions);

    if (agentResult.finalAnswer == null) {
      // Retry yielded no answer; stop retrying.
      break;
    }

    verdict = await criticReview(
      question,
      agentResult.finalAnswer,
      makeTrajectory(agentResult),
      criticOptions,
    );
    criticVerdicts.push(verdict);
  }

  return { ...agentResult, criticVerdicts, retriesAttempted };
}

/**
 * Smoke tests for gaia-decomposer.ts (ADR-135 Track E)
 *
 * All HTTP calls are mocked — no live API calls, no cost.
 * Covers 7 assertions:
 *  1. Atomic question → decomposed=false, single sub-question = original
 *  2. 3-step question → decomposed=true, 3 sub-questions in dependency order
 *  3. Malformed JSON response → fallback to atomic (graceful degradation)
 *  4. API error → fallback to atomic (graceful degradation)
 *  5. synthesizeFromSubAnswers — atomic question returns sub-answer directly (no API call)
 *  6. synthesizeFromSubAnswers — valid JSON response → finalAnswer + reasoning
 *  7. synthesizeFromSubAnswers — malformed JSON → fallback to last sub-answer
 *
 * Run with:
 *   npx tsx src/benchmarks/gaia-decomposer.smoke.ts
 *
 * Expected cost: $0 (all mocked).
 */

import { decomposeQuestion, synthesizeFromSubAnswers, DecomposedQuestion } from './gaia-decomposer.js';

// ---------------------------------------------------------------------------
// Minimal fetch mock
// ---------------------------------------------------------------------------

type MockFetchResponder = (url: string, init: RequestInit) => {
  ok: boolean;
  status: number;
  text: () => Promise<string>;
  json: () => Promise<unknown>;
};

function installFetchMock(responder: MockFetchResponder): void {
  (globalThis as unknown as Record<string, unknown>).fetch = (
    url: unknown,
    init: unknown,
  ) => {
    const r = responder(url as string, init as RequestInit);
    return Promise.resolve(r);
  };
}

function mockSuccessResponse(jsonBody: unknown): ReturnType<MockFetchResponder> {
  const bodyStr = JSON.stringify(jsonBody);
  return {
    ok: true,
    status: 200,
    text: () => Promise.resolve(bodyStr),
    json: () => Promise.resolve(jsonBody),
  };
}

function mockErrorResponse(status: number): ReturnType<MockFetchResponder> {
  return {
    ok: false,
    status,
    text: () => Promise.resolve(`HTTP ${status} error`),
    json: () => Promise.reject(new Error('error response has no JSON')),
  };
}

/** Build a minimal Anthropic Messages API response shape. */
function anthropicTextResponse(text: string, inputTokens = 100, outputTokens = 50): unknown {
  return {
    id: 'msg_test',
    type: 'message',
    role: 'assistant',
    content: [{ type: 'text', text }],
    model: 'claude-haiku-4-5',
    stop_reason: 'end_turn',
    usage: { input_tokens: inputTokens, output_tokens: outputTokens },
  };
}

// ---------------------------------------------------------------------------
// Test runner
// ---------------------------------------------------------------------------

const PASS = '\x1b[32mPASS\x1b[0m';
const FAIL = '\x1b[31mFAIL\x1b[0m';

let failures = 0;
let passed = 0;

function check(label: string, condition: boolean): void {
  if (condition) {
    console.log(`  ${PASS}  ${label}`);
    passed++;
  } else {
    console.log(`  ${FAIL}  ${label}`);
    failures++;
  }
}

// ---------------------------------------------------------------------------
// Smoke tests
// ---------------------------------------------------------------------------

async function runSmoke(): Promise<void> {
  console.log('\n=== gaia-decomposer smoke (mocked, $0) ===\n');

  // Set a fake API key so resolveApiKey() doesn't throw
  process.env.ANTHROPIC_API_KEY = 'sk-ant-test-key';

  // ─────────────────────────────────────────────────────────────────────────
  // Test 1: Atomic question → decomposed=false, single sub-question
  // ─────────────────────────────────────────────────────────────────────────
  console.log('-- Test 1: Atomic question --');
  {
    const atomicPayload = {
      decomposed: false,
      subQuestions: ['What year was the Eiffel Tower built?'],
      synthesisHint: 'Use directly.',
    };
    installFetchMock(() => mockSuccessResponse(anthropicTextResponse(JSON.stringify(atomicPayload))));

    const result = await decomposeQuestion('What year was the Eiffel Tower built?');

    check('decomposed=false for atomic question', result.decomposed === false);
    check('single sub-question equals original', result.subQuestions.length === 1 && result.subQuestions[0] === 'What year was the Eiffel Tower built?');
    check('cost > 0 (Haiku tokens consumed)', result.cost > 0);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Test 2: 3-step complex question → decomposed=true, 3 sub-questions in order
  // ─────────────────────────────────────────────────────────────────────────
  console.log('\n-- Test 2: 3-step complex question --');
  {
    const complexPayload = {
      decomposed: true,
      subQuestions: [
        'What year was the Eiffel Tower built?',
        'What decade contains the year 1889?',
        'Who directed the highest-grossing film of the 1880s?',
      ],
      synthesisHint: 'The answer to sub-question 3 is the final answer.',
    };
    installFetchMock(() => mockSuccessResponse(anthropicTextResponse(JSON.stringify(complexPayload))));

    const question = 'Who directed the highest-grossing film of the decade the Eiffel Tower was built?';
    const result = await decomposeQuestion(question);

    check('decomposed=true for 3-step question', result.decomposed === true);
    check('3 sub-questions returned', result.subQuestions.length === 3);
    check('first sub-question asks about Eiffel Tower year', result.subQuestions[0].toLowerCase().includes('eiffel tower'));
    check('synthesisHint is non-empty', result.synthesisHint.length > 0);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Test 3: Malformed JSON response → fallback to atomic
  // ─────────────────────────────────────────────────────────────────────────
  console.log('\n-- Test 3: Malformed JSON fallback --');
  {
    installFetchMock(() =>
      mockSuccessResponse(anthropicTextResponse('This is not JSON at all { broken')),
    );

    const question = 'What is the capital of France?';
    const result = await decomposeQuestion(question);

    check('malformed JSON → decomposed=false', result.decomposed === false);
    check('malformed JSON → sub-question is original', result.subQuestions[0] === question);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Test 4: API error → fallback to atomic
  // ─────────────────────────────────────────────────────────────────────────
  console.log('\n-- Test 4: API error fallback --');
  {
    installFetchMock(() => mockErrorResponse(500));

    const question = 'How many planets are in the solar system?';
    const result = await decomposeQuestion(question);

    check('API error → decomposed=false', result.decomposed === false);
    check('API error → sub-question is original', result.subQuestions[0] === question);
    check('API error → cost=0', result.cost === 0);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Test 5: synthesizeFromSubAnswers — atomic question (decomposed=false)
  //         returns sub-answer directly WITHOUT an API call
  // ─────────────────────────────────────────────────────────────────────────
  console.log('\n-- Test 5: synthesize — atomic passthrough (no API call) --');
  {
    // Install a fetch mock that throws if called — should NOT be called
    let fetchCalled = false;
    installFetchMock(() => {
      fetchCalled = true;
      return mockSuccessResponse({ finalAnswer: 'unexpected', reasoning: 'should not reach here' });
    });

    const atomicDecomposed: DecomposedQuestion = {
      originalQuestion: 'What year was the Eiffel Tower built?',
      subQuestions: ['What year was the Eiffel Tower built?'],
      synthesisHint: 'Use directly.',
      decomposed: false,
      cost: 0,
    };

    const result = await synthesizeFromSubAnswers(atomicDecomposed, ['1889']);

    check('atomic synthesize returns sub-answer directly', result.finalAnswer === '1889');
    check('atomic synthesize has cost=0', result.cost === 0);
    check('atomic synthesize did NOT call API', fetchCalled === false);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Test 6: synthesizeFromSubAnswers — valid JSON → finalAnswer + reasoning
  // ─────────────────────────────────────────────────────────────────────────
  console.log('\n-- Test 6: synthesize — valid JSON response --');
  {
    const synthPayload = {
      finalAnswer: 'Georges Méliès',
      reasoning: 'The highest-grossing film of the 1880s was X. Its director was Georges Méliès.',
    };
    installFetchMock(() => mockSuccessResponse(anthropicTextResponse(JSON.stringify(synthPayload))));

    const decomposed: DecomposedQuestion = {
      originalQuestion: 'Who directed the highest-grossing film of the decade the Eiffel Tower was built?',
      subQuestions: [
        'What year was the Eiffel Tower built?',
        'What decade contains 1889?',
        'Who directed the highest-grossing film of the 1880s?',
      ],
      synthesisHint: 'The director from sub-question 3 is the answer.',
      decomposed: true,
      cost: 0.0003,
    };

    const result = await synthesizeFromSubAnswers(
      decomposed,
      ['1889', '1880s', 'Georges Méliès'],
    );

    check('synthesize returns correct finalAnswer', result.finalAnswer === 'Georges Méliès');
    check('synthesize reasoning is non-empty', result.reasoning.length > 0);
    check('synthesize cost > 0 (Sonnet tokens consumed)', result.cost > 0);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Test 7: synthesizeFromSubAnswers — malformed JSON → fallback to last sub-answer
  // ─────────────────────────────────────────────────────────────────────────
  console.log('\n-- Test 7: synthesize — malformed JSON fallback --');
  {
    installFetchMock(() =>
      mockSuccessResponse(anthropicTextResponse('{ bad json here ]]}')),
    );

    const decomposed: DecomposedQuestion = {
      originalQuestion: 'How many people live in Tokyo?',
      subQuestions: [
        'What is the population of Tokyo metropolitan area?',
        'What is the population of Tokyo proper?',
      ],
      synthesisHint: 'Use the Tokyo proper figure.',
      decomposed: true,
      cost: 0.0003,
    };

    const result = await synthesizeFromSubAnswers(
      decomposed,
      ['37.4 million (metropolitan)', '13.96 million (proper)'],
    );

    check('malformed JSON fallback → returns last sub-answer', result.finalAnswer === '13.96 million (proper)');
    check('malformed JSON fallback → reasoning mentions parse error', result.reasoning.toLowerCase().includes('parse error'));
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Summary
  // ─────────────────────────────────────────────────────────────────────────
  const total = passed + failures;
  console.log(`\n=== smoke ${failures === 0 ? 'PASSED' : `FAILED (${failures}/${total} assertion(s))`} — ${passed}/${total} passed ===\n`);

  if (failures > 0) process.exit(1);
}

// Run when executed directly
const isMain = process.argv[1] && (
  process.argv[1].endsWith('gaia-decomposer.smoke.ts') ||
  process.argv[1].endsWith('gaia-decomposer.smoke.js')
);
if (isMain) {
  runSmoke().catch((err) => {
    console.error('Smoke failed with exception:', err);
    process.exit(1);
  });
}

export { runSmoke };

/**
 * GAIA Question Decomposer — ADR-135 Track E
 *
 * Decomposes complex GAIA benchmark questions into 1-5 ordered sub-questions
 * that can each be answered with a single tool call, then synthesizes the
 * sub-answers into a final response.
 *
 * Motivation (iter 29 finding): tool quality is the bottleneck on L1 (~20.8%).
 * Bad tools that fail on complex queries may succeed on focused sub-queries.
 * This mimics what humans do at 92% on GAIA (decompose-then-solve).
 * Expected L1 lift: +5-10pp on multi-step questions (~30-40% of L1 set).
 *
 * Design:
 *  - NEW standalone file only; NOT wired into gaia-bench.ts to avoid merge
 *    conflicts with in-flight iter 29/31/34/35/36 branches.
 *    Wiring is a small follow-up PR.
 *  - `decomposeQuestion()` — Haiku-cheap classification + decomposition
 *    (~$0.0003 per question).
 *  - `synthesizeFromSubAnswers()` — Sonnet synthesis from sub-answers
 *    (the sub-answers are the hard work; synthesis is just combination).
 *  - Atomic questions are returned as-is — no overhead when not needed.
 *  - Graceful fallback to atomic on API errors or malformed JSON.
 *
 * Cost discipline:
 *  - Decomposition uses claude-haiku-4-5 (~$0.0003/question).
 *  - Synthesis uses claude-sonnet-4-6 (~$0.002/question).
 *  - Total overhead per question (when decomposed): ~$0.002-0.003.
 *
 * Plugin sync TODO (follow-up PR after gaia-bench wiring):
 *  - Update plugins/ruflo-workflows/commands/gaia-run.md with --decompose flag.
 *  - Update plugins/ruflo-workflows/skills/gaia-debugging/SKILL.md: add
 *    decomposition as a recommended strategy for multi-step failures.
 *
 * Refs: ADR-135, ADR-133, iter 29 finding, #2156
 */

import { execSync } from 'node:child_process';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ANTHROPIC_API_URL = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_API_VERSION = '2023-06-01';

/**
 * Haiku for cheap decomposition classification (~$0.0003/question).
 * Callers can override via DecomposerOptions.model.
 */
const DEFAULT_DECOMPOSER_MODEL = 'claude-haiku-4-5';

/**
 * Sonnet for synthesis — sub-answers are the expensive part, synthesis is
 * just recombination, but needs good reasoning. Callers can override.
 */
const DEFAULT_SYNTHESIZER_MODEL = 'claude-sonnet-4-6';

const DECOMPOSER_MAX_TOKENS = 512;
const SYNTHESIZER_MAX_TOKENS = 512;

/** Haiku pricing per million tokens (2026-05-27). */
const HAIKU_INPUT_COST_PER_M = 0.8;
const HAIKU_OUTPUT_COST_PER_M = 4.0;

/** Sonnet pricing per million tokens (2026-05-27). */
const SONNET_INPUT_COST_PER_M = 3.0;
const SONNET_OUTPUT_COST_PER_M = 15.0;

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface DecomposedQuestion {
  /** The original unmodified question text. */
  originalQuestion: string;
  /**
   * Ordered sub-questions in dependency order (1-5).
   * If decomposed=false, contains exactly one entry equal to originalQuestion.
   */
  subQuestions: string[];
  /**
   * Brief hint for how to combine sub-answers into the final answer.
   * Example: "Multiply the two values found in sub-questions 1 and 2."
   */
  synthesisHint: string;
  /**
   * true if the question was split into multiple sub-questions;
   * false if it was deemed atomic (single lookup / single computation).
   */
  decomposed: boolean;
  /** USD spent on the decomposition API call (0 if fallback/atomic). */
  cost: number;
}

export interface DecomposerOptions {
  /**
   * Model to use for decomposition classification.
   * Default: 'claude-haiku-4-5' (cheap).
   */
  model?: string;
  /**
   * Maximum sub-questions to produce when decomposing.
   * Default: 5.
   */
  maxSubQuestions?: number;
  /** API key override. Falls back to ANTHROPIC_API_KEY env var. */
  apiKey?: string;
}

export interface SynthesizerOptions {
  /**
   * Model to use for final-answer synthesis.
   * Default: 'claude-sonnet-4-6'.
   */
  model?: string;
  /** API key override. Falls back to ANTHROPIC_API_KEY env var. */
  apiKey?: string;
}

export interface SynthesisResult {
  /** The synthesized final answer string. */
  finalAnswer: string;
  /** Brief reasoning that led to the final answer. */
  reasoning: string;
  /** USD spent on the synthesis API call. */
  cost: number;
}

// ---------------------------------------------------------------------------
// API key resolution (mirrors gaia-agent.ts / gaia-judge.ts pattern)
// ---------------------------------------------------------------------------

function resolveApiKey(supplied?: string): string {
  if (supplied && supplied.trim()) return supplied.trim();

  const envKey = process.env.ANTHROPIC_API_KEY;
  if (envKey && envKey.trim()) return envKey.trim();

  try {
    const out = execSync(
      'gcloud secrets versions access latest --secret=ANTHROPIC_API_KEY 2>/dev/null',
      { encoding: 'utf-8', timeout: 10_000 },
    ).trim();
    if (out) return out;
  } catch {
    /* fall through */
  }

  throw new Error(
    'ANTHROPIC_API_KEY not found. Set the env var or store it in GCP Secret Manager ' +
    'under "ANTHROPIC_API_KEY".',
  );
}

// ---------------------------------------------------------------------------
// Anthropic Messages API helper
// ---------------------------------------------------------------------------

interface AnthropicResponse {
  content: Array<{ type: string; text?: string }>;
  usage: { input_tokens: number; output_tokens: number };
}

async function callAnthropic(
  systemPrompt: string,
  userMessage: string,
  model: string,
  maxTokens: number,
  apiKey: string,
): Promise<{ text: string; tokensIn: number; tokensOut: number }> {
  const body = JSON.stringify({
    model,
    max_tokens: maxTokens,
    system: systemPrompt,
    messages: [{ role: 'user', content: userMessage }],
  });

  const response = await fetch(ANTHROPIC_API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': ANTHROPIC_API_VERSION,
    },
    body,
  });

  if (!response.ok) {
    const errText = await response.text().catch(() => '(no body)');
    throw new Error(`Anthropic API error ${response.status}: ${errText}`);
  }

  const data = (await response.json()) as AnthropicResponse;
  const textBlock = data.content.find((c) => c.type === 'text');
  const text = textBlock?.text ?? '';

  return {
    text,
    tokensIn: data.usage.input_tokens,
    tokensOut: data.usage.output_tokens,
  };
}

// ---------------------------------------------------------------------------
// Decomposer prompt
// ---------------------------------------------------------------------------

function buildDecomposerSystemPrompt(maxSubQuestions: number): string {
  return [
    'You are decomposing GAIA benchmark questions into sub-questions for a tool-using agent.',
    '',
    `Rules:`,
    '1. If the question is ATOMIC (single fact lookup or single computation — one tool call',
    '   would answer it directly), return:',
    '   {"decomposed": false, "subQuestions": ["<original question>"], "synthesisHint": "Use directly."}',
    '',
    `2. If the question requires ${maxSubQuestions > 2 ? '2-' + maxSubQuestions : '2'} dependent steps, decompose into ORDERED`,
    '   sub-questions where each can be answered with a single tool call:',
    '   {"decomposed": true, "subQuestions": ["...", "...", "..."], "synthesisHint": "How to combine"}',
    '',
    'Sub-question requirements:',
    '  - Each sub-question must be SELF-CONTAINED (no pronouns referring to earlier sub-questions).',
    '  - Sub-questions must be in DEPENDENCY ORDER (earlier answers feed into later questions if needed).',
    '  - Sub-questions should be specific enough for a single web search or computation.',
    `  - Maximum ${maxSubQuestions} sub-questions.`,
    '',
    'Examples of ATOMIC questions (decomposed=false):',
    '  "What year was the Eiffel Tower built?"',
    '  "What is 25% of 840?"',
    '  "Who wrote Pride and Prejudice?"',
    '',
    'Examples of COMPLEX questions (decomposed=true):',
    '  "Who directed the highest-grossing film of the decade that contained the year',
    '   the Eiffel Tower was built?" → sub-questions:',
    '    1. "What year was the Eiffel Tower built?"',
    '    2. "What decade contains [year from Q1]?" (compute from Q1 answer)',
    '    3. "What was the highest-grossing film of [decade from Q2]?"',
    '    4. "Who directed [film from Q3]?"',
    '',
    'Respond with JSON only. No markdown, no explanation outside the JSON object.',
  ].join('\n');
}

// ---------------------------------------------------------------------------
// Synthesis prompt
// ---------------------------------------------------------------------------

function buildSynthesizerSystemPrompt(): string {
  return [
    'You are synthesizing a final answer to a GAIA benchmark question from answers',
    'to sub-questions.',
    '',
    'Rules:',
    '1. Use ONLY the sub-answers provided — do not hallucinate additional information.',
    '2. The final answer must be CONCISE — match the GAIA expected format (often a',
    '   single word, number, name, or short phrase).',
    '3. Apply the synthesis hint if provided.',
    '4. State your reasoning briefly, then give the final answer.',
    '',
    'Respond with JSON only:',
    '{"finalAnswer": "<concise answer>", "reasoning": "<brief chain of reasoning, ≤300 chars>"}',
  ].join('\n');
}

// ---------------------------------------------------------------------------
// JSON parsing helpers
// ---------------------------------------------------------------------------

interface DecomposerPayload {
  decomposed?: boolean;
  subQuestions?: unknown[];
  synthesisHint?: string;
}

function parseDecomposerResponse(raw: string): DecomposerPayload | null {
  // Strip optional code fences
  const clean = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try {
    return JSON.parse(clean) as DecomposerPayload;
  } catch {
    return null;
  }
}

interface SynthesizerPayload {
  finalAnswer?: string;
  reasoning?: string;
}

function parseSynthesizerResponse(raw: string): SynthesizerPayload | null {
  const clean = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try {
    return JSON.parse(clean) as SynthesizerPayload;
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Atomic fallback
// ---------------------------------------------------------------------------

function atomicFallback(questionText: string): DecomposedQuestion {
  return {
    originalQuestion: questionText,
    subQuestions: [questionText],
    synthesisHint: 'Use directly.',
    decomposed: false,
    cost: 0,
  };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Decomposes a complex question into 1-5 sub-questions in dependency order,
 * OR returns the question as-is if it is already atomic.
 *
 * Uses `claude-haiku-4-5` by default for cheap classification + decomposition
 * (~$0.0003 per question).
 *
 * Heuristics the model uses internally for "should decompose":
 *  - Question contains "and", "then", "after", "if X …"
 *  - Question contains multiple named entities that must each be looked up
 *  - Question asks for a derived/computed answer (X of Y where Y must be found)
 *
 * Graceful degradation: on API errors or malformed JSON, returns the question
 * as atomic so the calling agent can still attempt a direct answer.
 *
 * @param questionText - The full GAIA question text.
 * @param options      - Optional overrides (model, maxSubQuestions, apiKey).
 * @returns            - DecomposedQuestion with subQuestions and synthesisHint.
 */
export async function decomposeQuestion(
  questionText: string,
  options?: DecomposerOptions,
): Promise<DecomposedQuestion> {
  const model = options?.model ?? DEFAULT_DECOMPOSER_MODEL;
  const maxSubQuestions = options?.maxSubQuestions ?? 5;

  let apiKey: string;
  try {
    apiKey = resolveApiKey(options?.apiKey);
  } catch {
    // No API key available — return atomic fallback (graceful degradation)
    return atomicFallback(questionText);
  }

  let text: string;
  let tokensIn: number;
  let tokensOut: number;

  try {
    ({ text, tokensIn, tokensOut } = await callAnthropic(
      buildDecomposerSystemPrompt(maxSubQuestions),
      `Question: ${questionText}`,
      model,
      DECOMPOSER_MAX_TOKENS,
      apiKey,
    ));
  } catch {
    // API error — return atomic fallback so the pipeline can continue
    return atomicFallback(questionText);
  }

  const costUsd =
    (tokensIn / 1_000_000) * HAIKU_INPUT_COST_PER_M +
    (tokensOut / 1_000_000) * HAIKU_OUTPUT_COST_PER_M;

  const parsed = parseDecomposerResponse(text);

  // Validate parsed payload — fall back to atomic on any malformed response
  if (
    parsed === null ||
    !Array.isArray(parsed.subQuestions) ||
    parsed.subQuestions.length === 0
  ) {
    return { ...atomicFallback(questionText), cost: costUsd };
  }

  const subQuestions = parsed.subQuestions
    .slice(0, maxSubQuestions)
    .map((q) => String(q).trim())
    .filter((q) => q.length > 0);

  if (subQuestions.length === 0) {
    return { ...atomicFallback(questionText), cost: costUsd };
  }

  const decomposed = parsed.decomposed !== false && subQuestions.length > 1;
  const synthesisHint = String(parsed.synthesisHint ?? 'Combine sub-answers into a final answer.').trim();

  return {
    originalQuestion: questionText,
    subQuestions,
    synthesisHint,
    decomposed,
    cost: costUsd,
  };
}

/**
 * Given a decomposed question and answers to each sub-question, synthesizes
 * a final concise answer.
 *
 * Uses `claude-sonnet-4-6` by default for higher reasoning quality — the
 * sub-answers contain the hard-won information; synthesis is recombination.
 *
 * Graceful degradation: on API errors or malformed JSON, returns the last
 * sub-answer concatenated with reasoning note.
 *
 * @param decomposed  - The DecomposedQuestion from `decomposeQuestion()`.
 * @param subAnswers  - Array of string answers, one per sub-question.
 *                      Must be the same length as decomposed.subQuestions.
 * @param options     - Optional overrides (model, apiKey).
 * @returns           - SynthesisResult with finalAnswer, reasoning, and cost.
 */
export async function synthesizeFromSubAnswers(
  decomposed: DecomposedQuestion,
  subAnswers: string[],
  options?: SynthesizerOptions,
): Promise<SynthesisResult> {
  const model = options?.model ?? DEFAULT_SYNTHESIZER_MODEL;

  // If not truly decomposed, just return the single sub-answer directly
  if (!decomposed.decomposed || decomposed.subQuestions.length === 1) {
    const singleAnswer = subAnswers[0] ?? '';
    return {
      finalAnswer: singleAnswer,
      reasoning: 'Atomic question — sub-answer is the final answer.',
      cost: 0,
    };
  }

  let apiKey: string;
  try {
    apiKey = resolveApiKey(options?.apiKey);
  } catch {
    const fallback = subAnswers[subAnswers.length - 1] ?? '';
    return {
      finalAnswer: fallback,
      reasoning: 'No API key — returning last sub-answer as fallback.',
      cost: 0,
    };
  }

  // Build the user message: list each sub-question with its answer
  const qaLines = decomposed.subQuestions.map((q, i) => {
    const a = subAnswers[i] ?? '(no answer)';
    return `Sub-question ${i + 1}: ${q}\nSub-answer ${i + 1}: ${a}`;
  });

  const userMessage = [
    `Original question: ${decomposed.originalQuestion}`,
    '',
    'Sub-question answers:',
    qaLines.join('\n\n'),
    '',
    `Synthesis hint: ${decomposed.synthesisHint}`,
  ].join('\n');

  let text: string;
  let tokensIn: number;
  let tokensOut: number;

  try {
    ({ text, tokensIn, tokensOut } = await callAnthropic(
      buildSynthesizerSystemPrompt(),
      userMessage,
      model,
      SYNTHESIZER_MAX_TOKENS,
      apiKey,
    ));
  } catch {
    const fallback = subAnswers[subAnswers.length - 1] ?? '';
    return {
      finalAnswer: fallback,
      reasoning: 'API error during synthesis — returning last sub-answer.',
      cost: 0,
    };
  }

  const costUsd =
    (tokensIn / 1_000_000) * SONNET_INPUT_COST_PER_M +
    (tokensOut / 1_000_000) * SONNET_OUTPUT_COST_PER_M;

  const parsed = parseSynthesizerResponse(text);

  if (!parsed || !parsed.finalAnswer) {
    // Malformed JSON — return last sub-answer as fallback
    const fallback = subAnswers[subAnswers.length - 1] ?? '';
    return {
      finalAnswer: fallback,
      reasoning: `Parse error — raw: ${text.slice(0, 100)}`,
      cost: costUsd,
    };
  }

  return {
    finalAnswer: String(parsed.finalAnswer).trim(),
    reasoning: String(parsed.reasoning ?? '').slice(0, 300),
    cost: costUsd,
  };
}

/**
 * GAIA End-to-End Smoke — ADR-133
 *
 * Wires gaia-agent.ts + gaia-judge.ts into a single end-to-end pipeline:
 *
 *   for each question in SMOKE_FIXTURE:
 *     1. runGaiaAgent(question)  — Haiku agent loop, ≤8 turns
 *     2. judgeAnswer(question, result.finalAnswer)  — exact-match fast-path,
 *        Sonnet LLM-judge only if exact-match misses
 *
 * Reports: pass rate, total cost, mean turn count.
 * Asserts: ≥ 3/5 questions pass (lenient — smoke fixture is not trivial).
 *
 * Cost discipline:
 *   - Agent: claude-haiku-4-5 at $0.25/$1.25 per M tokens
 *   - Judge: claude-sonnet-4-6 at $3/$15 per M tokens (only when needed)
 *   - Expected total for 5 questions × ~2 turns × Haiku + 1-2 Sonnet
 *     judge calls ≈ $0.02
 *
 * Usage:
 *   ANTHROPIC_API_KEY=sk-ant-... npx tsx src/benchmarks/gaia-e2e-smoke.ts
 *
 * Refs: ADR-133, #2156
 */

import * as os from 'node:os';
import * as path from 'node:path';
import {
  SMOKE_FIXTURE,
  GaiaQuestion,
} from './gaia-loader.js';
import {
  runGaiaAgent,
  GaiaAgentResult,
} from './gaia-agent.js';
import {
  judgeAnswer,
  JudgeResult,
  JudgeOptions,
} from './gaia-judge.js';

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Agent model — Haiku only for cost discipline. */
const AGENT_MODEL = 'claude-haiku-4-5';

/** Judge model — Sonnet for semantic judgments (only when exact-match fails). */
const JUDGE_MODEL = 'claude-sonnet-4-6';

/** Minimum pass rate for smoke to succeed. */
const MIN_PASS_RATE = 3 / 5;

// Haiku pricing ($/M tokens)
const HAIKU_IN = 0.25;
const HAIKU_OUT = 1.25;

// Sonnet pricing ($/M tokens)
const SONNET_IN = 3.0;
const SONNET_OUT = 15.0;

// ---------------------------------------------------------------------------
// Result row
// ---------------------------------------------------------------------------

interface E2ERow {
  question: GaiaQuestion;
  agentResult: GaiaAgentResult;
  judgeResult: JudgeResult;
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

async function runE2ESmoke(): Promise<void> {
  const hasKey = !!(process.env.ANTHROPIC_API_KEY?.trim());
  if (!hasKey) {
    console.error(
      'ANTHROPIC_API_KEY is required for the end-to-end smoke.\n' +
      'Set it with: export ANTHROPIC_API_KEY=sk-ant-...',
    );
    process.exit(1);
  }

  const cacheDir = path.join(os.homedir(), '.cache', 'ruflo', 'gaia', 'judgments');
  const judgeOpts: JudgeOptions = { judgeModel: JUDGE_MODEL, cacheDir };

  const questions = SMOKE_FIXTURE;
  const rows: E2ERow[] = [];

  console.log(`\n=== GAIA End-to-End Smoke (${questions.length} questions) ===\n`);
  console.log(
    `Agent: ${AGENT_MODEL}  |  Judge: ${JUDGE_MODEL}\n` +
    `Questions: ${questions.length}  |  Min pass rate: ${(MIN_PASS_RATE * 100).toFixed(0)}%\n`,
  );

  for (const q of questions) {
    process.stdout.write(`[${q.task_id}] "${q.question.slice(0, 60)}..." `);

    // Run agent
    const agentResult = await runGaiaAgent(q, { model: AGENT_MODEL });

    // Judge
    const judgeResult = await judgeAnswer(
      { id: q.task_id, expected: q.final_answer, questionText: q.question },
      agentResult.finalAnswer,
      judgeOpts,
    );

    rows.push({ question: q, agentResult, judgeResult });

    const verdict = judgeResult.passed ? '\x1b[32mPASS\x1b[0m' : '\x1b[31mFAIL\x1b[0m';
    const path_ = judgeResult.scoringPath;
    console.log(
      `${verdict}  (turns=${agentResult.turns}, ` +
      `answer="${agentResult.finalAnswer ?? 'null'}", ` +
      `expected="${q.final_answer}", path=${path_})`,
    );
  }

  // ── Summary ──
  console.log('\n--- Summary ---\n');

  const passed = rows.filter((r) => r.judgeResult.passed).length;
  const total = rows.length;
  const passRate = passed / total;

  let totalAgentCostUsd = 0;
  let totalJudgeCostUsd = 0;
  let totalTurns = 0;

  for (const row of rows) {
    const { agentResult, judgeResult } = row;
    totalTurns += agentResult.turns;
    totalAgentCostUsd +=
      (agentResult.totalInputTokens / 1_000_000) * HAIKU_IN +
      (agentResult.totalOutputTokens / 1_000_000) * HAIKU_OUT;
    totalJudgeCostUsd += judgeResult.judgeCostUsd ?? 0;
  }

  const totalCostUsd = totalAgentCostUsd + totalJudgeCostUsd;
  const meanTurns = totalTurns / total;

  console.log(`Pass rate      : ${passed}/${total}  (${(passRate * 100).toFixed(0)}%)`);
  console.log(`Mean turns     : ${meanTurns.toFixed(1)}`);
  console.log(`Agent cost     : $${totalAgentCostUsd.toFixed(5)}  (Haiku)`);
  console.log(`Judge cost     : $${totalJudgeCostUsd.toFixed(5)}  (Sonnet, only when needed)`);
  console.log(`Total cost     : $${totalCostUsd.toFixed(5)}`);

  // ── Per-row detail ──
  console.log('\n--- Per-question detail ---\n');
  for (const row of rows) {
    const { question, agentResult, judgeResult } = row;
    const verdict = judgeResult.passed ? 'PASS' : 'FAIL';
    console.log(
      `  ${verdict}  ${question.task_id}  turns=${agentResult.turns}  ` +
      `path=${judgeResult.scoringPath}  ` +
      `answer="${agentResult.finalAnswer ?? 'null'}"  ` +
      `expected="${question.final_answer}"`,
    );
    if (judgeResult.judgeReason) {
      console.log(`        reason: ${judgeResult.judgeReason}`);
    }
    if (agentResult.error) {
      console.log(`        error : ${agentResult.error}`);
    }
  }

  // ── Assertion ──
  console.log('');
  if (passRate >= MIN_PASS_RATE) {
    console.log(
      `\x1b[32mSmoke PASSED\x1b[0m — ${passed}/${total} ≥ ${(MIN_PASS_RATE * 100).toFixed(0)}% required.\n`,
    );
  } else {
    console.error(
      `\x1b[31mSmoke FAILED\x1b[0m — ${passed}/${total} < ${(MIN_PASS_RATE * 100).toFixed(0)}% required.\n`,
    );
    process.exit(1);
  }
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

const isMain = process.argv[1] && (
  process.argv[1].endsWith('gaia-e2e-smoke.ts') ||
  process.argv[1].endsWith('gaia-e2e-smoke.js')
);
if (isMain) {
  runE2ESmoke().catch((err) => {
    console.error('E2E smoke failed:', err);
    process.exit(1);
  });
}

export { runE2ESmoke };

/**
 * Smoke tests for extractFinalAnswer + buildUserMessage (iter 53a T2 narrowed).
 *
 * Iter 53a changes vs iter 52 T2:
 *   - Stage 2/3 (prose fallback) REMOVED — extractFinalAnswer is Stage 1 only.
 *   - Commitment prompt no longer has "FINAL_ANSWER: unknown" surrender instruction.
 *   - Reversed-text preprocessor PRESERVED (not the source of regressions).
 *
 * Anti-regression suite (7 cases):
 *   These are the exact failure modes from iter 52 T2 that must not regress.
 *   They test that the extraction logic is stable and correct for the 7 questions
 *   where iter 52 broke but iter 51 was correct.
 *
 * Run (after build):
 *   node dist/benchmarks/gaia-extract.smoke.js
 *
 * Exit 0 on all pass, 1 on any failure.
 *
 * Refs: ADR-133, ADR-135, iter 52 T2, iter 53a, #2156
 */

// ---------------------------------------------------------------------------
// Import the functions under test (via the compiled JS path at runtime).
// We keep a local copy of the types here to avoid circular build deps.
// ---------------------------------------------------------------------------

interface AnthropicResponse {
  id: string;
  model: string;
  stop_reason: string;
  content: Array<{ type: string; text?: string }>;
  usage: { input_tokens: number; output_tokens: number };
}

// Dynamic import so this file can run either as TS source (tsx) or compiled JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let _extractFinalAnswer: (resp: AnthropicResponse) => string | null;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let _buildUserMessage: (question: string) => string;

function makeResp(text: string): AnthropicResponse {
  return {
    id: 'test',
    model: 'test',
    stop_reason: 'end_turn',
    content: [{ type: 'text', text }],
    usage: { input_tokens: 0, output_tokens: 0 },
  };
}

// ---------------------------------------------------------------------------
// Test cases — (label, rawText, expectedExtraction) triples.
// expectedExtraction === null means we expect null (no answer found).
// ---------------------------------------------------------------------------

interface TestCase {
  label: string;
  input: string;
  expected: string | null;
  isUserMsg?: boolean;    // if true, test buildUserMessage instead
}

const CASES: TestCase[] = [
  // ---------------------------------------------------------------------------
  // Stage 1: primary FINAL_ANSWER: pattern (iter 53a: this is the ONLY stage)
  // ---------------------------------------------------------------------------
  {
    label: 'Stage1 basic FINAL_ANSWER:',
    input: 'I searched and found the capital.\nFINAL_ANSWER: Paris',
    expected: 'Paris',
  },
  {
    label: 'Stage1 case-insensitive final_answer:',
    input: 'The result is known.\nfinal_answer: 42',
    expected: '42',
  },
  {
    label: 'Stage1 with leading whitespace',
    input: 'Done.\n   FINAL_ANSWER:   Tokyo   ',
    expected: 'Tokyo',
  },

  // ---------------------------------------------------------------------------
  // Prose-only outputs with no FINAL_ANSWER: tag — must return null (iter 53a).
  // These were previously handled by Stage 2/3 (iter 52 T2).
  // In iter 53a, we rely on the agent committing with the tag instead.
  // ---------------------------------------------------------------------------
  {
    label: 'Prose-only "The answer is X" — null in iter 53a (no Stage 2)',
    input: 'After analysis, the answer is Right.',
    expected: null,
  },
  {
    label: 'Prose-only "Therefore X" — null in iter 53a (no Stage 2)',
    input: 'Based on the clues, therefore the answer is Berlin.',
    expected: null,
  },
  {
    label: 'Prose-only "Answer: X" — null in iter 53a (no Stage 2)',
    input: 'Let me compute this.\nAnswer: 17',
    expected: null,
  },
  {
    label: 'Prose-only all-caps last line — null in iter 53a (no Stage 3)',
    input: 'I computed the value based on many steps.\nRIGHT',
    expected: null,
  },
  {
    label: 'Prose-only numeric last line — null in iter 53a (no Stage 3)',
    input: 'The final calculation gives us:\n346',
    expected: null,
  },
  {
    label: 'Prose-only short-phrase last line — null in iter 53a (no Stage 3)',
    input: 'After extensive research, the result is:\nBerlin, Germany',
    expected: null,
  },

  // Null case: no answer extractable (verbose prose, no commitment)
  {
    label: 'Null case: only tool-call reasoning, no commitment',
    input: 'I tried searching but could not find the specific information requested.',
    expected: null,
  },

  // ---------------------------------------------------------------------------
  // Reversed text pre-processor (buildUserMessage) — PRESERVED in iter 53a
  // ---------------------------------------------------------------------------
  {
    label: 'Reversed text: adds decoded hint',
    input: '.rewsna eht sa "tfel" drow eht fo etisoppo eht etirw ,ecnetnes siht dnatsrednu uoy fI',
    expected: '[NOTE:',
    isUserMsg: true,
  },
  {
    label: 'Normal text: no hint added',
    input: 'What is the capital of France?',
    expected: 'What is the capital of France?',
    isUserMsg: true,
  },

  // ---------------------------------------------------------------------------
  // Anti-regression suite (iter 53a) — 7 cases for iter 52 regressions.
  //
  // These represent the exact regression patterns from iter 52 T2:
  //   a1e91b78: agent surrendered with "unknown" (commitment prompt over-trigger)
  //   935e2cff: agent gave empty answer (Stage 2/3 failed after extraction)
  //   305ac316: agent gave empty answer (Stage 2/3 failed after extraction)
  //   7673d772: agent gave empty answer (Stage 2/3 failed after extraction)
  //   3f57289b: Stage 3 grabbed wrong number from prose
  //   50ec8903: Stage 3 grabbed markdown fragment instead of correct answer
  //   5a0c1adf: Stage 3 grabbed "Claus Peter" instead of correct "Claus"
  //
  // Each test constructs a synthetic response that mimics the failure mode
  // and asserts the correct Stage 1 extraction behavior.
  // ---------------------------------------------------------------------------

  // AR-1: a1e91b78 — agent used to surrender with "FINAL_ANSWER: unknown"
  //   In iter 52, system prompt said to output "FINAL_ANSWER: unknown" if unsure.
  //   With that instruction removed, the agent reasons further and finds the answer.
  //   This test verifies: if the agent DOES output a correct FINAL_ANSWER, we extract it.
  {
    label: 'AR-1 (a1e91b78): Stage1 extracts correct answer — not "unknown"',
    input: 'I found the video. The maximum number of bird species seen together is 3.\nFINAL_ANSWER: 3',
    expected: '3',
  },

  // AR-2: 935e2cff — agent had the answer but Stage 2 produced empty string
  //   In iter 53a, agent should output FINAL_ANSWER: Research correctly.
  {
    label: 'AR-2 (935e2cff): Stage1 extracts "Research" correctly',
    input: 'After reviewing the policy document, R stands for Research.\nFINAL_ANSWER: Research',
    expected: 'Research',
  },

  // AR-3: 305ac316 — agent had "Wojciech" but extraction failed
  {
    label: 'AR-3 (305ac316): Stage1 extracts Polish name correctly',
    input: 'The actor played Wojciech in the movie.\nFINAL_ANSWER: Wojciech',
    expected: 'Wojciech',
  },

  // AR-4: 7673d772 — agent had "inference" but extraction failed
  {
    label: 'AR-4 (7673d772): Stage1 extracts legal term correctly',
    input: 'The fifth section of the federal rule uses the word "inference".\nFINAL_ANSWER: inference',
    expected: 'inference',
  },

  // AR-5: 3f57289b — Stage 3 grabbed wrong number (525 instead of 519)
  //   The regression was caused by Stage 3 picking a wrong number from prose.
  //   With Stage 3 removed, Stage 1 is the only source — agent must use the tag.
  {
    label: 'AR-5 (3f57289b): Stage1 extracts correct at-bat count',
    input: 'Reggie Jackson had 525 at-bats but the player with most walks had 519.\nFINAL_ANSWER: 519',
    expected: '519',
  },

  // AR-6: 50ec8903 — Stage 3 grabbed "- Orange-Green edge →" (markdown fragment)
  //   With Stage 3 removed, only FINAL_ANSWER: tag is extracted.
  {
    label: 'AR-6 (50ec8903): Stage1 extracts Rubik cube colors correctly',
    input: 'After solving the cube configuration, the answer is green, white.\nFINAL_ANSWER: green, white',
    expected: 'green, white',
  },

  // AR-7: 5a0c1adf — Stage 3 grabbed "Claus Peter" (too many words)
  //   With Stage 3 removed, only FINAL_ANSWER: tag is extracted.
  {
    label: 'AR-7 (5a0c1adf): Stage1 extracts first name only, not "Claus Peter"',
    input: 'The conductor\'s full name is Claus Peter Flor, but his first name is Claus.\nFINAL_ANSWER: Claus',
    expected: 'Claus',
  },
];

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
  // Import at runtime to work with both tsx and compiled JS.
  const mod = await import('./gaia-agent.js');
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const m = mod as any;

  _extractFinalAnswer = m._extractFinalAnswerForTest;
  _buildUserMessage = m._buildUserMessageForTest;

  if (typeof _extractFinalAnswer !== 'function' || typeof _buildUserMessage !== 'function') {
    console.error(
      'ERROR: _extractFinalAnswerForTest / _buildUserMessageForTest not exported from gaia-agent.' +
      '\nAdd `export { extractFinalAnswer as _extractFinalAnswerForTest, ' +
      'buildUserMessage as _buildUserMessageForTest }` to gaia-agent.ts.',
    );
    process.exit(1);
  }

  let failures = 0;
  const PASS = '\x1b[32mPASS\x1b[0m';
  const FAIL = '\x1b[31mFAIL\x1b[0m';

  console.log('\n=== gaia-extract smoke (iter 53a T2 narrowed) ===\n');
  console.log('Suite: 12 original + 7 anti-regression = 19 cases\n');

  for (const tc of CASES) {
    let actual: string | null;

    if (tc.isUserMsg) {
      actual = _buildUserMessage(tc.input);
      // For user message tests, check startsWith instead of exact equality.
      const pass = tc.expected === null
        ? actual === null
        : actual !== null && (tc.expected === actual || actual.startsWith(tc.expected));
      if (pass) {
        console.log(`  ${PASS}  ${tc.label}`);
      } else {
        console.log(`  ${FAIL}  ${tc.label}`);
        console.log(`         expected starts-with: ${JSON.stringify(tc.expected)}`);
        console.log(`         actual:               ${JSON.stringify((actual ?? '').slice(0, 80))}`);
        failures++;
      }
    } else {
      actual = _extractFinalAnswer(makeResp(tc.input));
      const pass = tc.expected === null
        ? actual === null
        : actual !== null && actual === tc.expected;
      if (pass) {
        console.log(`  ${PASS}  ${tc.label}`);
      } else {
        console.log(`  ${FAIL}  ${tc.label}`);
        console.log(`         expected: ${JSON.stringify(tc.expected)}`);
        console.log(`         actual:   ${JSON.stringify(actual)}`);
        failures++;
      }
    }
  }

  const total = CASES.length;
  const passed = total - failures;
  console.log(`\n=== ${failures === 0 ? 'ALL PASSED' : `${failures} FAILED`} (${passed}/${total} cases) ===\n`);
  if (failures > 0) process.exit(1);
}

main().catch((err) => {
  console.error('Smoke crashed:', err);
  process.exit(2);
});

/**
 * GAIA Hardness Predictor — Feature Extraction (ADR-136 Track Q)
 *
 * Extracts a 17-dimensional feature vector from a GaiaQuestion for use
 * in the linear hardness classifier.  Deliberately avoids external
 * dependencies (no spacy, no heavy NLP) — all extraction is regex-based
 * with O(1) per question.
 *
 * Feature vector layout (17 dims):
 *   [0]  question length in characters (normalised / 500)
 *   [1]  question length in words      (normalised / 100)
 *   [2]  sentence count                (normalised / 5)
 *   [3]  question word: "what"         (0/1)
 *   [4]  question word: "how"          (0/1)
 *   [5]  question word: "who/when/where" (0/1)
 *   [6]  question word: "calculate/compute/how many/what percentage" (0/1)
 *   [7]  has numeric token             (0/1)
 *   [8]  has year token (4-digit)      (0/1)
 *   [9]  has comparison keyword        (0/1)
 *   [10] estimated named-entity count  (normalised / 5)
 *   [11] digit-token count             (normalised / 5)
 *   [12] multi-hop signal              (0/1)  — bridge/relative clause pattern
 *   [13] requires math                 (0/1)  — "how many/much/percentage/calculate/compute"
 *   [14] temporal chain                (0/1)  — "before/after X happened / since / until"
 *   [15] tool implication count        (normalised / 4)  — PDF/image/video/URL markers
 *   [16] file attachment present       (0/1)
 *
 * All continuous values are min-max normalised to [0, 1] using fixed
 * divisors chosen so typical GAIA questions fall in [0.1, 0.9].
 *
 * Refs: ADR-136, #2156
 */

import type { GaiaQuestion } from '../gaia-loader.js';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface FeatureVector {
  /** Raw 17-element array in [0, 1]. */
  values: number[];
  /** Human-readable labels matching values index. */
  labels: string[];
}

// ---------------------------------------------------------------------------
// Feature labels (in order, matches values array)
// ---------------------------------------------------------------------------

export const FEATURE_LABELS: readonly string[] = [
  'len_chars_norm',
  'len_words_norm',
  'sentence_count_norm',
  'qword_what',
  'qword_how',
  'qword_who_when_where',
  'qword_calc_compute',
  'has_numeric',
  'has_year',
  'has_comparison',
  'entity_count_norm',
  'digit_token_norm',
  'multi_hop_signal',
  'requires_math',
  'temporal_chain',
  'tool_implication_norm',
  'has_file_attachment',
] as const;

// ---------------------------------------------------------------------------
// Regex catalogue (compiled once at module load)
// ---------------------------------------------------------------------------

// Named entity proxy: capitalised word sequences (not at sentence start)
// e.g. "Barack Obama", "New York City", "United States of America"
const RE_ENTITY = /(?<!^|\.\s{1,3})(?:[A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,4})/g;

const RE_YEAR = /\b(1[0-9]{3}|20[0-9]{2})\b/g;
const RE_DIGIT_TOKEN = /\b\d[\d,._]*/g;
const RE_NUMERIC = /\b\d/;
const RE_COMPARISON = /\b(more|fewer|greater|less|compare|versus|vs\.?|differ|increase|decrease|ratio|proportion)\b/i;
const RE_MULTI_HOP = /\b(the\s+\w+\s+that\s+|which\s+was\s+|who\s+was\s+|whose\s+|of\s+the\s+\w+\s+that\s+)/i;
// Requires math: stems without trailing \b to handle "calculate", "multiply", "division", etc.
const RE_MATH = /\b(how\s+many|how\s+much|what\s+percentage|what\s+fraction|what\s+proportion|calculat|comput|multipli|divis|subtract|sum\s+of|total\s+of|average\s+of|product\s+of|express\s+as\s+a\s+decimal)/i;
const RE_TEMPORAL = /\b(before|after|since|until|during|between\s+\d|in\s+the\s+year|by\s+the\s+time|at\s+the\s+time)\b/i;

// Tool implication markers
const RE_TOOL_FILE = /\b(pdf|\.docx|\.xlsx|\.csv|file|attachment|document|spreadsheet)\b/i;
const RE_TOOL_IMAGE = /\b(image|photo|picture|screenshot|figure|diagram|chart)\b/i;
const RE_TOOL_VIDEO = /\b(video|youtube|clip|footage)\b/i;
const RE_TOOL_URL = /https?:\/\//i;

// Question-word detection (first word of question, or full-text for calc/compute)
const RE_QWORD_WHAT = /^(what|which)\b/i;
const RE_QWORD_HOW = /^how\b/i;
const RE_QWORD_WHO_WHEN_WHERE = /^(who|when|where|why|whom)\b/i;
// calc/compute: fires if question contains calculate/compute anywhere (stems, no trailing \b)
const RE_QWORD_CALC = /\b(calculat|comput|how\s+many|what\s+percentage|how\s+much)/i;

// Sentence boundary (rough — period/exclamation/question-mark followed by space+capital)
const RE_SENTENCE = /[.!?]\s+[A-Z]/g;

// ---------------------------------------------------------------------------
// Helper: clamp value to [0, 1]
// ---------------------------------------------------------------------------

function clamp(v: number, max: number): number {
  return Math.min(v / max, 1.0);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract the 17-dimensional feature vector from a GaiaQuestion.
 * All features are in [0, 1].  Never throws.
 */
export function extractFeatures(q: GaiaQuestion): FeatureVector {
  const text = q.question ?? '';

  // ── Syntactic scalars ──────────────────────────────────────────────────
  const lenChars = text.length;
  const words = text.trim().split(/\s+/).filter(Boolean);
  const lenWords = words.length;
  const sentenceMatches = text.match(RE_SENTENCE);
  const sentenceCount = 1 + (sentenceMatches ? sentenceMatches.length : 0);

  // ── Question-word one-hot ─────────────────────────────────────────────
  const firstWord = text.trim();
  const qwWhat = RE_QWORD_WHAT.test(firstWord) ? 1 : 0;
  const qwHow = RE_QWORD_HOW.test(firstWord) ? 1 : 0;
  const qwWhoWhenWhere = RE_QWORD_WHO_WHEN_WHERE.test(firstWord) ? 1 : 0;
  const qwCalcCompute = RE_QWORD_CALC.test(text) ? 1 : 0;

  // ── Lexical booleans ──────────────────────────────────────────────────
  const hasNumeric = RE_NUMERIC.test(text) ? 1 : 0;

  // Count year tokens
  const yearMatches = text.match(RE_YEAR);
  const hasYear = yearMatches && yearMatches.length > 0 ? 1 : 0;

  const hasComparison = RE_COMPARISON.test(text) ? 1 : 0;

  // ── Named entity proxy (capitalised word sequences) ───────────────────
  // Reset lastIndex for global regex
  RE_ENTITY.lastIndex = 0;
  let entityCount = 0;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const m = RE_ENTITY.exec(text);
    if (!m) break;
    entityCount++;
  }

  // ── Digit token count ─────────────────────────────────────────────────
  RE_DIGIT_TOKEN.lastIndex = 0;
  const digitTokenMatches = text.match(RE_DIGIT_TOKEN);
  const digitTokenCount = digitTokenMatches ? digitTokenMatches.length : 0;

  // ── Multi-hop signal ──────────────────────────────────────────────────
  const multiHopSignal = RE_MULTI_HOP.test(text) ? 1 : 0;

  // ── Math requirement ──────────────────────────────────────────────────
  const requiresMath = RE_MATH.test(text) ? 1 : 0;

  // ── Temporal chain ────────────────────────────────────────────────────
  const temporalChain = RE_TEMPORAL.test(text) ? 1 : 0;

  // ── Tool implication (PDF/image/video/URL → file_read/web_browse/image_describe) ──
  let toolImplication = 0;
  if (RE_TOOL_FILE.test(text) || q.file_name) toolImplication++;
  if (RE_TOOL_IMAGE.test(text)) toolImplication++;
  if (RE_TOOL_VIDEO.test(text)) toolImplication++;
  if (RE_TOOL_URL.test(text)) toolImplication++;

  // ── File attachment ───────────────────────────────────────────────────
  const hasFileAttachment = q.file_name && q.file_name.trim() ? 1 : 0;

  // ── Assemble normalised vector ────────────────────────────────────────
  const values: number[] = [
    clamp(lenChars, 500),        // [0]
    clamp(lenWords, 100),        // [1]
    clamp(sentenceCount, 5),     // [2]
    qwWhat,                      // [3]
    qwHow,                       // [4]
    qwWhoWhenWhere,               // [5]
    qwCalcCompute,               // [6]
    hasNumeric,                  // [7]
    hasYear,                     // [8]
    hasComparison,               // [9]
    clamp(entityCount, 5),       // [10]
    clamp(digitTokenCount, 5),   // [11]
    multiHopSignal,              // [12]
    requiresMath,                // [13]
    temporalChain,               // [14]
    clamp(toolImplication, 4),   // [15]
    hasFileAttachment ? 1 : 0,   // [16]
  ];

  return { values, labels: FEATURE_LABELS as string[] };
}

/**
 * Smoke tests for gaia-hardness predictor — ADR-136 Track Q
 *
 * All tests are mock-based (no live API calls, no HF token, $0 cost).
 *
 * Test matrix:
 *   1. Feature extraction: math question fires requiresMath + qword_calc
 *   2. Feature extraction: simple factual question has low complexity signal
 *   3. Feature extraction: question with file attachment fires has_file_attachment
 *   4. Feature extraction: multi-hop question fires multi_hop_signal
 *   5. Cold-start fallback: untrained predictor returns medium with confidence=0.5
 *   6. Train on mock data: predictor becomes trained after ≥ 10 examples
 *   7. Trained predictor: math-heavy question predicts harder than trivial question
 *   8. Export/import: weights round-trip through JSON without loss
 *
 * Refs: ADR-136, #2156
 */

import assert from 'node:assert/strict';
import { extractFeatures, FEATURE_LABELS } from './features.js';
import { HardnessPredictor, type LabeledExample, type DifficultyClass } from './predictor.js';
import type { GaiaQuestion } from '../gaia-loader.js';

// ---------------------------------------------------------------------------
// Fixture helpers
// ---------------------------------------------------------------------------

function makeQuestion(text: string, overrides: Partial<GaiaQuestion> = {}): GaiaQuestion {
  return {
    task_id: 'smoke-test',
    level: 1,
    question: text,
    final_answer: 'X',
    file_name: null,
    file_path: null,
    ...overrides,
  };
}

function labelIndex(label: string): number {
  return FEATURE_LABELS.indexOf(label);
}

// ---------------------------------------------------------------------------
// Test 1: Math question fires expected features
// ---------------------------------------------------------------------------

function testMathQuestionFeatures(): void {
  const q = makeQuestion(
    'What is 15 multiplied by 4? Calculate the exact product.',
  );
  const fv = extractFeatures(q);

  const calcIdx = labelIndex('qword_calc_compute');
  const mathIdx = labelIndex('requires_math');
  const numIdx = labelIndex('has_numeric');

  assert.ok(calcIdx >= 0, 'qword_calc_compute feature not found');
  assert.ok(mathIdx >= 0, 'requires_math feature not found');
  assert.ok(numIdx >= 0, 'has_numeric feature not found');

  assert.equal(fv.values[numIdx], 1, 'has_numeric should be 1 for "15 multiplied by 4"');
  // "Calculate" or "what" triggers calc compute or requires_math
  const eitherMath = fv.values[calcIdx] === 1 || fv.values[mathIdx] === 1;
  assert.ok(eitherMath, 'math question should fire qword_calc_compute or requires_math');

  console.log('  [PASS] Test 1: math question fires expected features');
}

// ---------------------------------------------------------------------------
// Test 2: Simple factual question has low complexity
// ---------------------------------------------------------------------------

function testSimpleFactualQuestion(): void {
  const q = makeQuestion('What is the capital of France?');
  const fv = extractFeatures(q);

  assert.equal(fv.values.length, 17, 'feature vector should have 17 dims');

  const multiHopIdx = labelIndex('multi_hop_signal');
  const toolIdx = labelIndex('tool_implication_norm');
  const fileIdx = labelIndex('has_file_attachment');

  assert.equal(fv.values[multiHopIdx], 0, 'simple question should have no multi-hop signal');
  assert.equal(fv.values[toolIdx], 0, 'simple question should have no tool implication');
  assert.equal(fv.values[fileIdx], 0, 'simple question should have no file attachment');

  // Word count should be normalised well below 1
  const wordNormIdx = labelIndex('len_words_norm');
  assert.ok(fv.values[wordNormIdx] < 0.3, 'short question should have normalised word count < 0.3');

  console.log('  [PASS] Test 2: simple factual question has low complexity signal');
}

// ---------------------------------------------------------------------------
// Test 3: File attachment fires has_file_attachment
// ---------------------------------------------------------------------------

function testFileAttachmentFeature(): void {
  const q = makeQuestion('Analyse the attached PDF document and extract the table.', {
    file_name: 'document.pdf',
    file_path: '/tmp/document.pdf',
  });
  const fv = extractFeatures(q);

  const fileIdx = labelIndex('has_file_attachment');
  const toolIdx = labelIndex('tool_implication_norm');

  assert.equal(fv.values[fileIdx], 1, 'question with file_name should have has_file_attachment=1');
  assert.ok(fv.values[toolIdx] > 0, 'PDF question should have tool_implication > 0');

  console.log('  [PASS] Test 3: file attachment fires has_file_attachment');
}

// ---------------------------------------------------------------------------
// Test 4: Multi-hop question fires multi_hop_signal
// ---------------------------------------------------------------------------

function testMultiHopFeature(): void {
  const q = makeQuestion(
    'Who was the president of the country that won the most gold medals at the Olympics that was held in the city that hosted the 1936 Games?',
  );
  const fv = extractFeatures(q);

  const multiHopIdx = labelIndex('multi_hop_signal');
  assert.equal(fv.values[multiHopIdx], 1, 'multi-hop question should fire multi_hop_signal');

  console.log('  [PASS] Test 4: multi-hop question fires multi_hop_signal');
}

// ---------------------------------------------------------------------------
// Test 5: Cold-start fallback returns medium with confidence=0.5
// ---------------------------------------------------------------------------

function testColdStartFallback(): void {
  const predictor = new HardnessPredictor();
  assert.equal(predictor.isTrained, false, 'new predictor should not be trained');

  const q = makeQuestion('What is the capital of France?');
  const result = predictor.predict(q);

  assert.equal(result.difficulty, 'medium', 'cold-start should return medium');
  assert.equal(result.confidence, 0.5, 'cold-start should return confidence=0.5');
  assert.equal(result.budget.model, 'sonnet', 'medium budget should use sonnet');
  assert.equal(result.budget.maxTurns, 8, 'medium budget should have maxTurns=8');
  assert.equal(result.budget.votingAttempts, 1, 'medium budget should have votingAttempts=1');

  console.log('  [PASS] Test 5: cold-start fallback returns medium with confidence=0.5');
}

// ---------------------------------------------------------------------------
// Test 6: Becomes trained after ≥ 10 labelled examples
// ---------------------------------------------------------------------------

function testBecomesTrainedWith10Examples(): void {
  const predictor = new HardnessPredictor();

  // Generate 15 mock examples (mix of correct/incorrect)
  const examples: LabeledExample[] = [];
  for (let i = 0; i < 15; i++) {
    examples.push({
      question: makeQuestion(`Mock question number ${i} about topic ${i % 3}`),
      wasCorrect: i % 3 !== 0,
      turns: 3 + (i % 6),
    });
  }

  assert.equal(predictor.isTrained, false, 'should not be trained before training');
  predictor.train(examples);
  assert.equal(predictor.isTrained, true, 'should be trained after ≥10 examples');

  console.log('  [PASS] Test 6: predictor becomes trained after ≥ 10 examples');
}

// ---------------------------------------------------------------------------
// Test 7: Trained predictor scores math question harder than trivial question
// ---------------------------------------------------------------------------

function testTrainedRelativeHardness(): void {
  const predictor = new HardnessPredictor({ conservativeMode: false });

  // Train on 20 examples with clear pattern:
  // - Short simple questions → correct (easy)
  // - Long multi-step questions → incorrect (hard)
  const examples: LabeledExample[] = [];
  for (let i = 0; i < 10; i++) {
    examples.push({
      question: makeQuestion(`What is the capital of country ${i}?`),
      wasCorrect: true,
      turns: 2,
    });
    examples.push({
      question: makeQuestion(
        `Calculate the exact percentage difference between ${i * 100} and ${i * 100 + 50}, ` +
        `then multiply by the number of years between 1990 and 2023. ` +
        `Express as a decimal rounded to 3 places.`,
      ),
      wasCorrect: false,
      turns: 12,
    });
  }

  predictor.train(examples);

  const trivialQ = makeQuestion('What is the capital of France?');
  const mathQ = makeQuestion(
    'Calculate the exact percentage difference between 750 and 1250, ' +
    'then multiply by the number of years between 1990 and 2023. ' +
    'Express as a decimal rounded to 3 places.',
  );

  const trivialResult = predictor.predict(trivialQ);
  const mathResult = predictor.predict(mathQ);

  // The difficulty ordering should not put math as easier than trivial.
  const ORDER: Record<DifficultyClass, number> = { easy: 0, medium: 1, hard: 2 };
  assert.ok(
    ORDER[mathResult.difficulty] >= ORDER[trivialResult.difficulty],
    `math question (${mathResult.difficulty}) should be ≥ trivial (${trivialResult.difficulty})`,
  );

  console.log(
    `  [PASS] Test 7: math="${mathResult.difficulty}" (conf=${mathResult.confidence.toFixed(2)}) ≥ trivial="${trivialResult.difficulty}" (conf=${trivialResult.confidence.toFixed(2)})`,
  );
}

// ---------------------------------------------------------------------------
// Test 8: Weights round-trip through JSON export/import
// ---------------------------------------------------------------------------

function testWeightRoundTrip(): void {
  const predictor = new HardnessPredictor();

  const examples: LabeledExample[] = [];
  for (let i = 0; i < 12; i++) {
    examples.push({
      question: makeQuestion(`Question ${i}`),
      wasCorrect: i % 2 === 0,
      turns: 4 + i,
    });
  }
  predictor.train(examples);

  const exported = predictor.export();
  assert.ok(exported !== null, 'exported state should not be null after training');

  const predictor2 = new HardnessPredictor();
  predictor2.import(exported!);
  assert.equal(predictor2.isTrained, true, 'imported predictor should be trained');

  // Both predictors should give the same result for the same question.
  const q = makeQuestion('How many sides does a hexagon have?');
  const r1 = predictor.predict(q);
  const r2 = predictor2.predict(q);
  assert.equal(r1.difficulty, r2.difficulty, 'exported/imported predictor should give same difficulty');
  assert.ok(
    Math.abs(r1.confidence - r2.confidence) < 0.001,
    'exported/imported predictor should give same confidence',
  );

  console.log('  [PASS] Test 8: weights round-trip through export/import without loss');
}

