/**
 * Load GAIA validation questions.
 *
 * - With `smokeOnly: true` (or when HF_TOKEN is unavailable): returns the 5-question
 *   smoke fixture — no network call, no token required.
 * - Otherwise: authenticates to HF, downloads level N questions, caches locally.
 *
 * @throws if HF_TOKEN is missing and smokeOnly is false
 */
export async function loadGaia(options: LoadGaiaOptions = {}): Promise<GaiaQuestion[]> {
  const { level = 1, limit, smokeOnly = false, cacheDir = defaultCacheDir() } = options;

  if (smokeOnly) {
    const filtered = SMOKE_FIXTURE.filter((q) => q.level === level);
    return limit !== undefined ? filtered.slice(0, limit) : filtered;
  }

  const token = resolveHfToken();
  const questions = await downloadGaiaLevel(level, token, cacheDir);
  // Resolve attachment files in parallel (iter-53b: populates file_path on each question)
  await resolveAttachments(questions, token, cacheDir);
  return limit !== undefined ? questions.slice(0, limit) : questions;
}

/**
 * Returns the cache directory path (does not create it).
 */
export function getGaiaCacheDir(override?: string): string {
  return override ?? defaultCacheDir();
}

/**
 * GAIA Tool: file_read — ADR-133-PR2 / iter-53b attachment-tools
 *
 * Reads a file from the local filesystem and returns its contents as a
 * UTF-8 string.  Performs content-type dispatch based on extension +
 * magic bytes:
 *
 * Supported extraction formats (iter-53b):
 *   - Plain text, JSON, CSV, XML, HTML, Markdown, JS/TS, Python, shell, YAML
 *   - XLSX  — openpyxl subprocess (cell values + fill colours)
 *   - PPTX  — python-pptx subprocess (per-slide text)
 *   - PNG / JPEG / GIF / WebP — returns IMAGE_BASE64 marker for vision API
 *   - MP3 / WAV — OpenAI Whisper (tiny model) subprocess transcript
 *   - .py source file — returned as UTF-8 text (no execution)
 *
 * For PDF / DOCX / other binary: descriptive stub (PR-4 deferred).
 *
 * IMAGE_BASE64 marker format:
 *   [IMAGE_BASE64:{"mediaType":"image/png","base64":"...","path":"/abs/path"}]
 *
 * The agent loop in gaia-agent.ts must parse this marker when it appears
 * in a tool_result and convert it to an Anthropic vision content block.
 *
 * Maximum file size: 5 MB.  Paths must be absolute.
 *
 * Refs: ADR-133, #2156, iter-53b
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import { execFileSync } from 'node:child_process';
import { GaiaTool, ToolDefinition } from './types.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MAX_FILE_BYTES = 5 * 1024 * 1024; // 5 MB

// ---------------------------------------------------------------------------
// Content-type detection
// ---------------------------------------------------------------------------

const EXT_TO_TYPE: Record<string, string> = {
  '.txt': 'text/plain',
  '.md': 'text/markdown',
  '.json': 'application/json',
  '.csv': 'text/csv',
  '.xml': 'application/xml',
  '.html': 'text/html',
  '.htm': 'text/html',
  '.yaml': 'application/yaml',
  '.yml': 'application/yaml',
  '.js': 'application/javascript',
  '.ts': 'application/typescript',
  '.py': 'text/x-python',
  '.sh': 'application/x-sh',
  '.bash': 'application/x-sh',
  '.zsh': 'application/x-sh',
  // Handled binary (extraction implemented)
  '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  '.pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.mp3': 'audio/mpeg',
  '.wav': 'audio/wav',
  // Stub binary (deferred)
  '.pdf': 'application/pdf',
  '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  '.mp4': 'video/mp4',
};

/** Binary types for which we have extraction logic in iter-53b. */
const HANDLED_BINARY_TYPES = new Set([
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
  'audio/mpeg',
  'audio/wav',
]);

/** Binary types for which we return a stub (no extraction yet). */
const STUB_BINARY_TYPES = new Set([
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'video/mp4',
]);

function detectContentType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return EXT_TO_TYPE[ext] ?? 'application/octet-stream';
}

/** Quick magic-byte check for common binary signatures. */
function hasBinaryMagic(buf: Buffer): boolean {
  if (buf.length < 4) return false;
  // PDF: %PDF
  if (buf[0] === 0x25 && buf[1] === 0x50 && buf[2] === 0x44 && buf[3] === 0x46) return true;
  // PNG: \x89PNG
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) return true;
  // JPEG: \xff\xd8
  if (buf[0] === 0xff && buf[1] === 0xd8) return true;
  // GIF: GIF8
  if (buf[0] === 0x47 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x38) return true;
  // ZIP (DOCX/XLSX/PPTX): PK\x03\x04
  if (buf[0] === 0x50 && buf[1] === 0x4b && buf[2] === 0x03 && buf[3] === 0x04) return true;
  return false;
}

// ---------------------------------------------------------------------------
// Path validation
// ---------------------------------------------------------------------------

function validatePath(filePath: string): void {
  if (!filePath || typeof filePath !== 'string') {
    throw new Error('file_read: `path` must be a non-empty string.');
  }
  if (!path.isAbsolute(filePath)) {
    throw new Error(
      `file_read: path must be absolute. Got: "${filePath}". ` +
        'Resolve relative GAIA attachment paths against the cache directory before calling file_read.',
    );
  }
  if (filePath.includes('\0')) {
    throw new Error('file_read: path contains null byte — rejected.');
  }
}

// ---------------------------------------------------------------------------
// Python subprocess helper
// ---------------------------------------------------------------------------

/**
 * Run a Python script passed via stdin, with optional positional args.
 * Uses execFileSync with stdin input to avoid shell-escaping issues.
 */
function runPython(script: string, args: string[], timeoutMs: number): string {
  return execFileSync('python3', ['-', ...args], {
    input: script,
    encoding: 'utf-8',
    timeout: timeoutMs,
  }).trim();
}

// ---------------------------------------------------------------------------
// Extraction helpers
// ---------------------------------------------------------------------------

/** Map an ARGB/RGB integer or tuple to a human-readable colour name. */
function colorName(r: number, g: number, b: number): string {
  if (r < 40 && g < 40 && b < 40) return 'black';
  if (r > 215 && g > 215 && b > 215) return 'white';
  if (r > 200 && g < 80 && b < 80) return 'red';
  if (r < 80 && g > 150 && b < 80) return 'green';
  if (r < 80 && g < 80 && b > 200) return 'blue';
  if (r > 200 && g > 200 && b < 80) return 'yellow';
  if (r > 200 && g > 100 && b < 80) return 'orange';
  if (r > 130 && g < 80 && b > 130) return 'purple';
  if (r < 80 && g > 150 && b > 150) return 'teal';
  if (r > 150 && g < 100 && b < 100) return 'dark-red';
  if (r > 150 && g > 150 && b > 150) return 'light-gray';
  if (r < 100 && g < 100 && b < 100) return 'dark-gray';
  return `rgb(${r},${g},${b})`;
}

/**
 * Extract XLSX content via openpyxl Python subprocess.
 * Returns cell values + fill colours as structured text.
 */
function extractXlsx(filePath: string): string {
  const script = [
    'import sys, json',
    'from openpyxl import load_workbook',
    'wb = load_workbook(sys.argv[1])',
    'out = []',
    'for ws in wb.worksheets:',
    "    sheet = {'sheet': ws.title, 'cells': []}",
    '    for row in ws.iter_rows():',
    '        for cell in row:',
    '            fill = cell.fill',
    '            color = None',
    "            if fill and fill.fill_type == 'solid':",
    '                fg = fill.fgColor',
    "                if fg.type == 'rgb' and fg.rgb not in ('00000000', 'FFFFFFFF', '00FFFFFF', 'FF000000', 'FFFFFFFF'):",
    '                    color = fg.rgb',
    '            # Include cell if it has a value OR a color',
    '            if cell.value is None and color is None:',
    '                continue',
    "            entry = {'coord': cell.coordinate, 'value': str(cell.value) if cell.value is not None else ''}",
    '            if color:',
    "                entry['color'] = color",
    "            sheet['cells'].append(entry)",
    '    out.append(sheet)',
    'print(json.dumps(out))',
  ].join('\n');

  let raw: string;
  try {
    raw = runPython(script, [filePath], 30_000);
  } catch (err) {
    throw new Error(`XLSX extraction failed: ${err instanceof Error ? err.message : String(err)}`);
  }

  let parsed: Array<{ sheet: string; cells: Array<{ coord: string; value: string; color?: string }> }>;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return `[XLSX parse error]\nRaw output:\n${raw.slice(0, 2000)}`;
  }

  const lines: string[] = [`[XLSX: ${path.basename(filePath)} — ${parsed.length} sheet(s)]`];
  for (const ws of parsed) {
    lines.push(`\n--- Sheet: ${ws.sheet} ---`);
    for (const cell of ws.cells) {
      const colorPart = cell.color
        ? (() => {
            const hex = cell.color.slice(-6);
            const r = parseInt(hex.slice(0, 2), 16);
            const g = parseInt(hex.slice(2, 4), 16);
            const b = parseInt(hex.slice(4, 6), 16);
            return ` [fill:${colorName(r, g, b)}]`;
          })()
        : '';
      lines.push(`  ${cell.coord}: ${cell.value}${colorPart}`);
    }
  }
  return lines.join('\n');
}

/**
 * Extract PPTX content via python-pptx Python subprocess.
 * Returns per-slide text.
 */
function extractPptx(filePath: string): string {
  const script = [
    'import sys, json',
    'from pptx import Presentation',
    'prs = Presentation(sys.argv[1])',
    'out = []',
    'for i, slide in enumerate(prs.slides):',
    '    texts = []',
    '    for shape in slide.shapes:',
    '        if not shape.has_text_frame:',
    '            continue',
    '        for para in shape.text_frame.paragraphs:',
    "            t = ''.join(run.text for run in para.runs).strip()",
    '            if t:',
    '                texts.append(t)',
    "    out.append({'slide': i + 1, 'texts': texts})",
    'print(json.dumps(out))',
  ].join('\n');

  let raw: string;
  try {
    raw = runPython(script, [filePath], 30_000);
  } catch (err) {
    throw new Error(`PPTX extraction failed: ${err instanceof Error ? err.message : String(err)}`);
  }

  let parsed: Array<{ slide: number; texts: string[] }>;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return `[PPTX parse error]\nRaw output:\n${raw.slice(0, 2000)}`;
  }

  const lines: string[] = [`[PPTX: ${path.basename(filePath)} — ${parsed.length} slide(s)]`];
  for (const s of parsed) {
    lines.push(`\n--- Slide ${s.slide} ---`);
    for (const t of s.texts) lines.push(`  ${t}`);
  }
  return lines.join('\n');
}

/**
 * Encode image as base64 and return the IMAGE_BASE64 marker.
 * The agent loop will convert this to an Anthropic vision content block.
 */
function extractImage(filePath: string, contentType: string): string {
  const buf = fs.readFileSync(filePath);
  const b64 = buf.toString('base64');
  const marker = JSON.stringify({ mediaType: contentType, base64: b64, path: filePath });
  return `[IMAGE_BASE64:${marker}]`;
}

/**
 * Transcribe audio via OpenAI Whisper (tiny model) Python subprocess.
 */
function extractAudio(filePath: string): string {
  const script = [
    'import sys',
    'import whisper',
    'model = whisper.load_model("tiny")',
    'result = model.transcribe(sys.argv[1])',
    "print(result['text'].strip())",
  ].join('\n');

  let transcript: string;
  try {
    transcript = runPython(script, [filePath], 120_000);
  } catch (err) {
    throw new Error(`Audio transcription failed: ${err instanceof Error ? err.message : String(err)}`);
  }

  return `[Audio transcript: ${path.basename(filePath)}]\n\n${transcript}`;
}

// ---------------------------------------------------------------------------
// GaiaTool implementation
// ---------------------------------------------------------------------------

export class FileReadTool implements GaiaTool {
  readonly name = 'file_read';

  readonly definition: ToolDefinition = {
    name: 'file_read',
    description:
      'Read the contents of a local file and return them as text. ' +
      'The path must be absolute. ' +
      'For XLSX files: returns cell values and fill colours. ' +
      'For PPTX files: returns per-slide text. ' +
      'For image files (PNG/JPEG/GIF/WebP): returns an IMAGE_BASE64 marker for vision API use. ' +
      'For audio files (MP3/WAV): returns a Whisper transcript. ' +
      'For Python source files (.py): returns the source code as text. ' +
      `Maximum file size: ${MAX_FILE_BYTES / 1024 / 1024} MB.`,
    input_schema: {
      type: 'object',
      properties: {
        path: {
          type: 'string',
          description: 'Absolute path to the file to read.',
        },
      },
      required: ['path'],
    },
  };

  async execute(input: Record<string, unknown>): Promise<string> {
    const filePath = String(input['path'] ?? '').trim();
    validatePath(filePath);

    let stat: fs.Stats;
    try {
      stat = fs.statSync(filePath);
    } catch (e: unknown) {
      const err = e as NodeJS.ErrnoException;
      if (err.code === 'ENOENT') {
        throw new Error(`file_read: file not found: ${filePath}`);
      }
      throw new Error(`file_read: cannot stat "${filePath}": ${String(e)}`);
    }

    if (!stat.isFile()) {
      throw new Error(`file_read: "${filePath}" is not a regular file.`);
    }

    if (stat.size > MAX_FILE_BYTES) {
      throw new Error(
        `file_read: file too large (${stat.size} bytes > ${MAX_FILE_BYTES} byte limit): ${filePath}`,
      );
    }

    const contentType = detectContentType(filePath);

    // --- HANDLED binary types: extraction implemented ---
    if (HANDLED_BINARY_TYPES.has(contentType)) {
      if (
        contentType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      ) {
        return extractXlsx(filePath);
      }
      if (
        contentType === 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
      ) {
        return extractPptx(filePath);
      }
      if (contentType.startsWith('image/')) {
        return extractImage(filePath, contentType);
      }
      if (contentType.startsWith('audio/')) {
        return extractAudio(filePath);
      }
    }

    // --- STUB binary types: no extraction yet ---
    if (STUB_BINARY_TYPES.has(contentType)) {
      return (
        `[Binary file: ${contentType}]\n` +
        `Path: ${filePath}\n` +
        `Size: ${stat.size} bytes\n` +
        `Note: Text extraction for this format is not yet implemented. ` +
        `Describe what you expect the file to contain based on context.`
      );
    }

    // --- Read full file for magic-byte check ---
    const buf = fs.readFileSync(filePath);
    if (hasBinaryMagic(buf)) {
      return (
        `[Binary file — magic bytes detected]\n` +
        `Path: ${filePath}\n` +
        `Size: ${stat.size} bytes\n` +
        `Detected content-type: ${contentType}`
      );
    }

    // --- Plain text ---
    let text: string;
    try {
      text = buf.toString('utf-8');
    } catch {
      text = buf.toString('latin1');
    }

    const header = `[File: ${path.basename(filePath)} | type: ${contentType} | size: ${stat.size} bytes]\n\n`;
    return header + text;
  }
}

// ---------------------------------------------------------------------------
// Convenience factory
// ---------------------------------------------------------------------------

export function createFileReadTool(): FileReadTool {
  return new FileReadTool();
}

/**
 * GAIA Tool: grounded_query — ADR-135 / iter-33
 *
 * Calls Gemini 2.5 Flash with the google_search grounding tool and returns
 * a synthesised factual answer plus source citations in a single API call.
 *
 * Architectural advantage over web_search (Google Custom Search):
 *   - web_search: raw snippets → agent reads + parses → 2-3 extra turns
 *   - grounded_query: Gemini synthesises an answer + cites sources in 1 call
 *
 * This is Ruflo's cross-provider stack in action:
 *   Gemini grounds (google_search tool) → Sonnet/Haiku reasons → answer
 *
 * Credential resolution (mirrors performance-capability.ts / web_search.ts):
 *   1. process.env.GOOGLE_AI_API_KEY
 *   2. gcloud secrets versions access latest --secret=GOOGLE_AI_API_KEY --project=ruv-dev
 *   3. Throws with clear instructions if neither is available
 *
 * Free tier: 1500 grounded queries/day on Gemini 2.5 Flash.
 * Pricing: ~$0.075/M input tokens, ~$0.30/M output tokens, grounding free <1500/day.
 *
 * Regression note (iter-47): this file was absent from feat/adr-135-integrate-tracks
 * because the grounded-query-gemini branch was not cherry-picked during Track integration.
 * The omission caused a 36-question empty-answer failure in iter-42 (13.2% vs 49.1% baseline).
 *
 * Refs: ADR-133, ADR-135, iter-30 research, iter-33, iter-47, #2156
 * Live-tested 2026-05-27: Mercedes Sosa GAIA L1 question → HTTP 200, 4 sources.
 */

import { GaiaTool, ToolDefinition } from './types.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const GEMINI_GENERATE_CONTENT_URL =
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent';

const DEFAULT_MAX_TOKENS = 1024;
const REQUEST_TIMEOUT_MS = 30_000;

// Gemini 2.5 Flash pricing (USD per 1M tokens, grounding free under 1500/day)
const PRICE_INPUT_PER_M = 0.075;
const PRICE_OUTPUT_PER_M = 0.30;

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface GroundedQueryInput {
  query: string;
  max_tokens?: number;
}

export interface GroundedQuerySource {
  title: string;
  uri: string;
  snippet?: string;
}

export interface GroundedQueryResult {
  /** Synthesised factual answer from Gemini. */
  answer: string;
  /** Web pages Gemini cited when composing its answer. */
  sources: GroundedQuerySource[];
  /** Auto-formulated search queries issued by Gemini. */
  search_queries_used: string[];
  /** True when grounding metadata was returned (sources or search_queries present). */
  grounded: boolean;
  /** Always 'gemini-2.5-flash' for this tool. */
  model: string;
  /** Estimated cost in USD. */
  cost_usd: number;
}

// ---------------------------------------------------------------------------
// Internal Gemini API response shape
// ---------------------------------------------------------------------------

interface GeminiPart {
  text?: string;
}

interface GeminiGroundingChunk {
  web?: { title?: string; uri?: string };
}

interface GeminiGroundingSupport {
  groundingChunkIndices?: number[];
  segment?: { text?: string };
}

interface GeminiGroundingMetadata {
  groundingChunks?: GeminiGroundingChunk[];
  webSearchQueries?: string[];
  groundingSupports?: GeminiGroundingSupport[];
}

interface GeminiCandidate {
  content?: { parts?: GeminiPart[] };
  groundingMetadata?: GeminiGroundingMetadata;
}

interface GeminiUsageMetadata {
  promptTokenCount?: number;
  candidatesTokenCount?: number;
}

interface GeminiGenerateContentResponse {
  candidates?: GeminiCandidate[];
  usageMetadata?: GeminiUsageMetadata;
}

// ---------------------------------------------------------------------------
// Test hooks (same pattern as web_search.ts — injected without module patching)
// ---------------------------------------------------------------------------

export interface GroundedQueryTestHooks {
  /** Override the API key resolver. */
  resolveKey?: () => Promise<string>;
  /** Override the actual HTTP fetch so tests never make live calls. */
  fetchResponse?: (
    query: string,
    maxTokens: number,
    apiKey: string,
  ) => Promise<GeminiGenerateContentResponse>;
}

export const groundedQueryTestHooks: GroundedQueryTestHooks = {};

// ---------------------------------------------------------------------------
// Credential resolution
// ---------------------------------------------------------------------------

/**
 * Resolve a Google AI API key.
 *
 * Order: env var → gcloud secret → throw.
 * Never returns null — throws with actionable guidance if no key is found.
 */
export async function resolveGoogleAIApiKey(): Promise<string> {
  // 1. Environment variable (fastest path, used in test mocks and CI)
  const envKey = process.env['GOOGLE_AI_API_KEY'];
  if (envKey) return envKey;

  // 2. GCP Secrets Manager (matches resolveApiKey pattern in gaia-bench.ts)
  try {
    const { execSync } = await import('node:child_process');
    const key = execSync(
      'gcloud secrets versions access latest --secret=GOOGLE_AI_API_KEY --project=ruv-dev 2>/dev/null',
      { encoding: 'utf-8', timeout: 5_000 },
    ).trim();
    if (key) return key;
  } catch {
    // gcloud not installed, project unreachable, or secret not yet created
  }

  throw new Error(
    'grounded_query: No Google AI API key found.\n' +
      'Set GOOGLE_AI_API_KEY env var, or ensure `gcloud` is authenticated and\n' +
      'the secret GOOGLE_AI_API_KEY exists in GCP project ruv-dev.\n' +
      'Get a free key at: https://aistudio.google.com/apikey',
  );
}

// ---------------------------------------------------------------------------
// Gemini Grounding API call
// ---------------------------------------------------------------------------

/**
 * Call Gemini 2.5 Flash with google_search grounding and parse the response.
 *
 * Exported so smoke tests can exercise the parser without live HTTP (via
 * groundedQueryTestHooks.fetchResponse).
 */
export async function callGeminiGrounded(
  query: string,
  maxTokens: number,
  apiKey: string,
): Promise<GroundedQueryResult> {
  const url = `${GEMINI_GENERATE_CONTENT_URL}?key=${encodeURIComponent(apiKey)}`;

  const requestBody = {
    contents: [{ parts: [{ text: query }] }],
    tools: [{ google_search: {} }],
    generationConfig: { maxOutputTokens: maxTokens },
  };

  let rawBody: GeminiGenerateContentResponse;

  if (groundedQueryTestHooks.fetchResponse) {
    rawBody = await groundedQueryTestHooks.fetchResponse(query, maxTokens, apiKey);
  } else {
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      body: JSON.stringify(requestBody),
    });

    if (!resp.ok) {
      const errText = (await resp.text()).slice(0, 400);
      throw new Error(`grounded_query: Gemini HTTP ${resp.status}: ${errText}`);
    }

    rawBody = (await resp.json()) as GeminiGenerateContentResponse;
  }

  return parseGeminiResponse(rawBody);
}

/**
 * Parse a raw Gemini generateContent response into GroundedQueryResult.
 * Exported for unit testing the parser independently.
 */
export function parseGeminiResponse(body: GeminiGenerateContentResponse): GroundedQueryResult {
  const candidate = body.candidates?.[0];

  // Extract text answer
  const answer = (candidate?.content?.parts ?? [])
    .map((p) => p.text ?? '')
    .join('');

  // Extract grounding metadata
  const meta = candidate?.groundingMetadata;
  const chunks = meta?.groundingChunks ?? [];
  const searchQueries = meta?.webSearchQueries ?? [];

  // Build source list from grounding chunks (deduplicate by URI)
  const seenUris = new Set<string>();
  const sources: GroundedQuerySource[] = [];

  for (const chunk of chunks) {
    const uri = chunk.web?.uri ?? '';
    const title = chunk.web?.title ?? '';
    if (uri && !seenUris.has(uri)) {
      seenUris.add(uri);
      sources.push({ title, uri });
    }
  }

  // Estimate cost
  const inputTokens = body.usageMetadata?.promptTokenCount ?? 0;
  const outputTokens = body.usageMetadata?.candidatesTokenCount ?? 0;
  const costUsd =
    (inputTokens / 1_000_000) * PRICE_INPUT_PER_M +
    (outputTokens / 1_000_000) * PRICE_OUTPUT_PER_M;

  return {
    answer,
    sources,
    search_queries_used: searchQueries,
    grounded: sources.length > 0 || searchQueries.length > 0,
    model: 'gemini-2.5-flash',
    cost_usd: costUsd,
  };
}

// ---------------------------------------------------------------------------
// Format output for Claude (mirrors web_search formatResults pattern)
// ---------------------------------------------------------------------------

function formatResult(result: GroundedQueryResult): string {
  const lines: string[] = [];
  lines.push(`[grounded_query model: ${result.model}]`);

  if (result.answer) {
    lines.push('');
    lines.push(result.answer.trim());
  }

  if (result.sources.length > 0) {
    lines.push('');
    lines.push('Sources:');
    for (let i = 0; i < result.sources.length; i++) {
      const s = result.sources[i];
      lines.push(`[${i + 1}] ${s.title}`);
      lines.push(`    ${s.uri}`);
    }
  }

  if (result.search_queries_used.length > 0) {
    lines.push('');
    lines.push(`Search queries: ${result.search_queries_used.join('; ')}`);
  }

  if (!result.grounded) {
    lines.push('');
    lines.push('[Note: No grounding metadata returned — answer is unverified.]');
  }

  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// GaiaTool implementation
// ---------------------------------------------------------------------------

export class GroundedQueryTool implements GaiaTool {
  readonly name = 'grounded_query';

  readonly definition: ToolDefinition = {
    name: 'grounded_query',
    description:
      'Query Google Search via Gemini 2.5 Flash grounding. ' +
      'Returns a synthesised factual answer with source citations in a single call — ' +
      'more efficient than web_search for factoid questions because Gemini pre-synthesises ' +
      'the answer rather than returning raw snippets. ' +
      'Use this for: factual lookups, "what year did X happen", "how many Y", ' +
      '"who is Z", or any question requiring current web information with a clean answer. ' +
      'Use web_search instead when you need to read a source page in full.',
    input_schema: {
      type: 'object',
      properties: {
        query: {
          type: 'string',
          description: 'Question or factual lookup to ground via Google Search.',
        },
        max_tokens: {
          type: 'number',
          description: `Maximum response length in tokens (default: ${DEFAULT_MAX_TOKENS}).`,
        },
      },
      required: ['query'],
    },
  };

  private readonly apiKey?: string;

  constructor(opts?: { apiKey?: string }) {
    this.apiKey = opts?.apiKey;
  }

  async execute(input: Record<string, unknown>): Promise<string> {
    const query = String(input['query'] ?? '').trim();
    if (!query) {
      throw new Error('grounded_query: `query` input is required and must be non-empty.');
    }

    const maxTokens = Math.min(
      Math.max(64, Number(input['max_tokens'] ?? DEFAULT_MAX_TOKENS)),
      8192,
    );

    const resolveKeyFn = groundedQueryTestHooks.resolveKey ?? resolveGoogleAIApiKey;
    const apiKey = this.apiKey ?? (await resolveKeyFn());

    process.stderr.write(
      `[grounded_query] model=gemini-2.5-flash query=${JSON.stringify(query)}\n`,
    );

    const result = await callGeminiGrounded(query, maxTokens, apiKey);

    process.stderr.write(
      `[grounded_query] grounded=${result.grounded} sources=${result.sources.length} ` +
        `cost_usd=${result.cost_usd.toFixed(6)}\n`,
    );

    return formatResult(result);
  }
}

