function formatStatus(status: unknown): string {
  const statusStr = String(status);
  switch (statusStr) {
    case 'active':
      return output.success(statusStr);
    case 'idle':
      return output.warning(statusStr);
    case 'inactive':
    case 'stopped':
      return output.dim(statusStr);
    case 'error':
      return output.error(statusStr);
    default:
      return statusStr;
  }
}

