const modulesCommand: Command = {
  name: 'modules',
  aliases: ['communities', 'louvain'],
  description: 'Detect module communities using Louvain algorithm',
  options: [
    {
      name: 'output',
      short: 'o',
      description: 'Output file path',
      type: 'string',
    },
    {
      name: 'format',
      short: 'f',
