// Check agentic-flow v3 integration (filesystem-based to avoid slow WASM/DB init)
async function checkAgenticFlow(): Promise<HealthCheck> {
  try {
    // Walk common node_modules paths to find agentic-flow/package.json
    const candidates = [
      join(process.cwd(), 'node_modules', 'agentic-flow', 'package.json'),
      join(process.cwd(), '..', 'node_modules', 'agentic-flow', 'package.json'),
    ];
    let pkgJsonPath: string | null = null;
    for (const p of candidates) {
      if (existsSync(p)) { pkgJsonPath = p; break; }
    }
    if (!pkgJsonPath) {
      return {
        name: 'agentic-flow',
        status: 'warn',
        message: 'Not installed (optional — embeddings/routing will use fallbacks)',
        fix: 'npm install agentic-flow@latest'
      };
    }
    const pkg = JSON.parse(readFileSync(pkgJsonPath, 'utf-8'));
    const version = pkg.version || 'unknown';
    const exports = pkg.exports || {};
    const features = [
      exports['./reasoningbank'] ? 'ReasoningBank' : null,
      exports['./router'] ? 'Router' : null,
      exports['./transport/quic'] ? 'QUIC' : null,
    ].filter(Boolean);
    return {
      name: 'agentic-flow',
      status: 'pass',
      message: `v${version} (${features.join(', ')})`
    };
  } catch {
    return { name: 'agentic-flow', status: 'warn', message: 'Check failed' };
  }
}

// Check encryption-at-rest status (ADR-096 Phase 5)
//
// Reports four facets without disclosing the key itself:
//   1. Gate status — is CLAUDE_FLOW_ENCRYPT_AT_REST set?
//   2. Key resolution — does CLAUDE_FLOW_ENCRYPTION_KEY resolve to a valid
//      32-byte key (env-var path only; keychain/passphrase are deferred)?
//   3. Key fingerprint — first 16 hex chars of sha256(key) so users can
//      sanity-check across machines without ever logging the key bytes.
//   4. High-tier store presence — for sessions/, terminals/, .swarm/memory.db
//      report whether on-disk bytes carry the RFE1 magic (encrypted) or not.
async function checkEncryptionAtRest(): Promise<HealthCheck> {
  if (!isEncryptionEnabled()) {
    return {
      name: 'Encryption at Rest',
      status: 'warn',
      message: 'Off — session/terminal/memory stores are plaintext (mode 0600 only)',
      fix: 'export CLAUDE_FLOW_ENCRYPT_AT_REST=1 && export CLAUDE_FLOW_ENCRYPTION_KEY=<64-char-hex>',
    };
  }

  // Gate is on — try to resolve the key. Fail-closed if missing or malformed.
  const rawKey = process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
  if (!rawKey) {
    return {
      name: 'Encryption at Rest',
      status: 'fail',
      message: 'Gate is on but CLAUDE_FLOW_ENCRYPTION_KEY is unset (fail-closed)',
      fix: 'Generate a key: openssl rand -hex 32 → export CLAUDE_FLOW_ENCRYPTION_KEY=<value>',
    };
  }
  let keyFingerprint: string;
  try {
    const key = decodeKey(rawKey);
    keyFingerprint = createHash('sha256').update(key).digest('hex').slice(0, 16);
  } catch (err) {
    return {
      name: 'Encryption at Rest',
      status: 'fail',
      message: `CLAUDE_FLOW_ENCRYPTION_KEY invalid: ${err instanceof Error ? err.message : String(err)}`,
      fix: 'Provide a 64-char hex or 44-char base64 key (32 bytes)',
    };
  }

  // Check the three high-tier store paths for RFE1 magic
  const cwd = process.cwd();
  const stores: Array<{ label: string; path: string }> = [
    { label: 'sessions/', path: join(cwd, '.claude-flow', 'sessions') },
    { label: 'terminals', path: join(cwd, '.claude-flow', 'terminals', 'store.json') },
    { label: 'memory.db', path: join(cwd, '.swarm', 'memory.db') },
  ];
  const status: string[] = [];
  for (const s of stores) {
    if (!existsSync(s.path)) {
      status.push(`${s.label}=∅`);
      continue;
    }
    try {
      const stat = statSync(s.path);
      if (stat.isDirectory()) {
        // Sessions: probe the first .json file
        const { readdirSync } = await import('fs');
        const files = readdirSync(s.path).filter(f => f.endsWith('.json'));
        if (files.length === 0) { status.push(`${s.label}=∅`); continue; }
        const first = readFileSync(join(s.path, files[0]));
        status.push(`${s.label}=${isEncryptedBlob(first) ? 'enc' : 'plain'}`);
      } else {
        const buf = readFileSync(s.path);
        status.push(`${s.label}=${isEncryptedBlob(buf) ? 'enc' : 'plain'}`);
      }
    } catch {
      status.push(`${s.label}=err`);
    }
  }

  return {
    name: 'Encryption at Rest',
    status: 'pass',
    message: `On — key fp:${keyFingerprint}… (${status.join(' ')})`,
  };
}

// Format health check result
function formatCheck(check: HealthCheck): string {
  const icon = check.status === 'pass' ? output.success('✓') :
               check.status === 'warn' ? output.warning('⚠') :
               output.error('✗');
  return `${icon} ${check.name}: ${check.message}`;
}

// Main doctor command
export const doctorCommand: Command = {
  name: 'doctor',
  description: 'System diagnostics and health checks',
  options: [
    {
      name: 'fix',
      short: 'f',
      // #1791.5 — flag name was misleading: it does NOT auto-apply fixes,
      // it only prints the suggested commands so the user can run them
      // themselves. Make that explicit in the help output.
      description: 'Print suggested fix commands (does not auto-apply — copy/paste them yourself)',
      type: 'boolean',
      default: false
    },
    {
      name: 'install',
      short: 'i',
      description: 'Auto-install missing dependencies (Claude Code CLI)',
      type: 'boolean',
      default: false
    },
    {
      name: 'component',
      short: 'c',
      description: 'Check specific component (version, node, npm, config, daemon, memory, api, git, mcp, claude, disk, typescript, agentic-flow, encryption, federation, metaharness)',
      type: 'string'
    },
    {
      name: 'verbose',
      short: 'v',
      description: 'Verbose output',
      type: 'boolean',
      default: false
    }
  ],
  examples: [
    { command: 'claude-flow doctor', description: 'Run full health check' },
    { command: 'claude-flow doctor --fix', description: 'Print suggested fix commands (does not auto-apply)' },
    { command: 'claude-flow doctor --install', description: 'Auto-install missing dependencies' },
    { command: 'claude-flow doctor -c version', description: 'Check for stale npx cache' },
    { command: 'claude-flow doctor -c claude', description: 'Check Claude Code CLI only' }
  ],
  action: async (ctx: CommandContext): Promise<CommandResult> => {
    const showFix = ctx.flags.fix as boolean;
    const autoInstall = ctx.flags.install as boolean;
    const component = ctx.flags.component as string;
    const verbose = ctx.flags.verbose as boolean;

    output.writeln();
    output.writeln(output.bold('RuFlo Doctor'));
    output.writeln(output.dim('System diagnostics and health check'));
    output.writeln(output.dim('─'.repeat(50)));
    output.writeln();

    const allChecks: (() => Promise<HealthCheck>)[] = [
      checkVersionFreshness,
      checkNodeVersion,
      checkNpmVersion,
      checkClaudeCode,
      checkGit,
      checkGitRepo,
      checkConfigFile,
      checkStaleSettingsNpx, // #2448 — runaway `npx @latest` in statusLine/hooks
      checkDaemonStatus,
      checkMemoryDatabase,
      checkApiKeys,
      checkMcpServers,
      checkAIDefence, // #1807
      checkDiskSpace,
      checkBuildTools,
      checkAgenticFlow,
      checkEncryptionAtRest, // ADR-096 Phase 5
      checkFederationBreaker, // ADR-097 Phase 4
      checkMetaharness, // ADR-150 — MetaHarness upstream package
      checkMetaharnessIntegration, // iter 45 — ruflo-side integration layer
    ];

    const componentMap: Record<string, () => Promise<HealthCheck>> = {
      'version': checkVersionFreshness,
      'freshness': checkVersionFreshness,
      'node': checkNodeVersion,
      'npm': checkNpmVersion,
      'claude': checkClaudeCode,
      'config': checkConfigFile,
      'stale-settings': checkStaleSettingsNpx, // #2448
      'daemon': checkDaemonStatus,
      'memory': checkMemoryDatabase,
      'api': checkApiKeys,
      'git': checkGit,
      'mcp': checkMcpServers,
      'aidefence': checkAIDefence, // #1807
      'disk': checkDiskSpace,
      'typescript': checkBuildTools,
      'agentic-flow': checkAgenticFlow,
      'encryption': checkEncryptionAtRest, // ADR-096 Phase 5
      'federation': checkFederationBreaker, // ADR-097 Phase 4
      'metaharness': checkMetaharness, // ADR-150 — upstream package
      'metaharness-integration': checkMetaharnessIntegration, // iter 45 — ruflo-side
    };

    let checksToRun = allChecks;
    if (component && componentMap[component]) {
      checksToRun = [componentMap[component]];
    }

    const results: HealthCheck[] = [];
    const fixes: string[] = [];

    // OPTIMIZATION: Run all checks in parallel for 3-5x faster execution
    const spinner = output.createSpinner({ text: 'Running health checks in parallel...', spinner: 'dots' });
    spinner.start();

    try {
      // Execute all checks concurrently
      const checkResults = await Promise.allSettled(checksToRun.map(check => check()));
      spinner.stop();

      // Process results in order
      for (const settledResult of checkResults) {
        if (settledResult.status === 'fulfilled') {
          const result = settledResult.value;
          results.push(result);
          output.writeln(formatCheck(result));

          if (result.fix && (result.status === 'fail' || result.status === 'warn')) {
            fixes.push(`${result.name}: ${result.fix}`);
          }
        } else {
          const errorResult: HealthCheck = {
            name: 'Check',
            status: 'fail',
            message: settledResult.reason?.message || 'Unknown error'
          };
          results.push(errorResult);
          output.writeln(formatCheck(errorResult));
        }
      }
    } catch (error) {
      spinner.stop();
      output.writeln(output.error('Failed to run health checks'));
    }

    // Auto-install missing dependencies if requested
    if (autoInstall) {
      const claudeCodeResult = results.find(r => r.name === 'Claude Code CLI');
      if (claudeCodeResult && claudeCodeResult.status !== 'pass') {
        const installed = await installClaudeCode();
        if (installed) {
          // Re-check Claude Code after installation
          const newCheck = await checkClaudeCode();
          const idx = results.findIndex(r => r.name === 'Claude Code CLI');
          if (idx !== -1) {
            results[idx] = newCheck;
            // Update fixes list
            const fixIdx = fixes.findIndex(f => f.startsWith('Claude Code CLI:'));
            if (fixIdx !== -1 && newCheck.status === 'pass') {
              fixes.splice(fixIdx, 1);
            }
          }
          output.writeln(formatCheck(newCheck));
        }
      }
    }

    // Summary
    const passed = results.filter(r => r.status === 'pass').length;
    const warnings = results.filter(r => r.status === 'warn').length;
    const failed = results.filter(r => r.status === 'fail').length;

    output.writeln();
    output.writeln(output.dim('─'.repeat(50)));
    output.writeln();

    const summaryParts = [
      output.success(`${passed} passed`),
      warnings > 0 ? output.warning(`${warnings} warnings`) : null,
      failed > 0 ? output.error(`${failed} failed`) : null
    ].filter(Boolean);

    output.writeln(`Summary: ${summaryParts.join(', ')}`);

    // Show fixes — #1791.5: header makes it explicit these are commands you
    // run yourself, not actions doctor took.
    if (showFix && fixes.length > 0) {
      output.writeln();
      output.writeln(output.bold('Suggested commands (run them yourself):'));
      output.writeln();
      for (const fix of fixes) {
        output.writeln(output.dim(`  ${fix}`));
      }
    } else if (fixes.length > 0 && !showFix) {
      output.writeln();
      output.writeln(output.dim(`Run with --fix to see ${fixes.length} suggested command${fixes.length > 1 ? 's' : ''} (does not auto-apply)`));
    }

    // Overall result
    if (failed > 0) {
      output.writeln();
      output.writeln(output.error('Some checks failed. Please address the issues above.'));
      return { success: false, exitCode: 1, data: { passed, warnings, failed, results } };
    } else if (warnings > 0) {
      output.writeln();
      output.writeln(output.warning('All checks passed with some warnings.'));
      return { success: true, data: { passed, warnings, failed, results } };
    } else {
      output.writeln();
      output.writeln(output.success('All checks passed! System is healthy.'));
      return { success: true, data: { passed, warnings, failed, results } };
    }
  }
};

export default doctorCommand;

/**
 * V3 CLI Eject Command — ADR-150 Phase-2 differentiator.
 *
 * Lifts the calling ruflo/claude-flow project into a renamed standalone
 * harness using `metaharness --from-existing <dir>`. Attribution to
 * ruflo is preserved via the upstream's `<!-- ruflo-attribution-block -->`
 * convention.
 *
 *   npx ruflo eject --name my-harness                  # dry-run plan
 *   npx ruflo eject --name my-harness --confirm        # actually eject
 *   npx ruflo eject --name my-harness --target /abs/out --confirm
 *
 * SAFETY GATES (load-bearing)
 *   1. Dry-run by default. `--confirm` required for any disk write.
 *   2. `--target` MUST resolve OUTSIDE the calling repo root. Default
 *      is `/tmp/ruflo-eject-<ts>-<name>/`. Writing to the calling repo
 *      is refused with exit 2 — protects the user from `cwd: $ruflo`
 *      eject accidents.
 *   3. Refuses existing target dirs (no overwrites).
 *   4. Subprocess + 10-minute hard timeout. No library import; no
 *      static `@metaharness/*` dependency.
 *
 * ADR-150 ARCHITECTURAL CONSTRAINT
 *   When metaharness is unavailable (offline, no network), the command
 *   exits 0 with a structured "feature not available" message. Ruflo
 *   continues to function — rule #3 (graceful degradation).
 *
 * Created with ruv.io
 */

import type { Command, CommandContext, CommandResult } from '../types.js';
import { output } from '../output.js';
import { spawnSync } from 'child_process';
import { existsSync } from 'fs';
import { resolve as resolvePath } from 'path';
import { tmpdir } from 'os';

interface EjectOptions {
  name: string | null;
  target: string | null;
  confirm: boolean;
  format: 'table' | 'json';
}

function parseArgs(args: string[]): EjectOptions {
  const o: EjectOptions = { name: null, target: null, confirm: false, format: 'table' };
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '--name') o.name = args[++i] || null;
    else if (a === '--target') o.target = args[++i] || null;
    else if (a === '--confirm') o.confirm = true;
    else if (a === '--format') o.format = (args[++i] || 'table') as 'table' | 'json';
  }
  return o;
}

function runEject(targetDir: string, name: string): { exitCode: number; stderr: string; degraded?: boolean } {
  const r = spawnSync(
    'npx',
    ['-y', 'metaharness@latest', '--from-existing', process.cwd(), '--name', name, '--target', targetDir, '--yes'],
    {
      stdio: 'inherit',
      env: process.env,
      timeout: 10 * 60 * 1000,
      shell: process.platform === 'win32',
    }
  );
  const stderr = '';  // stdio: inherit — captured by terminal not by us
  if (r.status === null) {
    return { exitCode: 124, stderr: 'subprocess timed out after 10 minutes', degraded: false };
  }
  if (r.error && /ENOENT|spawn/.test(String(r.error.message || ''))) {
    return { exitCode: 127, stderr: 'metaharness binary unavailable', degraded: true };
  }
  return { exitCode: r.status, stderr };
}

export const ejectCommand: Command = {
  name: 'eject',
  description:
    'Lift the calling ruflo project into a renamed standalone harness via metaharness --from-existing (ADR-150 Phase 2). Dry-run by default; --confirm required to write.',
  options: [
    {
      name: 'name',
      description: 'Name for the ejected harness (required)',
      type: 'string' as const,
      required: false,
    },
    {
      name: 'target',
      description: 'Absolute output dir (default: /tmp/ruflo-eject-<ts>-<name>/); refused if inside the calling repo',
      type: 'string' as const,
    },
    {
      name: 'confirm',
      description: 'Actually write the eject. Without this flag the command prints a dry-run plan and exits.',
      type: 'boolean' as const,
      default: false,
    },
    {
      name: 'format',
      description: 'Output format: table | json',
      type: 'string' as const,
      default: 'table',
    },
  ],
  examples: [
    { command: 'npx ruflo eject --name my-harness', description: 'Dry-run; prints what would happen' },
    {
      command: 'npx ruflo eject --name my-harness --confirm',
      description: 'Eject to /tmp/ruflo-eject-<ts>-my-harness/',
    },
    {
      command: 'npx ruflo eject --name my-harness --target /abs/out --confirm',
      description: 'Eject to a specific dir (must be outside the calling repo)',
    },
  ],
  async action(context: CommandContext): Promise<CommandResult> {
    // iter 128 — flags declared on the Command get parsed by the CLI parser
    // and land in context.flags (NOT context.options or context.args).
    // Fall back to parseArgs(context.args) for programmatic invocations
    // where the parser wasn't used (e.g. unit tests).
    const ctx = context as { args?: string[]; flags?: Record<string, unknown> };
    const parsedArgs = parseArgs(ctx.args || []);
    const flagName = ctx.flags?.name as string | undefined;
    const flagTarget = ctx.flags?.target as string | undefined;
    const flagConfirm = ctx.flags?.confirm as boolean | undefined;
    const flagFormat = ctx.flags?.format as 'table' | 'json' | undefined;
    const opts: EjectOptions = {
      name: flagName || parsedArgs.name,
      target: flagTarget || parsedArgs.target,
      confirm: typeof flagConfirm === 'boolean' ? flagConfirm : parsedArgs.confirm,
      format: (flagFormat || parsedArgs.format) as 'table' | 'json',
    };

    if (!opts.name) {
      output.writeln(output.error('eject: --name is required'));
      output.writeln('');
      output.writeln('Example: npx ruflo eject --name my-harness');
      return { success: false, exitCode: 2, data: { error: 'name-required' } };
    }

    // Safety: resolve target, refuse calling-repo paths.
    const repoRoot = resolvePath(process.cwd());
    const target = opts.target
      ? resolvePath(opts.target)
      : resolvePath(tmpdir(), `ruflo-eject-${Date.now()}-${opts.name}`);
    if (target === repoRoot || target.startsWith(repoRoot + '/')) {
      output.writeln(output.error(`eject: refusing to write to ${target}`));
      output.writeln(output.error(`This is inside the calling repo (${repoRoot}). Pick a --target OUTSIDE the repo.`));
      return { success: false, exitCode: 2, data: { error: 'target-inside-repo', target, repoRoot } };
    }
    if (existsSync(target)) {
      output.writeln(output.error(`eject: target ${target} already exists — refusing to overwrite`));
      return { success: false, exitCode: 2, data: { error: 'target-exists', target } };
    }

    const plan = {
      name: opts.name,
      sourceRepo: repoRoot,
      target,
      confirm: opts.confirm,
      command: `npx -y metaharness@latest --from-existing ${repoRoot} --name ${opts.name} --target ${target} --yes`,
    };

    if (!opts.confirm) {
      if (opts.format === 'json') {
        output.writeln(JSON.stringify({ ...plan, dryRun: true }, null, 2));
      } else {
        output.writeln(output.bold('# ruflo eject (dry-run)'));
        output.writeln('');
        output.writeln(`name:       ${plan.name}`);
        output.writeln(`sourceRepo: ${plan.sourceRepo}`);
        output.writeln(`target:     ${plan.target}`);
        output.writeln('');
        output.writeln(output.dim('Would execute:'));
        output.writeln(output.dim(`  ${plan.command}`));
        output.writeln('');
        output.writeln('Re-run with --confirm to actually eject.');
      }
      return { success: true, exitCode: 0, data: { ...plan, dryRun: true } };
    }

    // Actually run.
    output.writeln(output.bold('# ruflo eject — running'));
    output.writeln('');
    output.writeln(`Ejecting ${repoRoot} → ${target} as "${opts.name}"...`);
    output.writeln('');
    const r = runEject(target, opts.name);
    if (r.degraded) {
      output.writeln(output.warning('eject: metaharness binary unavailable — feature degraded'));
      output.writeln(output.dim('(ADR-150 graceful degradation: ruflo runs without it; install with `npm i -D metaharness`.)'));
      return { success: true, exitCode: 0, data: { ...plan, degraded: true, reason: 'metaharness-not-available' } };
    }
    if (r.exitCode !== 0) {
      output.writeln(output.error(`eject: metaharness exited ${r.exitCode}`));
      if (r.stderr) output.writeln(output.dim(r.stderr.slice(0, 400)));
      return { success: false, exitCode: r.exitCode, data: { ...plan, exitCode: r.exitCode } };
    }
    output.writeln('');
    output.writeln(output.bold(`✓ Ejected to ${target}`));
    output.writeln('');
    output.writeln(output.dim('Next steps:'));
    output.writeln(output.dim(`  cd ${target}`));
    output.writeln(output.dim('  npm install'));
    output.writeln(output.dim('  npx harness doctor'));
    return { success: true, exitCode: 0, data: { ...plan, ejected: true } };
  },
};

export default ejectCommand;

