  description: 'GAIA benchmark harness -- measure agent pass-rate on real GAIA questions',
  subcommands: [runCommand],
  examples: [
    {
      command: 'claude-flow gaia-bench run --level 1 --limit 10 --models claude-haiku-4-5 --output json',
