const statusCommand: Command = {
  name: 'status',
  aliases: ['info', 'get'],
  description: 'Get task status and details',
  options: [
    {
      name: 'id',
      description: 'Task ID',
      type: 'string'
    },
    {
      name: 'logs',
      description: 'Include execution logs',
      type: 'boolean',
