/**
 * Configuration Adapter
 * Converts between SystemConfig and V3Config types
 */

import type { SystemConfig } from '@claude-flow/shared';
import type { V3Config } from './types.js';

/**
 * Convert SystemConfig to V3Config (CLI-specific format)
 */
export function systemConfigToV3Config(systemConfig: SystemConfig): V3Config {
  return {
    version: '3.0.0',
    projectRoot: systemConfig.orchestrator?.session?.dataDir || process.cwd(),

    // Agent configuration
    agents: {
      defaultType: 'coder',
      autoSpawn: false, // Not in SystemConfig
      maxConcurrent: systemConfig.orchestrator?.lifecycle?.maxConcurrentAgents ?? 15,
      timeout: systemConfig.orchestrator?.lifecycle?.spawnTimeout ?? 300000,
      providers: [],
    },

    // Swarm configuration
    swarm: {
      topology: normalizeTopology(systemConfig.swarm?.topology),
      maxAgents: systemConfig.swarm?.maxAgents ?? 15,
      autoScale: systemConfig.swarm?.autoScale?.enabled ?? false,
      coordinationStrategy: systemConfig.swarm?.coordination?.consensusRequired ? 'consensus' : 'leader',
      healthCheckInterval: systemConfig.swarm?.coordination?.timeoutMs ?? 10000,
    },

    // Memory configuration
    memory: {
      backend: normalizeMemoryBackend(systemConfig.memory?.type),
      persistPath: systemConfig.memory?.path || './data/memory',
      cacheSize: systemConfig.memory?.maxSize ?? 1000000,
      enableHNSW: systemConfig.memory?.agentdb?.indexType === 'hnsw',
      vectorDimension: systemConfig.memory?.agentdb?.dimensions ?? 384, // Match all-MiniLM-L6-v2 output (#1395 Bug 5)
    },

    // MCP configuration
    mcp: {
      serverHost: systemConfig.mcp?.transport?.host || 'localhost',
      serverPort: systemConfig.mcp?.transport?.port ?? 3000,
      autoStart: false, // Not in SystemConfig
      transportType: systemConfig.mcp?.transport?.type || 'stdio',
      tools: [], // Not in SystemConfig
    },

    // CLI preferences
    cli: {
      colorOutput: true,
      interactive: true,
      verbosity: 'normal',
      outputFormat: 'text',
      progressStyle: 'spinner',
    },

    // Hooks configuration
    hooks: {
      enabled: false,
      autoExecute: false,
      hooks: [],
    },
  };
}

/**
 * Convert V3Config to SystemConfig
 */
export function v3ConfigToSystemConfig(v3Config: V3Config): Partial<SystemConfig> {
  return {
    orchestrator: {
      lifecycle: {
        maxConcurrentAgents: v3Config.agents.maxConcurrent,
        spawnTimeout: v3Config.agents.timeout,
        terminateTimeout: 10000,
        maxSpawnRetries: 3,
      },
      session: {
        dataDir: v3Config.projectRoot,
        persistSessions: true,
        sessionRetentionMs: 3600000,
      },
      health: {
        checkInterval: v3Config.swarm.healthCheckInterval,
        historyLimit: 100,
        degradedThreshold: 1,
        unhealthyThreshold: 2,
      },
    },

    swarm: {
      topology: denormalizeTopology(v3Config.swarm.topology),
      maxAgents: v3Config.swarm.maxAgents,
      autoScale: {
        enabled: v3Config.swarm.autoScale,
        minAgents: 1,
        maxAgents: v3Config.swarm.maxAgents,
        scaleUpThreshold: 0.8,
        scaleDownThreshold: 0.3,
      },
      coordination: {
        consensusRequired: v3Config.swarm.coordinationStrategy === 'consensus',
        timeoutMs: v3Config.swarm.healthCheckInterval,
        retryPolicy: {
          maxRetries: 3,
          backoffMs: 500,
        },
      },
      communication: {
        protocol: 'events',
        batchSize: 10,
        flushIntervalMs: 100,
      },
    },

    memory: {
      type: denormalizeMemoryBackend(v3Config.memory.backend),
      path: v3Config.memory.persistPath,
      maxSize: v3Config.memory.cacheSize,
      agentdb: {
        dimensions: v3Config.memory.vectorDimension,
        indexType: v3Config.memory.enableHNSW ? 'hnsw' : 'flat',
        efConstruction: 200,
        m: 16,
        quantization: 'none',
      },
    },

    mcp: {
      name: 'ruflo',
      version: '3.0.0',
      transport: {
        type: v3Config.mcp.transportType as 'stdio' | 'http' | 'websocket',
        host: v3Config.mcp.serverHost,
        port: v3Config.mcp.serverPort,
      },
      capabilities: {
        tools: true,
        resources: true,
        prompts: true,
        logging: true,
      },
    },
  };
}

/**
 * Normalize topology from SystemConfig to V3Config
 */
function normalizeTopology(
  topology: string | undefined
): 'hierarchical' | 'mesh' | 'ring' | 'star' | 'hybrid' | 'hierarchical-mesh' {
  switch (topology) {
    case 'hierarchical':
    case 'mesh':
    case 'ring':
    case 'star':
    case 'hybrid':
    case 'hierarchical-mesh':
      return topology;
    case 'adaptive':
      return 'hybrid';
    default:
      return 'hierarchical';
  }
}

/**
 * Denormalize topology from V3Config to SystemConfig
 */
function denormalizeTopology(
  topology: 'hierarchical' | 'mesh' | 'ring' | 'star' | 'hybrid' | 'hierarchical-mesh'
): 'hierarchical' | 'mesh' | 'ring' | 'star' | 'adaptive' | 'hierarchical-mesh' {
  if (topology === 'hybrid') {
    return 'hierarchical-mesh';
  }
  return topology;
}

/**
 * Normalize memory backend from SystemConfig to V3Config
 */
function normalizeMemoryBackend(
  backend: string | undefined
): 'memory' | 'sqlite' | 'agentdb' | 'hybrid' {
  switch (backend) {
    case 'memory':
    case 'sqlite':
    case 'agentdb':
    case 'hybrid':
      return backend;
    case 'redis':
      return 'memory'; // Redis maps to memory for CLI purposes
    default:
      return 'hybrid';
  }
}

/**
 * Denormalize memory backend from V3Config to SystemConfig
 */
function denormalizeMemoryBackend(
  backend: 'memory' | 'sqlite' | 'agentdb' | 'hybrid'
): 'memory' | 'sqlite' | 'agentdb' | 'hybrid' | 'redis' {
  return backend;
}

/**
 * Encryption-at-rest vault primitives (ADR-096 Phase 1).
 *
 * Goal: provide deterministic encrypt/decrypt of arbitrary Buffers with a
 * symmetric key, using a magic-byte format so readers of older plaintext
 * stores can detect-then-pass-through during the migration window.
 *
 * Phase 1 deliberately ships only the cipher primitives + the env-var key
 * source. Keychain (keytar) and interactive passphrase resolution land in
 * a follow-up iteration so the blast radius of this commit is limited to
 * a single self-contained module with no native dependencies.
 *
 * Wire format (output of encryptBuffer):
 *
 *   +---------+-----------+----------------+--------+
 *   | magic 4 |   iv 12   |  ciphertext N  | tag 16 |
 *   +---------+-----------+----------------+--------+
 *      "RFE1"   random       AES-256-GCM     GCM
 *
 * The magic distinguishes encrypted blobs from plaintext during the
 * incremental migration: readers call isEncryptedBlob() and either
 * decryptBuffer() or treat the bytes as plaintext, so existing
 * .claude-flow/sessions/*.json files keep working unchanged.
 */

import {
  createCipheriv,
  createDecipheriv,
  randomBytes,
  timingSafeEqual,
} from 'node:crypto';

// ── Constants ────────────────────────────────────────────────────────────────

/** ASCII "RFE1" — Ruflo File Encrypted v1. 4 bytes. */
export const MAGIC = Buffer.from([0x52, 0x46, 0x45, 0x31]); // "RFE1"
const MAGIC_LEN = MAGIC.length; // 4
const IV_LEN = 12;              // GCM-recommended nonce size
const TAG_LEN = 16;             // GCM auth tag
const KEY_LEN = 32;             // AES-256
const ALG = 'aes-256-gcm' as const;
const MIN_BLOB_LEN = MAGIC_LEN + IV_LEN + TAG_LEN; // empty plaintext still has these

const ENV_ENABLE_FLAG = 'CLAUDE_FLOW_ENCRYPT_AT_REST';
const ENV_KEY_VAR = 'CLAUDE_FLOW_ENCRYPTION_KEY';

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * True when at-rest encryption should be applied to writes.
 *
 * Truthy values: "1", "true", "yes", "on" (case-insensitive). Anything else
 * — including unset — keeps the legacy plaintext path. This is the gate
 * that lets the 1865-test baseline keep passing unchanged while users opt
 * into encryption.
 */
export function isEncryptionEnabled(): boolean {
  const v = process.env[ENV_ENABLE_FLAG];
  if (typeof v !== 'string') return false;
  const norm = v.trim().toLowerCase();
  return norm === '1' || norm === 'true' || norm === 'yes' || norm === 'on';
}

/**
 * Resolve a 32-byte encryption key from CLAUDE_FLOW_ENCRYPTION_KEY.
 *
 * Phase 1 supports only the env-var source; keychain and passphrase
 * resolution are deferred to a follow-up iteration (see ADR-096). When
 * encryption is enabled but no key resolves, this throws with a clear
 * message rather than silently falling back to plaintext (fail-closed).
 *
 * Accepted encodings (auto-detected by length):
 *   - 64-char hex (32 bytes)
 *   - 44-char base64 (32 bytes + padding)
 *   - exactly 32 raw bytes (rare; for callers that pre-decode)
 *
 * Anything else is rejected — we'd rather fail loudly than encrypt with a
 * truncated key.
 */
export function getKey(): Buffer {
  const raw = process.env[ENV_KEY_VAR];
  if (!raw) {
    throw new Error(
      `${ENV_ENABLE_FLAG} is set but ${ENV_KEY_VAR} is not. ` +
      `Provide a 32-byte key as 64-char hex or 44-char base64. ` +
      `See ADR-096 for keychain/passphrase support (coming in a follow-up).`,
    );
  }
  return decodeKey(raw);
}

/**
 * Decode a key string. Exposed for testing and for the future passphrase
 * resolver, which will scrypt-derive a Buffer and hand it back through here
 * to share the same length-check.
 */
export function decodeKey(raw: string): Buffer {
  const trimmed = raw.trim();
  // Hex first — strict 64 chars [0-9a-fA-F]
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    return Buffer.from(trimmed, 'hex');
  }
  // Base64 — accept padded 44-char or unpadded 43-char forms
  if (/^[A-Za-z0-9+/]{43}=?$/.test(trimmed)) {
    const buf = Buffer.from(trimmed, 'base64');
    if (buf.length === KEY_LEN) return buf;
  }
  throw new Error(
    `Invalid ${ENV_KEY_VAR}: expected 32-byte key as 64-char hex or 44-char base64`,
  );
}

/**
 * Encrypt a plaintext Buffer with AES-256-GCM. Returns the wire-format
 * blob: magic(4) || iv(12) || ciphertext(N) || tag(16).
 *
 * The IV is freshly randomized per call. Reusing a (key, iv) pair under
 * GCM is catastrophic — every call MUST produce a different IV. Node's
 * randomBytes is csprng-backed so this is automatic; the function takes
 * no IV input deliberately.
 */
export function encryptBuffer(plaintext: Buffer, key: Buffer): Buffer {
  if (!Buffer.isBuffer(plaintext)) {
    throw new TypeError('encryptBuffer: plaintext must be a Buffer');
  }
  if (!Buffer.isBuffer(key) || key.length !== KEY_LEN) {
    throw new TypeError(`encryptBuffer: key must be a ${KEY_LEN}-byte Buffer`);
  }
  const iv = randomBytes(IV_LEN);
  const cipher = createCipheriv(ALG, key, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([MAGIC, iv, ciphertext, tag]);
}

/**
 * Decrypt a wire-format blob. Verifies the magic byte (sanity), parses
 * iv + ciphertext + tag, runs AES-256-GCM decrypt, and lets the GCM
 * auth tag fail loudly on tamper (Node throws "Unsupported state or
 * unable to authenticate data" — we let that propagate).
 *
 * Pre-condition: caller has already determined this is an encrypted
 * blob via isEncryptedBlob(). decryptBuffer throws on bad magic so a
 * mistaken plaintext blob still fails loudly rather than producing
 * garbage.
 */
export function decryptBuffer(blob: Buffer, key: Buffer): Buffer {
  if (!Buffer.isBuffer(blob)) {
    throw new TypeError('decryptBuffer: blob must be a Buffer');
  }
  if (!Buffer.isBuffer(key) || key.length !== KEY_LEN) {
    throw new TypeError(`decryptBuffer: key must be a ${KEY_LEN}-byte Buffer`);
  }
  if (blob.length < MIN_BLOB_LEN) {
    throw new Error(
      `decryptBuffer: blob too short (${blob.length}B; need >= ${MIN_BLOB_LEN}B)`,
    );
  }
  const magic = blob.subarray(0, MAGIC_LEN);
  // timingSafeEqual to avoid an oracle on the magic bytes specifically;
  // not strictly required (the magic isn't secret) but cheap and correct.
  if (!timingSafeEqual(magic, MAGIC)) {
    throw new Error(
      'decryptBuffer: bad magic — blob is not Ruflo-encrypted (RFE1)',
    );
  }
  const iv = blob.subarray(MAGIC_LEN, MAGIC_LEN + IV_LEN);
  const tag = blob.subarray(blob.length - TAG_LEN);
  const ciphertext = blob.subarray(MAGIC_LEN + IV_LEN, blob.length - TAG_LEN);

  const decipher = createDecipheriv(ALG, key, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

/**
 * Magic-byte sniff. True iff the blob starts with the RFE1 magic AND is
 * long enough to be a valid encrypted blob. Used by readers during the
 * incremental migration: legacy plaintext files return false and flow
 * through the existing read path unchanged.
 *
 * Note: this is a heuristic. A plaintext file that happens to start with
 * "RFE1" would be misdetected — we accept that vanishingly small risk
 * because (a) the four bytes 0x52,0x46,0x45,0x31 are an unusual prefix
 * for JSON (`{`, `[`) or SQLite (`SQLite format 3`), and (b) decryption
 * will then fail with a clear error rather than silently corrupt.
 */
export function isEncryptedBlob(blob: Buffer): boolean {
  if (!Buffer.isBuffer(blob)) return false;
  if (blob.length < MIN_BLOB_LEN) return false;
  return timingSafeEqual(blob.subarray(0, MAGIC_LEN), MAGIC);
}

/**
 * Restricted-permission file helpers.
 *
 * audit_1776853149979: session/memory/terminal stores were written with the
 * process umask, which on most macOS/Linux setups leaves them world-readable
 * (mode 0644). They contain conversation snapshots, agent prompts, and
 * terminal command history — anyone else on the host can read them.
 *
 * These helpers write atomically and force mode 0600 (files) / 0700 (dirs).
 * chmod fails silently on Windows, where POSIX modes don't apply — that's
 * fine, the OS-level ACL surface there is different.
 *
 * ADR-096 Phase 2: optional opt-in encryption-at-rest. When the caller
 * passes `encrypt: true` AND the env-gated vault is enabled, payloads are
 * AES-256-GCM-encrypted before hitting disk. Reads use the magic-byte
 * sniff so legacy plaintext files keep working unchanged during the
 * incremental migration.
 */

import { chmodSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import {
  decryptBuffer,
  encryptBuffer,
  getKey,
  isEncryptedBlob,
  isEncryptionEnabled,
} from './encryption/vault.js';

/**
 * Create a directory tree with mode 0700 (owner-only). No-op if exists.
 * Uses recursive: true so missing parents are created with the same mode.
 */
export function mkdirRestricted(path: string): void {
  mkdirSync(path, { recursive: true, mode: 0o700 });
}

/**
 * Options for writeFileRestricted. Object form so we can grow the API
 * without churning every call site.
 */
export interface WriteOptions {
  /** Buffer encoding when `data` is a string. Ignored for Buffer payloads. */
  encoding?: BufferEncoding;
  /**
   * If true AND encryption is globally enabled (CLAUDE_FLOW_ENCRYPT_AT_REST),
   * encrypt the payload with AES-256-GCM before writing. If encryption is
   * NOT enabled, this flag is silently ignored — the legacy plaintext path
   * runs unchanged. Default: false.
   */
  encrypt?: boolean;
}

/**
 * Write a file and tighten its permissions to mode 0600 (owner read/write).
 *
 * Two call signatures, both supported (the legacy positional one keeps
 * existing call sites working without churn):
 *
 *   writeFileRestricted(path, data)                      // plaintext, utf-8
 *   writeFileRestricted(path, data, 'utf-8')             // legacy: encoding only
 *   writeFileRestricted(path, data, { encrypt: true })   // opt-in encryption
 */
export function writeFileRestricted(
  path: string,
  data: string | Buffer,
  optsOrEncoding: BufferEncoding | WriteOptions = 'utf-8',
): void {
  const opts: WriteOptions =
    typeof optsOrEncoding === 'string'
      ? { encoding: optsOrEncoding }
      : optsOrEncoding;
  const encoding = opts.encoding ?? 'utf-8';

  let payload: string | Buffer = data;
  if (opts.encrypt && isEncryptionEnabled()) {
    const plaintext = Buffer.isBuffer(data) ? data : Buffer.from(data, encoding);
    payload = encryptBuffer(plaintext, getKey());
  }

  // For encrypted payloads we always have a Buffer — pass through without an
  // encoding so writeFileSync doesn't try to text-decode it.
  if (Buffer.isBuffer(payload)) {
    writeFileSync(path, payload);
  } else {
    writeFileSync(path, payload, encoding);
  }

  try {
    chmodSync(path, 0o600);
  } catch {
    // Windows / FS without POSIX modes — silently skip.
  }
}

/**
 * Read a file and transparently decrypt if it carries the RFE1 magic.
 *
 * Returns a string when the caller asks for one (default utf-8). Returns
 * a Buffer when `encoding` is null. This matches Node's readFileSync
 * shape so the function is a near-drop-in replacement.
 *
 * Migration semantics:
 *   - If the file IS encrypted, decrypt and return.
 *   - If the file is NOT encrypted, return its raw bytes (string-decoded
 *     under `encoding` if requested).
 *
 * That means a reader can be migrated *first*, before its writer flips
 * `encrypt: true`, without breaking on the legacy plaintext path.
 */
export function readFileMaybeEncrypted(
  path: string,
  encoding?: BufferEncoding,
): string;
export function readFileMaybeEncrypted(
  path: string,
  encoding: null,
): Buffer;
export function readFileMaybeEncrypted(
  path: string,
  encoding: BufferEncoding | null = 'utf-8',
): string | Buffer {
  const raw = readFileSync(path);
  let plain: Buffer;
  if (isEncryptedBlob(raw)) {
    plain = decryptBuffer(raw, getKey());
  } else {
    plain = raw;
  }
  return encoding === null ? plain : plain.toString(encoding);
}

/**
 * V3 CLI Main Entry Point
 * Modernized CLI for RuFlo V3
 *
 * Created with ❤️ by ruv.io
 */

// MUST be the first import — installs console filter for the cosmetic
// "[AgentDB Patch] Controller index not found" warning before any
// agentic-flow / agentdb code can load. ES module imports are evaluated
// in source order, so this file runs its side effects before any other
// import in this module's import graph (including transitive imports of
// agentic-flow via commands/index.js).
import './log-filters.js';

import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import type { Command, CommandContext, CommandResult, V3Config, CLIError } from './types.js';
import { CommandParser, commandParser } from './parser.js';
import { OutputFormatter, output } from './output.js';
import { commands, commandsByCategory, getCommandsByCategory, commandRegistry, getCommand, getCommandAsync, getCommandNames, getLazyCommandNames, hasCommand } from './commands/index.js';
import { suggestCommand } from './suggest.js';
import { runStartupUpdateCheck } from './update/index.js';

// Read version from package.json at runtime
function getPackageVersion(): string {
  try {
    const __filename = fileURLToPath(import.meta.url);
    const __dirname = dirname(__filename);
    // Navigate from dist/src to package root
    const pkgPath = join(__dirname, '..', '..', 'package.json');
    const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'));
    return pkg.version || '3.0.0';
  } catch {
    return '3.0.0';
  }
}

export const VERSION = getPackageVersion();

export interface CLIOptions {
  name?: string;
  description?: string;
  version?: string;
  interactive?: boolean;
}

/**
 * V3 CLI Application
 */
export class CLI {
  private name: string;
  private description: string;
  private version: string;
  private parser: CommandParser;
  private output: OutputFormatter;
  private interactive: boolean;

  constructor(options: CLIOptions = {}) {
    this.name = options.name || 'ruflo';
    this.description = options.description || 'RuFlo V3 - AI Agent Orchestration Platform';
    this.version = options.version || VERSION;
    this.parser = commandParser;
    this.output = output;
    this.interactive = options.interactive ?? process.stdin.isTTY ?? false;

    // Register all core (synchronously loaded) commands with full definitions
    for (const cmd of commands) {
      this.parser.registerCommand(cmd);
    }

    // Register lazy command names so the parser can recognize them during
    // argument resolution without importing their modules. Fix for #1596:
    // prevents `daemon start` from being mis-routed to the `start` command.
    for (const name of getLazyCommandNames()) {
      this.parser.registerLazyCommandName(name);
    }
  }

  /**
   * Run the CLI with given arguments
   */
  async run(args: string[] = process.argv.slice(2)): Promise<void> {
    try {
      // #1791.2 — If the user invoked a lazy command (e.g. `hive-mind task`),
      // pre-load it BEFORE parsing so the parser can build scoped flag
      // aliases for its subcommands. Without this, short flags defined on
      // the lazy command's subcommand options (`-d` for description, etc.)
      // never get into the alias map and silently fall through to global
      // resolution — the user sees `[ERROR] Task description is required`
      // even though they passed `-d "smoke"`.
      for (const arg of args) {
        if (arg.startsWith('-')) continue;
        if (this.parser.isLazyOnly(arg)) {
          const cmd = await getCommandAsync(arg);
          if (cmd) this.parser.registerCommand(cmd);
        }
        break; // only the first non-flag positional is the command name
      }

      // Parse arguments
      const parseResult = this.parser.parse(args);
      const { command: commandPath, flags, positional } = parseResult;

      // Handle global flags
      if (flags.version || flags.V) {
        this.showVersion();
        return;
      }

      if (flags.noColor) {
        this.output.setColorEnabled(false);
      }

      // Set verbosity level based on flags
      if (flags.quiet) {
        this.output.setVerbosity('quiet');
      } else if (flags.verbose) {
        this.output.setVerbosity(process.env.DEBUG ? 'debug' : 'verbose');
      }

      // Verbose mode: show parsed arguments
      if (this.output.isVerbose()) {
        this.output.printDebug(`Command: ${commandPath.join(' ') || '(none)'}`);
        this.output.printDebug(`Positional: [${positional.join(', ')}]`);
        this.output.printDebug(`Flags: ${JSON.stringify(Object.fromEntries(Object.entries(flags).filter(([k]) => k !== '_')))}`);
        this.output.printDebug(`CWD: ${process.cwd()}`);
      }

      // Run startup update check (non-blocking, silent on skip)
      if (!flags.noUpdate && commandPath[0] !== 'update') {
        this.checkForUpdatesOnStartup().catch(() => {/* silent */});
      }

      // Handle lazy-loaded commands that weren't recognized by the parser
      // If commandPath is empty but positional has a command name, check if it's lazy-loadable
      if (commandPath.length === 0 && positional.length > 0 && !positional[0].startsWith('-')) {
        const potentialCommand = positional[0];
        if (hasCommand(potentialCommand)) {
          // This is a lazy-loaded command, treat it as the command
          commandPath.push(potentialCommand);
          positional.shift();
        }
      }

      // No command - show help or suggest correction
      if (commandPath.length === 0 || flags.help || flags.h) {
        if (commandPath.length > 0) {
          // #1791.4 — pass the FULL command path so subcommands like
          // `hive-mind spawn --help` render spawn's own options/examples
          // instead of falling back to the parent's SUBCOMMANDS list.
          await this.showCommandHelp(commandPath);
        } else if (positional.length > 0 && !positional[0].startsWith('-')) {
          // First positional looks like an attempted command - suggest correction
          const attemptedCommand = positional[0];
          this.output.printError(`Unknown command: ${attemptedCommand}`);
          const availableCommands = Array.from(new Set([...commands.map(c => c.name), ...getCommandNames()]));
          const { message } = suggestCommand(attemptedCommand, availableCommands);
          this.output.writeln(this.output.dim(`  ${message}`));
          process.exit(1);
        } else {
          await this.showHelp();
        }
        return;
      }

      // Find and execute command
      const commandName = commandPath[0];
      // First check the parser's registry (for dynamically registered commands)
      // Then fall back to the static registry, then try lazy loading
      let command = this.parser.getCommand(commandName) || getCommand(commandName);

      // If not found in sync registry, try lazy loading
      if (!command && hasCommand(commandName)) {
        command = await getCommandAsync(commandName);
      }

      if (!command) {
        this.output.printError(`Unknown command: ${commandName}`);
        // Smart suggestions - include lazy-loadable commands in suggestions
        const availableCommands = Array.from(new Set([...commands.map(c => c.name), ...getCommandNames()]));
        const { message } = suggestCommand(commandName, availableCommands);
        this.output.writeln(this.output.dim(`  ${message}`));
        process.exit(1);
      }

      // Handle subcommand (supports nested subcommands)
      let targetCommand = command;
      let subcommandArgs = positional;

      // Process command path (e.g., ['hooks', 'worker', 'list'])
      // Note: When parser includes subcommand in commandPath, positional already excludes it
      if (commandPath.length > 1 && command.subcommands) {
        const subcommandName = commandPath[1];
        const subcommand = command.subcommands.find(
          sc => sc.name === subcommandName || sc.aliases?.includes(subcommandName)
        );

        if (subcommand) {
          targetCommand = subcommand;
          // Parser already extracted subcommand from positional, so use as-is
          subcommandArgs = positional;

          // Check for nested subcommand (level 2)
          if (commandPath.length > 2 && subcommand.subcommands) {
            const nestedName = commandPath[2];
            const nestedSubcommand = subcommand.subcommands.find(
              sc => sc.name === nestedName || sc.aliases?.includes(nestedName)
            );
            if (nestedSubcommand) {
              targetCommand = nestedSubcommand;
              // Parser already extracted nested subcommand too
              subcommandArgs = positional;
            }
          }
        }
      } else if (positional.length > 0 && command.subcommands) {
        // Check if first positional is a subcommand
        const subcommandName = positional[0];
        const subcommand = command.subcommands.find(
          sc => sc.name === subcommandName || sc.aliases?.includes(subcommandName)
        );

        if (subcommand) {
          targetCommand = subcommand;
          subcommandArgs = positional.slice(1);

          // Check for nested subcommand (level 2 from positional)
          if (subcommandArgs.length > 0 && subcommand.subcommands) {
            const nestedName = subcommandArgs[0];
            const nestedSubcommand = subcommand.subcommands.find(
              sc => sc.name === nestedName || sc.aliases?.includes(nestedName)
            );
            if (nestedSubcommand) {
              targetCommand = nestedSubcommand;
              subcommandArgs = subcommandArgs.slice(1);
            }
          }
        }
      }

      // Validate flags
      const validationErrors = this.parser.validateFlags(flags, targetCommand);
      if (validationErrors.length > 0) {
        for (const error of validationErrors) {
          this.output.printError(error);
        }
        process.exit(1);
      }

      // Build context
      const ctx: CommandContext = {
        args: subcommandArgs,
        flags,
        config: await this.loadConfig(flags.config as string),
        cwd: process.cwd(),
        interactive: this.interactive && !flags.quiet
      };

      // Execute command
      if (targetCommand.action) {
        if (this.output.isVerbose()) {
          this.output.printDebug(`Executing: ${targetCommand.name}`);
        }

        const startTime = Date.now();
        const result = await targetCommand.action(ctx);

        if (this.output.isVerbose()) {
          this.output.printDebug(`Completed in ${Date.now() - startTime}ms`);
        }

        if (result && !result.success) {
          process.exit(result.exitCode || 1);
        }
      } else {
        // No action - show command help (full path so nested subcommands work)
        await this.showCommandHelp(commandPath);
      }
    } catch (error) {
      // Don't re-handle if this is a process.exit error (from mocked tests)
      const errorMessage = (error as Error).message;
      if (errorMessage && errorMessage.startsWith('process.exit:')) {
        throw error; // Re-throw so tests can capture the exit code
      }
      this.handleError(error as Error);
    }
  }

  /**
   * Show main help
   */
  private async showHelp(): Promise<void> {
    this.output.writeln();
    this.output.writeln(this.output.bold(`${this.name} v${this.version}`));
    this.output.writeln(this.output.dim(this.description));
    this.output.writeln();

    this.output.writeln(this.output.bold('USAGE:'));
    this.output.writeln(`  ${this.name} <command> [subcommand] [options]`);
    this.output.writeln();

    // PERF-03: Load all commands by category (lazy-loaded on demand)
    const categories = await getCommandsByCategory();

    // Primary Commands
    this.output.writeln(this.output.bold('PRIMARY COMMANDS:'));
    for (const cmd of categories.primary) {
      if (cmd.hidden) continue;
      const name = cmd.name.padEnd(12);
      this.output.writeln(`  ${this.output.highlight(name)} ${cmd.description}`);
    }
    this.output.writeln();

    // Advanced Commands
    if (categories.advanced.length > 0) {
      this.output.writeln(this.output.bold('ADVANCED COMMANDS:'));
      for (const cmd of categories.advanced) {
        if (cmd.hidden) continue;
