        patternCategories: { learned: realSona.totalPatterns }, // Simplified
        successRate: totalRoutes > 0
          ? Math.round((realSona.successfulRoutings / totalRoutes) * 100) / 100
          : 0,
        implementation: 'real-sona',
      };
