          operation,
          avgLatencyMs: Math.round((data.totalMs / data.count) * 1000) / 1000,
          opsCount: data.count,
          percentOfTotal: Math.round((data.totalMs / (totalOpMs || 1)) * 10000) / 100,
        }))
