  handler: async (args: Record<string, unknown>): Promise<MCPToolResult> => {
    { const v = validateText(args.input, 'input'); if (!v.valid) return { content: [{ type: 'text', text: JSON.stringify({ error: v.error }) }], isError: true }; }
