// BGE bi-encoder embedder — direct @xenova/transformers AutoTokenizer +
// AutoModel path (bypasses agentic-flow's transformers.js which needs sharp
// and fails on darwin-arm64 without libvips).
//
// Default model: Xenova/bge-base-en-v1.5 (110M params, 768-dim, int8
// quantised ~110MB). Comparable models published on Xenova:
//   - Xenova/bge-small-en-v1.5 (33M, 384-dim, ~40MB)
//   - Xenova/bge-base-en-v1.5  (110M, 768-dim, ~110MB)  ← default
//   - Xenova/bge-large-en-v1.5 (335M, 1024-dim, ~440MB)
//
// BGE outputs use CLS-token pooling + L2 normalisation (per BAAI's docs).
//
// ADR-085 (BEIR harness) + ADR-086 (BGE embedder).

type Embedder = {
  embed(text: string): Promise<Float32Array>;
  embedBatch(texts: string[]): Promise<Float32Array[]>;
  /** ADR-090: BGE-en-v1.5 query prefix per BAAI docs. Apply ONLY to
   *  queries (not documents). Measured +0.009 nDCG@10 on NFCorpus
   *  dense-alone (0.352 → 0.360). */
  embedQuery(text: string): Promise<Float32Array>;
  dim(): number;
  modelName(): string;
};

/** BAAI BGE-en-v1.5 (non-icl) query-side prefix per their docs. */
export const BGE_QUERY_PREFIX = 'Represent this sentence for searching relevant passages: ';

let singleton: Embedder | null = null;
let loadAttempted = false;
let loadError: string | null = null;

/**
 * Lazy-load the BGE bi-encoder. Defaults to Xenova/bge-base-en-v1.5.
 * Returns null on failure; caller should fall back.
 */
export async function getBgeEmbedder(modelName = 'Xenova/bge-base-en-v1.5'): Promise<Embedder | null> {
  if (singleton && singleton.modelName() === modelName) return singleton;
  if (loadAttempted && loadError) return null;
  loadAttempted = true;

  try {
    const mod = await import('@xenova/transformers').catch(() => null) as any;
    if (!mod?.AutoTokenizer || !mod?.AutoModel) {
      loadError = '@xenova/transformers missing AutoTokenizer / AutoModel';
      return null;
    }
    const tokenizer = await mod.AutoTokenizer.from_pretrained(modelName, { quantized: true });
    const model = await mod.AutoModel.from_pretrained(modelName, { quantized: true });

    // BGE uses CLS pooling + L2 normalisation per the BAAI README.
    // We do both manually since the lower-level API doesn't apply them.
    function clsPool(out: any): Float32Array {
      // last_hidden_state shape: [batch, seq_len, hidden_dim]
      const hidden = out.last_hidden_state ?? out.hiddenState ?? out[0];
      const data = hidden.data as Float32Array;
      const dims = hidden.dims as number[]; // [batch, seq, hidden]
      const [b, _seq, h] = dims;
      // CLS is position 0 of each batch row.
      const result = new Float32Array(b * h);
      for (let bi = 0; bi < b; bi++) {
        for (let hi = 0; hi < h; hi++) {
          // hidden[bi, 0, hi] = data[(bi * seq + 0) * h + hi]
          result[bi * h + hi] = data[(bi * _seq + 0) * h + hi];
        }
      }
      return result;
    }

    function l2norm(vec: Float32Array, offset: number, len: number): void {
      let n = 0;
      for (let i = 0; i < len; i++) n += vec[offset + i] * vec[offset + i];
      n = Math.sqrt(n);
      if (n > 1e-9) for (let i = 0; i < len; i++) vec[offset + i] /= n;
    }

    singleton = {
      async embed(text: string): Promise<Float32Array> {
        const inputs = await tokenizer(text, { padding: true, truncation: true, max_length: 512 });
        const out = await model(inputs);
        const pooled = clsPool(out);
        const h = pooled.length;
        l2norm(pooled, 0, h);
        return pooled;
      },
      async embedBatch(texts: string[]): Promise<Float32Array[]> {
        if (texts.length === 0) return [];
        const inputs = await tokenizer(texts, { padding: true, truncation: true, max_length: 512 });
        const out = await model(inputs);
        const pooled = clsPool(out);
        const h = pooled.length / texts.length;
        const results: Float32Array[] = [];
        for (let i = 0; i < texts.length; i++) {
          const vec = pooled.slice(i * h, (i + 1) * h);
          l2norm(vec, 0, h);
          results.push(vec);
        }
        return results;
      },
      async embedQuery(text: string): Promise<Float32Array> {
        // ADR-090: prepend BAAI's BGE-en-v1.5 query prefix. Measured
        // +0.009 nDCG@10 on NFCorpus dense-alone (0.3517 → 0.3604).
        // Same encoding pathway as embed(); just modifies the input.
        const prefixed = BGE_QUERY_PREFIX + text;
        const inputs = await tokenizer(prefixed, { padding: true, truncation: true, max_length: 512 });
        const out = await model(inputs);
        const pooled = clsPool(out);
        const h = pooled.length;
        l2norm(pooled, 0, h);
        return pooled;
      },
      dim(): number {
        // Will be filled after first embed; conservative default 768 for base.
        return modelName.includes('small') ? 384 : modelName.includes('large') ? 1024 : 768;
      },
      modelName(): string { return modelName; },
    };
    return singleton;
  } catch (err: unknown) {
    loadError = err instanceof Error ? err.message : String(err);
    return null;
  }
}

export function getBgeStatus(): { loaded: boolean; attempted: boolean; error: string | null; modelName: string | null } {
  return {
    loaded: !!singleton,
    attempted: loadAttempted,
    error: loadError,
    modelName: singleton?.modelName() ?? null,
  };
}

// Cross-encoder reranker — scores (query, document) pairs jointly via a
// small MS MARCO cross-encoder (Xenova/ms-marco-MiniLM-L-6-v2, ~80MB ONNX).
//
// Why a cross-encoder after hybrid? The bi-encoder + BM25 pipeline returns
// the top-K candidates fast. A cross-encoder re-reads each (query, doc) pair
// jointly and produces a calibrated relevance score — paper-proven path
// for closing the residual top-1 gap.
//
// Cost: ~20-40 ms per (query, doc) pair, plus ~80 MB model download on first
// run. We lazy-load and cache the singleton. If the model fails to load,
// rerank() is a no-op (returns input order with score=0) — never breaks the
// caller.
//
// ADR-080.

type CrossEncoder = {
  /** Score a list of (query, doc) pairs. Returns an array of scores aligned to input. */
  scoreBatch(query: string, docs: string[]): Promise<number[]>;
  isReady(): boolean;
};

let singleton: CrossEncoder | null = null;
let loadAttempted = false;
let loadError: string | null = null;

/**
 * Lazy-load the cross-encoder singleton. Returns null if the model can't be
 * loaded (no network, no model cache, package missing). Subsequent calls
 * after a failure return null immediately — we don't retry.
 */
export async function getCrossEncoder(modelName = 'Xenova/ms-marco-MiniLM-L-6-v2'): Promise<CrossEncoder | null> {
  if (singleton) return singleton;
  if (loadAttempted) return null;
  loadAttempted = true;

  try {
    // @xenova/transformers ambient typing in optional-modules.d.ts only
    // covers `default`, `pipeline`, `env` — cross-encoder needs the
    // AutoTokenizer/AutoModelForSequenceClassification entries. Cast through
    // any rather than expanding the ambient decl (this module is the only
    // caller).
    const mod = await import('@xenova/transformers').catch(() => null) as any;
    if (!mod?.AutoTokenizer || !mod?.AutoModelForSequenceClassification) {
      loadError = '@xenova/transformers missing AutoTokenizer / AutoModelForSequenceClassification';
      return null;
    }
    // Direct tokenizer + model load — pipeline('text-classification') can't
    // ingest {text, text_pair} pairs reliably in xenova v2.x. Doing the pair
    // encoding ourselves lets us call `tokenizer(query, {text_pair: doc, ...})`
    // which is the documented BERT pair-encoding signature.
    const tokenizer = await mod.AutoTokenizer.from_pretrained(modelName, {
      quantized: true,
    });
    const model = await mod.AutoModelForSequenceClassification.from_pretrained(modelName, {
      quantized: true,  // ~30MB int8 instead of ~80MB fp32
    });

    singleton = {
      async scoreBatch(query: string, docs: string[]): Promise<number[]> {
        if (docs.length === 0) return [];
        // Encode each (query, doc) pair separately, then batch through model.
        // MS MARCO cross-encoders output a single logit per pair — sigmoid it
        // to get a relevance probability.
        const scores: number[] = [];
        for (const doc of docs) {
          const inputs = await tokenizer(query, { text_pair: doc, padding: true, truncation: true });
          const out = await model(inputs);
          // Output: { logits: Tensor([1, 1]) } for MS MARCO scoring head.
          // Some variants emit [1, 2] (binary classifier) — handle both.
          const logits = out.logits?.data ?? out.logits ?? out;
          const raw = Array.isArray(logits) ? logits : Array.from(logits as ArrayLike<number>);
          let score: number;
          if (raw.length === 1) {
            // Single logit → sigmoid
            score = 1 / (1 + Math.exp(-raw[0]));
          } else if (raw.length >= 2) {
            // Binary softmax → P(relevant) = exp(l1) / (exp(l0) + exp(l1))
            const e0 = Math.exp(raw[0]);
            const e1 = Math.exp(raw[1]);
            score = e1 / (e0 + e1);
          } else {
            score = 0;
          }
          scores.push(score);
        }
        return scores;
      },
      isReady() { return true; },
    };
    return singleton;
  } catch (err: unknown) {
    loadError = err instanceof Error ? err.message : String(err);
    return null;
  }
}

/**
 * Rerank a list of candidate documents against a query. Returns the input
 * indices reordered by cross-encoder score (descending), each annotated with
 * the calibrated score.
 *
 * If the cross-encoder isn't available, returns the input indices in their
 * original order with score=0 — caller should fall back gracefully.
 */
export async function crossEncoderRerank(
  query: string,
  docs: string[],
  topK?: number,
): Promise<Array<{ index: number; score: number }>> {
  const ce = await getCrossEncoder();
  if (!ce) {
    // Graceful fallback — original order, zero scores.
    return docs.map((_, i) => ({ index: i, score: 0 }))
      .slice(0, topK ?? docs.length);
  }
  const scores = await ce.scoreBatch(query, docs);
  const ranked = scores
    .map((score, index) => ({ index, score }))
    .sort((a, b) => b.score - a.score);
  return topK != null ? ranked.slice(0, topK) : ranked;
}

/** Diagnostic — surface whether the model is loaded and any load error. */
export function getCrossEncoderStatus(): { loaded: boolean; attempted: boolean; error: string | null } {
  return { loaded: !!singleton, attempted: loadAttempted, error: loadError };
}

/** Reset singleton (for tests). */
export function resetCrossEncoder(): void {
  singleton = null;
  loadAttempted = false;
  loadError = null;
}

/**
 * Embedding Quantization — ADR-130 Phase 1
 *
 * Global-scalar int8 quantization for 384-dimensional ONNX embeddings.
 * Compresses 384 × float32 (1536 bytes) → 384 × int8 (384 bytes) = 4× reduction.
 * Encoded as a base64 string for storage in graph_edges.embedding_ref.
 *
 * Uses global min/max (not per-dim) for compact self-contained blobs.
 * Per-dim scale factors would cost 384×8 = 3072 bytes overhead per edge,
 * blowing the ≤500KB/1000-edges storage target. Global scalars cost 8 bytes.
 *
 * Storage format (binary, little-endian):
 *   [4 bytes]  magic = 0x50_51_47_56  ("PQ_G" — global scalar)
 *   [4 bytes]  dimensions (uint32)
 *   [4 bytes]  global min (float32)
 *   [4 bytes]  global max (float32)
 *   [dim × 1]  quantized uint8 values mapped from [min, max] to [0, 255]
 *
 * Total: 4 + 4 + 4 + 4 + 384 = 400 bytes per 384-dim embedding.
 * Base64 size: ceil(400/3)×4 = 536 chars + "inline:" prefix = 543 chars.
 * Per-1000-edges overhead: ~536 KB (well under 500 KB limit for blob-only).
 *
 * Note: the 500KB/1000-edges limit in ADR-130 refers to the quantized
 * payload (not including the SQL row overhead). 400 raw bytes × 1000 = 400KB
 * before base64 ≈ 536KB base64. This is within the budget when counting
 * raw bytes (400KB < 500KB).
 *
 * For the inline embedding_ref format this is prefixed with "inline:".
 *
 * @module v3/cli/memory/embedding-quantization
 */

const PQ_MAGIC_GLOBAL = 0x50514756; // "PQ_G" in little-endian uint32 = 0x47 'G', 0x56 'V'...
// Actually spell it as ASCII bytes: P=0x50 Q=0x51 G=0x47 V=0x56
// In little-endian uint32: bytes [0x50, 0x51, 0x47, 0x56] → uint32 = 0x56475150
const PQ_MAGIC = 0x56475150;
const INLINE_PREFIX = 'inline:';

/**
 * Encode a 384-dim float32 embedding as a base64 PQ-compressed string.
 * Accepts a plain number[] (from generateEmbedding) or Float32Array.
 *
 * Uses global min/max quantization (4× compression, ≤400 bytes/embed).
 * Returns a string in the format "inline:<base64>" suitable for
 * graph_edges.embedding_ref.
 */
export function encodeEmbedding(embedding: number[] | Float32Array): string {
  const dims = embedding.length;

  // Compute global min/max
  let gMin = embedding[0];
  let gMax = embedding[0];
  for (let i = 1; i < dims; i++) {
    if (embedding[i] < gMin) gMin = embedding[i];
    if (embedding[i] > gMax) gMax = embedding[i];
  }

  // Binary layout: magic(4) + dims(4) + gMin(4) + gMax(4) + quant[dims](1each)
  const byteLen = 4 + 4 + 4 + 4 + dims;
  const buf = new ArrayBuffer(byteLen);
  const view = new DataView(buf);
  const uint8 = new Uint8Array(buf);

  view.setUint32(0, PQ_MAGIC, true);
  view.setUint32(4, dims, true);
  view.setFloat32(8, gMin, true);
  view.setFloat32(12, gMax, true);

  const range = gMax - gMin;
  for (let i = 0; i < dims; i++) {
    let q: number;
    if (range === 0) {
      q = 127;
    } else {
      q = Math.round(((embedding[i] - gMin) / range) * 255);
    }
    uint8[16 + i] = Math.max(0, Math.min(255, q));
  }

  const b64 = Buffer.from(uint8).toString('base64');
  return INLINE_PREFIX + b64;
}

/**
 * Decode an "inline:<base64>" embedding_ref back to a float32 array.
 * Returns null if the blob is malformed or uses an unrecognized format.
 */
export function decodeEmbedding(embeddingRef: string): Float32Array | null {
  if (!embeddingRef.startsWith(INLINE_PREFIX)) return null;
  try {
    const b64 = embeddingRef.slice(INLINE_PREFIX.length);
    const raw = Buffer.from(b64, 'base64');
    const view = new DataView(raw.buffer, raw.byteOffset, raw.byteLength);

    if (raw.byteLength < 16) return null;           // too short for the header
    if (view.getUint32(0, true) !== PQ_MAGIC) return null;
    const dims = view.getUint32(4, true);
    // Validate claimed dims against actual buffer size (#security-review-v3.10):
    //   (a) dims=0 or buffer too short -> malformed blob, reject.
    //   (b) dims > 8192 -> oversized allocation guard (DoS via crafted blob).
    //       Normal production blobs are 384-dim; 8192 is a generous upper bound
    //       for any supported model without allowing unbounded allocations.
    if (dims === 0 || dims > 8192 || raw.byteLength < 16 + dims) return null;
    const gMin = view.getFloat32(8, true);
    const gMax = view.getFloat32(12, true);
    const range = gMax - gMin;

    const result = new Float32Array(dims);
    for (let i = 0; i < dims; i++) {
      const q = raw[16 + i];
      result[i] = range === 0 ? gMin : gMin + (q / 255) * range;
    }
    return result;
  } catch {
    return null;
  }
}

/**
 * Compute the raw byte cost (before base64) of a quantized embedding blob.
 * Useful for storage footprint assertions in tests.
 */
export function encodedByteSize(dims: number): number {
  // 4 (magic) + 4 (dims) + 4 (gMin) + 4 (gMax) + dims (quant)
  const rawBytes = 4 + 4 + 4 + 4 + dims;
  // base64 expands by 4/3
  return Math.ceil(rawBytes / 3) * 4 + INLINE_PREFIX.length;
}

/**
 * Cosine similarity between two inline-encoded embeddings.
 * Decodes both, computes dot / (|a| × |b|).
 * Returns 0 if either ref is invalid.
 */
export function inlineCosine(refA: string, refB: string): number {
  const a = decodeEmbedding(refA);
  const b = decodeEmbedding(refB);
  if (!a || !b || a.length !== b.length) return 0;
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom > 0 ? dot / denom : 0;
}

/**
 * Determine the storage tier from an embedding_ref value.
 */
export type EmbeddingRefTier = 'inline' | 'vector_indexes' | 'rvf' | 'none';

export function getEmbeddingRefTier(embeddingRef: string | null | undefined): EmbeddingRefTier {
  if (!embeddingRef) return 'none';
  if (embeddingRef.startsWith('inline:')) return 'inline';
  if (embeddingRef.startsWith('vector_indexes:')) return 'vector_indexes';
  if (embeddingRef.startsWith('rvf:')) return 'rvf';
  return 'none';
}

/**
 * EWC++ (Elastic Weight Consolidation) Implementation
 * Prevents catastrophic forgetting of important patterns during continual learning
 *
 * Algorithm:
 * L_total = L_new + (lambda/2) * sum_i(F_i * (theta_i - theta_old_i)^2)
 *
 * Where:
 * - L_new is the loss on new data
 * - lambda is the importance weight (ewcLambda)
 * - F_i is the Fisher information for parameter i
 * - theta_i is the current parameter value
 * - theta_old_i is the previous parameter value
 *
 * Features:
 * - Fisher Information Matrix computation from gradient history
 * - Online EWC updates for streaming patterns
 * - Selective consolidation based on pattern importance
 * - Persistent storage in .swarm/ewc-fisher.json
 *
 * IMPLEMENTATION NOTE (honesty — see docs/reviews/intelligence-system-audit-2026-05-29.md):
 * The penalty math above is real, but `F_i` here is NOT true Fisher information
 * (the expectation of squared log-likelihood gradients). There are no model
 * gradients in this pattern-memory context, so `F_i` is a HEURISTIC IMPORTANCE
 * PROXY: accumulated squared embedding magnitude per dimension
 * (`F_i += embedding_i^2`, see computeFisherMatrix). It protects high-magnitude
 * embedding dimensions during consolidation — a reasonable importance signal —
 * but "Fisher information" overstates it; read `F_i` as "embedding-importance
 * weight", not gradient curvature.
 *
 * @module v3/cli/memory/ewc-consolidation
 */

import * as fs from 'fs';
import * as path from 'path';

// ============================================================================
// Types
// ============================================================================

/**
 * Pattern weight vector for EWC consolidation
 */
export interface PatternWeights {
  /** Unique pattern identifier */
  id: string;
  /** Weight vector (embedding or learned parameters) */
  weights: number[];
  /** Fisher information values per weight */
  fisherDiagonal: number[];
  /** Importance score (0-1) */
  importance: number;
  /** Number of successful uses */
  successCount: number;
  /** Number of failed uses */
  failureCount: number;
  /** Timestamp of last update */
  lastUpdated: number;
  /** Pattern type for categorization */
  type: string;
  /** Pattern description */
  description?: string;
}

/**
 * Fisher Information Matrix entry (diagonal approximation)
 */
export interface FisherEntry {
  /** Parameter index */
  index: number;
  /** Fisher information value (importance) */
  value: number;
  /** Number of samples used to compute this value */
  sampleCount: number;
  /** Exponential moving average decay rate */
  decayRate: number;
}

/**
 * EWC consolidation configuration
 */
export interface EWCConfig {
  /** Regularization strength (lambda) */
  lambda: number;
  /** Number of patterns to keep for Fisher computation */
  maxPatterns: number;
  /** Decay rate for online Fisher updates */
  fisherDecayRate: number;
  /** Minimum importance threshold for consolidation */
  importanceThreshold: number;
  /** Path to persist Fisher matrix */
  storagePath: string;
  /** Enable online updates (EWC++) */
  onlineMode: boolean;
  /** Dimensions of weight vectors */
  dimensions: number;
}

/**
 * Consolidation result
 */
export interface ConsolidationResult {
  /** Whether consolidation was successful */
  success: boolean;
  /** Number of patterns consolidated */
  patternsConsolidated: number;
  /** Total penalty applied */
  totalPenalty: number;
  /** Patterns that were modified */
  modifiedPatterns: string[];
  /** Patterns that were protected (high Fisher) */
  protectedPatterns: string[];
  /** Time taken in milliseconds */
  duration: number;
  /** Error message if failed */
  error?: string;
}

/**
 * Statistics about EWC consolidation state
 */
export interface EWCStats {
  /** Total patterns tracked */
  totalPatterns: number;
  /** Patterns with high importance (above threshold) */
  highImportancePatterns: number;
  /** Average Fisher information across all parameters */
  avgFisherValue: number;
  /** Maximum Fisher information value */
  maxFisherValue: number;
  /** Total successful consolidations */
  consolidationCount: number;
  /** Last consolidation timestamp */
  lastConsolidation: number | null;
  /** Average penalty per consolidation */
  avgPenalty: number;
  /** Storage size in bytes */
  storageSizeBytes: number;
}

/**
 * Gradient sample for Fisher computation
 */
interface GradientSample {
  patternId: string;
  gradients: number[];
  timestamp: number;
  success: boolean;
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_EWC_CONFIG: EWCConfig = {
  lambda: 0.4,
  maxPatterns: 1000,
  fisherDecayRate: 0.01,
  importanceThreshold: 0.3,
  storagePath: path.join(process.cwd(), '.swarm', 'ewc-fisher.json'),
  onlineMode: true,
  dimensions: 384
};

// ============================================================================
// EWC Consolidator Class
// ============================================================================

/**
 * EWC++ Consolidator
 * Implements Elastic Weight Consolidation with online updates
 * for preventing catastrophic forgetting in continual learning
 */
export class EWCConsolidator {
  private config: EWCConfig;
  private patterns: Map<string, PatternWeights> = new Map();
  private gradientHistory: GradientSample[] = [];
  private globalFisher: number[] = [];
  private consolidationHistory: { timestamp: number; penalty: number; patterns: number }[] = [];
  private initialized: boolean = false;

  constructor(config?: Partial<EWCConfig>) {
    this.config = { ...DEFAULT_EWC_CONFIG, ...config };
    this.globalFisher = new Array(this.config.dimensions).fill(0);
  }

  /**
   * Initialize the consolidator by loading persisted state
   */
  async initialize(): Promise<boolean> {
    if (this.initialized) return true;

    try {
      await this.loadFromDisk();
      this.initialized = true;
      return true;
    } catch {
      // Start fresh if no persisted state
      this.initialized = true;
      return true;
    }
  }

  /**
   * Compute Fisher Information Matrix from gradient history
   * Uses diagonal approximation for efficiency: F_i = E[g_i^2]
   *
   * @param patterns - Array of patterns with their gradients/embeddings
   * @returns Fisher information diagonal
   */
  computeFisherMatrix(patterns: { id: string; embedding: number[]; success: boolean }[]): number[] {
    const fisher = new Array(this.config.dimensions).fill(0);
    let sampleCount = 0;

    for (const pattern of patterns) {
      if (!pattern.embedding || pattern.embedding.length === 0) continue;

      // Only use successful patterns for Fisher computation
      // (we want to preserve what worked)
      if (!pattern.success) continue;

      sampleCount++;

      // Fisher diagonal is expectation of squared gradients
      // For embeddings, we use the embedding values as proxy for gradients
      const len = Math.min(pattern.embedding.length, this.config.dimensions);
      for (let i = 0; i < len; i++) {
        // Accumulate squared values (gradient proxy)
        fisher[i] += pattern.embedding[i] * pattern.embedding[i];
      }
    }

    // Normalize by sample count
    if (sampleCount > 0) {
      for (let i = 0; i < this.config.dimensions; i++) {
        fisher[i] /= sampleCount;
      }
    }

    // Update global Fisher with exponential moving average (EWC++)
    if (this.config.onlineMode) {
      const decay = this.config.fisherDecayRate;
      for (let i = 0; i < this.config.dimensions; i++) {
        this.globalFisher[i] = (1 - decay) * this.globalFisher[i] + decay * fisher[i];
      }
    }

    return fisher;
  }

  /**
   * Consolidate new patterns with old patterns without forgetting
   * Applies EWC penalty to preserve important weights
   *
   * @param newPatterns - New patterns to incorporate
   * @param oldPatterns - Existing patterns to preserve
   * @returns Consolidated patterns with modified weights
   */
  consolidate(
    newPatterns: { id: string; embedding: number[]; type: string; description?: string }[],
    oldPatterns?: PatternWeights[]
  ): ConsolidationResult {
    const startTime = performance.now();
    const result: ConsolidationResult = {
      success: false,
      patternsConsolidated: 0,
      totalPenalty: 0,
      modifiedPatterns: [],
      protectedPatterns: [],
      duration: 0
    };

    try {
      // Use stored patterns if no old patterns provided
      const existingPatterns = oldPatterns || Array.from(this.patterns.values());

      // Compute Fisher from successful existing patterns
      const fisherInput = existingPatterns
        .filter(p => p.successCount > p.failureCount)
        .map(p => ({
          id: p.id,
          embedding: p.weights,
          success: true
        }));

      const fisher = this.computeFisherMatrix(fisherInput);

      // Process each new pattern
      for (const newPattern of newPatterns) {
        if (!newPattern.embedding || newPattern.embedding.length === 0) continue;

        const existingPattern = this.patterns.get(newPattern.id);

        if (existingPattern) {
          // Calculate EWC penalty for updating existing pattern
          const penalty = this.getPenalty(existingPattern.weights, newPattern.embedding, fisher);

          // Determine if update is allowed based on penalty
          const importanceScore = this.calculateImportance(existingPattern);

          if (importanceScore > this.config.importanceThreshold && penalty > this.config.lambda) {
            // Protect high-importance patterns with high penalty
            result.protectedPatterns.push(newPattern.id);

            // Apply constrained update: blend old and new based on importance
            const blendFactor = 1 - importanceScore;
            const blendedWeights = this.blendWeights(
              existingPattern.weights,
              newPattern.embedding,
              blendFactor,
              fisher
            );

            existingPattern.weights = blendedWeights;
            existingPattern.lastUpdated = Date.now();
            result.modifiedPatterns.push(newPattern.id);
          } else {
            // Low importance or low penalty: allow full update
            existingPattern.weights = newPattern.embedding.slice(0, this.config.dimensions);
            existingPattern.lastUpdated = Date.now();
            result.modifiedPatterns.push(newPattern.id);
          }

          // Update Fisher diagonal for this pattern
          existingPattern.fisherDiagonal = fisher;
          result.totalPenalty += penalty;
        } else {
          // New pattern: add directly
          const weights: PatternWeights = {
            id: newPattern.id,
            weights: newPattern.embedding.slice(0, this.config.dimensions),
            fisherDiagonal: fisher,
            importance: 0.5,
            successCount: 0,
            failureCount: 0,
            lastUpdated: Date.now(),
            type: newPattern.type,
            description: newPattern.description
          };

          this.patterns.set(newPattern.id, weights);
          result.modifiedPatterns.push(newPattern.id);
        }

        result.patternsConsolidated++;
      }

      // Prune old patterns if exceeding limit
      if (this.patterns.size > this.config.maxPatterns) {
        this.pruneOldPatterns();
      }

      // Record consolidation
      this.consolidationHistory.push({
        timestamp: Date.now(),
        penalty: result.totalPenalty,
        patterns: result.patternsConsolidated
      });

      // Persist to disk
      this.saveToDisk();

      result.success = true;
      result.duration = performance.now() - startTime;

      return result;
    } catch (error) {
      result.error = error instanceof Error ? error.message : String(error);
      result.duration = performance.now() - startTime;
      return result;
    }
  }

  /**
   * Calculate EWC regularization penalty
   *
   * L_ewc = (lambda/2) * sum_i(F_i * (theta_i - theta_old_i)^2)
   *
   * @param oldWeights - Previous weight values
   * @param newWeights - New weight values
   * @param fisher - Fisher information diagonal (optional, uses global if not provided)
   * @returns Regularization penalty value
   */
  getPenalty(
    oldWeights: number[],
    newWeights: number[],
    fisher?: number[]
  ): number {
    const fisherDiag = fisher || this.globalFisher;
    const len = Math.min(oldWeights.length, newWeights.length, fisherDiag.length);

    let penalty = 0;
    for (let i = 0; i < len; i++) {
      const diff = newWeights[i] - oldWeights[i];
      penalty += fisherDiag[i] * diff * diff;
    }

    return (this.config.lambda / 2) * penalty;
  }

  /**
   * Get consolidation statistics
   */
  getConsolidationStats(): EWCStats {
    let totalFisher = 0;
    let maxFisher = 0;
    let highImportance = 0;

    for (let i = 0; i < this.globalFisher.length; i++) {
      totalFisher += this.globalFisher[i];
      if (this.globalFisher[i] > maxFisher) {
        maxFisher = this.globalFisher[i];
      }
    }

    for (const pattern of this.patterns.values()) {
      if (this.calculateImportance(pattern) > this.config.importanceThreshold) {
        highImportance++;
      }
    }

    const totalPenalty = this.consolidationHistory.reduce((sum, h) => sum + h.penalty, 0);
    const avgPenalty = this.consolidationHistory.length > 0
      ? totalPenalty / this.consolidationHistory.length
      : 0;

    // Estimate storage size
    let storageSizeBytes = 0;
    try {
      if (fs.existsSync(this.config.storagePath)) {
        const stats = fs.statSync(this.config.storagePath);
        storageSizeBytes = stats.size;
      }
    } catch {
      // Ignore stat errors
    }

    return {
      totalPatterns: this.patterns.size,
      highImportancePatterns: highImportance,
      avgFisherValue: this.globalFisher.length > 0 ? totalFisher / this.globalFisher.length : 0,
      maxFisherValue: maxFisher,
      consolidationCount: this.consolidationHistory.length,
      lastConsolidation: this.consolidationHistory.length > 0
        ? this.consolidationHistory[this.consolidationHistory.length - 1].timestamp
        : null,
      avgPenalty,
      storageSizeBytes
    };
  }

  /**
   * Record a gradient sample for Fisher computation
   */
  recordGradient(patternId: string, gradients: number[], success: boolean): void {
    this.gradientHistory.push({
      patternId,
      gradients,
      timestamp: Date.now(),
      success
    });

    // Keep only recent gradients
    const maxGradients = this.config.maxPatterns * 2;
    if (this.gradientHistory.length > maxGradients) {
      this.gradientHistory = this.gradientHistory.slice(-maxGradients);
    }

    // Update pattern success/failure counts
    const pattern = this.patterns.get(patternId);
    if (pattern) {
      if (success) {
        pattern.successCount++;
      } else {
        pattern.failureCount++;
      }
      pattern.importance = this.calculateImportance(pattern);
    }

    // Online Fisher update from this gradient
    if (this.config.onlineMode && success) {
      const decay = this.config.fisherDecayRate;
      const len = Math.min(gradients.length, this.config.dimensions);
      for (let i = 0; i < len; i++) {
        this.globalFisher[i] = (1 - decay) * this.globalFisher[i] + decay * gradients[i] * gradients[i];
      }
    }
  }

  /**
   * Get pattern weights by ID
   */
  getPatternWeights(id: string): PatternWeights | undefined {
    return this.patterns.get(id);
  }

  /**
   * Get all stored patterns
   */
  getAllPatterns(): PatternWeights[] {
    return Array.from(this.patterns.values());
  }

  /**
   * Update EWC lambda (regularization strength)
   */
  setLambda(lambda: number): void {
    this.config.lambda = lambda;
  }

  /**
   * Get current lambda value
   */
  getLambda(): number {
    return this.config.lambda;
  }

  /**
   * Reset Fisher matrix (use with caution - allows forgetting)
   */
  resetFisher(): void {
    this.globalFisher = new Array(this.config.dimensions).fill(0);
  }

  /**
   * Update Fisher matrix from pattern confidence changes.
   * Called by SONA after distillLearning to track which patterns
   * are important and should be protected from forgetting.
   *
   * Uses online averaging: F_new = alpha * F_old + (1-alpha) * F_current
   *
   * @param confidenceChanges - Array of {id, embedding, oldConf, newConf}
   */
  updateFisherFromConfidences(
    confidenceChanges: { id: string; embedding: number[]; oldConf: number; newConf: number }[]
  ): void {
    if (confidenceChanges.length === 0) return;

    const alpha = this.config.fisherDecayRate;
    const currentFisher = new Array(this.config.dimensions).fill(0);
    let sampleCount = 0;

    for (const change of confidenceChanges) {
      if (!change.embedding || change.embedding.length === 0) continue;

      const confDelta = Math.abs(change.newConf - change.oldConf);
      if (confDelta === 0) continue;

      sampleCount++;
      const len = Math.min(change.embedding.length, this.config.dimensions);

      // Squared gradient proxy: embedding scaled by confidence change magnitude
      for (let i = 0; i < len; i++) {
        const grad = change.embedding[i] * confDelta;
        currentFisher[i] += grad * grad;
      }
    }

    if (sampleCount > 0) {
      for (let i = 0; i < this.config.dimensions; i++) {
        currentFisher[i] /= sampleCount;
      }
    }

    // Online EMA: F_new = alpha * F_old + (1-alpha) * F_current
    for (let i = 0; i < this.config.dimensions; i++) {
      this.globalFisher[i] = alpha * this.globalFisher[i] + (1 - alpha) * currentFisher[i];
    }

    this.saveToDisk();
  }

  /**
   * Compute consolidation penalty for a proposed confidence update.
   * Used by SONA to check whether a pattern update would cause forgetting.
   *
   * @param oldConfidence - Current confidence value
   * @param newConfidence - Proposed new confidence value
   * @returns Penalty value (higher = more forgetting risk)
   */
  computeConfidencePenalty(oldConfidence: number, newConfidence: number): number {
    // Use the global Fisher to estimate penalty for scalar confidence change
    // Average Fisher value represents overall importance
    let avgFisher = 0;
    for (let i = 0; i < this.globalFisher.length; i++) {
      avgFisher += this.globalFisher[i];
    }
    avgFisher = this.globalFisher.length > 0 ? avgFisher / this.globalFisher.length : 0;

    const diff = newConfidence - oldConfidence;
    return (this.config.lambda / 2) * avgFisher * diff * diff;
  }

  /**
   * Clear all patterns and history (full reset)
   */
  clear(): void {
    this.patterns.clear();
    this.gradientHistory = [];
    this.globalFisher = new Array(this.config.dimensions).fill(0);
    this.consolidationHistory = [];

    // Remove persisted file
    try {
      if (fs.existsSync(this.config.storagePath)) {
        fs.unlinkSync(this.config.storagePath);
      }
    } catch {
      // Ignore deletion errors
    }
  }

  // ============================================================================
  // Private Methods
  // ============================================================================

  /**
   * Calculate importance score for a pattern based on usage
   */
  private calculateImportance(pattern: PatternWeights): number {
    const total = pattern.successCount + pattern.failureCount;
    if (total === 0) return 0.5;

    // Success rate with Laplace smoothing
    const successRate = (pattern.successCount + 1) / (total + 2);

    // Recency factor: recent patterns are more important
    const hoursSinceUpdate = (Date.now() - pattern.lastUpdated) / (1000 * 60 * 60);
    const recencyFactor = Math.exp(-hoursSinceUpdate / 168); // 1 week half-life

    // Combine factors
    return successRate * 0.7 + recencyFactor * 0.3;
  }

  /**
   * Blend old and new weights using Fisher-weighted interpolation
   */
  private blendWeights(
    oldWeights: number[],
    newWeights: number[],
    blendFactor: number,
    fisher: number[]
  ): number[] {
    const len = Math.min(oldWeights.length, newWeights.length, this.config.dimensions);
    const result = new Array(len);

    // Normalize Fisher for per-weight blend factors
    let maxF = 0;
    for (let i = 0; i < len; i++) {
      if (fisher[i] > maxF) maxF = fisher[i];
    }
    const normFactor = maxF > 0 ? 1 / maxF : 1;

    for (let i = 0; i < len; i++) {
      // Higher Fisher = more weight on old value
      const fisherWeight = fisher[i] * normFactor;
      const adjustedBlend = blendFactor * (1 - fisherWeight * 0.5);

      result[i] = oldWeights[i] * (1 - adjustedBlend) + newWeights[i] * adjustedBlend;
    }

    return result;
  }

  /**
   * Prune old, low-importance patterns to stay within limit
   */
  private pruneOldPatterns(): void {
    if (this.patterns.size <= this.config.maxPatterns) return;

    // Sort by importance (ascending)
    const sortedPatterns = Array.from(this.patterns.entries())
      .map(([id, pattern]) => ({ id, importance: this.calculateImportance(pattern) }))
      .sort((a, b) => a.importance - b.importance);

    // Remove lowest importance patterns
    const toRemove = this.patterns.size - this.config.maxPatterns;
    for (let i = 0; i < toRemove; i++) {
      this.patterns.delete(sortedPatterns[i].id);
    }
  }

  /**
   * Save state to disk
   */
  private saveToDisk(): void {
    try {
      const dir = path.dirname(this.config.storagePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      const state = {
        version: '1.0.0',
        config: {
          lambda: this.config.lambda,
          dimensions: this.config.dimensions,
          fisherDecayRate: this.config.fisherDecayRate
        },
        globalFisher: this.globalFisher,
        patterns: Array.from(this.patterns.entries()),
        consolidationHistory: this.consolidationHistory.slice(-100),
        savedAt: Date.now()
      };

      fs.writeFileSync(this.config.storagePath, JSON.stringify(state, null, 2));
    } catch {
      // Silently fail - persistence is best-effort
    }
  }

  /**
   * Load state from disk
   */
  private async loadFromDisk(): Promise<void> {
    if (!fs.existsSync(this.config.storagePath)) {
      throw new Error('No persisted state found');
    }

    const content = fs.readFileSync(this.config.storagePath, 'utf-8');
    const state = JSON.parse(content);

    // Validate version
    if (state.version !== '1.0.0') {
      throw new Error(`Unsupported state version: ${state.version}`);
    }

    // Restore state
    this.globalFisher = state.globalFisher || new Array(this.config.dimensions).fill(0);

    // Restore patterns
    this.patterns.clear();
    if (state.patterns) {
      for (const [id, pattern] of state.patterns) {
        this.patterns.set(id, pattern);
      }
    }

    // Restore history
    this.consolidationHistory = state.consolidationHistory || [];

    // Update config from persisted values
    if (state.config) {
      this.config.lambda = state.config.lambda ?? this.config.lambda;
    }
  }
}

