let sonaCoordinator: LocalSonaCoordinator | null = null;
let reasoningBank: LocalReasoningBank | null = null;
let intelligenceInitialized = false;
let globalStats = {
  trajectoriesRecorded: 0,
  patternsLearned: 0,
  signalsProcessed: 0,
  lastAdaptation: null as number | null
};

