} from './types.js';
import { PluginDiscoveryService } from './discovery.js';
import { searchPlugins, findSimilarPlugins } from './search.js';

/**
 * High-level Plugin Store API
 */
export class PluginStore {
  private discovery: PluginDiscoveryService;
  private registry: PluginRegistry | null = null;

  constructor(config?: Partial<PluginStoreConfig>) {
    this.discovery = new PluginDiscoveryService(config);
  }

  /**
   * Initialize the store by discovering the registry
   */
  async initialize(registryName?: string): Promise<boolean> {
    const result = await this.discovery.discoverRegistry(registryName);
    if (result.success && result.registry) {
      this.registry = result.registry;
      return true;
    }
    return false;
  }

  /**
   * Check if store is initialized
   */
  isInitialized(): boolean {
    return this.registry !== null;
  }

  /**
   * Get the current registry
   */
  getRegistry(): PluginRegistry | null {
    return this.registry;
  }

  /**
   * Search plugins
   */
  search(options: PluginSearchOptions = {}): PluginSearchResult {
    if (!this.registry) {
      return {
        plugins: [],
        total: 0,
        page: 1,
        pageSize: options.limit || 20,
        hasMore: false,
        query: options,
      };
    }
    return searchPlugins(this.registry, options);
  }

  /**
   * Get a plugin by ID
   */
  getPlugin(pluginId: string): PluginEntry | undefined {
    return this.registry?.plugins.find(p => p.id === pluginId);
  }

  /**
   * Get similar plugins
   */
  getSimilarPlugins(pluginId: string, limit: number = 5): PluginEntry[] {
    if (!this.registry) return [];
    return findSimilarPlugins(this.registry, pluginId, limit);
  }

  /**
   * Get featured plugins
   */
  getFeatured(): PluginEntry[] {
    if (!this.registry) return [];
    return this.registry.featured
      .map(id => this.registry!.plugins.find(p => p.id === id))
      .filter((p): p is PluginEntry => p !== undefined);
  }

  /**
   * Get official plugins
   */
  getOfficial(): PluginEntry[] {
    if (!this.registry) return [];
    return this.registry.official
      .map(id => this.registry!.plugins.find(p => p.id === id))
      .filter((p): p is PluginEntry => p !== undefined);
  }

  /**
   * Get trending plugins
   */
  getTrending(): PluginEntry[] {
    if (!this.registry) return [];
    return this.registry.trending
      .map(id => this.registry!.plugins.find(p => p.id === id))
      .filter((p): p is PluginEntry => p !== undefined);
  }

  /**
   * Get newest plugins
   */
  getNewest(): PluginEntry[] {
    if (!this.registry) return [];
    return this.registry.newest
      .map(id => this.registry!.plugins.find(p => p.id === id))
      .filter((p): p is PluginEntry => p !== undefined);
  }

  /**
   * Get discovery service
   */
  getDiscovery(): PluginDiscoveryService {
    return this.discovery;
  }

  /**
   * Refresh registry
   */
  async refresh(registryName?: string): Promise<boolean> {
    this.discovery.clearCache();
    return this.initialize(registryName);
  }
}

/**
 * Create a new plugin store instance
 */
export function createPluginStore(config?: Partial<PluginStoreConfig>): PluginStore {
  return new PluginStore(config);
}

/**
 * Plugin Search Service
 * Search and filter plugins from the registry
 */

import type {
  PluginEntry,
  PluginRegistry,
  PluginSearchOptions,
  PluginSearchResult,
} from './types.js';

/**
 * Search plugins in the registry
 */
export function searchPlugins(
  registry: PluginRegistry,
  options: PluginSearchOptions = {}
): PluginSearchResult {
  let plugins = [...registry.plugins];

  // Text search (name, displayName, description, tags)
  if (options.query) {
    const query = options.query.toLowerCase();
    plugins = plugins.filter(p =>
      p.name?.toLowerCase().includes(query) ||
      p.displayName?.toLowerCase().includes(query) ||
      p.description?.toLowerCase().includes(query) ||
      (p.tags || []).some(t => t.toLowerCase().includes(query)) ||
      (p.keywords || []).some(k => k.toLowerCase().includes(query))
    );
  }

  // Category filter
  if (options.category) {
    plugins = plugins.filter(p =>
      (p.categories || []).includes(options.category!)
    );
  }

  // Type filter
  if (options.type) {
    plugins = plugins.filter(p => p.type === options.type);
  }

  // Tags filter (match any)
  if (options.tags && options.tags.length > 0) {
    plugins = plugins.filter(p =>
      options.tags!.some(tag => (p.tags || []).includes(tag))
    );
  }

  // Author filter
  if (options.author) {
    plugins = plugins.filter(p =>
      p.author.id === options.author ||
      p.author.displayName?.toLowerCase().includes(options.author!.toLowerCase())
    );
  }

  // Rating filter
  if (options.minRating !== undefined) {
    plugins = plugins.filter(p => p.rating >= options.minRating!);
  }

  // Downloads filter
  if (options.minDownloads !== undefined) {
    plugins = plugins.filter(p => p.downloads >= options.minDownloads!);
  }

  // Verified filter
  if (options.verified !== undefined) {
    plugins = plugins.filter(p => p.verified === options.verified);
  }

  // Trust level filter
  if (options.trustLevel) {
    const trustOrder = ['unverified', 'community', 'verified', 'official'];
    const minIndex = trustOrder.indexOf(options.trustLevel);
    plugins = plugins.filter(p => {
      const pluginIndex = trustOrder.indexOf(p.trustLevel);
      return pluginIndex >= minIndex;
    });
  }

  // Permissions filter
  if (options.permissions && options.permissions.length > 0) {
    plugins = plugins.filter(p =>
      options.permissions!.every(perm => (p.permissions || []).includes(perm))
    );
  }

  // Security audit filter
  if (options.hasSecurityAudit !== undefined) {
    plugins = plugins.filter(p =>
      options.hasSecurityAudit ? p.securityAudit !== undefined : true
    );
  }

  // Sort
  const sortBy = options.sortBy || 'downloads';
  const sortOrder = options.sortOrder || 'desc';

  plugins.sort((a, b) => {
    let comparison = 0;
    switch (sortBy) {
      case 'downloads':
        comparison = a.downloads - b.downloads;
        break;
      case 'rating':
        comparison = a.rating - b.rating;
        break;
      case 'newest':
        comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
        break;
      case 'name':
        comparison = a.name.localeCompare(b.name);
        break;
      case 'reputation':
        comparison = a.author.reputation - b.author.reputation;
        break;
    }
    return sortOrder === 'desc' ? -comparison : comparison;
  });

  // Pagination
  const total = plugins.length;
  const limit = options.limit || 20;
  const offset = options.offset || 0;
  const page = Math.floor(offset / limit) + 1;

  plugins = plugins.slice(offset, offset + limit);

  return {
    plugins,
    total,
    page,
    pageSize: limit,
    hasMore: offset + limit < total,
    query: options,
  };
}

/**
 * Get search suggestions based on partial query
 */
export function getPluginSearchSuggestions(
  registry: PluginRegistry,
  partialQuery: string,
  limit: number = 10
): string[] {
  const query = partialQuery.toLowerCase();
  const suggestions = new Set<string>();

  // Search in plugin names
  for (const plugin of registry.plugins) {
    if (plugin.name.toLowerCase().includes(query)) {
      suggestions.add(plugin.name);
    }
    if (plugin.displayName.toLowerCase().includes(query)) {
      suggestions.add(plugin.displayName);
    }
    // Search in tags
    for (const tag of plugin.tags || []) {
      if (tag.toLowerCase().includes(query)) {
        suggestions.add(tag);
      }
    }
    // Search in keywords
    for (const keyword of plugin.keywords || []) {
      if (keyword.toLowerCase().includes(query)) {
        suggestions.add(keyword);
      }
    }
  }

  return Array.from(suggestions).slice(0, limit);
}

/**
 * Get tag cloud with counts
 */
export function getPluginTagCloud(registry: PluginRegistry): Map<string, number> {
  const tagCounts = new Map<string, number>();

  for (const plugin of registry.plugins) {
    for (const tag of plugin.tags || []) {
      tagCounts.set(tag, (tagCounts.get(tag) || 0) + 1);
    }
  }

  // Sort by count descending
  const sortedEntries = Array.from(tagCounts.entries()).sort((a, b) => b[1] - a[1]);
  return new Map(sortedEntries);
}

/**
 * Get category statistics
 */
export function getPluginCategoryStats(registry: PluginRegistry): Map<string, number> {
  const categoryCounts = new Map<string, number>();

  for (const plugin of registry.plugins) {
    for (const category of plugin.categories || []) {
      categoryCounts.set(category, (categoryCounts.get(category) || 0) + 1);
    }
  }

  return categoryCounts;
}

/**
 * Find similar plugins based on tags and category
 */
export function findSimilarPlugins(
  registry: PluginRegistry,
  pluginId: string,
  limit: number = 5
): PluginEntry[] {
  const targetPlugin = registry.plugins.find(p => p.id === pluginId);
  if (!targetPlugin) {
    return [];
  }

  // Score plugins by tag overlap and category match
  const scored = registry.plugins
    .filter(p => p.id !== pluginId)
    .map(plugin => {
      let score = 0;

      // Tag overlap
      const tagOverlap = (plugin.tags || []).filter(t =>
        (targetPlugin.tags || []).includes(t)
      ).length;
      score += tagOverlap * 2;

      // Category match
      const categoryMatch = (plugin.categories || []).some(c =>
        (targetPlugin.categories || []).includes(c)
      );
      if (categoryMatch) score += 3;

      // Type match
      if (plugin.type === targetPlugin.type) score += 2;

      // Same author bonus
      if (plugin.author.id === targetPlugin.author.id) score += 1;

      return { plugin, score };
    })
    .filter(s => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);

  return scored.map(s => s.plugin);
}

/**
 * Get featured plugins
 */
export function getFeaturedPlugins(registry: PluginRegistry): PluginEntry[] {
  return registry.featured
    .map(id => registry.plugins.find(p => p.id === id))
    .filter((p): p is PluginEntry => p !== undefined);
}

/**
 * Get trending plugins
 */
export function getTrendingPlugins(registry: PluginRegistry): PluginEntry[] {
  return registry.trending
    .map(id => registry.plugins.find(p => p.id === id))
    .filter((p): p is PluginEntry => p !== undefined);
}

/**
 * Get newest plugins
 */
export function getNewestPlugins(registry: PluginRegistry): PluginEntry[] {
  return registry.newest
    .map(id => registry.plugins.find(p => p.id === id))
    .filter((p): p is PluginEntry => p !== undefined);
}

/**
 * Get official plugins
 */
export function getOfficialPlugins(registry: PluginRegistry): PluginEntry[] {
  return registry.official
    .map(id => registry.plugins.find(p => p.id === id))
    .filter((p): p is PluginEntry => p !== undefined);
}

/**
 * Get plugins by permission
 */
export function getPluginsByPermission(
  registry: PluginRegistry,
  permission: string
): PluginEntry[] {
  return registry.plugins.filter(p =>
    (p.permissions || []).includes(permission as any)
  );
}

/**
 * Plugin Store Types
 * Decentralized plugin marketplace using IPFS
 * Extends the pattern store architecture for plugins
 */

import type { TrustLevel } from '../../transfer/types.js';

/**
 * Plugin entry in the registry
 */
export interface PluginEntry {
  // Identity
  id: string;
  name: string;
  displayName: string;
  description: string;
  version: string;

  // Storage
  cid: string;
  size: number;
  checksum: string;

  // Metadata
  author: PluginAuthor;
  license: string;
  categories: string[];
  tags: string[];
  keywords: string[];

  // Stats
  downloads: number;
  rating: number;
  ratingCount: number;
  lastUpdated: string;
  createdAt: string;

  // Requirements
  minClaudeFlowVersion: string;
  maxClaudeFlowVersion?: string;
  dependencies: PluginDependency[];
  peerDependencies?: PluginDependency[];

  // Plugin-specific
  type: PluginType;
  hooks: string[];
  commands: string[];
  permissions: PluginPermission[];
  exports: string[];

  // Verification
  verified: boolean;
  trustLevel: TrustLevel;
  signature?: string;
  publicKey?: string;

  // Security
  securityAudit?: SecurityAudit;
  knownVulnerabilities?: string[];
}

/**
 * Plugin types
 *
 * ADR-150 added 'harness' — a MetaHarness-generated standalone agent
 * harness. Harnesses share the ruflo plugin registry shape (per
 * `buildRegistryEntry()` from metaharness) so `npx ruflo plugins list
 * --type harness` surfaces community harnesses alongside plugins.
 */
export type PluginType =
  | 'agent'      // Adds new agent types
  | 'hook'       // Adds new hooks
  | 'command'    // Adds CLI commands
  | 'provider'   // Adds AI providers
  | 'integration'// External integrations
  | 'theme'      // UI themes
  | 'core'       // Core functionality extensions
  | 'hybrid'     // Multiple types
  | 'harness';   // ADR-150 — MetaHarness-generated standalone harness

/**
 * Plugin dependency
 */
export interface PluginDependency {
  name: string;
  version: string;
  optional?: boolean;
}

/**
 * Plugin permissions
 */
export type PluginPermission =
  | 'network'      // Network access
  | 'filesystem'   // File system access
  | 'execute'      // Execute external commands
  | 'memory'       // Access memory system
  | 'agents'       // Spawn/manage agents
  | 'credentials'  // Access credentials
  | 'config'       // Modify configuration
  | 'hooks'        // Register hooks
  | 'privileged';  // Full system access

/**
 * Security audit info
 */
export interface SecurityAudit {
  auditor: string;
  auditDate: string;
  auditVersion: string;
  passed: boolean;
  issues: SecurityIssue[];
  reportCid?: string;
}

/**
 * Security issue
 */
export interface SecurityIssue {
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  resolved: boolean;
  resolvedVersion?: string;
}

/**
 * Plugin author info
 */
export interface PluginAuthor {
  id: string;
  displayName?: string;
  email?: string;
  website?: string;
  publicKey?: string;
  verified: boolean;
  plugins: number;
  totalDownloads: number;
  reputation: number;
}

/**
 * Plugin category
 */
export interface PluginCategory {
  id: string;
  name: string;
  description: string;
  pluginCount: number;
  icon?: string;
  subcategories?: PluginCategory[];
}

/**
 * Decentralized plugin registry
 * Stored on IPFS with IPNS pointer for updates
 */
export interface PluginRegistry {
  // Registry metadata
  version: string;
  type: 'plugins';
  updatedAt: string;
  ipnsName: string;
  previousCid?: string;

  // Content
  plugins: PluginEntry[];
  categories: PluginCategory[];
  authors: PluginAuthor[];

  // Stats
  totalPlugins: number;
  totalDownloads: number;
  totalAuthors: number;

  // Featured/promoted
  featured: string[];
  trending: string[];
  newest: string[];
  official: string[];

  // Verification
  registrySignature?: string;
  registryPublicKey?: string;

  // Compatibility matrix
  compatibilityMatrix: CompatibilityEntry[];
}

/**
 * Compatibility entry
 */
export interface CompatibilityEntry {
  pluginId: string;
  pluginVersion: string;
  claudeFlowVersions: string[];
  tested: boolean;
  notes?: string;
}

/**
 * Search query options for plugins
 */
export interface PluginSearchOptions {
  query?: string;
  category?: string;
  type?: PluginType;
  tags?: string[];
  author?: string;
  minRating?: number;
  minDownloads?: number;
  verified?: boolean;
  trustLevel?: TrustLevel;
  permissions?: PluginPermission[];
  hasSecurityAudit?: boolean;
  sortBy?: 'downloads' | 'rating' | 'newest' | 'name' | 'reputation';
  sortOrder?: 'asc' | 'desc';
  limit?: number;
  offset?: number;
}

/**
 * Search result
 */
export interface PluginSearchResult {
  plugins: PluginEntry[];
  total: number;
  page: number;
  pageSize: number;
  hasMore: boolean;
  query: PluginSearchOptions;
}

/**
 * Publish options for plugins
 */
export interface PluginPublishOptions {
  name: string;
  displayName: string;
  description: string;
  version: string;
  categories: string[];
  tags: string[];
  license: string;
  type: PluginType;
  hooks?: string[];
  commands?: string[];
  permissions: PluginPermission[];
  dependencies?: PluginDependency[];
  privateKeyPath?: string;
  requestAudit?: boolean;
}

/**
 * Publish result
 */
export interface PluginPublishResult {
  success: boolean;
  pluginId: string;
  cid: string;
  registryCid: string;
  gatewayUrl: string;
  message: string;
  auditRequestId?: string;
}

/**
 * Download options for plugins
 */
export interface PluginDownloadOptions {
  output?: string;
  verify?: boolean;
  install?: boolean;
  global?: boolean;
  skipDependencies?: boolean;
}

/**
 * Download result
 */
export interface PluginDownloadResult {
  success: boolean;
  plugin: PluginEntry;
  outputPath?: string;
  installed?: boolean;
  verified: boolean;
  size: number;
  dependenciesInstalled?: string[];
}

/**
 * Known plugin registries (bootstrap nodes)
 */
export interface KnownPluginRegistry {
  name: string;
  description: string;
  ipnsName: string;
  gateway: string;
  publicKey: string;
  trusted: boolean;
  official: boolean;
}

/**
 * Plugin store configuration
 */
export interface PluginStoreConfig {
  // Registry discovery
  registries: KnownPluginRegistry[];
  defaultRegistry: string;

  // IPFS settings
  gateway: string;
  timeout: number;

  // Cache settings
  cacheDir: string;
  cacheExpiry: number;

  // Security
  requireVerification: boolean;
  requireSecurityAudit: boolean;
  minTrustLevel: TrustLevel;
  trustedAuthors: string[];
  blockedPlugins: string[];
  allowedPermissions: PluginPermission[];
  requirePermissionPrompt: boolean;

  // User identity
  authorId?: string;
  privateKeyPath?: string;
}

/**
 * Plugin installation manifest
 */
export interface PluginManifest {
  name: string;
  version: string;
  cid: string;
  installedAt: string;
  enabled: boolean;
  config?: Record<string, unknown>;
}

/**
 * Installed plugins database
 */
export interface InstalledPlugins {
