  }>;
  timestamp: number;
}

export interface PerformanceMetrics {
  requestCount: number;
  errorCount: number;
  errorRate: number;
  avgResponseTimeMs: number;
  p50ResponseTimeMs: number;
  p95ResponseTimeMs: number;
  p99ResponseTimeMs: number;
