/**
 * Production Retry Mechanisms
 *
 * Provides retry with:
 * - Exponential backoff
 * - Jitter
 * - Per-error-type configuration
 * - Circuit breaker integration
 *
 * @module @claude-flow/cli/production/retry
 */

// ============================================================================
// Types
// ============================================================================

export interface RetryConfig {
  // Maximum retry attempts
  maxAttempts: number;
  // Initial delay in milliseconds
  initialDelayMs: number;
  // Maximum delay in milliseconds
  maxDelayMs: number;
  // Exponential backoff multiplier
  backoffMultiplier: number;
  // Add random jitter (0-1)
  jitter: number;
  // Errors that should not be retried
  nonRetryableErrors: string[];
  // Custom retry decision function
  shouldRetry?: (error: Error, attempt: number) => boolean;
  // Called before each retry
  onRetry?: (error: Error, attempt: number, delayMs: number) => void;
}

export interface RetryResult<T> {
  success: boolean;
  result?: T;
  error?: Error;
  attempts: number;
  totalTimeMs: number;
  retryHistory: Array<{ attempt: number; error: string; delayMs: number }>;
}

export type RetryStrategy = 'exponential' | 'linear' | 'constant' | 'fibonacci';

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_CONFIG: RetryConfig = {
  maxAttempts: 3,
  initialDelayMs: 1000,
  maxDelayMs: 30000,
  backoffMultiplier: 2,
  jitter: 0.1,
  nonRetryableErrors: [
    'validation',
    'authentication',
    'authorization',
    'not_found',
  ],
};

// ============================================================================
// Retry Implementation
// ============================================================================

/**
 * Calculate delay for a given attempt
 */
function calculateDelay(
  attempt: number,
  config: RetryConfig,
  strategy: RetryStrategy = 'exponential'
): number {
  let delay: number;

  switch (strategy) {
    case 'linear':
      delay = config.initialDelayMs * attempt;
      break;

    case 'constant':
      delay = config.initialDelayMs;
      break;

    case 'fibonacci':
      delay = config.initialDelayMs * fibonacci(attempt);
      break;

    case 'exponential':
    default:
      delay = config.initialDelayMs * Math.pow(config.backoffMultiplier, attempt - 1);
  }

  // Apply max delay cap
  delay = Math.min(delay, config.maxDelayMs);

  // Apply jitter
  if (config.jitter > 0) {
    const jitterRange = delay * config.jitter;
    delay += (Math.random() - 0.5) * 2 * jitterRange;
  }

  return Math.round(Math.max(0, delay));
}

/**
 * Fibonacci helper for fibonacci backoff
 */
function fibonacci(n: number): number {
  if (n <= 1) return 1;
  let a = 1, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
}

/**
 * Check if an error should be retried
 */
function shouldRetryError(
  error: Error,
  attempt: number,
  config: RetryConfig
): boolean {
  // Check custom retry function
  if (config.shouldRetry) {
    return config.shouldRetry(error, attempt);
  }

  // Check non-retryable error patterns
  const message = error.message.toLowerCase();
  for (const pattern of config.nonRetryableErrors) {
    if (message.includes(pattern.toLowerCase())) {
      return false;
    }
  }

  // Default: retry if we haven't exceeded max attempts
  return attempt < config.maxAttempts;
}

/**
 * Sleep for a given number of milliseconds
 */
function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Execute a function with retry logic
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  config: Partial<RetryConfig> = {},
  strategy: RetryStrategy = 'exponential'
): Promise<RetryResult<T>> {
  const finalConfig = { ...DEFAULT_CONFIG, ...config };
  const startTime = Date.now();
  const retryHistory: Array<{ attempt: number; error: string; delayMs: number }> = [];

  let lastError: Error | undefined;
  let attempt = 0;

  while (attempt < finalConfig.maxAttempts) {
    attempt++;

    try {
      const result = await fn();
      return {
        success: true,
        result,
        attempts: attempt,
        totalTimeMs: Date.now() - startTime,
        retryHistory,
      };
    } catch (error) {
      lastError = error as Error;

      // Check if we should retry
      if (!shouldRetryError(lastError, attempt, finalConfig)) {
        return {
          success: false,
          error: lastError,
          attempts: attempt,
          totalTimeMs: Date.now() - startTime,
          retryHistory,
        };
      }

      // Calculate delay
      const delay = calculateDelay(attempt, finalConfig, strategy);

      // Record retry
      retryHistory.push({
        attempt,
        error: lastError.message,
        delayMs: delay,
      });

      // Call retry callback
      if (finalConfig.onRetry) {
        finalConfig.onRetry(lastError, attempt, delay);
      }

      // Wait before retrying
      if (attempt < finalConfig.maxAttempts) {
        await sleep(delay);
      }
    }
  }

  return {
    success: false,
    error: lastError,
    attempts: attempt,
    totalTimeMs: Date.now() - startTime,
    retryHistory,
  };
}

/**
 * Create a retryable version of a function
 */
export function makeRetryable<T extends (...args: unknown[]) => Promise<unknown>>(
  fn: T,
  config: Partial<RetryConfig> = {},
  strategy: RetryStrategy = 'exponential'
): (...args: Parameters<T>) => Promise<RetryResult<Awaited<ReturnType<T>>>> {
  return async (...args: Parameters<T>) => {
    return withRetry(() => fn(...args) as Promise<Awaited<ReturnType<T>>>, config, strategy);
  };
}

/**
 * Retry decorator for class methods
 */
export function Retryable(
  config: Partial<RetryConfig> = {},
  strategy: RetryStrategy = 'exponential'
) {
  return function (
    _target: unknown,
    _propertyKey: string,
    descriptor: PropertyDescriptor
  ) {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: unknown[]) {
      const result = await withRetry(
        () => originalMethod.apply(this, args),
        config,
        strategy
      );

      if (result.success) {
        return result.result;
      }

      throw result.error;
    };

    return descriptor;
  };
}

export default withRetry;

/**
 * V3 CLI Interactive Prompt System
 * Modern interactive prompts for user input
 */

import * as readline from 'readline';
import type {
  SelectPromptOptions,
  SelectOption,
  ConfirmPromptOptions,
  InputPromptOptions,
  MultiSelectPromptOptions
} from './types.js';
import { output, OutputFormatter } from './output.js';

// ============================================
// Core Prompt Infrastructure
// ============================================

class PromptManager {
  private rl: readline.Interface | null = null;
  private formatter: OutputFormatter;

  constructor(formatter: OutputFormatter = output) {
    this.formatter = formatter;
  }

  private createInterface(): readline.Interface {
    if (!this.rl) {
      this.rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
        terminal: true
      });

      // Handle cleanup on exit
      this.rl.on('close', () => {
        this.rl = null;
      });
    }
    return this.rl;
  }

  private close(): void {
    if (this.rl) {
      this.rl.close();
      this.rl = null;
    }
  }

  private async question(prompt: string): Promise<string> {
    return new Promise((resolve) => {
      const rl = this.createInterface();
      rl.question(prompt, (answer) => {
        resolve(answer);
      });
    });
  }

  // ============================================
  // Select Prompt
  // ============================================

  async select<T = string>(options: SelectPromptOptions<T>): Promise<T> {
    const { message, options: choices, default: defaultValue, pageSize = 10 } = options;

    this.formatter.writeln();
    this.formatter.writeln(this.formatter.bold(`? ${message}`));
    this.formatter.writeln(this.formatter.dim('  (Use arrow keys to navigate, enter to select)'));
    this.formatter.writeln();

    // Find default index
    let selectedIndex = 0;
    if (defaultValue !== undefined) {
      const idx = choices.findIndex(c => c.value === defaultValue);
      if (idx !== -1) selectedIndex = idx;
    }

    // Display options
    const displayChoices = (currentIndex: number, startIndex: number = 0) => {
      // Move cursor up to overwrite
      if (startIndex > 0 || currentIndex > 0) {
        process.stdout.write(`\x1b[${Math.min(choices.length, pageSize)}A`);
      }

      const endIndex = Math.min(startIndex + pageSize, choices.length);
      for (let i = startIndex; i < endIndex; i++) {
        const choice = choices[i];
        const isSelected = i === currentIndex;
        const prefix = isSelected ? this.formatter.info('>') : ' ';
        const label = isSelected
          ? this.formatter.highlight(choice.label)
          : choice.label;
        const hint = choice.hint ? this.formatter.dim(` - ${choice.hint}`) : '';
        const disabled = choice.disabled ? this.formatter.dim(' (disabled)') : '';

        this.formatter.writeln(`  ${prefix} ${label}${hint}${disabled}`);
      }
    };

    // Initial display
    displayChoices(selectedIndex);

    return new Promise<T>((resolve, reject) => {
      const rl = this.createInterface();

      // Enable raw mode for arrow key detection
      if (process.stdin.isTTY) {
        process.stdin.setRawMode(true);
      }
      process.stdin.resume();

      const handleKeypress = (key: Buffer) => {
        const keyStr = key.toString();

        // Arrow keys
        if (keyStr === '\x1b[A') { // Up
          do {
            selectedIndex = (selectedIndex - 1 + choices.length) % choices.length;
          } while (choices[selectedIndex].disabled && selectedIndex !== 0);
          displayChoices(selectedIndex);
        } else if (keyStr === '\x1b[B') { // Down
          do {
            selectedIndex = (selectedIndex + 1) % choices.length;
          } while (choices[selectedIndex].disabled && selectedIndex !== choices.length - 1);
          displayChoices(selectedIndex);
        } else if (keyStr === '\r' || keyStr === '\n') { // Enter
          cleanup();
          const selected = choices[selectedIndex];
          if (!selected.disabled) {
            this.formatter.writeln();
            this.formatter.writeln(this.formatter.success(`Selected: ${selected.label}`));
            resolve(selected.value);
          }
        } else if (keyStr === '\x03') { // Ctrl+C
          cleanup();
          reject(new Error('User cancelled'));
        }
      };

      const cleanup = () => {
        process.stdin.removeListener('data', handleKeypress);
        if (process.stdin.isTTY) {
          process.stdin.setRawMode(false);
        }
        this.close();
      };

      process.stdin.on('data', handleKeypress);
    });
  }

  // ============================================
  // Confirm Prompt
  // ============================================

  async confirm(options: ConfirmPromptOptions): Promise<boolean> {
    const {
      message,
      default: defaultValue = false,
      active = 'Yes',
      inactive = 'No'
    } = options;

    const defaultText = defaultValue ? `${active}/${inactive}` : `${active}/${inactive}`;
    const hint = defaultValue ? `[${active}]` : `[${inactive}]`;

    const prompt = `${this.formatter.bold('?')} ${message} ${this.formatter.dim(hint)} `;

    const answer = await this.question(prompt);
    this.close();

    if (answer === '') {
      return defaultValue;
    }

    const normalized = answer.toLowerCase().trim();

    if (['y', 'yes', 'true', '1'].includes(normalized)) {
      return true;
    }

    if (['n', 'no', 'false', '0'].includes(normalized)) {
      return false;
    }

    return defaultValue;
  }

  // ============================================
  // Input Prompt
  // ============================================

  async input(options: InputPromptOptions): Promise<string> {
    const {
      message,
      default: defaultValue,
      placeholder,
      validate,
      mask
    } = options;

    let prompt = `${this.formatter.bold('?')} ${message}`;

    if (defaultValue) {
      prompt += ` ${this.formatter.dim(`(${defaultValue})`)}`;
    } else if (placeholder) {
      prompt += ` ${this.formatter.dim(placeholder)}`;
    }

    prompt += ': ';

    while (true) {
      let answer: string;

      if (mask) {
        answer = await this.inputMasked(prompt);
      } else {
        answer = await this.question(prompt);
      }

      // Use default if empty
      if (answer === '' && defaultValue !== undefined) {
        answer = defaultValue;
      }

      // Validate
      if (validate) {
        const result = validate(answer);
        if (result !== true) {
          const errorMsg = typeof result === 'string' ? result : 'Invalid input';
          this.formatter.writeln(this.formatter.error(`  ${errorMsg}`));
          continue;
        }
      }

      this.close();
      return answer;
    }
  }

  private async inputMasked(prompt: string): Promise<string> {
    return new Promise((resolve) => {
      const rl = this.createInterface();
      let password = '';

      // Don't echo characters
      process.stdout.write(prompt);

      if (process.stdin.isTTY) {
        process.stdin.setRawMode(true);
      }
      process.stdin.resume();

      const handleData = (chunk: Buffer) => {
        const char = chunk.toString();

        if (char === '\n' || char === '\r') {
          // Enter pressed
          process.stdin.removeListener('data', handleData);
          if (process.stdin.isTTY) {
            process.stdin.setRawMode(false);
          }
          process.stdout.write('\n');
          resolve(password);
        } else if (char === '\x7f' || char === '\x08') {
          // Backspace
          if (password.length > 0) {
            password = password.slice(0, -1);
            process.stdout.write('\b \b');
          }
        } else if (char === '\x03') {
          // Ctrl+C
          process.stdin.removeListener('data', handleData);
          if (process.stdin.isTTY) {
            process.stdin.setRawMode(false);
          }
          resolve('');
        } else if (char.charCodeAt(0) >= 32) {
          // Printable character
          password += char;
          process.stdout.write('*');
        }
      };

      process.stdin.on('data', handleData);
    });
  }

  // ============================================
  // Multi-Select Prompt
  // ============================================

  async multiSelect<T = string>(options: MultiSelectPromptOptions<T>): Promise<T[]> {
    const {
      message,
      options: choices,
      default: defaultValues = [],
      required = false,
      min,
      max
    } = options;

    this.formatter.writeln();
    this.formatter.writeln(this.formatter.bold(`? ${message}`));
    this.formatter.writeln(this.formatter.dim('  (Use arrow keys to navigate, space to select, enter to confirm)'));
    this.formatter.writeln();

    // Initialize selection state
    const selected = new Set<number>();
    for (let i = 0; i < choices.length; i++) {
      // Check both default array and individual selected property
      if (defaultValues.includes(choices[i].value) || choices[i].selected) {
        selected.add(i);
      }
    }

    let currentIndex = 0;

    // Display options
    const displayChoices = () => {
      // Move cursor up to overwrite
      process.stdout.write(`\x1b[${choices.length}A`);

      for (let i = 0; i < choices.length; i++) {
        const choice = choices[i];
        const isCurrentRow = i === currentIndex;
        const isSelected = selected.has(i);

        const cursor = isCurrentRow ? this.formatter.info('>') : ' ';
        const checkbox = isSelected
          ? this.formatter.success('[x]')
          : this.formatter.dim('[ ]');
        const label = isCurrentRow
          ? this.formatter.highlight(choice.label)
          : choice.label;
        const hint = choice.hint ? this.formatter.dim(` - ${choice.hint}`) : '';
        const disabled = choice.disabled ? this.formatter.dim(' (disabled)') : '';

        this.formatter.writeln(`  ${cursor} ${checkbox} ${label}${hint}${disabled}`);
      }
    };

    // Initial display
    for (let i = 0; i < choices.length; i++) {
      this.formatter.writeln('');
    }
    displayChoices();

    return new Promise<T[]>((resolve, reject) => {
      const rl = this.createInterface();

      if (process.stdin.isTTY) {
        process.stdin.setRawMode(true);
      }
      process.stdin.resume();

      const handleKeypress = (key: Buffer) => {
        const keyStr = key.toString();

        if (keyStr === '\x1b[A') { // Up
          currentIndex = (currentIndex - 1 + choices.length) % choices.length;
          displayChoices();
        } else if (keyStr === '\x1b[B') { // Down
          currentIndex = (currentIndex + 1) % choices.length;
          displayChoices();
        } else if (keyStr === ' ') { // Space
          if (!choices[currentIndex].disabled) {
            if (selected.has(currentIndex)) {
              selected.delete(currentIndex);
            } else {
              // Check max limit
              if (!max || selected.size < max) {
                selected.add(currentIndex);
              }
            }
            displayChoices();
          }
        } else if (keyStr === '\r' || keyStr === '\n') { // Enter
          // Validate selection
          if (required && selected.size === 0) {
            this.formatter.writeln(this.formatter.error('  At least one option must be selected'));
            return;
          }
          if (min && selected.size < min) {
            this.formatter.writeln(this.formatter.error(`  At least ${min} options must be selected`));
            return;
          }

          cleanup();
          const selectedValues = Array.from(selected).map(i => choices[i].value);
          const selectedLabels = Array.from(selected).map(i => choices[i].label);
          this.formatter.writeln();
          this.formatter.writeln(this.formatter.success(`Selected: ${selectedLabels.join(', ')}`));
          resolve(selectedValues);
        } else if (keyStr === '\x03') { // Ctrl+C
          cleanup();
          reject(new Error('User cancelled'));
        } else if (keyStr === 'a') { // Select all
          if (!max || choices.length <= max) {
            for (let i = 0; i < choices.length; i++) {
              if (!choices[i].disabled) {
                selected.add(i);
              }
            }
            displayChoices();
          }
        } else if (keyStr === 'n') { // Select none
          selected.clear();
          displayChoices();
        }
      };

      const cleanup = () => {
        process.stdin.removeListener('data', handleKeypress);
        if (process.stdin.isTTY) {
          process.stdin.setRawMode(false);
        }
        this.close();
      };

      process.stdin.on('data', handleKeypress);
    });
  }

  // ============================================
  // Text Prompt (Multi-line)
  // ============================================

  async text(message: string, placeholder?: string): Promise<string> {
    this.formatter.writeln();
    this.formatter.writeln(this.formatter.bold(`? ${message}`));
    if (placeholder) {
      this.formatter.writeln(this.formatter.dim(`  ${placeholder}`));
    }
    this.formatter.writeln(this.formatter.dim('  (Enter an empty line to finish)'));
    this.formatter.writeln();

    const lines: string[] = [];

    while (true) {
      const line = await this.question('  > ');
      if (line === '') {
        break;
      }
      lines.push(line);
    }

    this.close();
    return lines.join('\n');
  }

  // ============================================
  // Number Prompt
  // ============================================

  async number(
    message: string,
    options: { default?: number; min?: number; max?: number; } = {}
  ): Promise<number> {
    const { default: defaultValue, min, max } = options;

    const validate = (value: string): boolean | string => {
      const num = Number(value);
      if (isNaN(num)) {
        return 'Please enter a valid number';
      }
      if (min !== undefined && num < min) {
        return `Value must be at least ${min}`;
      }
      if (max !== undefined && num > max) {
        return `Value must be at most ${max}`;
      }
      return true;
    };

    const result = await this.input({
      message,
      default: defaultValue?.toString(),
      validate
    });

    return Number(result);
  }

  // ============================================
  // Autocomplete Prompt
  // ============================================

  async autocomplete<T = string>(
    message: string,
    choices: SelectOption<T>[],
    options: { limit?: number } = {}
  ): Promise<T> {
    const { limit = 10 } = options;

    this.formatter.writeln();
    this.formatter.writeln(this.formatter.bold(`? ${message}`));
    this.formatter.writeln(this.formatter.dim('  (Type to filter, arrow keys to navigate)'));

    let query = '';
    let selectedIndex = 0;
    let filteredChoices = choices.slice(0, limit);

    const filterChoices = (q: string): SelectOption<T>[] => {
      if (q === '') return choices.slice(0, limit);

      const normalized = q.toLowerCase();
      return choices
        .filter(c => c.label.toLowerCase().includes(normalized))
        .slice(0, limit);
    };

    const displayChoices = () => {
      // Clear previous output
      process.stdout.write(`\x1b[${filteredChoices.length + 1}A`);
      process.stdout.write('\x1b[J');

      // Show input
      this.formatter.writeln(`  ${this.formatter.dim('>')} ${query}`);

      // Show filtered options
      for (let i = 0; i < filteredChoices.length; i++) {
        const choice = filteredChoices[i];
        const isSelected = i === selectedIndex;
        const prefix = isSelected ? this.formatter.info('>') : ' ';
        const label = isSelected ? this.formatter.highlight(choice.label) : choice.label;
        this.formatter.writeln(`  ${prefix} ${label}`);
      }
    };

    // Initial display
    this.formatter.writeln('');
    for (let i = 0; i < limit; i++) {
      this.formatter.writeln('');
    }
    displayChoices();

    return new Promise<T>((resolve, reject) => {
      const rl = this.createInterface();

      if (process.stdin.isTTY) {
        process.stdin.setRawMode(true);
      }
      process.stdin.resume();

      const handleKeypress = (key: Buffer) => {
        const keyStr = key.toString();

        if (keyStr === '\x1b[A') { // Up
          selectedIndex = Math.max(0, selectedIndex - 1);
          displayChoices();
        } else if (keyStr === '\x1b[B') { // Down
          selectedIndex = Math.min(filteredChoices.length - 1, selectedIndex + 1);
          displayChoices();
        } else if (keyStr === '\r' || keyStr === '\n') { // Enter
          if (filteredChoices.length > 0) {
            cleanup();
            const selected = filteredChoices[selectedIndex];
            this.formatter.writeln();
            this.formatter.writeln(this.formatter.success(`Selected: ${selected.label}`));
            resolve(selected.value);
          }
        } else if (keyStr === '\x7f' || keyStr === '\x08') { // Backspace
          query = query.slice(0, -1);
          filteredChoices = filterChoices(query);
          selectedIndex = 0;
          displayChoices();
        } else if (keyStr === '\x03') { // Ctrl+C
          cleanup();
          reject(new Error('User cancelled'));
        } else if (keyStr.charCodeAt(0) >= 32 && keyStr.charCodeAt(0) < 127) {
          // Printable character
          query += keyStr;
          filteredChoices = filterChoices(query);
          selectedIndex = 0;
          displayChoices();
        }
      };

      const cleanup = () => {
        process.stdin.removeListener('data', handleKeypress);
        if (process.stdin.isTTY) {
          process.stdin.setRawMode(false);
        }
        this.close();
      };

      process.stdin.on('data', handleKeypress);
    });
  }
}

// Export singleton and convenience functions
export const promptManager = new PromptManager();

export const select = <T = string>(options: SelectPromptOptions<T>) =>
  promptManager.select(options);

export const confirm = (options: ConfirmPromptOptions) =>
  promptManager.confirm(options);

export const input = (options: InputPromptOptions) =>
  promptManager.input(options);

export const multiSelect = <T = string>(options: MultiSelectPromptOptions<T>) =>
  promptManager.multiSelect(options);

export const text = (message: string, placeholder?: string) =>
  promptManager.text(message, placeholder);

export const number = (message: string, options?: { default?: number; min?: number; max?: number }) =>
  promptManager.number(message, options);

export const autocomplete = <T = string>(
  message: string,
  choices: SelectOption<T>[],
  options?: { limit?: number }
) => promptManager.autocomplete(message, choices, options);

#!/usr/bin/env node
/**
 * Headless Runtime for Background Workers
 * Runs without TTY for daemon processes and scheduled tasks
 *
 * Usage:
 *   npx @claude-flow/cli headless --worker <type>
 *   npx @claude-flow/cli headless --daemon
 *   npx @claude-flow/cli headless --benchmark
 *
 * Environment:
 *   CLAUDE_FLOW_HEADLESS=true
 *   CLAUDE_CODE_HEADLESS=true
 *
 * @module v3/cli/runtime/headless
 */

import { HeadlessWorkerExecutor, HEADLESS_WORKER_TYPES, type HeadlessWorkerType } from '../services/headless-worker-executor.js';
import { WorkerDaemon, getDaemon, startDaemon, stopDaemon } from '../services/worker-daemon.js';
import {
  initializeIntelligence,
  benchmarkAdaptation,
  getIntelligenceStats
} from '../memory/intelligence.js';
import {
  getHNSWStatus,
  batchCosineSim,
  flashAttentionSearch
} from '../memory/memory-initializer.js';

// ============================================================================
// Types
// ============================================================================

interface HeadlessConfig {
  mode: 'worker' | 'daemon' | 'benchmark' | 'status';
  workerType?: HeadlessWorkerType;
  timeout?: number;
  verbose?: boolean;
}

interface BenchmarkResults {
  sona: {
    avgMs: number;
    targetMet: boolean;
  };
  flashAttention: {
    throughputPerMs: number;
    speedup: number;
  };
  hnsw: {
    entriesIndexed: number;
    searchTime: number;
  };
}

// ============================================================================
// Main Runtime
// ============================================================================

/**
 * Parse command line arguments
 */
function parseArgs(): HeadlessConfig {
  const args = process.argv.slice(2);
  const config: HeadlessConfig = {
    mode: 'status',
    verbose: false
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg === '--worker' || arg === '-w') {
      config.mode = 'worker';
      config.workerType = args[++i] as HeadlessWorkerType;
    } else if (arg === '--daemon' || arg === '-d') {
      config.mode = 'daemon';
    } else if (arg === '--benchmark' || arg === '-b') {
      config.mode = 'benchmark';
    } else if (arg === '--status' || arg === '-s') {
      config.mode = 'status';
    } else if (arg === '--timeout' || arg === '-t') {
      config.timeout = parseInt(args[++i], 10) || 60000;
    } else if (arg === '--verbose' || arg === '-v') {
      config.verbose = true;
    } else if (arg === '--help' || arg === '-h') {
      showHelp();
      process.exit(0);
    }
  }

  return config;
}

/**
 * Show help message
 */
function showHelp(): void {
  console.log(`
Headless Runtime for RuFlo V3

Usage:
  headless --worker <type>    Run a specific worker
  headless --daemon           Start background daemon
  headless --benchmark        Run performance benchmarks
  headless --status           Show system status

Workers: ${HEADLESS_WORKER_TYPES.join(', ')}

Options:
  -w, --worker <type>   Worker type to run
  -d, --daemon          Run as daemon
  -b, --benchmark       Run benchmarks
  -s, --status          Show status
  -t, --timeout <ms>    Execution timeout (default: 60000)
  -v, --verbose         Verbose output
  -h, --help            Show help

Environment:
  CLAUDE_FLOW_HEADLESS=true   Enable headless mode
  CLAUDE_CODE_HEADLESS=true   Enable Claude Code headless

Examples:
  headless --worker audit --timeout 120000
  headless --daemon
  headless --benchmark
`);
}

/**
 * Run a specific worker
 */
async function runWorker(workerType: HeadlessWorkerType, timeout: number): Promise<void> {
  console.log(`[Headless] Starting worker: ${workerType}`);

  const executor = new HeadlessWorkerExecutor(process.cwd(), {
    maxConcurrent: 1,
    defaultTimeoutMs: timeout
  });

  try {
    const result = await executor.execute(workerType, {
      timeoutMs: timeout,
      model: 'sonnet',
      sandbox: 'permissive'
    });

    if (result.success) {
      console.log(`[Headless] Worker ${workerType} completed successfully`);
      console.log(`[Headless] Duration: ${result.durationMs}ms`);
      if (result.output) {
        console.log(`[Headless] Output: ${JSON.stringify(result.output).slice(0, 500)}...`);
      }
    } else {
      console.error(`[Headless] Worker ${workerType} failed: ${result.error}`);
      process.exit(1);
    }
  } finally {
    // executor doesn't have shutdown, just let it be garbage collected
  }
}

/**
 * Run daemon mode
 */
async function runDaemon(): Promise<void> {
  console.log('[Headless] Starting daemon mode...');

  // Start the daemon
  const daemon = await startDaemon(process.cwd());

  console.log('[Headless] Daemon started');
  console.log('[Headless] Press Ctrl+C to stop');

  // Handle shutdown
  process.on('SIGINT', async () => {
    console.log('\n[Headless] Shutting down daemon...');
    await stopDaemon();
    process.exit(0);
  });

  process.on('SIGTERM', async () => {
    console.log('\n[Headless] Received SIGTERM, shutting down...');
    await stopDaemon();
    process.exit(0);
  });

  // Keep process running
  await new Promise(() => {});
}

/**
 * Run benchmarks
 */
async function runBenchmarks(): Promise<BenchmarkResults> {
  console.log('=== RuFlo V3 Performance Benchmarks ===\n');

  // Initialize intelligence
  await initializeIntelligence();

  // SONA Benchmark
  console.log('1. SONA Adaptation Benchmark (10,000 iterations)...');
  const sonaResult = benchmarkAdaptation(10000);
  console.log(`   Average: ${sonaResult.avgMs.toFixed(4)}ms`);
  console.log(`   Target (<0.05ms): ${sonaResult.targetMet ? '✅ ACHIEVED' : '❌ NOT MET'}`);

  // Flash Attention Benchmark
  console.log('\n2. Flash Attention Search Benchmark...');
  const dim = 384;
  const count = 10000;
  const query = new Float32Array(dim).map(() => Math.random() - 0.5);
  const vectors = Array.from({ length: count }, () =>
    new Float32Array(dim).map(() => Math.random() - 0.5)
  );

  // Warmup
  flashAttentionSearch(query, vectors, { k: 10 });

  const flashStart = performance.now();
  for (let i = 0; i < 10; i++) {
    flashAttentionSearch(query, vectors, { k: 10 });
  }
  const flashTime = (performance.now() - flashStart) / 10;
  const throughput = count / flashTime;

  // Brute force comparison
  const bruteStart = performance.now();
  for (let i = 0; i < 10; i++) {
    const scores = batchCosineSim(query, vectors);
    Array.from({ length: count }, (_, i) => i)
      .sort((a, b) => scores[b] - scores[a])
      .slice(0, 10);
  }
  const bruteTime = (performance.now() - bruteStart) / 10;
  const speedup = bruteTime / flashTime;

  console.log(`   Throughput: ${throughput.toFixed(0)} vectors/ms`);
  console.log(`   Time for 10k vectors: ${flashTime.toFixed(2)}ms`);
  console.log(`   Speedup vs brute force: ${speedup.toFixed(2)}x`);

  // HNSW Status
  console.log('\n3. HNSW Index Status...');
  const hnswStatus = getHNSWStatus();
  console.log(`   Entries indexed: ${hnswStatus.entryCount}`);
  console.log(`   Initialized: ${hnswStatus.initialized}`);

  // Intelligence Stats
  console.log('\n4. Intelligence System Stats...');
  const stats = getIntelligenceStats();
  console.log(`   SONA enabled: ${stats.sonaEnabled}`);
  console.log(`   Patterns learned: ${stats.patternsLearned}`);
  console.log(`   Avg adaptation time: ${stats.avgAdaptationTime.toFixed(4)}ms`);

  console.log('\n=== Benchmark Complete ===');

  return {
    sona: {
      avgMs: sonaResult.avgMs,
      targetMet: sonaResult.targetMet
    },
    flashAttention: {
      throughputPerMs: throughput,
      speedup
    },
    hnsw: {
      entriesIndexed: hnswStatus.entryCount,
      searchTime: flashTime
    }
  };
}

/**
 * Show system status
 */
async function showStatus(): Promise<void> {
  console.log('=== RuFlo V3 System Status ===\n');

  // Check daemon
  const daemon = getDaemon();
  console.log('Daemon:');
  if (daemon) {
    const status = daemon.getStatus();
    console.log(`  Running: ${status.running}`);
    console.log(`  PID: ${status.pid}`);
    console.log(`  Workers: ${status.workers.size}`);
  } else {
    console.log('  Not initialized');
  }

  // Intelligence
  const stats = getIntelligenceStats();
  console.log('\nIntelligence:');
  console.log(`  SONA enabled: ${stats.sonaEnabled}`);
  console.log(`  ReasoningBank size: ${stats.reasoningBankSize}`);
  console.log(`  Patterns learned: ${stats.patternsLearned}`);

  // HNSW
  const hnsw = getHNSWStatus();
  console.log('\nHNSW Index:');
  console.log(`  Initialized: ${hnsw.initialized}`);
  console.log(`  Entries: ${hnsw.entryCount}`);

  console.log('\nEnvironment:');
  console.log(`  CLAUDE_FLOW_HEADLESS: ${process.env.CLAUDE_FLOW_HEADLESS || 'not set'}`);
  console.log(`  CLAUDE_CODE_HEADLESS: ${process.env.CLAUDE_CODE_HEADLESS || 'not set'}`);
  console.log(`  NODE_ENV: ${process.env.NODE_ENV || 'development'}`);
}

/**
 * Main entry point
 */
async function main(): Promise<void> {
  // Set headless environment
  process.env.CLAUDE_FLOW_HEADLESS = 'true';

  const config = parseArgs();

  try {
    switch (config.mode) {
      case 'worker':
        if (!config.workerType || !HEADLESS_WORKER_TYPES.includes(config.workerType)) {
          console.error(`Invalid worker type. Available: ${HEADLESS_WORKER_TYPES.join(', ')}`);
          process.exit(1);
        }
        await runWorker(config.workerType, config.timeout || 60000);
        break;

      case 'daemon':
        await runDaemon();
        break;

      case 'benchmark':
        await runBenchmarks();
        break;

      case 'status':
      default:
        await showStatus();
        break;
    }
  } catch (error) {
    console.error('[Headless] Error:', error instanceof Error ? error.message : String(error));
    process.exit(1);
  }
}

// Run if executed directly
main().catch(console.error);

export { main, runWorker, runDaemon, runBenchmarks, showStatus };
export type { HeadlessConfig, BenchmarkResults };

/**
 * Parent-death watchdog (#2234).
 *
 * `ruflo mcp start` runs as a double-forked grandchild of Claude Code (`npx -y
 * ruflo … mcp start` → `npm exec …` → `node … mcp start`). When Claude Code
 * exits, only the `npm exec` shim is terminated; the `node` server reparents to
 * `launchd`/`init` (`ppid === 1`) and silently lingers — leaving ~50 MB and an
 * open database handle per restart. Over a week this accumulates to ~20
 * orphaned servers (~1 GB), and an arbitrary stale one can win the next stdio
 * handshake, transparently serving superseded code.
 *
 * Cheap, robust fix: poll `process.ppid`. When it becomes 1 (and didn't start
 * there), our original parent has exited — we're orphaned. Run the cleanup
 * hook and exit cleanly.
 *
 * @module runtime/parent-death-watchdog
 */

export interface ParentDeathWatchdogOptions {
  /** Poll interval in ms. Default 2000. */
  intervalMs?: number;
  /**
   * Cleanup hook fired when orphaning is detected. May be async. After it
   * resolves (or throws), the process exits with code 0 (success) / 1 (error).
   * Defaults to `process.exit(0)` directly.
   */
  onOrphaned?: () => void | Promise<void>;
  /** Override `process.ppid` getter (tests). */
  ppidGetter?: () => number;
  /** Override `process.exit` (tests). */
  exit?: (code: number) => void;
}

export interface ParentDeathWatchdog {
  stop(): void;
  /** Manually trigger the orphan check (used by tests). */
  checkOnce(): Promise<void>;
}

/**
 * Install a parent-death watchdog. Safe to call once per process; calling
 * twice replaces the previous interval.
 */
export function installParentDeathWatchdog(opts: ParentDeathWatchdogOptions = {}): ParentDeathWatchdog {
  const intervalMs = opts.intervalMs ?? 2000;
  const get = opts.ppidGetter ?? (() => process.ppid);
  const exit = opts.exit ?? ((code: number) => process.exit(code));
  const onOrphaned = opts.onOrphaned;

  const initialPpid = get();
  let triggered = false;
  let timer: NodeJS.Timeout | undefined;

  const triggerOrphaned = async (): Promise<void> => {
    if (triggered) return;
    triggered = true;
    if (timer) {
      clearInterval(timer);
      timer = undefined;
    }
    try {
      if (onOrphaned) await onOrphaned();
      exit(0);
    } catch {
      exit(1);
    }
  };

  const checkOnce = async (): Promise<void> => {
    // Only trigger when we *transition* to ppid=1; if we already started there
    // (process launched directly under launchd/init) it isn't an orphan event.
    const ppid = get();
    if (ppid === 1 && initialPpid !== 1) await triggerOrphaned();
  };

  timer = setInterval(() => {
    void checkOnce();
  }, intervalMs);
  // Don't keep the event loop alive on the watchdog alone.
  if (typeof (timer as NodeJS.Timeout).unref === 'function') (timer as NodeJS.Timeout).unref();

  return {
    stop() {
      if (timer) {
        clearInterval(timer);
        timer = undefined;
      }
    },
    checkOnce,
  };
}

# RuVector NPM Package API Documentation

Version: 0.1.95
Package: `ruvector`
Repository: https://github.com/ruvnet/ruvector

## Overview

RuVector is a high-performance vector database for Node.js with automatic native/WASM fallback. It provides self-learning intelligence for Claude Code with Q-learning optimization, vector memory, and automatic agent routing.

## Installation

```bash
npm install ruvector
```

## MCP Server Integration

Add to Claude Code:

```bash
claude mcp add ruvector-mcp -- npx ruvector mcp-server
```

---

## Hooks API Reference

The hooks API provides 30+ MCP tools for intelligent agent routing, code analysis, and self-learning capabilities.

### Core Routing Functions

#### `hooks_route`

Routes a task to the best agent based on learned patterns.

**Input Parameters:**
| Parameter | Type | Required | Description |
|-----------|------|----------|-------------|
| `task` | string | Yes | Task description to route |
| `file` | string | No | File path for context-aware routing |

**Return Type:**
```typescript
interface RouteResult {
  success: boolean;
  task: string;
  file?: string;
  agent: string;           // Recommended agent (e.g., "typescript-developer")
  confidence: number;      // Confidence score 0.0-1.0
  reason: string;          // Explanation for routing decision
  alternates?: string[];   // Alternative agent suggestions
  sonaPatterns?: number;   // Number of SONA patterns used (if engine enabled)
  engineRouted?: boolean;  // Whether full engine was used
}
```

**Example Usage:**
```javascript
// MCP Tool Call
const result = await mcp.call('hooks_route', {
  task: 'implement user authentication',
  file: 'src/auth/login.ts'
});

// CLI Usage
npx ruvector hooks route "implement user login"
```

**Error Handling:**
- Returns default agent mapping if no patterns learned
- Falls back to file extension-based routing if task unclear

