interface DeployOptions {
  output?: string;
  toIpfs: boolean;
  anonymize: AnonymizationLevel;
  pin: boolean;
  gateway: string;
  validate: boolean;
  verbose: boolean;
}

/**
 * Parse CLI arguments
 */
function parseArgs(): DeployOptions {
  const args = process.argv.slice(2);
  const options: DeployOptions = {
    toIpfs: false,
    anonymize: 'standard',
    pin: true,
    gateway: 'https://w3s.link',
    validate: true,
    verbose: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    switch (arg) {
      case '--output':
      case '-o':
        options.output = args[++i];
        break;
      case '--to-ipfs':
      case '--ipfs':
        options.toIpfs = true;
        break;
      case '--anonymize':
      case '-a':
        options.anonymize = args[++i] as AnonymizationLevel;
        break;
      case '--no-pin':
        options.pin = false;
        break;
      case '--gateway':
      case '-g':
        options.gateway = args[++i];
        break;
      case '--no-validate':
        options.validate = false;
        break;
      case '--verbose':
      case '-v':
        options.verbose = true;
        break;
      case '--help':
      case '-h':
        printHelp();
        process.exit(0);
    }
  }

  return options;
}

