/**
 * CFP Format Serializer
 * Claude Flow Pattern format serialization
 */

import type { CFPFormat, SerializationFormat, PatternCollection } from '../types.js';
import * as crypto from 'crypto';

// Version info
const CFP_VERSION = '1.0.0';
const GENERATOR = 'claude-flow@3.0.0-alpha';

/**
 * Create a new CFP document
 */
export function createCFP(options: {
  name: string;
  description: string;
  patterns: PatternCollection;
  author?: { id: string; displayName?: string };
  license?: string;
  tags?: string[];
  language?: string;
  framework?: string;
}): CFPFormat {
  const now = new Date().toISOString();
  const id = crypto.randomUUID();

  return {
    magic: 'CFP1',
    version: CFP_VERSION,
    createdAt: now,
    generatedBy: GENERATOR,

    metadata: {
      id,
      name: options.name,
      description: options.description,
      author: options.author ? {
        id: options.author.id,
        displayName: options.author.displayName,
        verified: false,
      } : undefined,
      license: options.license || 'MIT',
      tags: options.tags || [],
      language: options.language,
      framework: options.framework,
      createdAt: now,
      updatedAt: now,
    },

    anonymization: {
      level: 'minimal',
      appliedTransforms: [],
      piiRedacted: false,
      pathsStripped: false,
      timestampsGeneralized: false,
      checksum: '',
    },

    patterns: options.patterns,

    statistics: calculateStatistics(options.patterns),
  };
}

/**
 * Calculate pattern statistics
 */
function calculateStatistics(patterns: PatternCollection): CFPFormat['statistics'] {
  const counts: Record<string, number> = {
    routing: patterns.routing.length,
    complexity: patterns.complexity.length,
    coverage: patterns.coverage.length,
    trajectory: patterns.trajectory.length,
    custom: patterns.custom.length,
  };

  const total = Object.values(counts).reduce((a, b) => a + b, 0);

  // Calculate average confidence from routing patterns
  const confidences = patterns.routing.map(p => p.confidence);
  const avgConfidence = confidences.length > 0
    ? confidences.reduce((a, b) => a + b, 0) / confidences.length
    : 0;

  return {
    totalPatterns: total,
    avgConfidence,
    patternTypes: counts,
    timeRange: {
      start: new Date().toISOString(),
      end: new Date().toISOString(),
    },
  };
}

/**
 * Serialize CFP to JSON string
 */
export function serializeToJson(cfp: CFPFormat): string {
  // Calculate checksum before serialization
  const content = JSON.stringify({
    magic: cfp.magic,
    version: cfp.version,
    metadata: cfp.metadata,
    patterns: cfp.patterns,
  });

  cfp.anonymization.checksum = crypto
    .createHash('sha256')
    .update(content)
    .digest('hex');

  return JSON.stringify(cfp, null, 2);
}

/**
 * Serialize CFP to Buffer (for CBOR/binary formats)
 */
export function serializeToBuffer(cfp: CFPFormat, format: SerializationFormat): Buffer {
  // For now, just use JSON - in production, would use cbor-x or msgpack
  const json = serializeToJson(cfp);

  switch (format) {
    case 'json':
      return Buffer.from(json, 'utf-8');
    case 'cbor':
    case 'cbor.gz':
    case 'cbor.zstd':
    case 'msgpack':
      throw new Error(`Serialization format '${format}' is not implemented. Use 'json' instead.`);
    default:
      return Buffer.from(json, 'utf-8');
  }
}

/**
 * Deserialize CFP from string/buffer
 */
export function deserializeCFP(data: string | Buffer): CFPFormat {
  const str = typeof data === 'string' ? data : data.toString('utf-8');

  let parsed: CFPFormat;
  try {
    parsed = JSON.parse(str);
  } catch (e) {
    throw new Error(`Invalid CFP file: ${e instanceof Error ? e.message : String(e)}`);
  }

  // Validate magic bytes
  if (parsed.magic !== 'CFP1') {
    throw new Error(`Invalid CFP format: expected magic 'CFP1', got '${parsed.magic}'`);
  }

  return parsed;
}

/**
 * Validate CFP document
 */
export function validateCFP(cfp: CFPFormat): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  if (cfp.magic !== 'CFP1') {
    errors.push(`Invalid magic bytes: ${cfp.magic}`);
  }

  if (!cfp.version) {
    errors.push('Missing version');
  }

  if (!cfp.metadata?.id) {
    errors.push('Missing metadata.id');
  }

  if (!cfp.patterns) {
    errors.push('Missing patterns');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Get file extension for format
 */
export function getFileExtension(format: SerializationFormat): string {
  switch (format) {
    case 'json':
      return '.cfp.json';
    case 'cbor':
      return '.cfp';
    case 'cbor.gz':
      return '.cfp.gz';
    case 'cbor.zstd':
      return '.cfp.zst';
    case 'msgpack':
      return '.cfp.mp';
    default:
      return '.cfp';
  }
}

/**
 * Detect format from file path
 */
export function detectFormat(filePath: string): SerializationFormat {
  if (filePath.endsWith('.cfp.json')) return 'json';
  if (filePath.endsWith('.cfp.gz')) return 'cbor.gz';
  if (filePath.endsWith('.cfp.zst')) return 'cbor.zstd';
  if (filePath.endsWith('.cfp.mp')) return 'msgpack';
  return 'cbor';
}

/**
 * Google Cloud Storage Backend
 * Real storage implementation using gcloud CLI or GCS APIs
 *
 * @module @claude-flow/cli/transfer/storage/gcs
 * @version 3.0.0
 */

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { execFileSync } from 'child_process';

/**
 * GCS configuration
 */
export interface GCSConfig {
  bucket: string;
  projectId?: string;
  keyFile?: string;
  prefix?: string;
}

/**
 * GCS upload result
 */
export interface GCSUploadResult {
  success: boolean;
  uri: string;
  publicUrl: string;
  size: number;
  checksum: string;
  contentId: string;
}

/**
 * Get GCS configuration from environment
 */
export function getGCSConfig(): GCSConfig | null {
  const bucket = process.env.GCS_BUCKET || process.env.GOOGLE_CLOUD_BUCKET;
  if (!bucket) return null;

  return {
    bucket,
    projectId: process.env.GCS_PROJECT_ID || process.env.GOOGLE_CLOUD_PROJECT,
    keyFile: process.env.GOOGLE_APPLICATION_CREDENTIALS,
    prefix: process.env.GCS_PREFIX || 'claude-flow-patterns',
  };
}

/**
 * Validate GCS bucket name (prevents command injection via bucket names)
 */
function isValidBucketName(bucket: string): boolean {
  return /^[a-z0-9][a-z0-9._-]{1,221}[a-z0-9]$/.test(bucket);
}

/**
 * Validate GCS object path (no shell metacharacters)
 */
function isValidObjectPath(objectPath: string): boolean {
  return /^[a-zA-Z0-9_.\/\-]+$/.test(objectPath);
}

/**
 * Check if gcloud CLI is available
 */
export function isGCloudAvailable(): boolean {
  try {
    execFileSync('gcloud', ['--version'], { stdio: 'pipe' });
    return true;
  } catch {
    return false;
  }
}

/**
 * Check if authenticated with gcloud
 */
export async function isGCloudAuthenticated(): Promise<boolean> {
  try {
    execFileSync('gcloud', ['auth', 'print-access-token'], { stdio: 'pipe' });
    return true;
  } catch {
    return false;
  }
}

/**
 * Generate content ID from content hash
 */
function generateContentId(content: Buffer): string {
  const hash = crypto.createHash('sha256').update(content).digest('hex');
  return `cfp-${hash.slice(0, 16)}`;
}

/**
 * Upload content to Google Cloud Storage using gcloud CLI
 */
export async function uploadToGCS(
  content: Buffer,
  options: {
    name?: string;
    contentType?: string;
    config?: GCSConfig;
    metadata?: Record<string, string>;
  } = {}
): Promise<GCSUploadResult> {
  const config = options.config || getGCSConfig();
  if (!config) {
    throw new Error(
      'GCS not configured. Set GCS_BUCKET environment variable.\n' +
      'Or authenticate: gcloud auth login && gcloud config set project YOUR_PROJECT'
    );
  }

  const contentId = generateContentId(content);
  const checksum = crypto.createHash('sha256').update(content).digest('hex');
  const fileName = options.name || `${contentId}.cfp.json`;

  // Validate filename to prevent path traversal
  if (!/^[a-zA-Z0-9._\-]+$/.test(fileName) || fileName.includes('..')) {
    throw new Error(`Invalid filename: ${fileName}`);
  }

  const objectPath = config.prefix ? `${config.prefix}/${fileName}` : fileName;

  // S-1: Validate bucket name and object path to prevent command injection
  if (!isValidBucketName(config.bucket)) {
    throw new Error(`Invalid GCS bucket name: ${config.bucket}`);
  }
  if (!isValidObjectPath(objectPath)) {
    throw new Error(`Invalid GCS object path: ${objectPath}`);
  }

  console.log(`[GCS] Uploading to gs://${config.bucket}/${objectPath}...`);

  // Write content to temp file
  const tempDir = process.env.TMPDIR || '/tmp';
  const tempFile = path.join(tempDir, `claude-flow-upload-${Date.now()}.json`);
  fs.writeFileSync(tempFile, content);

  try {
    // Build gcloud args (array form prevents shell injection)
    const uploadArgs = ['storage', 'cp', tempFile, `gs://${config.bucket}/${objectPath}`];
    if (config.projectId) uploadArgs.push(`--project=${config.projectId}`);
    uploadArgs.push(`--content-type=${options.contentType || 'application/json'}`);

    execFileSync('gcloud', uploadArgs, { encoding: 'utf-8', stdio: 'pipe' });

    // Set metadata if provided
    if (options.metadata && Object.keys(options.metadata).length > 0) {
      const metadataJson = JSON.stringify(options.metadata);
      try {
        const metaArgs = ['storage', 'objects', 'update', `gs://${config.bucket}/${objectPath}`, `--custom-metadata=${metadataJson}`];
        if (config.projectId) metaArgs.push(`--project=${config.projectId}`);
        execFileSync('gcloud', metaArgs, { encoding: 'utf-8', stdio: 'pipe' });
      } catch {
        // Metadata update failed, but upload succeeded
      }
    }

    // Clean up temp file (validate path is within temp dir)
    const resolvedTemp = path.resolve(tempFile);
    if (resolvedTemp.startsWith(path.resolve(tempDir))) {
      fs.unlinkSync(tempFile);
    }

    const uri = `gs://${config.bucket}/${objectPath}`;
    const publicUrl = `https://storage.googleapis.com/${config.bucket}/${objectPath}`;

    console.log(`[GCS] Upload complete: ${uri}`);

    return {
      success: true,
      uri,
      publicUrl,
      size: content.length,
      checksum,
      contentId,
    };
  } catch (error) {
    // Clean up temp file on error (validate path is within temp dir)
    try {
      const resolvedTemp = path.resolve(tempFile);
      if (resolvedTemp.startsWith(path.resolve(tempDir))) {
        fs.unlinkSync(tempFile);
      }
    } catch { /* ignore */ }

    throw new Error(`GCS upload failed: ${error}`);
  }
}

/**
 * Download content from Google Cloud Storage
 */
export async function downloadFromGCS(
  uri: string,
  config?: GCSConfig
): Promise<Buffer | null> {
  const cfg = config || getGCSConfig();

  console.log(`[GCS] Downloading from ${uri}...`);

  // Write to temp file first
  const tempDir = process.env.TMPDIR || '/tmp';
  const tempFile = path.join(tempDir, `claude-flow-download-${Date.now()}.json`);

  try {
    // Download using gcloud storage cp (array form prevents shell injection)
    const downloadArgs = ['storage', 'cp', uri, tempFile];
    if (cfg?.projectId) downloadArgs.push(`--project=${cfg.projectId}`);
    execFileSync('gcloud', downloadArgs, { encoding: 'utf-8', stdio: 'pipe' });

    const content = fs.readFileSync(tempFile);
    const resolvedTemp = path.resolve(tempFile);
    if (resolvedTemp.startsWith(path.resolve(tempDir))) {
      fs.unlinkSync(tempFile);
    }

    console.log(`[GCS] Downloaded ${content.length} bytes`);
    return content;
  } catch (error) {
    try {
      const resolvedTemp = path.resolve(tempFile);
      if (resolvedTemp.startsWith(path.resolve(tempDir))) {
        fs.unlinkSync(tempFile);
      }
    } catch { /* ignore */ }

    console.error(`[GCS] Download failed: ${error}`);
    return null;
  }
}

/**
 * Check if object exists in GCS
 */
export async function existsInGCS(
  uri: string,
  config?: GCSConfig
): Promise<boolean> {
  const cfg = config || getGCSConfig();

  try {
    const lsArgs = ['storage', 'ls', uri];
    if (cfg?.projectId) lsArgs.push(`--project=${cfg.projectId}`);
    execFileSync('gcloud', lsArgs, { encoding: 'utf-8', stdio: 'pipe' });
    return true;
  } catch {
    return false;
  }
}

/**
 * List objects in GCS bucket with prefix
 */
export async function listGCSObjects(
  prefix?: string,
  config?: GCSConfig
): Promise<Array<{ name: string; size: number; updated: string }>> {
  const cfg = config || getGCSConfig();
  if (!cfg) return [];

  const objectPrefix = prefix || cfg.prefix || '';
  const uri = `gs://${cfg.bucket}/${objectPrefix}`;

  try {
    const listArgs = ['storage', 'ls', '-l', uri, '--format=json'];
    if (cfg.projectId) listArgs.push(`--project=${cfg.projectId}`);
    const result = execFileSync('gcloud', listArgs, { encoding: 'utf-8', stdio: 'pipe' });

    const objects = JSON.parse(result);
    return objects.map((obj: { name: string; size: number; updated: string }) => ({
      name: obj.name,
      size: obj.size || 0,
      updated: obj.updated || new Date().toISOString(),
    }));
  } catch {
    return [];
  }
}

/**
 * Delete object from GCS
 */
export async function deleteFromGCS(
  uri: string,
  config?: GCSConfig
): Promise<boolean> {
  const cfg = config || getGCSConfig();

  try {
    const rmArgs = ['storage', 'rm', uri];
    if (cfg?.projectId) rmArgs.push(`--project=${cfg.projectId}`);
    execFileSync('gcloud', rmArgs, { encoding: 'utf-8', stdio: 'pipe' });
    return true;
  } catch {
    return false;
  }
}

/**
 * Get GCS storage status
 */
export function getGCSStatus(): {
  available: boolean;
  authenticated: boolean;
  bucket?: string;
  message: string;
} {
  const config = getGCSConfig();
  const gcloudAvailable = isGCloudAvailable();

  if (!gcloudAvailable) {
    return {
      available: false,
      authenticated: false,
      message: 'gcloud CLI not installed. Install from: https://cloud.google.com/sdk/docs/install',
    };
  }

  if (!config?.bucket) {
    return {
      available: true,
      authenticated: false,
      message: 'GCS bucket not configured. Set GCS_BUCKET environment variable.',
    };
  }

  return {
    available: true,
    authenticated: true,
    bucket: config.bucket,
    message: `GCS configured with bucket: ${config.bucket}`,
  };
}

/**
 * Export for storage backend detection
 */
export function hasGCSCredentials(): boolean {
  return !!getGCSConfig() && isGCloudAvailable();
}

/**
 * Storage Backends
 * Supports IPFS and Google Cloud Storage for pattern transfer
 */

export * from './gcs.js';

/**
 * IPFS-Based Pattern Discovery
 * Secure discovery mechanism for finding patterns in decentralized environment
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import type {
  PatternRegistry,
  PatternEntry,
  KnownRegistry,
  StoreConfig,
} from './types.js';
import {
  BOOTSTRAP_REGISTRIES,
  DEFAULT_STORE_CONFIG,
  deserializeRegistry,
} from './registry.js';

/**
 * Discovery result
 */
export interface DiscoveryResult {
  success: boolean;
  registry?: PatternRegistry;
  source: string;
  fromCache: boolean;
  cid?: string;
  error?: string;
}

/**
 * Resolved IPNS result
 */
export interface IPNSResolution {
  ipnsName: string;
  cid: string;
  resolvedAt: string;
  expiresAt: string;
}

/**
 * Pattern Store Discovery Service
 * Handles secure discovery of pattern registries via IPFS/IPNS
 */
export class PatternDiscovery {
  private config: StoreConfig;
  private cache: Map<string, { registry: PatternRegistry; expiresAt: number }>;
  private ipnsCache: Map<string, IPNSResolution>;

  constructor(config: Partial<StoreConfig> = {}) {
    this.config = { ...DEFAULT_STORE_CONFIG, ...config };
    this.cache = new Map();
    this.ipnsCache = new Map();
  }

  /**
   * Discover and load the pattern registry
   */
  async discoverRegistry(registryName?: string): Promise<DiscoveryResult> {
    const targetRegistry = registryName || this.config.defaultRegistry;
    const knownRegistry = this.config.registries.find(r => r.name === targetRegistry);

    if (!knownRegistry) {
      return {
        success: false,
        source: targetRegistry,
        fromCache: false,
        error: `Unknown registry: ${targetRegistry}`,
      };
    }

    console.log(`[Discovery] Looking for registry: ${knownRegistry.name}`);

    // Check cache first
    const cached = this.getCachedRegistry(knownRegistry.ipnsName);
    if (cached) {
      console.log(`[Discovery] Found in cache`);
      return {
        success: true,
        registry: cached,
        source: knownRegistry.name,
        fromCache: true,
      };
    }

    // Resolve IPNS to get current CID
    console.log(`[Discovery] Resolving IPNS: ${knownRegistry.ipnsName}`);
    const resolution = await this.resolveIPNS(knownRegistry.ipnsName);

    if (!resolution) {
      return {
        success: false,
        source: knownRegistry.name,
        fromCache: false,
        error: 'Failed to resolve IPNS name',
      };
    }

    // Fetch registry from IPFS
    console.log(`[Discovery] Fetching from IPFS: ${resolution.cid}`);
    const registry = await this.fetchRegistry(resolution.cid, knownRegistry.gateway);

    if (!registry) {
      return {
        success: false,
        source: knownRegistry.name,
        fromCache: false,
        cid: resolution.cid,
        error: 'Failed to fetch registry from IPFS',
      };
    }

    // Verify registry if trusted
    if (knownRegistry.trusted && registry.registrySignature) {
      const verified = this.verifyRegistry(registry, knownRegistry.publicKey);
      if (!verified) {
        console.warn(`[Discovery] Warning: Registry signature verification failed`);
      }
    }

    // Cache the result
    this.cacheRegistry(knownRegistry.ipnsName, registry);

    return {
      success: true,
      registry,
      source: knownRegistry.name,
      fromCache: false,
      cid: resolution.cid,
    };
  }

  /**
   * Resolve IPNS name to CID via real IPFS gateway
   */
  async resolveIPNS(ipnsName: string): Promise<IPNSResolution | null> {
    // Check cache
    const cached = this.ipnsCache.get(ipnsName);
    if (cached && new Date(cached.expiresAt) > new Date()) {
      return cached;
    }

    const gateways = [
      'https://ipfs.io',
      'https://dweb.link',
      'https://cloudflare-ipfs.com',
    ];

    for (const gateway of gateways) {
      try {
        console.log(`[Discovery] Resolving IPNS via ${gateway}...`);

        // Try IPNS resolution endpoint
        const response = await fetch(`${gateway}/api/v0/name/resolve?arg=${ipnsName}`, {
          method: 'POST',
          signal: AbortSignal.timeout(10000),
        });

        if (response.ok) {
          const data = await response.json() as { Path: string };
          const cid = data.Path?.replace('/ipfs/', '') || '';

          if (cid) {
            const resolution: IPNSResolution = {
              ipnsName,
              cid,
              resolvedAt: new Date().toISOString(),
              expiresAt: new Date(Date.now() + 3600000).toISOString(), // 1 hour
            };

            this.ipnsCache.set(ipnsName, resolution);
            console.log(`[Discovery] Resolved IPNS to CID: ${cid}`);
            return resolution;
          }
        }

        // Fallback: Try fetching content directly via IPNS gateway URL
        const ipnsResponse = await fetch(`${gateway}/ipns/${ipnsName}`, {
          method: 'HEAD',
          signal: AbortSignal.timeout(10000),
          redirect: 'follow',
        });

        if (ipnsResponse.ok) {
          // Extract CID from final URL if redirected
          const finalUrl = ipnsResponse.url;
          const cidMatch = finalUrl.match(/\/ipfs\/([a-zA-Z0-9]+)/);
          if (cidMatch) {
            const cid = cidMatch[1];
            const resolution: IPNSResolution = {
              ipnsName,
              cid,
              resolvedAt: new Date().toISOString(),
              expiresAt: new Date(Date.now() + 3600000).toISOString(),
            };

            this.ipnsCache.set(ipnsName, resolution);
            console.log(`[Discovery] Resolved IPNS via redirect to CID: ${cid}`);
            return resolution;
          }
        }
      } catch (error) {
        console.warn(`[Discovery] IPNS resolution via ${gateway} failed:`, error);
        // Continue to next gateway
      }
    }

    // Fallback: Generate deterministic CID for well-known registries
    console.warn(`⚠ [Discovery] OFFLINE MODE - Could not resolve IPNS: ${ipnsName}`);
    console.warn(`⚠ [Discovery] Using built-in fallback registry (may be outdated)`);
    const fallbackCid = this.generateFallbackCID(ipnsName);
    const resolution: IPNSResolution = {
      ipnsName,
      cid: fallbackCid,
      resolvedAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + 3600000).toISOString(),
    };

    this.ipnsCache.set(ipnsName, resolution);
    return resolution;
  }

  /**
   * Generate deterministic fallback CID for offline/demo mode
   */
  private generateFallbackCID(input: string): string {
    const hash = crypto.createHash('sha256').update(input + 'registry').digest();
    const prefix = 'bafybei';
    const base32Chars = 'abcdefghijklmnopqrstuvwxyz234567';
    let result = prefix;
    for (let i = 0; i < 44; i++) {
      result += base32Chars[hash[i % hash.length] % 32];
    }
    return result;
  }

  /**
   * Fetch registry from IPFS gateway
   */
  async fetchRegistry(cid: string, gateway: string): Promise<PatternRegistry | null> {
    const url = `${gateway}/ipfs/${cid}`;
    console.log(`[Discovery] Fetching: ${url}`);

    try {
      const response = await fetch(url, {
        signal: AbortSignal.timeout(30000),
      });

      if (response.ok) {
        const text = await response.text();
        try {
          const registry = JSON.parse(text) as PatternRegistry;
          console.log(`[Discovery] Fetched registry with ${registry.patterns?.length || 0} patterns`);
          return registry;
        } catch {
          console.error(`[Discovery] Invalid registry JSON`);
        }
      }
    } catch (error) {
      console.warn(`[Discovery] Fetch from ${gateway} failed:`, error);
    }

    // Try alternative gateways
    const alternativeGateways = [
      'https://ipfs.io',
      'https://dweb.link',
      'https://cloudflare-ipfs.com',
      'https://gateway.pinata.cloud',
    ];

    for (const altGateway of alternativeGateways) {
      if (altGateway === gateway) continue;
      try {
        const altUrl = `${altGateway}/ipfs/${cid}`;
        console.log(`[Discovery] Trying alternative: ${altUrl}`);

        const response = await fetch(altUrl, {
          signal: AbortSignal.timeout(15000),
        });

        if (response.ok) {
          const registry = await response.json() as PatternRegistry;
          console.log(`[Discovery] Fetched registry from ${altGateway}`);
          return registry;
        }
      } catch {
        // Continue to next gateway
      }
    }

    // Check for GCS-hosted registry
    try {
      const { hasGCSCredentials, downloadFromGCS } = await import('../storage/gcs.js');
      if (hasGCSCredentials()) {
        const gcsUri = `gs://claude-flow-patterns/registry/${cid}.json`;
        console.log(`[Discovery] Trying GCS: ${gcsUri}`);
        const buffer = await downloadFromGCS(gcsUri);
