          console.log(`[Discovery] Fetched registry from GCS`);
          return registry;
        }
      }
    } catch {
      // GCS not available
    }

    // Return fallback genesis registry if all else fails
    console.log(`[Discovery] Using built-in genesis registry`);
    return this.getGenesisRegistry(cid);
  }

